INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e51f0c1286860b6f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: "Feel blue" means?', '{"A":"Feel sad","B":"Feel happy","C":"Feel energetic","D":"Feel angry"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Feel blue” is an idiom in English meaning to feel unhappy or depressed.The word “blue” is symbolically used for sadness or low mood.Last verified on 13-06-2026', 0, 0, 0, 1790961792435) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dd598b6c811aeba3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: "To throw in towel" means?', '{"A":"To correct a mistake","B":"To accept defeat","C":"To put in effort","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "To throw in the towel" means to accept defeat or give up.It is used when someone admits they cannot continue.The idiom comes from the sport of boxing.A trainer throws a towel into the ring to stop the fight.It symbolizes surrender or quitting.Last verified on 18-07-2026', 0, 0, 0, 1790961792435) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_42fe40cffe6fc5cf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: A broken reed means?', '{"A":"Strong support","B":"Unreliable person","C":"Brave leader","D":"Hard worker"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A broken reed means a weak, ineffective person or thing that cannot be depended on when you need helpناقابلِ اعتبار سہارا یا غیر معتبر شخص ہے۔Last updated NA on 10-09-2026', 0, 0, 0, 1790961792435) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_df36348c0b70e47e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: At arms length means ______?', '{"A":"Near","B":"At a distance","C":"Little distance","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “At arm’s length” means to avoid becoming too close, intimate, or friendly with someone or something.فاصلہ رکھنا (keeping a distance)Last updated question NS on 10-09-2026', 0, 0, 0, 1790961792435) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_668fd03dd7eb468d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: Beat about the bush means?', '{"A":"To avoid discussing a topic directly","B":"To avoid the main topic","C":"To avoid taking about what is important","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Beat about the bush means to avoid discussing the main point directly.It is used when someone talks indirectly instead of addressing the important issue.Example: Stop beating about the bush and tell me what happened.Last verified on 07-09-2026', 0, 0, 0, 1790961792435) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1074bf8e21b7a4e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: "Burning the midnight oil" means?', '{"A":"Staying up late into the night / to study or work","B":"Work late into the night","C":"To work till late night","D":"Working very hard","E":"All of these"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The idiom means working or studying late into the night, especially with great effort.The phrase originates from the time when oil lamps were used for light during nighttime work.Example: Students burn the midnight oil before exams to prepare well.Last verified on 08-05-2026', 0, 0, 0, 1790961792435) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1a03fbf227622286', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: Piece of cake means?', '{"A":"Bear the enmity","B":"Easy task","C":"Be happy","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The idiom “piece of cake” means something very easy to do.Example: “The exam was a piece of cake.”Last verified on 16-05-2026', 0, 0, 0, 1790961792435) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c8aa7abcf93dba2e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: "Tie the knot” means?', '{"A":"Getting married","B":"Friendship","C":"Enmity","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Tie the knot” means to get married.It is commonly used to refer to the act of marriage.Last verified on 11-08-2026', 0, 0, 0, 1790961792435) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a02d43b66da5bc59', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: Let sleeping dogs lie means?', '{"A":"To avoid disturbing someone","B":"To avoid restarting a conflict","C":"To kill the sleeping dogs","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The idiom “Let sleeping dogs lie” means not to bring up an old problem or conflict again.It advises leaving a troublesome situation alone if it is already settled.Last verified on 09-08-2026', 0, 0, 0, 1790961792524) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9a71744f97ff766d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: The Alpha and Omega means?', '{"A":"A beautiful object","B":"Beginning and end","C":"A good man","D":"Something divine"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The idiom "The Alpha and Omega" is taken from Christianity and refers to Jesus."Alpha" is the first letter of Greek alphabet."Omega" is the last letter of Greek alphabet.Therefore, the meaning of the idiom is ''The beginning and the end''.Last verified on 08-08-2026', 0, 0, 0, 1790961792524) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ab8bbca2d7255551', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: Out of the blue means?', '{"A":"From nowhere","B":"Unexpectedly/Suddenly","C":"Clearly","D":"Both A and B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "Out of the blue" means Unexpectedly/Suddenly.It refers to something happening without warning or surprise, like a sudden event or occurrence.Last verified on 06-08-2026', 0, 0, 0, 1790961792524) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_78bcd67c7a7c73e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: At one''s beck and call means?', '{"A":"To be under one''s subjugation","B":"To be always at one''s service","C":"Enjoying oneself without caring for others","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation At one''s beck and call means to be always ready to obey someone''s orders or help immediately.It refers to being constantly available to serve someone.Last verified on 28-07-2026', 0, 0, 0, 1790961792524) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_14d3c833e8e18315', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: To get cold feet means?', '{"A":"To be afraid / feel afraid","B":"To run for life","C":"To fall sick","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To get cold feet means to become afraid or nervous before doing something.It is commonly used when someone loses courage at the last moment.Last verified on 27-07-2026', 0, 0, 0, 1790961792524) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b88198a0de244f68', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'The idiom “Under the weather” means?', '{"A":"To be ill","B":"Feeling unwell/sick","C":"Standing in bad weather","D":"Both A and B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Under the weather” is an idiom used for a person who is not feeling well or is sick.It commonly means ill or slightly unwell (feeling sick).Last verified on 24-06-2026', 0, 0, 0, 1790961792524) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bab4cef440bafade', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'What does the idiom "hit the nail right on the head" mean?', '{"A":"To be exactly correct","B":"Speaking directly to the point","C":"Perform as a task with exactness","D":"To say something that is exactly right","E":"All of these"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The idiom "hit the nail right on the head" broadly means to do or say something that is completely accurate, precise, and perfectly suited for the situation.Because it encompasses verbal accuracy, correct actions, and directness.Last verified on 19-01-2026', 0, 0, 0, 1790961792524) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_044d94686fdd13c6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Select the meaning of idiom: A blessing in disguise?', '{"A":"Sometimes that seems bad but it actually good","B":"A good thing that seems bad at first","C":"A bad situation","D":"Both A and B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "A blessing in disguise" means something that seems bad at first but later turns out to be good.It refers to an unexpected benefit hidden in an unpleasant situation.The idiom teaches that some difficulties bring positive results.Last verified on 08-05-2026', 0, 0, 0, 1790961792524) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_150f4605dc838dc9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: “To turn over a new leaf” means?', '{"A":"Do a new jobs","B":"Change one’s behaviour for the better","C":"Read between the pages of a book","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Turn over a new leaf" means to change one''s behaviour for the better and start a better life.It is an English idiom used when someone leaves bad habits behind.It refers to making a fresh start with positive actions.Last verified on 07-07-2026', 0, 0, 0, 1790961792620) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8431629049c2b7e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: Add fuel to the fire means?', '{"A":"Create problem","B":"Worsen bad situation","C":"Aggravate trouble","D":"Both B and C"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The idiom "add fuel to the fire" means to make a bad situation worse by aggravating the problem.It implies actions or words that intensify existing anger, conflict, or difficulty.Last verified on 01-04-2026', 0, 0, 0, 1790961792620) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_773f0b10a0ae8ed2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: Turn a deaf ear means?', '{"A":"Ignore","B":"Treat","C":"Teach","D":"Meet"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Turn a deaf ear means to deliberately ignore or refuse to listen to someone or something.It implies paying no attention to advice, requests, or complaints.Last verified on 02-07-2026', 0, 0, 0, 1790961792620) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d37aa38dc1f9d8f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: To steal someone’s thunder means?', '{"A":"To help someone","B":"To take attention","C":"To frighten someone","D":"To make someone happy"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To "steal someone’s thunder" means to take credit, attentionکسی کی محنت یا کامیابی کا کریڈٹ یا توجہ چُرا لینا۔Last updated question NS on 09 MAY 2026', 0, 0, 0, 1790961792620) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9d6e772a95f56d17', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: Rule of Thumb means?', '{"A":"A rough estimate","B":"Fixed rule","C":"Exact estimation","D":"An easy choice"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Rule of Thumb” refers to a general guideline based on practical experience, not a precise measurement.It is used when giving an approximate or rough estimate.Last verified on 30-03-2026', 0, 0, 0, 1790961792621) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_434a4f5b91661862', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: A pipe dream means?', '{"A":"Unattainable dream","B":"An impracticable wish","C":"Both A and B","D":"A bad dream"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A pipe dream means a dream or wish that is unlikely to happen or cannot be achieved.It refers to an unrealistic or impracticable idea.Last verified on 01-07-2026', 0, 0, 0, 1790961792621) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e120163c1401be8e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Complete the proverb: No man is a/an _______?', '{"A":"Island","B":"Sea","C":"Mountain","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct proverb is: “No man is an island.”It means no one can live completely alone without others.Human beings depend on society and relationships.Last verified on 20-06-2026', 0, 0, 0, 1790961792621) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_847a676a4fa68ed5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'The idiom “To smell a rat” means?', '{"A":"To detect something wrong","B":"To suspect a trick or detect","C":"To suspect that something is wrong","D":"To suspect foul dealings","E":"All of these"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “To smell a rat” means to suspect that something is wrong or dishonest.It is used when someone feels a trick, fraud, or foul play is involved.Last verified on 20-06-2026', 0, 0, 0, 1790961792621) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_155341c4c0933006', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'The phrase ''to have your hands full'' means?', '{"A":"To be a sinner","B":"To have plenty of wealth","C":"Something related to fighting","D":"To have too many things to do"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The idiom “to have your hands full” means being very busy.It describes a situation where a person has many responsibilities at the same time.Last verified on 20-06-2026', 0, 0, 0, 1790961792722) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3e61a8a9555d2045', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'The phrase "to ride roughshod over" means?', '{"A":"To act with extreme caution","B":"To dominate or treat others harshly without regard / To dominate or treat someone harshly without consideration","C":"To travel recklessly on horseback","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “To ride roughshod over” means to ignore others’ rights, feelings, or opinions.It suggests using power in a harsh or unfair way.It originally comes from horses trampling things under their hooves, symbolizing force and disregard.Last verified on 14-06-2026', 0, 0, 0, 1790961792722) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c48d8878bfe1dc4a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: To keeps one''s temper means?', '{"A":"To become hungry","B":"To become angry","C":"To be in good mood","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “To keep one’s temper” means to remain calm and not get angry.It is used when a person controls emotions in a stressful situation.Last verified on 06-06-2026', 0, 0, 0, 1790961792722) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_065e10a155f39d4d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: An “above board” person means?', '{"A":"Trustworthy","B":"To be honest in any business deal","C":"Honest","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Above Board means ایماندار یا قابل اعتماد شخص"Above board" means being honest and transparent in one''s dealings, without hiding any intentions.It refers to someone who is trustworthy and fair in their actions.Last verified on 04-06-2026', 0, 0, 0, 1790961792722) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c7b30c45afd6edb5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: To throw down the gauntlet means?', '{"A":"To surrender","B":"To accept defeat","C":"To issue a challenge someone to fight","D":"To avoid conflict"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To throw down the gauntlet means to issue a challenge, provoke a confrontation, or dare someone to argue or compete with youکسی کو چیلنج دینا، مقابلے کی دعوت دینا، یا جھگڑے/مقابلے پر اکسانا۔Last updated question NS on 09 MAY 2026', 0, 0, 0, 1790961792722) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_02cc7bd62162ce5b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'The idiom: "Let the cat out of bag." means?', '{"A":"To save cat","B":"To adopt measures","C":"To reveal secret / Give away a secret / Secret is revealed carelessly","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Cat is out of the bag" means Secret is revealed carelessly."Cat is out of the bag" means بلی تھیلے سے باہر ہے۔Secret is revealed carelessly means راز بے احتیاطی سے کھل جاتا ہے۔This idiom indicates that confidential information has been disclosed unintentionally or prematurely.Last verified on 25-05-2026', 0, 0, 0, 1790961792722) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7e6a279fda294eeb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'What does the idiom "Hit the sack" mean?', '{"A":"To punch a bag","B":"To go to bed or sleep","C":"To start a task","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Hit the sack” is a common English idiom.It means to go to bed or go to sleep.It is used in informal daily conversation.The phrase became popular in the early 20th century.Last verified on 24-05-2026', 0, 0, 0, 1790961792722) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bbd4d4886368c945', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'The Idiom: To bite the bullet means?', '{"A":"To act recklessly","B":"To make a quick decision","C":"To face a difficult or unpleasant situation with courage / Face a difficult situation bravely","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The idiom "to bite the bullet" means "to face a difficult or unpleasant situation with courage."It refers to enduring a tough situation bravely rather than avoiding it.Last verified on 24-05-2026', 0, 0, 0, 1790961792722) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bd137d9edd5877e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'What does the idiom cost an arm and a leg mean?', '{"A":"To be very cheap","B":"To be extremely expensive / Very expensive","C":"To be painful","D":"To be hard to carry"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This idiom is used when something costs a very large amount of money.It shows that the price is so high it feels like “giving up an arm and a leg.”Last verified on 23-05-2026', 0, 0, 0, 1790961792826) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8517da4c3a2245b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'The idiom "once a blue moon" means?', '{"A":"Often","B":"Rarely","C":"Rapidly","D":"Slowly"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The idiom “once in a blue moon” means something that happens very infrequently.It refers to an event that is rare or almost never happens.Last verified on 04-05-2026', 0, 0, 0, 1790961792826) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c09dc64ef224bce2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: At sixes and sevens means?', '{"A":"Quick","B":"Bewildered","C":"Come early","D":"Teenage"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “At sixes and sevens” means being confused, disorganized, or in a state of uncertainty.It describes a situation where things are not properly arranged.Example: After the sudden announcement, everyone was at sixes and sevens.Last verified on 18-05-2026', 0, 0, 0, 1790961792826) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6cea30f1263dd72b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: “To bell the cat” means?', '{"A":"To avoid danger","B":"To face the risk","C":"To play safely","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The idiom “to bell the cat” means to take responsibility for a dangerous or difficult task.It is used when someone is brave enough to face a risky situation that others avoid.The phrase comes from a fable where mice suggest putting a bell on a cat to be warned of its approach.Last verified on 10-05-2026', 0, 0, 0, 1790961792826) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fd02ab3bd6b59d27', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'What does the idiomatic expression to spill the beans mean?', '{"A":"To reveal a secret or surprise","B":"To make a mistake or error","C":"To share good news or exciting information","D":"To keep a secret or confidential information"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase to spill the beans is an idiomatic expression.It means to reveal a secret or surprise, often accidentally or unintentionally.Last verified on 03-04-2026', 0, 0, 0, 1790961792826) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d5178c3107e3607b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: Have an Axe to Grind means ____?', '{"A":"To use axe frequently","B":"To have a dispute with someone","C":"To be fair with someone","D":"Selfish motive"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The idiom “Have an axe to grind” means having a selfish or personal reason.It is used when someone acts for personal interest or hidden motive.It is often used in criticism when someone’s opinion is biased due to personal benefit.Last verified on 02-05-2026', 0, 0, 0, 1790961792826) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3a6cf5bfde8ad929', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'The idiom "A DARK HORSE" means?', '{"A":"A wicked fellow","B":"An unexpected winner","C":"A criminal getting the dirty water","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The idiom “A Dark Horse” means a person who wins unexpectedly.It refers to someone whose abilities are not well known.Such a person surprises everyone by sudden success.Commonly used in competitions, elections, or exams.Last verified on 28-04-2026', 0, 0, 0, 1790961792826) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b1965acf3b5aeafa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Complete the Idiom: Hell hath no fury like _____?', '{"A":"A devil is advocate","B":"A woman forgotten","C":"A burned woman","D":"A woman scorned"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The full idiom is "Hell hath no fury like a woman scorned".It means that a woman who has been wronged or rejected can be extremely angry or vengeful.Last verified on 22-04-2026', 0, 0, 0, 1790961792826) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cc7d540af6c76ce1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Complete the Idiom: Don''t judge a book by its _____ ?', '{"A":"Cover","B":"Page","C":"Size","D":"Object"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The saying "never judge a book by its cover" or "don''t judge a book by its cover" It means that you shouldn''t judge someone or something based only on what you see on the outside.Only on what you perceive without knowing the full situation.Last verified on 19-04-2026', 0, 0, 0, 1790961792920) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d4fa0e8193821845', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: To be rolling in money means ____?', '{"A":"Poor","B":"Stingy","C":"Very Rich","D":"Spending more than income"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “To be rolling in money” means having a lot of wealth.It describes someone who is extremely rich or financially well-off.Last verified on 04-04-2026', 0, 0, 0, 1790961792920) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e01f9e3487a9fbad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: To give a false coloring means _____?', '{"A":"To misrepresent","B":"To submit a false report","C":"To conceal the facts","D":"To be honest"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “To give a false coloring” means to present something in a misleading or distorted way.It involves misrepresenting facts to create a wrong impression.Last verified on 04-04-2026', 0, 0, 0, 1790961792920) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a00feb304700b807', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: "Red letter day" means?', '{"A":"A dangerous day","B":"An important day","C":"An eventful day","D":"A formidable day"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Red letter day” refers to a very important or special day in someone’s life.It comes from calendars where important dates were marked in red.Last verified on 03-04-2026', 0, 0, 0, 1790961792920) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bf62850434d1293d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'The Idiom: Prick up your ears means?', '{"A":"Listening carefully","B":"Ignoring","C":"Tuning out","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prick up your ears means to pay attention or listen carefully.It often to something surprising or important.Example: "She pricked up her ears when she heard her name mentioned in the conversation."Last verified on 02-04-2026', 0, 0, 0, 1790961792920) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_90cea51f44f9e9e5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'The idiom: Kick the bucket means?', '{"A":"To kill","B":"Achieve a goal","C":"To be successful","D":"To die"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If you say that someone has kicked the bucket, you mean that they have died. Synonyms: die, expire, perish, pass awayLast verified on 02-04-2026', 0, 0, 0, 1790961792920) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_575b49d668e6bee0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'The idiom To bury the hatchet means what?', '{"A":"To agree to end a quarrel","B":"Frequently","C":"Again and Again","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bury The Hatchet صلح کر لیناTo agree to end a quarrel: جھگڑا ختم کرنے پر راضی ہوناLast verified on 02-04-2026', 0, 0, 0, 1790961792920) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2e276b5acbd186f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'The idiom: ''To cry wolf'' means _____?', '{"A":"To listen eagerly","B":"To give false alarm","C":"To frighten someone","D":"To cry over little things"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To Cry Wolf means to ask help when you do not need it.To Cry Wolf means ضرورت نہ ہو پھر بھی مدد طلب کرناLast verified on 02-04-2026', 0, 0, 0, 1790961792920) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6d38de870ee42550', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Choose the closed possible meaning of the given idiom from the given option below: Led Astray?', '{"A":"In good direction","B":"Misguided","C":"Killed","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Led astray” means being guided in the wrong direction or into error.It implies misguidance or being deceived from the right path.Last verified on 30-03-2026', 0, 0, 0, 1790961793026) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f7decf50065573b6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Choose the correct meaning of idiom: To fish in troubled waters.', '{"A":"To make a personal profit out of disturbance","B":"To catch fish in flood water","C":"To dive in deep water","D":"Go for the daunting task"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct meaning of the idiom "To fish in troubled waters" is "To benefit from other people''s trouble."This phrase refers to taking advantage of a difficult or chaotic situation for personal gain.Last verified on 30-03-2026', 0, 0, 0, 1790961793026) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4b07ecdfaf94042b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: To lose face means:', '{"A":"To be helppless","B":"To look angry","C":"To be humiliated","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The idiom "to lose face" means to be humiliated.Definition: To suffer a loss of respect or to be humiliated.Last updated on 09-03-2026', 0, 0, 0, 1790961793026) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7be8b012392455e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: To make a clean breast of means?', '{"A":"To confess fully","B":"To destroy before it","C":"To praise oneself","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To make a clean breast of means to admit or confess something honestly and completely.It is often used when someone reveals a truth they were hiding.Last verified on 22-02-2026', 0, 0, 0, 1790961793026) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_17e535c71a58dacf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: To catch a tartar means?', '{"A":"To deal with someone or something that proves unexpectedly troublesome or powerful","B":"To meet with disaster","C":"To trap wanted criminal with great difficulty","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase means encountering a person or situation that is much harder to handle than expected.It originates from military slang, where soldiers mistakenly captured a strong enemy instead of an easy target.Last verified on 22-02-2022', 0, 0, 0, 1790961793026) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c1bb9c8da4f2bb70', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'What does the idiom Street Smart mean?', '{"A":"Someone who is very good at reading books","B":"Someone who is clever and practical in real-life situations","C":"Someone who always follows rules strictly","D":"Someone who is good at sports"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Street smart” means a person who is practically intelligent.Such a person can handle real-life problems wisely.It is about experience, not book knowledge.Used for people who make quick, smart decisions.Last verified on 15-02-2026', 0, 0, 0, 1790961793026) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e416c920829a996d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: Break a leg means?', '{"A":"Wish the luck/To wish someone good luck","B":"Dislocation leg inadvertently","C":"To dislocation the leg","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Break a leg mean, good luck Used primarily in theater, music, and performance, but also informally for, say, job interviews.Last updated 15-03-2026', 0, 0, 0, 1790961793026) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0848aac233029bf2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', '___ sign is used at the end of a sentence or a short phrase which express very strong feeling.', '{"A":"Exclamation","B":"Sign of interrogation","C":"Both","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An interjection is a word or expression that occurs as an utterance on its own and expresses a spontaneous feeling or reaction. It is a diverse category, encompassing many different parts of speech, such as exclamations, curses, greetings, response particles, hesitation markers, and other words. *****RY 15-01-2023', 0, 0, 0, 1790961793026) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d0fc574fdeda962b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Choose the meaning of the Idiom: A cat''s Paw means?', '{"A":"Person of soft nature","B":"Completely unarmed","C":"Person used as a tool to do something dangerous","D":"A narrow escape"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The idiom "a cat''s paw" refers to someone who is being used as a tool or instrument by another person to achieve a goal or accomplish a task, often in a way that involves risk or danger. The phrase is thought to have originated from the idea that a cat''s paw is used to test if a surface is hot or dangerous, and similarly, a person may be used as a "cat''s paw" to test the waters or take the fall for someone else.', 0, 0, 0, 1790961793121) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5c0bb3412804436e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'Idiom: Break out means?', '{"A":"Occur suddenly","B":"Break down","C":"Incomplete","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Break out refers to something happening suddenly, such as an epidemic, war, or fire.Example: "A fire broke out in the factory last night."', 0, 0, 0, 1790961793121) ON CONFLICT(id) DO NOTHING;
