INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e4e79dd812a143e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'The heavy losses in business came like a bolt from the blue. In the above sentence, the idiom "bolt from the blue" means', '{"A":"A thunderstorm","B":"An unexpected disaster","C":"A windfall","D":"An ominous warning","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The idiom "bolt from the blue" means غیر متوقع سانحہٖFor example: His resignation came like a bolt from the blue.Bolt means آسمانی بجلی', 0, 0, 0, 1790961793863) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_03334e4058802f16', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'The idiom "By hook or by crook" means what?', '{"A":"زبردستی","B":"کسی کا حق مارنا","C":"ہر جائز و ناجائز طریقے سے","D":"کسی کو تنگ کرنا"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Example : I want to win this match, by hook or by crook.', 0, 0, 0, 1790961793863) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f6ce1934beb63356', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'The idiom "butterflies in someone`s stomach" means', '{"A":"Being Nervous","B":"Being Excited","C":"Being Angry","D":"Being Hungry","E":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The idiom "butterflies in someone`s stomach" means to feel very nervous and restless.The idiom "butterflies in someone`s stomach" means بہت ہی گھبرایا ہوا یا پھر بہت ہی بے چین For example:Tomorrow is my first day at a new school, I have butterflies in my stomach.کل میرا اسکول میں پہلا دن ہے، میں بہت ہی گھبرایاہوا/بے چین ہوں۔', 0, 0, 0, 1790961793972) ON CONFLICT(id) DO NOTHING;
