INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3513c98f5e949d36', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'The idiom "as fit as a fiddle" means', '{"A":"In a good health","B":"in a happy mood","C":"in the limelight","D":"in the pink dress","E":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation As fit as a fiddle means صحتمند یا مضبوط My grandfather is 90 years old, but he is still as fit as a fiddle. میرے داد کی عمر نوے برس ہے لیکن وہ ابھی تک صحتمند ہیں۔', 0, 0, 0, 1790961793972) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7bc624e73de77ae8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'The idiom "In the pink" means', '{"A":"In a good health","B":"in a happy mood","C":"in the limelight","D":"in the pink dress","E":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the pink means صحتمند For example:Do you remember last night you were really in the pink?کیا آپ کو یاد ہے گزشتہ رات آپ بالکل صحتمد تھے؟', 0, 0, 0, 1790961793972) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d02b92bbdac16738', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'The idiom "Couch Potato" means what?', '{"A":"A person who sleeps all day","B":"A person who remains relaxed and calm","C":"A person who is simple in nature","D":"A person who watches too much television","E":"None of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Couch Potato means a lazy and inactive person especially : one who spends a great deal of time watching televisions . Couch potato means ایسا سست انسان جو سارا دن ٹی وی دیکھتا ہو', 0, 0, 0, 1790961793972) ON CONFLICT(id) DO NOTHING;
