INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_10e61fc346743e91', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'The idiom "Pull yourself together" means', '{"A":"Go to study","B":"Calm Down","C":"Try to understand","D":"Do a good job","E":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The idiom "Pull yourself together" means to become calm and behave normally again after being angry or upset.Pull yourself together means ناراض یا غصے میں آجانے کے بعد پرسکون ہوناHe was unable to pull himself together after he lost his entire family in the plane crash.', 0, 0, 0, 1790961793972) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0a1a16b5df1aee2f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_idioms', 'The idiom "Pull someone''s leg" means', '{"A":"Tell someone a secret","B":"Get upset with someone","C":"Joke with someone","D":"Trust someone","E":"All of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The idiom "Pull someone''s leg" means کسی کے ساتھ مذاق کرنا یا تنگ کرناFor example:I told you there was a monster in the closet, but I was just pulling your leg! میں نے تمہیں بتایا تھا وہاں الماری میں ایک مونسٹر ہے لیکن میں تو بس تمہارے ساتھ مذاق کررہا تھا۔', 0, 0, 0, 1790961793972) ON CONFLICT(id) DO NOTHING;
