INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d2042a7ab03e1172', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_one_word', 'One word substitution: One who speaks less?', '{"A":"Obsolete","B":"Hypocrite","C":"Misogynist","D":"Reticent"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Reticent means a person who speaks very little or is reserved in speech.Additional information:Obsolete → Something old-fashioned or no longer in useHypocrite → A person who pretends to have good morals but does not follow themMisogynist → A person who dislikes or hates womenLast verified on 20-06-2026', 0, 0, 0, 1790961794309) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_15870fc94c58befa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_one_word', 'One word substitution: Study of human face?', '{"A":"Mensuration","B":"Horology","C":"Physiognomy","D":"Sinology"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Physiognomy is the study of a human face and its features to understand character or personality.It links facial expressions and structure with behavior traits.Additional information:Horology → Study of time and clocksSinology → Study of Chinese language & cultureLast verified on 14-06-2026', 0, 0, 0, 1790961794309) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2c7a34981618d7e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_one_word', 'A person who is indifferent to pains and pleasure of life?', '{"A":"Stoic","B":"Sadist","C":"Psychiatrist","D":"Aristocrat"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A stoic is a person who remains calm and unaffected by pain, pleasure, or emotions.Stoicism is a philosophy that teaches self-control and endurance.Such people face difficulties without excessive complaint or excitement.The term originates from ancient Greek philosophy.Last verified on 04-06-2026', 0, 0, 0, 1790961794309) ON CONFLICT(id) DO NOTHING;
