INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8206d733e2b66e44', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_one_word', 'One who is incapable of being tired', '{"A":"Opportunist","B":"Extempore","C":"Indefatigable","D":"Idle","E":"Fatigued"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Indefatigable means نا تھکنے والا شخص، انتھک، بے تکان، بہت زیادہ محنتی', 0, 0, 0, 1790961794567) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_870bf429fcbf9cb5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_one_word', 'A person who asserts his opinion arrogantly without sufficient evidence is called:', '{"A":"Radical","B":"Fanatic","C":"Dogmatic","D":"Atheist","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A person who asserts his opinion arrogantly without sufficient evidence is called Dogmatic.Dogmatic ہٹ دھرم انسان، ایسا شخص جو اپنی رائے پر اڑا رئے، اپنی رائے رکھنے والاND06-08-2023', 0, 0, 0, 1790961794654) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_82f45c2c956c8c21', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_one_word', 'Mania for stealing articles', '{"A":"Logomania","B":"Nymphomania","C":"Kleptomania","D":"Hypomania"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kleptomania means a recurrent urge to steal, typically without regard for need or profit. Kleptomania means چوری کا جَنُون', 0, 0, 0, 1790961794654) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_46dce2db6d6ceebf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_one_word', 'Systematic scientific study of Teeth is known as:', '{"A":"Pedagogy","B":"Odontology","C":"Ornithology","D":"Cardiologist","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Important GK Agrostology: Study of Grasses Agronomy: soil management and crop production Odontology: a study of teeth Arthrology: Study of joints Nephrology: a study of kidneys Teeth have four categories – incisors, canines, premolars, and molars.SH10-8-2023', 0, 0, 0, 1790961794654) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d23bdcd462dd2d09', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_one_word', 'A person who is unable to pay his debts is called?', '{"A":"Bale","B":"Brood","C":"Caucus","D":"Insolvent"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Insolvent: One who is unable to pay his debts.Insolvent (Adjective): ایسا شخص جو اپنا قرض ادا نہ کر سکے۔', 0, 0, 0, 1790961794654) ON CONFLICT(id) DO NOTHING;
