INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fa3f1c937bf5144a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_one_word', 'A place where wild animals live is called', '{"A":"Forest","B":"Stable","C":"Lair","D":"Sanctuary"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Forest: a large area covered chiefly with trees and undergrowth.Stable: (of an object or structure) not likely to give way or overturn; firmly fixed.Lair: a place where a wild animal lives.Sanctuary: refuge or safety from pursuit, persecution, or other danger.', 0, 0, 0, 1790961794654) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3d7af41a5c4ff06c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_one_word', 'Laliophobia is a fear of________?', '{"A":"Heights","B":"Speaking","C":"Fire","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Laliophobia or lalophobia (from Greek lal, "speech") is the fear of speakingwhileAerophobia is an extreme fear of flying.Febriphobia is the fear of fever.Nyctophobia is the fear of Darkness.Anthophobia is the fear of flora.Heliophobia is the fear of the Sun, sunlight, or any bright light.Hemophobia, or blood phobia,', 0, 0, 0, 1790961794654) ON CONFLICT(id) DO NOTHING;
