INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_37050ba12fd507f6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_one_word', 'The study of which words occur together, and their frequency of co-occurrence:', '{"A":"connotation","B":"collocation","C":"implication","D":"location"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Collocation means the habitual juxtaposition of a particular word with another word or words with a frequency greater than chance.', 0, 0, 0, 1790961794808) ON CONFLICT(id) DO NOTHING;
