INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f2f5a8cb6cfe0b4f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'Choose the correct spelling: Acomodation, Accommodation, Accomodation, None of these', '{"A":"Acomodation","B":"Accommodation","C":"Accomodation","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Accommodation means رہائشAccommodation refers to a place to live or stay (lodging).Last verified on 08-06-2026', 0, 0, 0, 1790961798179) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ab3a0f1221acf50e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'Choose the correct spelling: Invairunment, Enviroment, Enwironment, Environment', '{"A":"Invairunment","B":"Environmen","C":"Enviroment","D":"Environment"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An environment consists of the surroundings, conditions, and influences—both biotic (living) and abiotic (non-living)Environment means ماحولLast updated by NA on 25-April-2026', 0, 0, 0, 1790961798179) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eb06486a4cd92ea9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'Choose the correct one word to replace the given sentence (A speech delivered without any preparation).', '{"A":"Extempore","B":"Contemporary","C":"Temporary","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Extempore means spoken or delivered without prior preparation.An extempore speech is given spontaneously or on the spot.Additional information:Contemporary means belonging to the present time.Temporary means lasting for a limited period.Exemplary means serving as a good example.Last verified on 09-09-2026', 0, 0, 0, 1790961798179) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b53bb0298627ec76', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'What is the correct plural form of ''analysis''?', '{"A":"Analysis","B":"Analyses","C":"Analayses","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Analysis” is a Greek-origin noun ending in -is.In plural form, -is changes to -es, making it analyses.It is an irregular plural, not formed by adding simple “s”.Last verified on 06-06-2026', 0, 0, 0, 1790961798179) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_395373f5e4b859a2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'The correct plural of ''phenomenon'' is?', '{"A":"Phenom","B":"Phenomenas","C":"Phenomena","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Phenomena is its correct plural form.Phenomenon is a singular noun.Example: Many natural phenomena occur in nature.Last verified on 07-07-2026', 0, 0, 0, 1790961798179) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4525ba2dfa15c0d7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'Choose the correct spelling: Necessary, Noccessary, Necesary, Neceessary', '{"A":"Necessary","B":"Noccessary","C":"Necesary","D":"Neceessary"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Necessary means ضروریLast verified on 09-02-2026', 0, 0, 0, 1790961798179) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8828c2145d200597', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'Choose the correct spelling: Millinnium, Millennium, Milennium, None of these', '{"A":"Millinnium","B":"Millennium","C":"Milennium","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Millennium means ہزار برسLast verified on 08-06-2026', 0, 0, 0, 1790961798179) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ce453bb11bea8b9b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'Choose the correct spelling: Committe, Commettee, Committee, None of these', '{"A":"Committe","B":"Commettee","C":"Committee","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Committee means پنچایتLast verified on 03-09-2026', 0, 0, 0, 1790961798179) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_75fa897500231af9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'Choose the sentence that is grammatically correct: Hardly he reached when the train left., Hardly he had reached when the train left., Hardly had he reached when the train left., Hardly did he reached when the train left.', '{"A":"Hardly he reached when the train left.","B":"Hardly he had reached when the train left.","C":"Hardly had he reached when the train left.","D":"Hardly did he reached when the train left."}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hardly had he reached when the train left.With “Hardly”, we use inversion (auxiliary before subject).Structure: Hardly + had + subject + past participle + when + past simple.It shows that one action happened immediately after another.Last verified on 09-06-2026', 0, 0, 0, 1790961798297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e8ef884d1ec7eec8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'Choose the correct sentence: She had an car., She have a car., She has a car., None of these', '{"A":"She had an car.","B":"She have a car.","C":"She has a car.","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Correct sentence: She has a car.With he, she, and it, we use has, not have.Has is the correct present tense form of have for a singular third-person subject.Last verified on 02-06-2026', 0, 0, 0, 1790961798297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f9ba2b2cbce699f9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'Choose the correct sentence: The jury has reached their verdict, The jury has reached its verdict, The jury reach its verdict, The jury have reached its verdict', '{"A":"The jury has reached their verdict","B":"The jury has reached its verdict","C":"The jury reach its verdict","D":"The jury have reached its verdict"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The jury has reached its verdict.Jury is a collective noun treated as singular here.Use has with a singular collective noun.Its agrees with the singular noun jury.Last verified on 07-07-2026', 0, 0, 0, 1790961798297) ON CONFLICT(id) DO NOTHING;
