INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b419d4877facd5e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'Choose the correct plural form of the sentence: "He is a smart boy."', '{"A":"He is smart boys","B":"They are smart boy","C":"They are smart boys","D":"We are smart boy"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "He" (singular) changes to "They" (plural)."Is" (singular verb) changes to "are" (plural verb)."Boy" becomes "boys" for plural.Correct plural sentence: They are smart boys.', 0, 0, 0, 1790961799529) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_28bdcd0f7bf70905', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'Many camels live in the desert. Choose the correct meaning of the homograph “desert”?', '{"A":"A dry, sandy land/area","B":"To abandon someone","C":"A type of plant","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Desert" refers to a barren, dry, sandy region with little rainfall.Desert means صحراA dry, sandy land means ایک خشک ، سینڈی زمین', 0, 0, 0, 1790961799529) ON CONFLICT(id) DO NOTHING;
