INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f21579b21efc8592', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'Choose the correct voice: She was motivating her friends.', '{"A":"Her friends are motivating her","B":"She is being motivated by her friends","C":"Her friends were being motivated by her","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The given sentence is in active voice (past continuous tense): She was motivating her friends.In passive voice, the object (her friends) becomes the subject: Her friends were being motivated by her.', 0, 0, 0, 1790961799610) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0298e1538d402b9a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'Choose the correct coordinate conjunction?', '{"A":"While","B":"Or","C":"If","D":"Until"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The words like for, and, nor, but, or, yet, and so are called: Coordinate Conjunctions."Or" is a coordinate conjunction, used to join two words, phrases, or clauses of equal importance.', 0, 0, 0, 1790961799610) ON CONFLICT(id) DO NOTHING;
