INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a08a903796e0ace4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'Select the correct "article" used in the sentence, "when I met him he was ____ intermediate" from the given choices:', '{"A":"a","B":"an","C":"the","D":"one"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Uses of AN before letters and numbers which sound like a vowel (A, E, I, O, U), such as "F" or "8". Remember sound not the spelling.', 0, 0, 0, 1790961800477) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8217fb9783e59977', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'Select the option which correct replaces the Underline words in the sentence below : Robina said that she had told everyone Except you and I.', '{"A":"Except you with","B":"Except you and me","C":"Except you and myself","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961800477) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e71da567441b962e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'Select the option which corrects in the sentence: If he was here, he would settle this dispute among the two of us.', '{"A":"If he had been","B":"If he were here","C":"If he is here","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If you find yourself debating whether to use “was” or “were” in a sentence, it’s likely that you’re dealing with an unreal conditional sentence. As a refresher, an unreal conditional sentence expresses events that are hypothetical or improbable.', 0, 0, 0, 1790961800536) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_143167ca04d32378', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'The chief lived in the stone house. In the above sentence the word "Stone" is a/an:', '{"A":"Verb","B":"Noun","C":"Adjective","D":"Adverb"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word stone is modifying the noun house. Therefore, the word stone is an adjective.', 0, 0, 0, 1790961800536) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bfc48e8d77602ba1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'They have not opened the doors for ages. (Choose the correct passive)', '{"A":"The doors have been opened by them for ages","B":"The doors have not been opened by us for ages","C":"The doors have not been opened by them for ages","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the present perfect tense we make passive verb forms by putting has/have + been before the past participle form of the verb.', 0, 0, 0, 1790961800536) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c15bd38a4411ba26', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'Marke the correct phrasal verb to complete the sentence "Aslam decided to __________ Jogging as he needed to lose weight " from the given choices.', '{"A":"Go against","B":"Take up","C":"Run app","D":"Get at"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Take upدوبارہ آغاز کرنا ۔ مصروف ہونا', 0, 0, 0, 1790961800536) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b4f3e9680b836794', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_articles', 'Keep your books on the table. In the above sentence, the word "On" is a/an:', '{"A":"Preposition","B":"Adverb","C":"Adjective","D":"Noun","E":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Several words are sometimes used as adverbs or sometimes used as prepositions.A word is a preposition when it governs a noun or a pronoun, It is an adverb when it does not.He moved on. “On” is an adverb here Keep your books on the table. “On” is a preposition here', 0, 0, 0, 1790961800536) ON CONFLICT(id) DO NOTHING;
