INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dd26b031b3f63fc0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_grammar', 'Correct sentence: She go to school everyday', '{"A":"She go to school everyday","B":"She goes to school everyday","C":"She is going to school everyday","D":"She gone to school everyday"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Correct sentence: She goes to school every day.“She” is a third-person singular subject (he, she, it).In Simple Present Tense, verbs with third-person singular take “-s” or “-es.”go → goeseat → eatsplay → playsLast updated by NA on 24-April-2026', 0, 0, 0, 1790961800930) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_89351501164a600f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_grammar', 'Find out correct sentence: She is better known by her father''s family name., She is better known to her father''s family name., She is better known for her father''s family name., She is better known with her father''s family name.', '{"A":"She is better known by her father''s family name.","B":"She is better known to her father''s family name.","C":"She is better known for her father''s family name.","D":"She is better known with her father''s family name."}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She is better known by her father''s family name.“Known by” is the correct prepositional phrase used to show identity or recognition.It indicates the name through which a person is recognized or addressed.Last verified on 26-05-2026', 0, 0, 0, 1790961800930) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_96e3bf2404447e28', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_grammar', 'Find out correct sentence: She raises children., She rises children., She rise children., She raises childrens.', '{"A":"She raises children.","B":"She rises children.","C":"She rise children.","D":"She raises childrens."}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She raises children.“Raises” is correct because it means to bring up or take care of children.The subject “She” requires the verb in third person singular form (raises).“Children” is already plural, so no “s” is added.Last verified on 26-05-2026', 0, 0, 0, 1790961800930) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2ef33f5c46ae6998', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_grammar', 'Choose one of correct sentence He is coward boy?', '{"A":"He is a cowardly boy","B":"He is cowarding boy","C":"He is cowardly boys","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He is a cowardly boyوہ بزدل لڑکا ہے"Cowardly" is the correct adjective to describe someone lacking courage. - "Coward" is a noun, so "cowardly" is used as an adjective before "boy."*************VU FIA SUB INSPECTOR PAPER 30-1-2021', 0, 0, 0, 1790961800930) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9690976eb2107c6d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_grammar', 'Choose grammatically correct sentence: No I have never been to a rock concert ,No I have never been to a concert', '{"A":"No I have never been to a rock concert","B":"No I have never been to a  concert","C":"No I have been to a rock concert","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation no i have never been to a rock concertنہیں میں کبھی کسی راک کنسرٹ میں نہیں گیا ہوں۔******RY 23-12-2022', 0, 0, 0, 1790961800930) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_25f926bab8b573e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_grammar', 'Identify correct sentence?The library lost its all book , The library lost its all books ,The library lost all its books', '{"A":"The library lost its all book","B":"The library lost its all books","C":"The library lost all its books","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Lost" is the correct past tense of "lose".The correct word order is "all its books", not "its all books".', 0, 0, 0, 1790961800930) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_eng_general', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'General English', 'top_english', 2233, 1790961800983) ON CONFLICT(id) DO UPDATE SET total_mcqs = 2233;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_113632fde51f9aad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Select the uncountable noun: Rain, Pencil, Ball, Chair', '{"A":"Rain","B":"Pencil","C":"Chair","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Rain" is an uncountable noun because it refers to a mass or substance that cannot be counted individually.Unlike pencil, ball, and chair (which are countable).Rain is measured in volume, not number.Last verified on 27-09-2026', 0, 0, 0, 1790961801073) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b478b55153377af2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Everyone could see how unhappy she was. (In the above sentence, which one is an example of Indefinite Pronoun).', '{"A":"See","B":"How","C":"She","D":"Everyone"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Everyone is an indefinite pronoun because it refers to people in general without naming specific individuals.She is a personal pronoun referring to a specific person.Words like everyone, anybody, someone, somebody are examples of indefinite pronouns.Last verified on 27-09-2026', 0, 0, 0, 1790961801073) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b32b8b3f653ec5e5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Select a possessive pronoun in the following sentence: I will show you to your room, ours is next door.', '{"A":"Ours","B":"Will","C":"Your","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Ours" is the possessive pronoun showing ownership of the room.It refers to "our room" without repeating the noun.Last verified on 27-09-2026', 0, 0, 0, 1790961801073) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eeb5157197358bf4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is good ______ mathematics.', '{"A":"In","B":"At","C":"On","D":"Into"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He is good at mathematics.وہ ریاضی میں اچھا ہے۔The adjective “good” commonly takes the preposition “at.”Good at is used to show skill or ability in a subject or activity.Last verified on 11-05-2026', 0, 0, 0, 1790961801073) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e3e7c28a43f0dd84', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Take this book ____ the table.', '{"A":"Into","B":"Off","C":"Of","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Off the table" means to remove something from the surface of the table.The correct phrase is: Take this book off the table.Last verified on 27-09-2026', 0, 0, 0, 1790961801073) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_466b37cb991d4c37', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is the purpose of including counterarguments in a persuasive essay?', '{"A":"To make the essay longer","B":"To weaken your own argument","C":"To summarize and repute opposing positions","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Counterarguments present the opposing views or arguments on an issue.They allow the writer to address and refute opposing positions.This makes the main argument more balanced and convincing.Last verified on 27-09-2026', 0, 0, 0, 1790961801073) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7cc731165839fe58', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which of the following is Model verb?Can, Could ,Be', '{"A":"Can","B":"Could","C":"Be","D":"Both A and B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Modal verbs are auxiliary verbs that express necessity, possibility, permission, or ability.These verbs are used to indicate various shades of meaning related to the main verb.Examples of modal verbs include:Can CouldMay MightMustShall ShouldWill Would', 0, 0, 0, 1790961801073) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c89312930e3704b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which one of the following is neuter?', '{"A":"Mother","B":"Wife","C":"Knife","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Neuter gender refers to non-living things; knife is an object, so it is neuter.Mother and wife are feminine (living beings).', 0, 0, 0, 1790961801073) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f7459a2ac51fb888', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which one is correct? They were at a party?, They are at a party?, They was at a party? None', '{"A":"They were at a party?","B":"They are at a party?","C":"They was at a party?","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation About a specific place where we are the preposition ''at '' will be used in the sentence. Therefore, out of the options given, the correct option will be '' at the party ''.', 0, 0, 0, 1790961801132) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8710b5f0270c803b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which of the following sentences contains an error in capitalization? My favorite book is To Kill a Mockingbird., The school is located in downtown new york city., I love listening to classical music, especially Mozart., They went to the beach and played volleyball.', '{"A":"My favorite book is To Kill a Mockingbird.","B":"The school is located in downtown new york city.","C":"I love listening to classical music, especially Mozart.","D":"They went to the beach and played volleyball."}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The school is located in downtown New York City.New York City is a proper noun, so each main word should be capitalized.The original sentence incorrectly wrote “new york city.”Last verified on 15-09-2026', 0, 0, 0, 1790961801132) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d8c1d5083cb53e7c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She is senior _______ me.', '{"A":"Than","B":"To","C":"Then","D":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "She is senior to me." This phrase correctly uses "to" to compare seniority or rank between individuals.We use “senior to”, not “senior than.”', 0, 0, 0, 1790961801132) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9e3ad6cf2e0bbf28', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Neither the principal nor the teachers ______ present.', '{"A":"At","B":"Was","C":"Were","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct sentence is "Neither the principal nor the teachers were present."With neither...nor, the verb agrees with the subject nearest to it.The nearest subject is teachers, which is plural.Therefore, the correct verb is were.This follows the rule of proximity.Last verified on 18-07-2026', 0, 0, 0, 1790961801132) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_25e1fbdea6fb327d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She agrees _______ my proposal.', '{"A":"With","B":"To","C":"For","D":"About"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use agree to when talking about a proposal, plan, suggestion, request, or offer.Therefore, the correct sentence is: "She agrees to my proposal.""Agree to" means to accept or approve something.Last verified on 11-07-2026', 0, 0, 0, 1790961801132) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6dbd4fc429ab75c2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He said, ''I am reading a book.'' (Indirect)', '{"A":"He says he was reading a book","B":"He said he is reading a book","C":"He said he was reading a book","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He said he was reading a book.• Direct Speech (Present Continuous “am reading”) changes into Past Continuous in Indirect Speech when reporting verb is in past tense.• “am reading” → “was reading”Last verified on 09-05-2026', 0, 0, 0, 1790961801132) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_38ae108469ba0774', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He has been working here _______ 2015.', '{"A":"For","B":"From","C":"Since","D":"Off"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The preposition “Since” denotes point of time also reason.He has been working here since 2015.The preposition “For” denotes period of time.She has worked here for 7 years.Last verified on 07-09-2026', 0, 0, 0, 1790961801132) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_653b3393fd0eeb60', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is the meaning of Haves and have-nots?', '{"A":"Rich and poor people","B":"Wise and foolish people","C":"Strong and weak people","D":"Young and old people"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Haves and have-nots refers to two distinct groups of people in society: the wealthy ("the haves") and the poor ("the have-nots")امیر اور غریب یا دار و نادار ہے', 0, 0, 0, 1790961801132) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7ca7846367aba0c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A Gordian Knot means :', '{"A":"To solve a very complex or difficult","B":"A piece of work","C":"An easy task","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Gordian knot means a very difficult, complicated, or seemingly impossible problem.کسی بہت پیچیدہ یا مشکل مسئلے کو فوری اور دلیری سے حل کرنا', 0, 0, 0, 1790961801212) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fa0b6e5114fb8fcb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'One word for "A hater/hating of knowledge and learning" is?', '{"A":"Misologist","B":"Bibliophile","C":"Misogynist","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A hater of knowledge and learning is called a misologist.It comes from the Greek words "miso-" (hatred) and "logos" (reasoning or knowledge).Additional information:A misogynist hates or distrusts womenA bibliophile loves or collects books.', 0, 0, 0, 1790961801212) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7d4dee606b8985fc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Translate into English: کسان چار روز سے ہل چلا رہا ہوگا', '{"A":"The farmer will have been ploughing since four days","B":"The farmer will have been plough since four days","C":"The farmer will have been ploughing for four days","D":"The farmer will had been ploughing since four days"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The farmer will have been ploughing for four days.The sentence is in the Future Perfect Continuous Tense.Structure: Subject + will have been + verb-ing + duration.“For” is used with a period/duration of time, such as four days, two hours, five years.“Since” is used with a specific starting point, such as Monday, 2020, 8 o’clock.Last verified on 09-09-2026', 0, 0, 0, 1790961801212) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_51681af39bf0268c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Even though the auditors _____ the accountant, his reputation was _____ by the allegations of fraud.', '{"A":"Indicted - Blemished","B":"Betrayed - Ruined","C":"Cleared - Condoned","D":"Exonerated - Tarnished"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence should read: "Even though the auditors exonerated the accountant, his reputation was tarnished by the allegations of fraud."This means that although the accountant was found not guilty (exonerated), the accusations of fraud still damaged his reputation (tarnished).Last verified on 08-09-2026', 0, 0, 0, 1790961801212) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_11e035a526ff1744', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'If I ___ rich, I would travel the world.', '{"A":"Was","B":"Were","C":"Have","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The subjunctive mood uses "were" for hypothetical situations, even with singular subjects.So, "If I were rich" is grammatically correct.Last verified on 07-09-2026', 0, 0, 0, 1790961801212) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f14d98023d068efc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The Synonyms of Indubitably is?', '{"A":"Undoubtedly","B":"Controversial","C":"Doubtful","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Indubitably means without doubt or uncertainty.Undoubtedly has the same meaning: certainly / unquestionablyIndubitably means شک یا غیر یقینی کے بغیرUndoubtedly means یقینی طور پر / بلا شبہLast verified on 06-09-2026', 0, 0, 0, 1790961801212) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4851e02d56e4fae0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He was afraid ___ his death?', '{"A":"By","B":"To","C":"From","D":"Of"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He was afraid of his death.Use of after the adjective afraid when you talk about a fear of a specific thing, person, or conceptStructure: Subject + auxiliary/linking verb + afraid of + noun/pronoun.Last updated by NS on 5-09-2026', 0, 0, 0, 1790961801212) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f13534486bac91b1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I prefer tea ____ coffee.', '{"A":"To","B":"For","C":"From","D":"With"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I prefer tea to coffeeUse "to" after the word "prefer" when you compare two things.We use "prefer + noun + to + noun" Last updated by NS on 5-09-2026', 0, 0, 0, 1790961801212) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8e109169968d0d68', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The book is lying _______ the table.', '{"A":"On","B":"Upon","C":"In","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The book is lying on the table.We use the preposition "on" when an object is resting on top of a flat surface, such as a table, desk, or shelf.Last updated by NA on 5-09-2026', 0, 0, 0, 1790961801301) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_afc69e51ea56a363', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She is afraid _____ the dog/darkness.', '{"A":"Off","B":"Of","C":"To","D":"From"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prepositions are used to connect words and show relationships.The phrase “afraid” is commonly used to show fear.The correct preposition after “afraid” is “of”.It is used to express fear of a person, thing, or situation.Last verified on 04-05-2026', 0, 0, 0, 1790961801301) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2b02f21d70ae3222', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Complete the sentence: Scarcely had it stopped raining _____ the sun came out.', '{"A":"While","B":"When","C":"But","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Scarcely…when” is a fixed pair used for quick succession of events.It shows one action immediately follows another.Correct structure: Scarcely had it stopped raining when the sun came out.Last verified on 21-05-2026', 0, 0, 0, 1790961801301) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0449ebe249fcd630', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Everything _____ to be in its place or Hyder gets very upset.', '{"A":"Will be needing","B":"Need","C":"Needs","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Everything needs to be in its place or Hyder gets very upset."سب کچھ اپنی جگہ پر ہونا چاہیے ورنہ حیدر بہت پریشان ہو جاتا ہے۔"Needs" is used here to indicate a requirement or necessity for everything to be properly arranged.Last verified on 25-08-2026', 0, 0, 0, 1790961801301) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d3c72aab01d4bb10', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'All communication with outside world has been cut _______?', '{"A":"Out","B":"Away","C":"Off","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrasal verb is “cut off”, meaning to stop or disconnect communication.“Cut off” is commonly used when communication or contact is completely stopped.Therefore, the correct sentence is: “All communication with the outside world has been cut off.”Last verified on 25-08-2026', 0, 0, 0, 1790961801301) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_59443b6baa024291', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who says that they should go to cellar?', '{"A":"Ellen","B":"Mrs. Spiedings","C":"Mr. Spiedings","D":"John"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mr. Spiedings suggests that they should go to the cellar.The cellar is mentioned as a place where they can go for safety.Last verified on 23-08-2026', 0, 0, 0, 1790961801301) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9fb8e468a76a9b07', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the word most similar EXPRESS?', '{"A":"Hide","B":"Describe","C":"Secret","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Express and Describe means بیان کرناLast verified on 22-08-2026', 0, 0, 0, 1790961801301) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4fb7c13af95d10e6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which punctuation mark is used to indicated the end of declarative sentence?', '{"A":"Question mark (?)","B":"Exclamation mark (!)","C":"Full stop (.)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A declarative sentence makes a statement and normally ends with a full stop (.).A full stop is also called a period in American English.It indicates that the statement is complete.Additional information:A question mark (?) is used at the end of an interrogative sentence.An exclamation mark (!) expresses strong emotion or emphasis.Last verified on 12-08-2026', 0, 0, 0, 1790961801301) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b9a84f2ca15773f6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Every worker _____ on duty.', '{"A":"Were","B":"Are","C":"Was","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct sentence is: “Every worker was on duty.”Every takes a singular noun and singular verb.Last verified on 08-08-2026', 0, 0, 0, 1790961801373) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_82d4c31faf9301c3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'To poke one''s nose into means _____?', '{"A":"To bury something","B":"To get involve in","C":"To take interest in other affairs","D":"Both B and C"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The idiom "to poke one''s nose into" means to interfere or involve oneself in someone else''s matters without invitation.It often in an intrusive way.Last verified on 01-04-2026', 0, 0, 0, 1790961801373) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4eeac38c91cc447d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_____ Man is mortal.', '{"A":"A","B":"An","C":"The","D":"No article required"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Man is mortal means انسان فانی ہےUniversal Truth doesn''t require article.', 0, 0, 0, 1790961801373) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_62d091aa05b4af23', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is a person called who speaks many languages?', '{"A":"Monolingual","B":"Bilingual","C":"Polyglot","D":"Linguist"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A polyglot is a person who can speak many languages, usually more than two.The word comes from the Greek words poly (many) and glotta (language).Additional information:Monolingual – Speaks 1 languageBilingual – Speaks 2 languagesTrilingual – Speaks 3 languagesMultilingual – Speaks more than 2 languagesLast verified on 20-07-2026', 0, 0, 0, 1790961801373) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8e2f5447a6c69151', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'His application for a visa was turned ______ by the consulate.', '{"A":"Down","B":"In","C":"Beyond","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrasal verb "turned down" means to refuse or reject something. In this sentence, the application for a visa was refused by the consulate. Last verified on 28-07-2026', 0, 0, 0, 1790961801373) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5a3f84124964e36e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'If he works hard, he _______ the examination.', '{"A":"Will pass","B":"Can pass","C":"Would have passed","D":"Would pass"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If he works hard, he will pass the examination.This is a First Conditional sentence: If + present simple, will + base verb."Will pass" expresses a likely future result if the condition is fulfilled.Last verified on 28-07-2026', 0, 0, 0, 1790961801373) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_204ddfcb1d1f50fe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The word “Kindness” is an example of?', '{"A":"Countable Noun","B":"Uncountable Noun","C":"Abstract Noun","D":"Material Noun"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Kindness" is an Abstract Noun because it names a quality or feeling that cannot be seen or touched.Abstract nouns refer to qualities, ideas, emotions, or states.Examples of Adjective → Abstract Noun:Kind → KindnessLazy → LazinessCruel → CrueltyWise → WisdomBrave → BraveryLast verified on 23-05-2026', 0, 0, 0, 1790961801373) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2332268e4f1d6320', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She ran quickly to catch the bus. What part of speech is the word ''Quickly''?', '{"A":"Adverb","B":"Verb","C":"Noun","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Quickly describes how she ran, modifying the verb "ran", which makes it an adverb.Adverbs often describe manner, time, place, or degree.Last verified on 22-07-2026', 0, 0, 0, 1790961801373) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ce8054b5fad4c1b4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It was kind _____ you to help.', '{"A":"Of","B":"To","C":"About","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It was kind of you to help.آپ کی مدد کرنا بہت مہربانی تھی۔"Of" is used with adjectives describing someone''s behavior.We use kind of + person to praise someone''s action.Last update 0n 21-07-2026 by NA', 0, 0, 0, 1790961801459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3ee7f42832604cd9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Amicus Curiae means ____?', '{"A":"American citizen","B":"Friend of the court","C":"An amusing person","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Amicus Curiae literally translated from Latin, is "friend of the court."It is plural is "amici curiae."Generally, it refers to a person or group who is not a party to an action but has a strong interest in the matter.Last update 0n 21-07-2026 by NA', 0, 0, 0, 1790961801459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1ebff45dc860f73b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What does To be in two minds mean?', '{"A":"To be unable to decide about some thing","B":"To be able to decide about some things","C":"Both of them","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Idiom: To be in two mindsMeaning: To be unable to decide between two choices.Urdu Meaning: دو رائے میں ہونا / فیصلہ نہ کر پاناLast update 0n 21-07-2026 by NA', 0, 0, 0, 1790961801459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_898cc60e994db47b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Court : Judge :: ___?', '{"A":"Hospital : Surgeon","B":"School : Doctor","C":"Market : Teacher","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A judge works in a court, similarly a surgeon works in a hospital.The analogy shows a professional associated with their workplace.Last verified on 20-07-2026', 0, 0, 0, 1790961801459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2a2856bb0b74b14a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A political system governed by wealthy people is known as ______?', '{"A":"Oligarchy","B":"Plutocracy","C":"Aristocracy","D":"Pantisocracy"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Plutocracy is a system of government in which wealthy people hold power or influence.The word comes from the Greek "Ploutos" (wealth) and "Kratos" (power/rule).Additional information:Oligarchy – Rule by a small group of peopleAristocracy – Rule by the noble or privileged classDemocracy – Rule by the peoplePantisocracy – An ideal system in which everyone shares equal governing powerLast verified on 20-07-2026', 0, 0, 0, 1790961801459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0836d13d4fda1df0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I do my work _____ carefully to make mistakes.', '{"A":"So","B":"Very","C":"Too","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Too...to means more than necessary, making something impossible.Correct expression: too + adverb + to + verb.Example: "I do my work too carefully to make mistakes." (I am so careful that I do not make mistakes.)Last verified on 19-07-2026', 0, 0, 0, 1790961801459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_691abaaea88c91fc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is very good _______ making stories.', '{"A":"On","B":"At","C":"In","D":"Towards"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "good at" is used to indicate skill or proficiency in a particular activity.So "He is very good at making stories" is the correct usage.وہ کہانیاں بنانے میں بہت ماہر ہے۔Last verified on 19-07-2026', 0, 0, 0, 1790961801459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_515f84621a3d1f21', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is blind ______ one eye.', '{"A":"In","B":"Of","C":"To","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct expression is "blind in one eye."Use in to describe blindness affecting a particular eye.Correct sentence: "He is blind in one eye."Examples: The old man is blind in one eye. The boy is blind in one eye.Last verified on 19-07-2026', 0, 0, 0, 1790961801459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_be97e00f839dcc59', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Sara shows great ability ________ Physics.', '{"A":"In","B":"At","C":"On","D":"About"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Correct sentence: "Sara shows great ability in Physics."The correct expression is ability in a subject or field.Last verified on 19-07-2026', 0, 0, 0, 1790961801518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8d0c27f5ff1c6e90', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You _____ very clear on the topic.', '{"A":"Consider","B":"Sound","C":"Express","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Correct sentence: "You sound very clear on the topic."آپ موضوع پر بہت واضح ہیں۔Sound means to seem or appear.Last verified on 19-07-2026', 0, 0, 0, 1790961801518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_13c67a4041191839', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Most of the guests arrived ______ car.', '{"A":"With","B":"By","C":"From","D":"In"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Correct sentence: "Most of the guests arrived by car."Use by with a general means of transport: by car, by bus, by train.Use in only when there is an article or possessive: in a car, in the car, in their car.Last verified on 19-07-2026', 0, 0, 0, 1790961801518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8553f5af7df3a576', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The girl bought a "beautiful" doll from the shop. The word beautiful is?', '{"A":"Adverb","B":"Pronoun","C":"Adjective","D":"Preposition"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the sentence "The girl bought a ''beautiful'' doll from the shop," the word "beautiful" is an adjective.Adjectives modify nouns or pronouns to describe or specify their qualities.Last verified on 06-05-2026', 0, 0, 0, 1790961801518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_97c41bd18de67ad8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The student said, "sir, I am not guilty ".', '{"A":"The student said with respect that he was not guilty","B":"The student pleaded that he was not guilty","C":"The student pleaded with respect that he was not guilty","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Correct: The student pleaded that he was not guilty.طالب علم نے کہا (اپنا دفاع کرتے ہوئے) کہ وہ قصوروار نہیں تھا۔Said + denial/defense → Pleaded thatRemove inverted commas.Present continuous tense chance into past continuous."Sir" is omitted in indirect speech."I" → "he" and "am" → "was"."With respect" is incorrect here.Last updated 18-07-2026 by NA', 0, 0, 0, 1790961801518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ed8583c88aaadba4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A white elephant means something ___?', '{"A":"Very beautiful","B":"Useless and costly","C":"Looks ugly","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A "white elephant" is something that is expensive to keep but has little or no practical use.It refers to a possession or project that costs a lot but provides little benefit.It often describes unprofitable buildings, projects, or assets.Last verified on 18-07-2026', 0, 0, 0, 1790961801518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e3e9a90fb24e3347', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Team, Crew and Family are ______?', '{"A":"Proper nouns","B":"Common nouns","C":"Collective nouns","D":"Material nouns"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Team, Crew, and Family are Collective Nouns because they refer to a group of people as a single unit.A collective noun names a collection of persons, animals, or things.Last verified on 18-07-2026', 0, 0, 0, 1790961801518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_071cf78fbab92bc2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Identify the word with a diphthong: Toil, Cut, Lip, Hat', '{"A":"Toil","B":"Cut","C":"Lip","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A diphthong is a complex vowel sound that begins with one vowel and glides into another within the same syllable."Toil" contains the diphthong /ɔɪ/ (as in "oil").Last verified on 18-07-2026', 0, 0, 0, 1790961801518) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_285fafabe7f4a2cc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Before going soldiers blew _____ the bridge.', '{"A":"Onto","B":"Away","C":"Up","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrasal verb is "blew up", which means "to destroy by explosion."The sentence becomes: "Before going, soldiers blew up the bridge.""Blow up" is commonly used for destroying bridges, buildings, or vehicles with explosives."Blew" is the past tense of blow.Last verified on 18-07-2026', 0, 0, 0, 1790961801582) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b4347fb4817189b1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The “greeting” which begins the letter is known as?', '{"A":"Conclusion","B":"Signature","C":"Heading","D":"Salutation"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The term "salutation" refers to the greeting at the beginning of a letter.Such as "Dear Sir/Madam."Last verified on 18-07-2026', 0, 0, 0, 1790961801582) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0c1af44a3d28e54f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is angry _____ me.', '{"A":"With","B":"By","C":"To","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Angry with" is the correct preposition when referring to a person."Angry at" is used for situations or things.Last verified on 16-07-2026', 0, 0, 0, 1790961801582) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7cf5e11f0147d55b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Identify the proper noun: Let''s go to Malaysia.', '{"A":"To","B":"Go","C":"Malaysia","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Proper nouns are specific names of people, places, or organizations."Malaysia" is the name of a country, making it a proper noun.Last verified on 16-07-2026', 0, 0, 0, 1790961801582) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1866174849c9fe7b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is the phrasal meaning of “Call it a day”?', '{"A":"To stop because one does not want to do any more / End work","B":"To stop doing something that is annoying","C":"To get rid of something that is harmful","D":"To stop and finish the whole matter"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Call it a day” means to stop working for the rest of the day.It is used when someone finishes their work or decides to rest.Example: We are tired, let’s call it a day.Last verified on 14-05-2026', 0, 0, 0, 1790961801582) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3d7c839a214c40f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is interested _____ reading books.', '{"A":"At","B":"On","C":"In","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct preposition with “interested” is in.So, the correct sentence is: He is interested in reading books.Last verified on 05-05-2026', 0, 0, 0, 1790961801582) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3651865c26c5ce3c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The committee __________ its report.', '{"A":"Has completed","B":"Have completed","C":"Had completed","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Meaning: The committee has finished its report.Committee is treated as a singular collective noun, so it takes has.Has completed is the correct present perfect tense.Last verified on 07-07-2026', 0, 0, 0, 1790961801582) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_328270b3b6b99bf7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'PRUDENT can be substituted with ______?', '{"A":"Wise","B":"Careless","C":"Foolish","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Prudent" means showing good judgment, caution, or wisdom."Wise" is a synonym, as it refers to being thoughtful and careful in decision-making.Prudent means سمجھداریWise means عقلمندLast verified on 01-07-2026', 0, 0, 0, 1790961801582) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_87e1122867e0fee9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Where there is a will, there is a _____?', '{"A":"Plan","B":"Path","C":"Solution","D":"Way"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Where there is a will, there is a way."This proverb means that determination and perseverance help people overcome obstacles and achieve success.A strong will motivates a person to find solutions to problems.It encourages hard work, confidence, and persistence.It teaches that nothing is impossible with firm determination.Last verified on 07-07-2026', 0, 0, 0, 1790961801663) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9be973f27e905f2d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She is married _______ business.', '{"A":"To","B":"With","C":"About","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Married to” is the correct standard English structure.It shows a direct relationship between the person and spouse.Last verified on 04-06-2026', 0, 0, 0, 1790961801663) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_36a2d1c77ba5e079', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Everyone was drowned. Here ''everyone'' is?', '{"A":"Interrogative pronoun","B":"Indefinite pronoun","C":"Demonstrative pronoun","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Everyone" is an indefinite pronoun as it refers to a non-specific group of people.It does not point to any particular individual but refers collectively to all people.Last verified on 03-04-2026', 0, 0, 0, 1790961801663) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7abac0a216ed17b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Most of the guests arrived ______ buses.', '{"A":"With","B":"By","C":"From","D":"In"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation By is used to show the means of transport (by bus, by train, by car).The correct sentence is: "Most of the guests arrived by buses."Last verified on 03-07-2026', 0, 0, 0, 1790961801663) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b9dbc119fb6f9891', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '"And music singing in the hills". Identify the figurative device in the line?', '{"A":"Metaphor","B":"Personification","C":"Alliteration","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Personification gives human qualities to non-human things.In the given line, "music singing" attributes a human action (singing) to music, making it personification.Last verified on 02-07-2026', 0, 0, 0, 1790961801663) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1e76f5f0e5a1cf7b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Each of the men received a reward. Here ''each'' is?', '{"A":"Possessive pronoun","B":"Indefinite pronoun","C":"Personal pronoun","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Each refers to individual members of a group without specifying them, making it an indefinite pronoun.It is used to emphasize every single person in the group ("each of the men").Last verified on 02-07-2026', 0, 0, 0, 1790961801663) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4e2af9961cc046e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the error in the sentence: They goes to same school', '{"A":"They","B":"Goes","C":"Same","D":"To"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "They go to the same school.""They" is a plural subject, so the correct verb form is "go", not "goes" (which is used with singular subjects like "he," "she," or "it").Additionally, "the" is missing before "same school."Last verified on 02-07-2026', 0, 0, 0, 1790961801663) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8d9f79c6b017c677', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He said, ''I was busy.'' (Indirect)', '{"A":"He says he was busy","B":"He said he is busy","C":"He said he was busy","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In indirect speech, past simple “was” usually remains “was”.Reporting verb “said” does not change in this case.So the correct conversion is: He said he was busy.Last verified on 15-05-2026', 0, 0, 0, 1790961801663) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_49678336bf063683', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We arrived ________ the station an hour late.', '{"A":"In","B":"On","C":"At","D":"For"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The preposition "at" is used for specific places or points, like stations or buildings."Arrived at" is the correct collocation for locations (e.g., at the airport, at school).Last verified on 02-07-2026', 0, 0, 0, 1790961801733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8b6c16801fefce74', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Mr. Ahmed is the black sheep of our family. Here BLACK SHEEP means?', '{"A":"Black in colour","B":"Clever","C":"Bad in nature","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Black sheep means a person who is different from or disliked by the rest of a group or family.It usually refers to someone with bad habits or a bad reputation.In the sentence, Mr. Ahmed is considered the unusual or disapproved member of the family.Last verified on 01-07-2026', 0, 0, 0, 1790961801733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bfa15114d271f333', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A burnt child ________ fire.', '{"A":"Avoids","B":"Dreads","C":"Ignores","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dreads means to fear something greatly.The proverb means a person who has suffered from something becomes very afraid of it in the future.Example: A child who was burned by fire will always fear fire.Last verified on 24-06-2026', 0, 0, 0, 1790961801733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c5872667517b6607', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A drowning man catches _______ a straw.', '{"A":"Up","B":"At","C":"On","D":"Over"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct idiom is “A drowning man catches at a straw.”It means a person in danger tries any possible small hope for survival.A drowning man catches at a straw means ڈوبتے کو تنکے کا سہارا۔Last verified on 23-06-2026', 0, 0, 0, 1790961801733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ce7eaf4f2bd533c3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The master was annoyed _____ servant.', '{"A":"With","B":"For","C":"On","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct preposition with “annoyed” is “with” when showing anger toward someone.So, the correct sentence is: The master was annoyed with the servant.Last verified on 22-06-2026', 0, 0, 0, 1790961801733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f50208a7e3bab108', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The continued to work in the field?', '{"A":"Even through it rained heavily","B":"Even through there is heavy rain","C":"In spite the heavy rains","D":"Although heavily rains"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence needs a clause showing contrast between action and rain.Correct structure is: Even though + past simple clause.', 0, 0, 0, 1790961801733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c8d67650c105c93c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The speaker did not properly space out his speech, but went on _____ one point only.', '{"A":"Stressing","B":"Avoiding","C":"Devoting","D":"Decrying"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase “went on ___ one point only” means repeatedly focusing on that point.“Stressing” fits because it means emphasizing a single idea continuously.Last verified on 20-06-2026', 0, 0, 0, 1790961801733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_46dc3dd7b0d98ae4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It was unanimously resolved that the parties _____ launching of popular programmes.', '{"A":"Should be unitedly undertaken","B":"Should be unitedly undertake","C":"Should unitedly undertake","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation After “it was unanimously resolved that…”, we use “should + base form of verb.”So the correct structure is: should undertake.“Unitedly” is an adverb and correctly placed before the verb.Last verified on 20-06-2026', 0, 0, 0, 1790961801733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_85f194ed0a008b54', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Sun _____ in the east.', '{"A":"Rises","B":"Rise","C":"Rised","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The subject “Sun” is singular, so we use the singular verb rises.This is a general truth, always stated in the present tense.Last verified on 17-06-2026', 0, 0, 0, 1790961801814) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_629980601cb4d92e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He died _____ cholera.', '{"A":"On","B":"For","C":"Of","D":"With"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use preposition of if a person dies from an illness.Die of means کسی بیماری سے مرناHe died of cholera.Last verified on 17-06-2026', 0, 0, 0, 1790961801814) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c7ef08eede3933e8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'If someone is "showing the white feather," they are?', '{"A":"To show signs of cowardice / Showing cowardice","B":"Pretending to be innocent","C":"Signaling surrender in battle","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “To show the white feather” means to behave in a cowardly way.It originally comes from the idea that a white feather symbolized lack of courage in fighting.It is used when someone avoids danger due to fear.Last verified on 14-06-2026', 0, 0, 0, 1790961801814) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_529d28f0da8ddb85', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I _____  living in this house since 1970.', '{"A":"Has been","B":"Have been","C":"Was","D":"Will be"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Correct sentence: “I have been living in this house since 1970.”“Since 1970” shows an action continuing from past to present.The correct tense is Present Perfect Continuous/Present Perfect structure (have been).Last verified on 11-06-2026', 0, 0, 0, 1790961801814) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ac47afed747b0969', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Analogy: Book : Read :: Pen : ?', '{"A":"Write","B":"Ink","C":"Paper","D":"Draw"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A book is used to read.Similarly, a pen is used to write.So the relationship is object : its function.Last verified on 11-06-2026', 0, 0, 0, 1790961801814) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9f28af8ade994b53', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He confided ______ me.', '{"A":"Of","B":"In","C":"From","D":"About"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrase is “confide in someone”.It means to share private or secret information with someone you trust.Last verified on 10-06-2026', 0, 0, 0, 1790961801814) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b4258185d24c90b1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I have been studying _____ 3 hours.', '{"A":"From","B":"For","C":"Since","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Correct sentence: "I have been studying for 3 hours."For is used to show a duration of time (e.g., for 3 hours, for two days).Since is used with a starting point in time (e.g., since 9 a.m., since Monday).Last verified on 09-06-2026', 0, 0, 0, 1790961801814) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4456afc7061943f5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'In the sentence "He runs fast", The word Fast is a?', '{"A":"Noun","B":"Verb","C":"Adverb","D":"Adjective"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Fast” is an adverb in this sentence because it describes how he runs.It modifies the verb “runs.”Adverbs explain manner, place, time, or degree.Here it shows the manner of action (how he runs).Last verified on 08-06-2026', 0, 0, 0, 1790961801815) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_952caf47e2065dfa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The analogy of: Book is to Reading and Fork is to ______?', '{"A":"Eating","B":"Drawing","C":"Writing","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A book is used for reading.Just as a fork is used for eating.Both objects are tools associated with their respective actions.Last verified on 07-06-2026', 0, 0, 0, 1790961801893) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fd4c8657cb10c864', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is the plural of ''Index''?', '{"A":"Indices","B":"Indexies","C":"Indexis","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Singular noun: Index Plural noun: IndicesIndex means فہرست Indices means فہرست کی جمعLast verified on 06-06-2026', 0, 0, 0, 1790961801893) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6e528190617a341a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The plural form of ''Fish'' is?', '{"A":"Fishes","B":"Fishez","C":"Fish","D":"Both A and C"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The plural of fish is usually fish. However, the plural fishes is also correct It is specifically used when referring to multiple different species or varieties of fish.Last verified on 06-06-2026', 0, 0, 0, 1790961801893) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_85a8e8767dfd93be', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who defined poetry as “Poetry is a spontaneous overflow of powerful feelings”?', '{"A":"Keats","B":"Wordsworth","C":"Coleridge","D":"Shelley"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This famous definition is given by William Wordsworth.He described poetry as a natural expression of strong emotions and feelings.It highlights the Romantic idea that poetry comes from the heart, not just rules or form.Last verified on 06-06-2026', 0, 0, 0, 1790961801893) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_43b75eeb1d0e1a25', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Elegy is a poem that is written about someone''s?', '{"A":"Honor","B":"Death","C":"Heroism","D":"Praise"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Elegy is a poem of mourning.It expresses sadness over death or loss.It may also praise the dead person’s life.Last verified on 23-05-2026', 0, 0, 0, 1790961801893) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9bfb27fdee8b5047', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who is the author of the book/novel  ''Nineteen Eighty Four''?', '{"A":"George Orwell","B":"Emile Zola","C":"Thomas Hardy","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The novel “Nineteen Eighty-Four” (1984) is written by George Orwell.It was published in 1949.It presents a dystopian future under a totalitarian government.The story warns about surveillance, loss of freedom, and state control over truth and society.Last verified on 06-06-2026', 0, 0, 0, 1790961801893) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1a3bf9d1b2668f91', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am worried ____ the exam.', '{"A":"In","B":"About","C":"On","D":"Of"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Worried about” is the correct fixed prepositional phrase.It shows concern for something specific.Last verified on 05-06-2026', 0, 0, 0, 1790961801893) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7fa452cf1d0ac750', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The train went _____ the tunnel.', '{"A":"From","B":"Under","C":"Through","D":"To"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The train went "through" the tunnel.ٹرین سرنگ میں سے گزری۔"Through" is used to indicate movement from one side to the other inside a space, like a tunnel.Last verified on 05-06-2026', 0, 0, 0, 1790961801893) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_67344251f7414986', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What type of word is "because" in the sentence: "She went to the store because she needed groceries"?', '{"A":"Verb","B":"Adjective","C":"Conjunction","D":"Adverb"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Because” joins two clauses: She went to the store + she needed groceries.It shows a reason (cause and effect relationship).So, it is a subordinating conjunction.Last verified on 04-06-2026', 0, 0, 0, 1790961801953) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_48e01653c76bceaf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'When she was in the university, she _______ wake up early in the morning.', '{"A":"Should","B":"Would have","C":"Would","D":"Can"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “When she was in the university” shows a past habit.“Would” is used to describe repeated past actions/habits.So the correct sentence is: She would wake up early in the morning.Last verified on 04-06-2026', 0, 0, 0, 1790961801953) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a5dd08c0b9827bbb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The new findings on the virus caused panic among the scientists and management ______?', '{"A":"Like","B":"Likely","C":"Alike","D":"Dislike"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Alike” means “both” or “in the same way.”It is used when two groups are affected similarly.The sentence shows panic in both scientists and management.Last verified on 04-06-2026', 0, 0, 0, 1790961801953) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0997c90b5a9804c7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'In the test, we will ______ your work and then give you detailed feedback.', '{"A":"Measure","B":"Check","C":"Assess","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Assess” means to evaluate or judge something carefully.In testing, teachers evaluate students’ work.It is the most appropriate word for formal examination feedback.It implies checking quality, performance, or understanding.Last verified on 04-06-2026', 0, 0, 0, 1790961801953) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_72fb1f676bdbad85', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'No one knows what color dinosaurs were ______ no sample of their skin has survived.', '{"A":"Because of","B":"Because that","C":"It is because","D":"Because"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Because of” is used before a noun phrase.The sentence explains the reason for unknown dinosaur color.No skin samples survived, so color cannot be known.Last verified on 04-06-2026', 0, 0, 0, 1790961801953) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f6a835783c79e163', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'There is something wonderful ____ him.', '{"A":"With","B":"To","C":"About","D":"For"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “About” is used to express concerning or relating to someone.The sentence shows admiration or special quality related to a person.“Something wonderful about him” is a correct and natural English structure.Last verified on 04-06-2026', 0, 0, 0, 1790961801953) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_da74970d2249877b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The river flows ______ the bridge.', '{"A":"Under","B":"In","C":"Of","D":"Along"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Under” means below something in position.A river flowing beneath a bridge is expressed as “under the bridge.”Last verified on 04-06-2026', 0, 0, 0, 1790961801953) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9d3e26e9bfe9ce28', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Analogy: _____ : Horse :: Board : Train.', '{"A":"Mount","B":"Ride","C":"Shoe","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The analogy Horse : Ride :: Board : Train makes sense because one rides a horse, just as one boards a train.The relationship involves the action associated with each mode of transport.Last verified on 04-06-2026', 0, 0, 0, 1790961801953) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_91456913cf561c79', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Particular is to Fussy as Meerk is to _____?', '{"A":"Subservient","B":"Independent","C":"Ignorant","D":"Brave"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The relationship between "Particular" and "Fussy" is one of synonym.Similarly, "Meerk" is one analogous should relate to "Subservient".Particular: پوشیدہFussy:ہلچلMeerk: شائستہSubservient: تابعدارLast verified on 04-06-2026', 0, 0, 0, 1790961802031) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ea750cc75c38150a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A library is a place ______?', '{"A":"Where you should study","B":"Where you always go to study","C":"Where readers go to read books and newspaper","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A library is a place where readers go to read books and newspapers.“Where” is a relative adverb used for places.It properly connects “place” with its function.Last verified on 26-05-2026', 0, 0, 0, 1790961802031) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2acdd163d8fe0ffe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Barking dogs _____ bite.', '{"A":"Never","B":"Always","C":"Seldom","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Barking dogs seldom bite.“Seldom” means rarely.It correctly completes the common proverb: barking dogs rarely bite.Last verified on 26-05-2026', 0, 0, 0, 1790961802031) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8fc29ab8a6a6564b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I was sandwiched _______ two fat men on the bus.', '{"A":"By","B":"In","C":"Between","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Between” is used when referring to two people or things.“Sandwiched between” means being tightly placed in the middle of two things.Last verified on 26-05-2026', 0, 0, 0, 1790961802031) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_59b3e60273a0241b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is taller _______ any other boy in the class.', '{"A":"To","B":"Than","C":"By","D":"That"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Than” is used for comparison (taller than, smaller than, faster than).After comparative adjective “taller,” we always use “than.”Last verified on 26-05-2026', 0, 0, 0, 1790961802031) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_70045df84ec55142', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I like this than that. Here ''than'' is?', '{"A":"Conjunction","B":"Pronoun","C":"Verb","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Than" is used to introduce the second element in a comparison.In the sentence, it connects "this" and "that," making it a conjunction.', 0, 0, 0, 1790961802031) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8ca535d64a486f4c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He threw the letter ______ the fire.', '{"A":"To","B":"In","C":"Into","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Correct sentence: “He threw the letter into the fire.”“Into” shows motion from outside to inside.Last verified on 26-05-2026', 0, 0, 0, 1790961802031) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9951defe9015f336', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Error detection: May I know what is your name, please.', '{"A":"What is","B":"May","C":"Please","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Correct form: “May I know what your name is, please?”In indirect questions, we say “what your name is”, not “what is your name”.So the word order in “What is” is wrong in this sentence.Last verified on 26-05-2026', 0, 0, 0, 1790961802031) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7394cbd79dff9f2b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Identify the conjunction: She is poor, yet she is honest.', '{"A":"Poor","B":"Yet","C":"Is","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Yet" is a coordinating conjunction that connects two contrasting ideas (being poor and being honest).It shows a contradiction or unexpected relationship between the two clauses.Last verified on 25-05-2026', 0, 0, 0, 1790961802122) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_37ff7b6c77e73df6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am satisfied _____ his performance.', '{"A":"For","B":"On","C":"By","D":"With"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "I am satisfied with his performance."میں اس کی کارکردگی سے مطمئن ہوں۔The preposition "with" is used to express satisfaction or dissatisfaction about something or someone.Last verified on 24-05-2026', 0, 0, 0, 1790961802122) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e869585efbbb31c4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Identify the conjunction: I like to read books and watch movies.', '{"A":"Like","B":"To","C":"And","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "And" is a conjunction that connects words, phrases, or clauses.In the sentence, "and" connects two activities: "read books" and "watch movies."Last verified on 06-05-2026', 0, 0, 0, 1790961802122) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_64e514a23979918f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She is fond ______ classical music.', '{"A":"By","B":"With","C":"Of","D":"For"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The adjective “fond” is commonly followed by the preposition “of.”“Fond of” means liking something very much.Last verified on 08-05-2026', 0, 0, 0, 1790961802122) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2ef22b01bd53915d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is Auxiliary verb?', '{"A":"A main action verb","B":"A verb that shows tense only","C":"A helping verb used with the main verb to form tense, voice, or mood","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Auxiliary verbs are helping verbs in English grammar.They are used with main verbs to form different tenses and structures.They help show tense, voice, mood, or aspect of a sentence.Common examples include is, am, are, was, have, has, do, will.Last verified on 23-05-2026', 0, 0, 0, 1790961802122) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bb8df9c2f7f5e2bf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The land was divided ______ the two sisters and the two brothers.', '{"A":"Into","B":"Between","C":"Among","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Use "between" when referring to two people or things.Use "among" when referring to more than two.Since the land is divided among four people (two sisters and two brothers).Last verified on 23-05-2026', 0, 0, 0, 1790961802122) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5614f016386e2575', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Identify the gerund: Always inspect the brakes before driving the car.', '{"A":"Spotted","B":"Driving","C":"Always","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A gerund is a verb form that functions as a noun and ends in -ing.In the sentence, "driving" is the gerund as it refers to the action of driving and functions as a noun in the context.Last verified on 08-02-2026', 0, 0, 0, 1790961802122) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d6a169c10c8642cd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'This book is divided _____ three parts.', '{"A":"In","B":"Into","C":"By","D":"With"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This book is divided into three parts.اس کتاب کو تین حصوں میں تقسیم کیا گیا ہے۔The preposition "into" is used to indicate a divisionLast updated question NS on 10 MAY 2026', 0, 0, 0, 1790961802122) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c42c95802dad06f6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What does "to draw the lines" mean?', '{"A":"To decide one''s occupation","B":"To set limits","C":"To prepare for the battle","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The idiom “to draw the lines” means to define limits or boundaries.It is used when setting clear rules or acceptable behavior.It helps distinguish what is allowed and what is not.Commonly used in social, legal, or personal contexts.Last verified on 23-05-2026', 0, 0, 0, 1790961802230) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7a01c961475cd650', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Milton''s Paradise Lost is written in _____?', '{"A":"Free verse","B":"Blank verse","C":"Heroic couplet","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Paradise Lost is written in unrhymed iambic pentameter, which is known as blank verse.This form gives the poem a grand and flowing style, suitable for epic poetry.Last verified on 23-05-2026', 0, 0, 0, 1790961802230) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b3b715ae5ba539cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He said, “I will call you.” Indirect', '{"A":"He said that he would call me.","B":"He told me that he would call me.","C":"He asked me that he would call me.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He said that he would call me.“Will” changes to would in indirect speech.Pronoun “you” changes to "me" (according to listener).“Said” remains “said that” unless object is specified.Last verified on 21-05-2026', 0, 0, 0, 1790961802230) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6e9dfa9e68a7bed9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Obdurate Urdu Meaning?', '{"A":"نرم دل","B":"ضدی","C":"خوش مزاج","D":"ایماندار"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Obdurate means ضد کرنے والاLast updated question NS on 09 MAY 2026', 0, 0, 0, 1790961802230) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c0698c0b47c27760', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He was ignorant ______ the whole situation?', '{"A":"Of","B":"With","C":"By","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He was ignorant of the whole situation.وہ ساری صورتحال سے بے خبر تھا۔It means he was unaware or lacked knowledge about the situation.Last verified on 17-05-2026', 0, 0, 0, 1790961802230) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6c32f849af3fc3f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Honesty is the best policy. In the above sentence, which word is an abstract noun?', '{"A":"Honesty","B":"Best","C":"Policy","D":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An abstract noun is a word that shows an idea, quality, or feeling.In the sentence, Honesty is the abstract noun.It represents a quality (truthfulness).Abstract nouns cannot be seen or touched.Example: Wisdom, Bravery, Cowardice, Death, Anger, Hate, Love and Beauty etc.Last verified on 17-05-2026', 0, 0, 0, 1790961802230) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6b181253a586bcc3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'No, sooner I reached home _______ it started to rain.', '{"A":"Than","B":"Was","C":"Had","D":"Yet"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct structure is “No sooner… than” for immediate sequence of events.It shows that the second action happened immediately after the first.Last verified on 17-05-2026', 0, 0, 0, 1790961802230) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c2c419a67986c5eb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She _____ since morning.', '{"A":"Sleep","B":"Has been sleeping","C":"Sleep","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The action started in the past and is continuing till now, so Present Perfect Continuous Tense is used.Correct sentence: She has been sleeping since morning.It has been raining since morning.Last verified on 17-05-2026', 0, 0, 0, 1790961802230) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_873d941ab01225c3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I was reading a novel when they _______ to see me.', '{"A":"Were coming","B":"Came","C":"Come","D":"Had come"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Was reading” is past continuous, so the second action should be in simple past.“Came” correctly shows a completed action that interrupted the ongoing action.Last verified on 17-05-2026', 0, 0, 0, 1790961802300) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fbdbad0bae2acd06', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He was the ___ thief of all.', '{"A":"Cleverest","B":"Clever","C":"Cleverer","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Cleverest" is the superlative form of "clever," used when comparing more than two things or people.The phrase "of all" indicates a comparison among many, requiring the superlative degree.Last verified on 17-05-2026', 0, 0, 0, 1790961802300) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9f58c4cb65021624', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Three hours will have passed when the bell ______?', '{"A":"Rings","B":"Will be ringing","C":"Will be rung","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When using future perfect tense ("will have passed"), the clause with "when" takes present simple tense — not future.So, the correct sentence is: "Three hours will have passed when the bell rings."Last verified on 17-05-2026', 0, 0, 0, 1790961802300) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0053d685f5285233', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'When I arrived, she ____ for me.', '{"A":"Waits","B":"Had waited","C":"Waited","D":"Was waiting"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When I arrived, she was waiting for me.جب میں پہنچا تو وہ میرا انتظار کر رہی تھی۔The past continuous tense "was waiting" is used to describe an action that was ongoing at a specific time in the past when another action occurred ("I arrived").This tense highlights that she was already in the process of waiting when you arrived.Last verified on 17-05-2026', 0, 0, 0, 1790961802300) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7897e9ec18f31a6a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The pavement thronged with pedestrians. Here ''Pavement'' means?', '{"A":"Footpath","B":"Hotel","C":"Shop","D":"Ground"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pavement means راہ گیروں کے چلنے کیلئے بنائی جانے والی پٹڑیFootpath means راہ گیروں کے چلنے کیلئے بنائی جانے والی پٹڑیLast verified on 17-05-2026', 0, 0, 0, 1790961802300) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fd533feb49bd2e77', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am not accustomed _______ being interrupted.', '{"A":"To","B":"At","C":"For","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase accustomed ended with “To” and is followed by “ing” form of a verb.Accustomed to something means کسی چیز کا عادی ہوناI am not accustomed to being interrupted.Last verified on 12-05-2026', 0, 0, 0, 1790961802300) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cfdedb8741d6dd50', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She has been living here _______ 1999.', '{"A":"For","B":"Since","C":"From","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Since” is used to show the starting point of an action in time.In Present Perfect Continuous tense, “since” is used with a specific year or date.The sentence shows an action continuing from 1999 until now.Last verified on 12-05-2026', 0, 0, 0, 1790961802300) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8fe0b0f1e132cf60', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who is the father of English Poetry?', '{"A":"John Milton","B":"William Wordsworth","C":"Geoffrey Chaucer","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Geoffrey Chaucer is known as the Father of English Poetry.He wrote in Middle English, making literature more accessible to common people.His famous work The Canterbury Tales is a landmark in English literature.Last verified on 16-05-2026', 0, 0, 0, 1790961802300) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fe4d4145bccc1763', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who wrote “Paradise Lost”', '{"A":"John Milton","B":"William Wordsworth","C":"Geoffrey Chaucer","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Paradise Lost was written by John Milton.It is an epic poem about Adam and Eve’s fall from Paradise.It was first published in 1667 in 10 books.The revised edition came in 1674 with 12 books.Last verified on 16-05-2026', 0, 0, 0, 1790961802362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_901dba5a6de35dfa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Thomas Hardy was a ______?', '{"A":"Late Victorian","B":"Mid Victorian","C":"Early Victorian","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Thomas Hardy (1840–1928) was a Late Victorian novelist and poet.His works, like Tess of the d’Urbervilles and Jude the Obscure.He explore themes of fate, society, and human struggle.Last verified on 16-05-2026', 0, 0, 0, 1790961802362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c8c9356f8018f5a0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I insisted _____ going.', '{"A":"On","B":"To","C":"For","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The verb “insist” is commonly followed by the preposition “on.”“Insist on” means to strongly demand or firmly maintain something.Last verified on 08-05-2026', 0, 0, 0, 1790961802362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3ea24d2ee319a3a7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is proud ________ his riches.', '{"A":"In","B":"For","C":"About","D":"Of"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally preposition "of" is used after "proud".Proud itself is an adjective.Rich means امیرRiches means دولتLast verified on 15-05-2026', 0, 0, 0, 1790961802362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1550e9e5fa99924f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is jealous ________ her success.', '{"A":"With","B":"Of","C":"On","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct preposition with “jealous” is “of”.We say “jealous of someone/something” in standard English.Example: He is jealous of her success.Last verified on 15-05-2026', 0, 0, 0, 1790961802362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_98c5af40a79ff0bd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Wisdom and patience were some of his many qualities. Here ''wisdom'' is?', '{"A":"Abstract noun","B":"Proper noun","C":"Concrete noun","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Wisdom" is an abstract noun because it refers to a quality or idea that cannot be seen or touched.It represents a state of mind, not a physical object.Last verified on 15-05-2026', 0, 0, 0, 1790961802362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d91ca54756dc8af7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He succeeded _________ working hard.', '{"A":"Through","B":"By","C":"For","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Correct structure: succeed + by + verb(-ing)Example: He succeeded by working hard.“By” shows the method or way of achieving something.Last verified on 14-05-2026', 0, 0, 0, 1790961802362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0183ea05f45a890e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Identify the conjunction: He ran fast because he was late.', '{"A":"Fast","B":"Because","C":"Was","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A conjunction connects two clauses or ideas; here, "because" links the reason for running fast.It shows cause and effect between "He ran fast" and "he was late."Last verified on 14-05-2026', 0, 0, 0, 1790961802362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a1971da9b2685630', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The students were ______ and the teacher, therefore, did not take the class.', '{"A":"Few","B":"Only few","C":"A less","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Few" is used to indicate a small number of students.It implying that the class was not sufficient for the teacher to proceed.Last verified on 12-05-2026', 0, 0, 0, 1790961802439) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f75b4891e8b7ed32', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Neither Hafsa nor children _______ coming to the party.', '{"A":"Is","B":"Are","C":"Is not","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation With "neither…nor", the verb agrees with the noun or pronoun closest to it.Here, "children" is plural, so the correct verb is are:Neither Hafsa nor children are coming to the party.Last verified on 08-03-2026', 0, 0, 0, 1790961802439) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ffe7ddd0c1437d5a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He arrived _____ time to catch the train.', '{"A":"In","B":"On","C":"At","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrase is “in time”, meaning early enough to do something.“In time to catch the train” means he arrived before the train left.“On time” means exactly at the scheduled time.Last verified on 12-05-2026', 0, 0, 0, 1790961802439) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_433afd31df0bc87a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is proficient ____ mathematics.', '{"A":"In","B":"Of","C":"With","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct preposition with “proficient” is in.“Proficient in” means skilled or expert in a subject.It is commonly used with subjects like mathematics, English, science.Last verified on 27-04-2026', 0, 0, 0, 1790961802439) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ac8f79da0a6b6e70', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Some distinguished teachers sat _____ the committee which recommended expansion higher education.', '{"A":"About","B":"On","C":"Between","D":"In"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use “on the committee” for being a member of a committee.“On” is the correct preposition used with groups, boards, and committees.Example: She serves on the education committee.Last verified on 12-05-2026', 0, 0, 0, 1790961802439) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_98ca4d28e562d0b8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'To have one''s hands full is to be completely _____ or have a difficult task.', '{"A":"Occupied","B":"Accommodated","C":"Employed","D":"Interlocked"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To have one''s hands full is to be completely occupied or have a difficult task.کسی کا ہاتھ بھرا ہونا مکمل طور پر قابض ہونا یا مشکل کام ہے۔It means being fully engaged or busy with work or responsibilities, leaving no time for additional tasks.Last verified on 12-05-2026', 0, 0, 0, 1790961802439) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0dcf3fce873ef911', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Amanah denotes?', '{"A":"Trust","B":"Enmity","C":"Greed","D":"Arrogance"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Amanah means being honest, trustworthy, and responsible in keeping a trust.Trust / امانت داری / دیانت داریLast updated question NS on 09 MAY 2026', 0, 0, 0, 1790961802439) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5959f49cd1a7c7a0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Each of the participants in the conference ______ provided with a digital guidebook.', '{"A":"Have been","B":"Are","C":"Was","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Each of the participants" is singular, so it takes a singular verb."Was provided" correctly matches the singular subject in past tense.Last verified on 12-05-2026', 0, 0, 0, 1790961802439) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4b3fc165dec983af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The principal eagerly looks forward _____ receiving an encouraging response into the matter.', '{"A":"For","B":"From","C":"To","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrase is "looks forward to", which means to anticipate something with pleasure.Example: "She looks forward to meeting you."Last verified on 11-05-2026', 0, 0, 0, 1790961802521) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0c326e47b2601790', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '______ suffer from forgetfulness.', '{"A":"Most very young people","B":"Most very old people","C":"Hardly any old persons","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Forgetfulness is more common among older individuals due to age-related memory changes.Correct sentence: "Most very old people suffer from forgetfulness."Last verified on 10-05-2026', 0, 0, 0, 1790961802521) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ce096ef85db93f74', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'If I ____ you, I would take the offer.', '{"A":"Was","B":"Were","C":"Are","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In conditional sentences (Type 2), we use "were" with if I/he/she/it for unreal or hypothetical situations.So, “If I were you” expresses an imaginary condition — something not real.Last verified on 09-05-2026', 0, 0, 0, 1790961802521) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dbe28b047cc69f97', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Admin is capable ______ doing anything.', '{"A":"Off","B":"With","C":"Of","D":"From"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation • The adjective “capable” always takes the preposition “of.”• Correct sentence: “Admin is capable of doing anything.”Examples:• Capable of solving problems• Capable of teaching students• Capable of managing work• Capable of making decisions• Capable of winning competitionsLast verified on 09-05-2026', 0, 0, 0, 1790961802521) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_303ed2b0bfa4ae98', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I hope you will find "someone" there to help you. The word someone is?', '{"A":"Relative pronoun","B":"Reflexive pronoun","C":"Indefinite pronoun","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Someone" is an indefinite pronoun because it refers to an unspecified person. Indefinite pronouns do not point to a specific noun and include words like someone, anyone, nobody, everybody, etc.Last verified on 09-05-2026', 0, 0, 0, 1790961802521) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_86ec54e250fc6ef9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '"Wow! His brother is back after three years." Here ''Wow!'' is _____?', '{"A":"Interjection","B":"Adjective","C":"Conjunction","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Wow!" expresses a sudden emotion or surprise, which makes it an interjection.Interjections are words used to express strong feelings or reactions, usually followed by an exclamation mark.Last verified on 19-04-2026', 0, 0, 0, 1790961802521) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_264f7d0147c563da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She is totally dependent ______ her parents.', '{"A":"Over","B":"On","C":"In","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrase is "dependent on", meaning relying for support or help.It means she relies completely on her parents for help or needs.Last verified on 05-05-2026', 0, 0, 0, 1790961802521) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_08bd7d81f812c22b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Sara said ,"I am happy".', '{"A":"Sara said that she is happy.","B":"Sara said that she was happy.","C":"Sara said that she had been happy.","D":"Sara says that she was happy."}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Direct speech shows the exact words of a speaker.Indirect (reported) speech changes tense and pronouns.In reported speech, present tense usually changes to past tense.“I am happy” becomes “she was happy” after reporting.Last verified on 04-05-2026', 0, 0, 0, 1790961802521) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a5ae849e25e76281', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Karachi is called to be the city of light. The word Karachi is?', '{"A":"Common noun","B":"Abstract noun","C":"Proper noun","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A proper noun is the name of a specific place, person, or thing.“Karachi” refers to a particular city.Proper nouns always start with a capital letter.Additional information:Common noun: city, boy, river (general names)Abstract noun: happiness, beauty, honesty (feelings/ideas)Last verified on 04-05-2026', 0, 0, 0, 1790961802592) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f802dd518a9619d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'To face the music means _____?', '{"A":"To be greeted rudely","B":"To be offered warm","C":"To be on the front seat in a concert","D":"To bear the consequence"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “To face the music” means to accept punishment or deal with the results of one’s actions.It implies taking responsibility for mistakes or misdeeds.Last verified on 30-03-2026', 0, 0, 0, 1790961802592) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e0949cdd48a14369', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Sentence Completion: To answer accurately is more important than ____?', '{"A":"A quick finish","B":"To finish quickly","C":"Finishing quickly","D":"You finish quickly"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence uses a comparison structure.“More important than” is followed by a to-infinitive phrase.So, “To finish quickly” is grammatically correct.It keeps both sides of the sentence in same form.Last verified on 29-04-2026', 0, 0, 0, 1790961802592) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_af65ef43a91c5792', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A black and white cow ________ grazing in the field.', '{"A":"Were","B":"Is","C":"Are","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "A black and white cow is grazing in the field."The subject "A black and white cow" is singular.So, the singular verb "is" is used.Last verified on 28-04-2026', 0, 0, 0, 1790961802592) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b7d59a7588ca858d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_____ yourself to the circumstances.', '{"A":"Adept","B":"Adopt","C":"Adapt","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Adapt" means to adjust or modify oneself to fit new conditions or circumstances.Adapt means موافقتIt is the correct verb in the context of adjusting to circumstances.Last verified on 26-04-2026', 0, 0, 0, 1790961802592) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1993d9c54d64256d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We gave ______ a meal.', '{"A":"At the visitors","B":"For the visitors","C":"The visitors","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct structure is “give someone something”.So we say: We gave the visitors a meal.“The visitors” is the correct object of the verb.Last verified on 24-04-2026', 0, 0, 0, 1790961802592) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e370f35ac1ddb057', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Select the adjective in the sentence: His performance, as usual, was excellent.', '{"A":"Excellent","B":"His","C":"Performance","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Excellent" describes the quality of the noun "performance", so it is an adjective.Adjectives modify or give more information about nouns or pronouns — here, it tells how the performance was.Last verified on 20-04-2026', 0, 0, 0, 1790961802592) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e6aafa46a97f217f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'None of you _____ done work correctly.', '{"A":"Were","B":"Has","C":"Have","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Has" is correct because "none" is often treated as singular in formal usage.It especially when referring to a singular action or condition, like completing work correctly.Last verified on 20-04-2026', 0, 0, 0, 1790961802592) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_837d82c032bfb9e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She always helps _____ poor.', '{"A":"The","B":"An","C":"A","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct article before “poor” is “the”.“The poor” refers to all poor people as a group.It is a common grammar rule in English.“The + adjective” is used to represent a class of people.Last verified on 20-04-2026', 0, 0, 0, 1790961802665) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a3a4cf198a9d9054', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'To be old as the hills means _____?', '{"A":"To be wise and learned","B":"To be old but foolish","C":"To be very ancient","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "as old as the hills" means something is very old or ancient.It emphasizes great age, often used to describe traditions, objects, or ideas that have existed for a long time.Last verified on 20-04-2026', 0, 0, 0, 1790961802665) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ba95785d0c58a537', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_____ : Launch :: Breakfast : Lunch.', '{"A":"Sandwich","B":"Dinner","C":"Countdown","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A countdown precedes a launch, just as breakfast precedes lunch.This analogy highlights the sequential relationship between events or activities.Last verified on 19-04-2026', 0, 0, 0, 1790961802665) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a9b2b651fe1d9bec', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He was true _________ his master.', '{"A":"To","B":"In","C":"On","D":"Of"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He was true to his master. I am true to my boss.She is true to her husband. “True to” is the correct preposition used to show loyalty or faithfulness to someone.The sentence means he was faithful and loyal to his master.Last verified 02-04-2026', 0, 0, 0, 1790961802665) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_73ebdc0c32ee245a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He may be slow ______ understanding.', '{"A":"At","B":"With","C":"To","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrase is “slow at understanding”, meaning not quick to grasp ideas.“At” is used to indicate skill or ability in a particular area.Last verified on 04-04-2026', 0, 0, 0, 1790961802665) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_017c5ed8645be38d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He _____ to contact the nearest police station for the last twenty minutes.', '{"A":"Was trying","B":"Has been trying","C":"Kept trying","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence shows an action that started in the past and is still continuing (“for the last twenty minutes”).“Has been trying” is the present perfect continuous tense, which fits this context perfectly.Last verified on 03-04-2026', 0, 0, 0, 1790961802665) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_680db23a32af1c4e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_____ my word, I am telling you nothing ____ the truth.', '{"A":"By... from","B":"Upon but","C":"On... outside","D":"By... but"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation By my word means I swear or promise.But the truth emphasizes the real fact despite any doubt.Last verified on 02-04-2026', 0, 0, 0, 1790961802665) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_aacee82c8b76f8ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Friendly is which part of speech?', '{"A":"Adverb","B":"Noun","C":"Adjective","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Friendly" is most commonly used as an adjective. It describes a person, thing, or situation as being kind, approachable, or characteristic of a friendIt is not an adverb because it does not describe an action.The adverb form is usually "in a friendly way"Last updated by NA on 28-06-2026', 0, 0, 0, 1790961802665) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_725f86f3a2e46dd7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She left the town under a cloud. Here ''Under a cloud'' means?', '{"A":"When it was raining","B":"With a heavy heart","C":"In disgrace","D":"Of his own accord"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Under a cloud is an English idiom.Under a cloud means in disgrace.Under a cloud means بدنامی یا رسوائیLast verified 02-04-2026', 0, 0, 0, 1790961802734) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6493af6161f5d05c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is going on _____ you and your family?', '{"A":"Between","B":"Among","C":"To","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Between is used when referring to two or more entities in a relationship or situation.So the correct sentence is: “What is going on between you and your family?”Last verified on 06-03-2026', 0, 0, 0, 1790961802734) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8c967ce1d91b387b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is no use/useless to cry over _____?', '{"A":"Milk","B":"Water","C":"Spilt milk","D":"Cold water"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It is no use/useless to cry over spilt milk (or spilled milk).Meaning: Do not dwell on past, unchangeable events.Last verified on 02-04-2026', 0, 0, 0, 1790961802734) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_867bf70e62e48f5a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Please open you book ____ page 10.', '{"A":"On","B":"At","C":"Is","D":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Please open your book to page 10.The preposition “to” is used when referring to a specific page in a book.', 0, 0, 0, 1790961802734) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_af07837b72f87e97', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Conjunction joins _____?', '{"A":"Two Phrases","B":"Two Clauses","C":"Two Sentences","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A conjunction is a word used to connect two clauses, such as "and," "but," or "because."While conjunctions can also link phrases or sentences, their primary role is to join clauses for smoother sentence construction.Last verified on 01-04-2026', 0, 0, 0, 1790961802734) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_867a94c211a4a08d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '"Wealthy" is a ____?', '{"A":"Adverb","B":"Noun","C":"Adjective","D":"Verb"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Wealthy" is an adjective.It describes someone who has a lot of wealth or is rich.Wealthy means دولت مندLast verified on 02-04-2026', 0, 0, 0, 1790961802734) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cd98429d8910cfce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'All jobs are respectable ________ of their nature.', '{"A":"Irrelevant","B":"Immaterial","C":"Irrespective","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrase is “irrespective of”, meaning without considering.It shows that all jobs deserve respect regardless of their nature.Last verified on 01-04-2026', 0, 0, 0, 1790961802734) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d019ea96760de9f1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I wish my father _______ alive today.', '{"A":"Were","B":"Is","C":"Was","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I wish my father were alive today.کاش آج میرے والد زندہ ہوتے۔The verb "were" is used in wishes or hypothetical situations to express something contrary to reality.In this case, "I wish my father were alive today" implies a wish that is not true in the present.Last verified on 01-04-2026', 0, 0, 0, 1790961802734) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f26d0db7622cac47', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Faux Pas means?', '{"A":"A lame person","B":"Luck","C":"False and incorrect step","D":"Wisdom"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Faux Pas means a social mistake. It is a French phrase. It literally means "false step" in French.Last verified on 01-04-2026', 0, 0, 0, 1790961802822) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2f57b8ab7aa0fdfe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Corrigendum means?', '{"A":"Things to be corrected","B":"Agenda of the meeting","C":"Study of some gender","D":"Correspondence"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Corrigendum means an error that needs correction, especially in printed or written work.It is commonly used for official corrections in books, documents, or notices.Last verified on 01-04-2026', 0, 0, 0, 1790961802822) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e78613b5a210b640', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The meaning of "Subway" is ____?', '{"A":"Underground Path/Passage","B":"Under a Tunnel","C":"Under the Ground","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A subway means an underground way used for transport.It carries large numbers of passengers in cities.Usually built under city streets for convenience.Sometimes passes under rivers or buildings.It is a fast and efficient urban transport system.Last verified on 01-04-2026', 0, 0, 0, 1790961802822) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_699368d5df2a1815', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Benefited a great deal ______ taking that online training course.', '{"A":"From","B":"With","C":"For","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase “benefited from” is used to indicate gaining an advantage or improvement due to something.Here, the online training course was the source of the benefit.Last verified on 31-03-2026', 0, 0, 0, 1790961802822) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_29c414f32fc6a6e5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The old lady almost encountered _____ but to everyone''s surprise she survived.', '{"A":"Dead","B":"Being dead","C":"Death","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase “encounter death” means to face a life-threatening situation.It emphasizes that she narrowly avoided dying but survived.Last verified on 31-03-2026', 0, 0, 0, 1790961802822) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b39b482076f6ab81', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They spent the evening _____ through forty years of accumulated junk.', '{"A":"Sifting","B":"Screening","C":"Sulking","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sifting means to examine carefully, especially to separate useful from unwanted items.It fits the context of sorting through junk thoroughly.Last verified on 31-03-2026', 0, 0, 0, 1790961802822) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_34c07a9609bbb091', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The factory was in a _____ condition and needed restoration work to be initiated.', '{"A":"Dilapidated","B":"Inundated","C":"Depreciated","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Dilapidated” means in a state of disrepair or ruin due to neglect or age.It fits the context of the factory needing restoration work.Last verified on 31-03-2026', 0, 0, 0, 1790961802822) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f28d8c531a3a4ef0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I cannot _____ further information about the case.', '{"A":"Divulge","B":"Discuss","C":"Determine","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Divulge” means to reveal or make known information that is secret or private.The sentence implies that the speaker cannot disclose more details about the case.Last verified on 31-03-2026', 0, 0, 0, 1790961802822) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_13eed12fff62c790', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Medieval kingdoms did not become constitutional republics overall; rather the change was _____?', '{"A":"Gradual","B":"Rapid","C":"Unexpected","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Medieval kingdoms slowly evolved over centuries instead of transforming suddenly.Political power shifted step by step toward representative institutions and constitutional systems.Last verified on 31-03-2026', 0, 0, 0, 1790961802904) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4b1280426aec562f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Cut the mustard means _____?', '{"A":"To come up expectations","B":"Bear the consequences","C":"Both","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cut the mustard means to come up to expectations.It refers to meeting or exceeding the required standards or expectations.It typically in performance or ability.Last verified on 31-03-2026', 0, 0, 0, 1790961802904) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ef233185cd0b46a1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Swim is to Fish as Walk is to?', '{"A":"Chair","B":"Bird","C":"Man","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Swim is an action naturally associated with a fish.Just as walk is a natural action associated with a man.Both represent characteristic movements of the respective entities.Last verified on 31-03-2026', 0, 0, 0, 1790961802904) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9d8d3ffe6840e212', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is very popular ___ his employees.', '{"A":"With","B":"At","C":"On","D":"As"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Popular with" is the correct phrase used to indicate that someone is well-liked by a specific group of people."With" correctly connects "popular" to "employees," showing their admiration or approval.Last verified on 31-03-2026', 0, 0, 0, 1790961802904) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4d9371509460acdd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '''Cat is to Kitten'' as Dog is to ____?', '{"A":"Colt","B":"Puppy","C":"Calf","D":"Baby"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cat is to a kitten as the dog is to a puppy.The young cat is called a kitten.The young one of dog is called a pup or puppy.Last verified on 30-03-2026', 0, 0, 0, 1790961802904) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_06594b5adbbbdd42', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Stone : Hard :: Feather : _____?', '{"A":"Bird","B":"White","C":"Soft","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The analogy compares characteristics: just as a stone is hard, a feather is soft.Last verified on 30-03-2026', 0, 0, 0, 1790961802904) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5c5d7efee84ec2b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He couldn''t _____ a moustache to the photo of his headmaster in the newspaper.', '{"A":"Resist from adding","B":"Resist adding","C":"Resist to add","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct structure is “resist + gerund (verb+ing)”, not infinitive.So, “He couldn’t resist adding a moustache…” is grammatically correct.Last verified on 30-03-2026', 0, 0, 0, 1790961802904) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5c57c7cf64a188f2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Appreciation is to Reward as Crime is to ______?', '{"A":"Guilt","B":"Punishment","C":"Allegation","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Appreciation leads to reward (positive action → positive result), similarly crime leads to punishment (negative action → negative result).The analogy is based on cause and effect relationship.Last verified on 30-03-2026', 0, 0, 0, 1790961802904) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_65ad8541742838ce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Chose the antonyms of PIQUE', '{"A":"Value","B":"Guilty","C":"Smooth","D":"Soothe"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pique بے زار کرنا، ناپسند یدگی کا اظہار کرنا، ناخوش کرناSoothe means سکون ملنا', 0, 0, 0, 1790961802976) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_80676d775e9681a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Shah Latif is called the “Saint ______ Bhit”.', '{"A":"From","B":"At","C":"Of","D":"In"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shah Abdul Latif Bhittai is famously called the “Saint of Bhit”, referring to his association with Bhit village.The preposition “of” correctly shows possession or relation.Last verified on 10-03-2026', 0, 0, 0, 1790961802976) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b5c08347f0063aa7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I feel tired, ______?', '{"A":"I so feel","B":"So am I","C":"So do I","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct answer is “So do I” because the main verb in the sentence is “feel”, which is an action, so the auxiliary “do” is used in the tag.It expresses agreement with someone’s feeling or action.Last verified on 09-03-2026', 0, 0, 0, 1790961802976) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6755d5ee5a09dc46', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '______ of Pakistan have received a state funeral.', '{"A":"Not any eminent citizens","B":"Hardly many renowned citizens","C":"The few main citizens","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Few individuals (including General Zia-ul-Haq, Abdul Sattar Edhi, and Dr. Ruth Pfau) of Pakistan have received a state funeral.Last verified on 09-03-2026', 0, 0, 0, 1790961802976) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_098a6a74a775c811', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He said, "Hurrah! we have won the match." This can be changed into an indirect statement as?', '{"A":"He exclaimed with joy that they had won the match.","B":"He exclaimed in the joy that they had win the match.","C":"He exclaimed in the joy that they have won the match.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Direct Speech:He said, “Hurrah! we have won the match.”Correct Indirect SentenceHe exclaimed with joy that they had won the match.“Hurrah!” shows joy, so we use “exclaimed with joy”.“we” → “they” (pronoun change).“have won” → “had won” (present perfect → past perfect because the reporting verb is past).Last updated on 06-March-2026', 0, 0, 0, 1790961802976) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e125f7325e664341', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I was fascinated by the idea. The Ssynonym of Fascinated is?', '{"A":"Concerned","B":"Captivate","C":"Interested","D":"Both B and C"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fascinated by means attracted by.Fascinated means گرویدہ ہوناInterested means دلچسپی رکھناCaptivate means سحر انگیزLast verified on 06-03-2026', 0, 0, 0, 1790961802976) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2a57475ddc747892', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Filter : Water :: ______?', '{"A":"Curtail : Activity","B":"Censor : Play","C":"Edit : Text","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The analogy "Filter : Water :: Censor : Play."Because filtering removes impurities from water.Just as censoring removes or restricts parts of a play.Last verified on 22-02-2026', 0, 0, 0, 1790961802976) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_73d525ebb7f7108a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Knife is to Cut as Pen is to _____?', '{"A":"Dig","B":"Cook","C":"Build","D":"Write"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A knife is a tool used to cut, similarly a pen is a tool used to write. This is an example of a tool-to-function analogy.Last verified on 15-02-2026', 0, 0, 0, 1790961802976) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1c08bdc5da6a9320', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Bird is to Nest as Child is to?', '{"A":"house","B":"bed","C":"room","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bird is to Nest as Child is to House (or Home). A bird lives in a nest Similarly, a child lives in a houseLast updated by NA on 25-April-2026', 0, 0, 0, 1790961803051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c98e0232062437ce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Though Aslam is poor, ____ he is honest.', '{"A":"But","B":"Yet","C":"Still","D":"Nevertheless"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Yet is used to show contrast between two clauses, meaning “in spite of that.”Example: “He is poor, yet he is generous.”Last verified on 04-02-2026', 0, 0, 0, 1790961803051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c536bc6cbdc8c23a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They walked down the stairs. Here ''down'' is?', '{"A":"Preposition of movement","B":"Preposition of time","C":"Preposition of position","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Down" in this sentence shows movement from a higher place to a lower place.Prepositions of movement indicate direction or motion, such as into, onto, up, down, across etc.Last verified on 28-01-2026', 0, 0, 0, 1790961803051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_60b5045fb30206d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am fed up ______ his mess.', '{"A":"With","B":"Of","C":"About","D":"In"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fed up is a phrase which means اکتا جانا یا بیزار ہوناI am fed up with his mess.Mess means بے ترتیبی', 0, 0, 0, 1790961803051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1c1bfd5ccad5383a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We haven’t seen each other since he _____?', '{"A":"Leave","B":"Was leaving","C":"Left","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word “since” refers to a specific point in the past, so the past simple tense is required.Correct sentence: “We haven’t seen each other since he left.”Last verified on 19-01-2026', 0, 0, 0, 1790961803051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_994ebc917c2a3c44', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'De facto means:', '{"A":"In practice","B":"By law","C":"By the wave","D":"By fiction"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation de facto means "in practice" or "in fact," describing a situation that exists in realityDe facto: حقیقت میں******LAST UPDATED 13-JANUARY-2026', 0, 0, 0, 1790961803051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_190f5e614b53c25f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Philately is a ________?', '{"A":"Hobby of stamp collecting","B":"Science of drugs","C":"The study of written record","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Philately is the hobby of collecting and studying postage stamps.It involves collecting, categorizing, and analyzing stamps from around the world.As well as learning about their history, design, and production.', 0, 0, 0, 1790961803051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_120436d3732566da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What do you understand by Intifada?', '{"A":"Ethnicity","B":"Uprising","C":"Peace","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Intifada" refers to an uprising, particularly associated with Palestinian revolts against Israeli occupation.The term has been used to describe popular movements of resistance and civil disobedience.', 0, 0, 0, 1790961803051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ef23b1614f9a297b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The Word “Tsunami” belongs to which language?', '{"A":"Japanese","B":"Chinese","C":"Urdu","D":"English","E":"Turkish"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tsunami means "Harbour Waves".World Tsunami Awareness Day is observed annually on November 5 to create awareness about this deadly disaster.', 0, 0, 0, 1790961803124) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_95d93e8c822bad89', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A book published after the writer''s death is called a _____________ ?', '{"A":"Novel","B":"Death Book","C":"Holy Book","D":"Posthumous","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Posthumous book means arising, occurring, or continuing after one''s deathAdditional Information:Post-haste means with great speed or immediacyPostscript means: an extra message Posterior means situated at the back of something', 0, 0, 0, 1790961803124) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e5ea53c96e382454', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Lawyer goes to Court and Doctor goes to _____?', '{"A":"Shop","B":"School","C":"Hospital","D":"Station"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lawyer goes to Court and Doctor goes to Hospital.Doctors work in hospitals to diagnose, treat, and care for patients.Lawyers work in courts to represent clients.', 0, 0, 0, 1790961803124) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6b4d2684f47f245a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'This is good enough. Here the word "enough" is ____?', '{"A":"Adverb","B":"Adjective","C":"Conjunction","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In this sentence, the word "enough" is functioning as an adverb modifying the adjective "good." It describes the degree or extent to which something is good. Therefore, "enough" is an adverb modifying the adjective "good."', 0, 0, 0, 1790961803124) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_383161404cd59bf9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I would have helped him if he _____ to me.', '{"A":"Came","B":"Had come","C":"Come","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I would have helped him if he had come to me.اگر وہ میرے پاس آتا تو میں اس کی مدد کرتا۔This is a third conditional sentence, used to talk about a hypothetical situation in the past.', 0, 0, 0, 1790961803124) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_85565d9f0a94a1a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Analogy: Race : Fatigue :: _____?', '{"A":"Round : boxing","B":"Fasting : hunger","C":"Hiking : gangrene","D":"Flower : color"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Race: Fatigue:: fasting: hunger," Just like participating in a race can lead to fatigue due to physical exertion, fasting (abstaining from food) can lead to hunger due to the lack of food intake. ** Additional information: Both situations involve a cause-and-effect relationship where one action results in a specific consequence.', 0, 0, 0, 1790961803124) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6a24fdf422d89f39', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_____ is a Relative Pronoun?', '{"A":"My self","B":"This book","C":"Everyone","D":"Who","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The relative pronoun is who....A relative pronoun is a word that is used to connect an independent clause to a dependent clause.The most common relative pronouns are: who, whom, whose, which, that...', 0, 0, 0, 1790961803124) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dc524d57a60e711e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'HOPE : ASPIRES :: _____?', '{"A":"Love: elevates","B":"Film: flam","C":"Fib: lie","D":"Fake: ordinary"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation HOPE : ASPIRES :: fib: lieThe words in each pair are synonyms.', 0, 0, 0, 1790961803124) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9910fa0730480e64', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He devotes much of his time __________ for the future.', '{"A":"Planed","B":"Planning","C":"Plans","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He devotes much of his time to planning for the future وہ اپنا زیادہ تر وقت مستقبل کی منصوبہ بندی میں صرف کرتا ہےSubject: "He"Verb: "devotes"The object of the verb: "Much of his time"Gerund Phrase (acting as a noun): "Planning for the future"', 0, 0, 0, 1790961803203) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fdaf9dbaa304c567', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'If she were free, she _______ to you.', '{"A":"Can talk","B":"Could talk","C":"Would talk","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If she were free, she would talk to you اگر وہ فارغ ہوتی تو آپ سے بات کرتیFormula for second conditional: If + past simple, would/wouldn''t + verb.', 0, 0, 0, 1790961803203) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d6a96b143edd3d6d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It was raining heavy yesterday, so they ________ out.', '{"A":"Did not go","B":"Did not went","C":"Would not go","D":"Would not gone"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It was raining heavily yesterday, so they did not go out.کل موسلا دھار بارش ہو رہی تھی اس لیے وہ باہر نہیں نکلے۔***"did not go" effectively communicates that they remained indoors because of the rain.', 0, 0, 0, 1790961803203) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8afd504ca50ce65f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I can not come to see you ____ tomorrow.', '{"A":"By","B":"Till","C":"Until","D":"Unless"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I cannot come to see you until tomorrow."Until" is the correct choice, as it refers to a point in time when something will happen.It indicating that the speaker cannot visit before tomorrow.', 0, 0, 0, 1790961803203) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4fd23b0b47807ce3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Few and far between means?', '{"A":"Very very distant","B":"Far and away","C":"Few in number but closely placed","D":"Both few in number and distant"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Few and far between → both few in number and distant (کم تعداد میں اور دور دور ہونا)', 0, 0, 0, 1790961803203) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f5506f6f1e532353', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'On who looks on the dark side of things', '{"A":"Obsolete","B":"Inaudible","C":"Pessimist","D":"All of these","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Obsolete means متروکInaudible means بہت دھیماPessimist means مایوسی پسند****', 0, 0, 0, 1790961803203) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c70d6a6abeac6b82', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A handwriting that cannot be read ?', '{"A":"Illegible","B":"Legible","C":"Lucid","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Illegible means Bad handwriting', 0, 0, 0, 1790961803203) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7477c694488bddd1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A conversation between two or more people is called?', '{"A":"Speech","B":"Dialogue","C":"Lecture","D":"Noise"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A dialogue is a conversation between two or more people.It is commonly used in stories, plays, and films to show interaction between characters.', 0, 0, 0, 1790961803203) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ab09391133a81f07', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A remedy which can cure all aliments:', '{"A":"Antiobodic","B":"Panacea","C":"Epidemic","D":"Pandemic","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Panacea means تمام بیماریوں کی دوائیPanacea means the treatment for all type of diseases.', 0, 0, 0, 1790961803290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3e7e8bcfaca9554c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A speech without preparation is called _____?', '{"A":"Extempore","B":"Temporary","C":"Conspiracy","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Extempore means بغیر کسی تیاری کے، برجستہExtempore refers to a speech or performance that is given without any prior preparation or memorization.It comes from the Latin phrase ''ex tempore'', which means ''out of the moment''.It is often used in public speaking events and debatesLast updated 25-07-2026 by NA', 0, 0, 0, 1790961803290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_837f99afb5eb03f6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Place where birds are kept is known as?', '{"A":"Zoo","B":"Apiary","C":"Armoury","D":"Aviary"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Aviary: a large cage, building, or enclosure for keeping birds in.Zoo: an establishment which maintains a collection of wild animals, typically in a park or gardens, for study, conservation, or display to the public.Apiary: a place where bees are kept; a collection of beehives.Armoury: a place where weapons are kept.', 0, 0, 0, 1790961803290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2600cc9dd4a567fb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A doctor who treats children is called?', '{"A":"Pedophile","B":"Fatalist","C":"Cardiologist","D":"Pediatrician"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pediatrics is the branch of medicine dealing with the health and medical care of infants, children, and adolescents.From birth up to the age of 18. The word “paediatrics” means “healer of children.”They are derived from two Greek words: (pais = child) and (iatros = doctor or healer).', 0, 0, 0, 1790961803290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0fe6cb9a63d025de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We trust/believe ______ one God.', '{"A":"On","B":"In","C":"At","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Usually in is used after trust or "believe".We trust in one God means ہم ایک خدا پر یقین رکھتے ہیںso the option "in" is best to keep the meaning of the original sentence.', 0, 0, 0, 1790961803290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5e54511e2ec7c13c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'There is no harm _______ him.', '{"A":"Too meet","B":"To meeting","C":"Meet","D":"In meeting"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We generally use in after harm.No harm in + ing form of a verb کوئی حرج نہیںThere is no harm In meeting him.اس سے ملنے میں کوئی حرج نہیں۔', 0, 0, 0, 1790961803290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1bc9d9a694f445d6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My aunt will ____ my home.', '{"A":"Visits","B":"Visit","C":"Visited","D":"Visiting"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "My aunt will visit my home.""میری خالہ میرے گھر آئیں گی۔""Visit" is the correct verb form to use with "will" because "will" is followed by the base form of the verb to indicate future tense.', 0, 0, 0, 1790961803290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6df547caa174c2f2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Her eyes were filled _____ tears.', '{"A":"By","B":"With","C":"On","D":"In"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We generally use with after filled. With is a preposition here.Her eyes were filled with tears اس کی آنکھیں آنسوؤں سے بھر گئیں۔', 0, 0, 0, 1790961803290) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e3fef0f8d4b09fab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Where ________ you born?', '{"A":"Is","B":"Was","C":"Were","D":"Have"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We generally use were with you.Were shows past tense.Where were you born means آپ کہاں پیدا ہوئے', 0, 0, 0, 1790961803380) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f61e0a178461f25e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We _________ a lot of work yesterday.', '{"A":"Do","B":"Does","C":"Did","D":"Done"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Here ''yesterday'' shows something happened in the past.This sentence is also simple.We generally use second form of verb in simple sentence of Past Indefinite Tense. Note: Do is the first, did is the second while done is the third form of verb. We did a lot of work yesterday means کل ہم نے بہت سارا کام کیا', 0, 0, 0, 1790961803380) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_21b1038318c66ca7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'There is ________ in the room.', '{"A":"Anybody","B":"Nobody","C":"Anyone","D":"Any person"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nobody is an indefinite pronoun. Nobody means کوئی بھی نہیں There is NOBODY in the room کمرے میں کوئی نہیں ہے۔', 0, 0, 0, 1790961803380) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2fed9b9942bbf5ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am glad _______ your success.', '{"A":"To","B":"For","C":"Of","D":"At","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I am glad for your success میں آپ کی کامیابی پر خوش ہوںWe use for to talk about a purpose or a reason for somethingGlad for" is used when you''re happy about something that has happened to someone else.', 0, 0, 0, 1790961803380) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bc426c27f0674442', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She has been exempted ________ night duty', '{"A":"With","B":"From","C":"For","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Exempt is a verb that is generally followed by the preposition “From”.She has been exempted from night duty means اس کو رات کی ڈیوٹی پر رعایت دی گئی ہے', 0, 0, 0, 1790961803380) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8ec9b7590e8e65f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Select similar word: Illustration', '{"A":"Goal","B":"Reason","C":"cause","D":"Explanation"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Illustration مثالExplanationوضاحت', 0, 0, 0, 1790961803380) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1bb59809af67969e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Please do not interfere __________ my personal affairs.', '{"A":"In","B":"Of","C":"About","D":"Off"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Please do no interfere in my personal affairs. براہ کرم میرے ذاتی معاملات میں مداخلت نہ کریں۔****Interfere in means مداخلت کرنا: When interfere is followed by in, it means to get involved in something that doesn''t concern you"In" is used as a proposition here', 0, 0, 0, 1790961803380) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_20e0f624f12c32e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the meaning of REMOTE', '{"A":"Located near","B":"Located Faraway","C":"Near","D":"Remove","E":"City"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Remote means دورFar away means دور*********VU FIA UDC CONSTABLE PAST PAPER 31-12-2021', 0, 0, 0, 1790961803380) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_65bb58cca16ad208', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Analogy: Human : Child :: ______?', '{"A":"Lion : Cub","B":"Duck : Drake","C":"Cow : Bull","D":"Fish : Prawn"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation animal and its child relation have been shown. The young of humans is called the child. The young lion is called a cubND07-3-2023', 0, 0, 0, 1790961803459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_271b1487bbb67482', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He has put ______ the meeting.', '{"A":"Away","B":"Out","C":"Off","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Put off" means to postpone or delay something.Put off means بند کرو', 0, 0, 0, 1790961803459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_373b145d79708083', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The matter is irrelevant ______ the topic for discussion.', '{"A":"About","B":"To","C":"Over","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrase is "irrelevant to," which means not related or connected to something."To" is the appropriate preposition used with "irrelevant" in this context.The matter is irrelevant to the topic for discussion.بات بحث کے لیے موضوع سے غیر متعلق ہے۔', 0, 0, 0, 1790961803459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_042862dfecbe5f0c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am envious _____ them.', '{"A":"Off","B":"Of","C":"On","D":"From"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Envious is generally followed by of.Envious of means jealous of.Envious means حاسد', 0, 0, 0, 1790961803459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_608733de3d4b82e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Sandalwood, ______, the more scent does it yield.', '{"A":"The more it is rubbed","B":"Rubbed it is the more","C":"The rubbed more it is","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The pattern is: "The more it is rubbed, the more scent it yields" (or "does it yield" in inverted form for emphasis).The first part must follow "The more + subject + verb" structure.', 0, 0, 0, 1790961803459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1c12aee700ce3589', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '______ is wearing his new uniform.', '{"A":"Every of the boys in the team","B":"Each of the boys on the team","C":"Every other from the boys","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Each of the boys” is grammatically correct and takes a singular verb (“is wearing”).“On the team” is the standard preposition (not in for team in this context).', 0, 0, 0, 1790961803459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_39046f11dfcda99a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She jumped _____ the bus.', '{"A":"Into","B":"On","C":"From","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "From" indicates movement away or out of a place, as in "jumped from the bus."The correct sentence is: "She jumped from the bus."وہ بس سے کود گئی۔', 0, 0, 0, 1790961803459) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b1938f086b0672af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They _____ finished their homework by the time we arrived.', '{"A":"Having","B":"Had","C":"Have","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation They had finished their homework by the time we arrived.ہمارے پہنچنے تک وہ اپنا ہوم ورک ختم کر چکے تھے۔The correct answer is "Had" because:The sentence uses the past perfect tense.The past perfect is used to show that one event happened before another event in the past.In this case, the homework was completed before "we arrived."', 0, 0, 0, 1790961803460) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_00422605314c6f79', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A group of elephants is called?', '{"A":"Tower","B":"Zeal","C":"Herd","D":"Mob"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A group of elephants is called a herd.Elephants are social animals.Elephants are live in family groups led by a matriarch.', 0, 0, 0, 1790961803533) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_16e43aad559eae67', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My sister loves to draw sketches as she is good _______ drawing.', '{"A":"From","B":"For","C":"Of","D":"At"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Good at is a phrase.Good at means expert.Good at means ماہر My sister loves to draw sketches as she is good at drawing.میری بہن کو خاکے بنانا پسند ہے کیونکہ وہ ڈرائنگ میں اچھی ہے۔', 0, 0, 0, 1790961803533) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c62042c229717e1f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_______ serious injuries, he managed to play well in the last match.', '{"A":"For","B":"In","C":"Despite","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Despite means in spite of.Despite means کے باوجود Despite serious injuries, he managed to Play well in the last matchشدید زخمی ہونے کے باوجود وہ آخری میچ میں اچھا کھیلنے میں کامیاب رہے', 0, 0, 0, 1790961803533) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_76b06360ca260a9a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '“A wet blanket” means', '{"A":"An exceedingly complicated problem or deadlock","B":"A small or insignificant member of a larger organization or system","C":"A rich, older, man who supports or spends lavishly on a usually much younger girlfriend","D":"A dull or depressing person who spoils other people’s enjoyment"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "A wet blanket" is a person who discourages others'' enjoyment or enthusiasm by being negative, unenthusiastic, or spoiling fun.', 0, 0, 0, 1790961803533) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a3ae5d4350cb3668', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What do you understand by ''omniscient''?', '{"A":"One who is present everywhere","B":"One who is merciful","C":"One who is powerful","D":"One who has all knowledge"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Omniscient ہر چیز کا علم رکھنے والا To be omniscient is to know everything. This often refers to a special power of God. If you combine the Latin roots omnis (meaning "all") and scientia (meaning "knowledge"), You''ll get omniscient, meaning "knowledge of all."', 0, 0, 0, 1790961803533) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d200e830fb7cc963', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am looking forward ________ spending time with my friends.', '{"A":"Too","B":"To","C":"Towards","D":"Upon"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase “look forward to” is always followed by a noun or gerund.The following phrase look forward is followed by verb + ing.I am looking forward to weekend/spending time with my friends.', 0, 0, 0, 1790961803533) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b77057eefb775f21', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He has been living in this house _____ five years.', '{"A":"From","B":"Since","C":"For","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use preposition for with years, months, days etc..For is used for numerals.', 0, 0, 0, 1790961803533) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_639f465f91cfcfab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Maiden Speech is called?', '{"A":"Support","B":"First speech","C":"Moral courage","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A maiden speech is the first speech given by a newly elected or appointed member of a legislature or parliament.', 0, 0, 0, 1790961803533) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_34043a37fb11b22e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Green pepper is very rich ________ vitamin C.', '{"A":"Of","B":"On","C":"In","D":"About"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The preposition “in” shows something inside. The phrase "rich in" is a standard English idiom used to describe something that contains a large amount of a particular substance or quality.', 0, 0, 0, 1790961803606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_65ff9b9c7c351a0f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'There is a dog barking the street. Here ''dog'' is?', '{"A":"Object","B":"Verb","C":"Subject","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ''Dog'' is the subject of the sentence — the one performing the action (barking).Though the sentence starts with "There is," the real subject comes after the verb "is."', 0, 0, 0, 1790961803606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_24a1c3513a11fde5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which of the following best defines a compound sentence?', '{"A":"A sentence with a subject and a verb","B":"Two independent clauses joined by a conjunction","C":"A sentence with only one idea","D":"A sentence ending with a question mark"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A compound sentence contains two independent clauses connected by a coordinating conjunction (e.g., and, but, or).Example: I like tea, but she prefers coffee.', 0, 0, 0, 1790961803606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_53739379526a377b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The train was help up on the account of an accident. Here "Hold up" means what?', '{"A":"To Adhere to","B":"To delay","C":"To lower","D":"To examine"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hold up means تاخیر کرناHold up is a phrasal verb which means to delay.The train was held up.', 0, 0, 0, 1790961803606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bd6cb2aa886803e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The horseman pulled the ___ of the horse.', '{"A":"Ranes","B":"Reins","C":"Rains","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The horseman pulled the reins of the horse to control its direction and speed.Reins are straps attached to the bridle.It allowing the rider to guide and communicate with the horse.Reins means لگام', 0, 0, 0, 1790961803606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_00a0306da79c9ce9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She felt ____ when went to stage.', '{"A":"Worried","B":"Nervous","C":"Anxious","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nervous means گھبراہٹ"Felt nervous" is the correct phrase for experiencing anxiety or unease before performing.Example: She felt nervous when she went on stage.جب وہ اسٹیج پر گئی تو اسے گھبراہٹ محسوس ہوئی۔', 0, 0, 0, 1790961803606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5bfb85b2a2fcdc43', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Do you see ___ blue sky', '{"A":"A","B":"The","C":"An","D":"It"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Do you see the blue sky?We use "the" here because "blue sky" is something specific and known to both the speaker and listener. - "The" is a definite article used before something particular or unique in context.', 0, 0, 0, 1790961803606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e95656ee21fbaddc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The man is poor ______ honest.', '{"A":"And","B":"If","C":"Or","D":"But"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The man is poor but honest.آدمی غریب ہے لیکن ایماندار ہے۔- The conjunction "but" is used to show contrast between being poor and honest.', 0, 0, 0, 1790961803606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_af77a005d5b5affc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Will you wait ___ I return', '{"A":"After","B":"When","C":"Till","D":"If"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Will you wait till I return?کیا آپ میرے واپس آنے تک انتظار کریں گے؟- Till/until is used to show something continues up to a point in time (here, “I return”).- So, "Will you wait till I return?" means "Will you wait up to the time I come back?', 0, 0, 0, 1790961803684) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_580310bc6d61e100', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Honest men speak ___________ truth.', '{"A":"A","B":"An","C":"The","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Honest men speak the truth.ایماندار لوگ سچ بولتے ہیں۔- "The" is the correct article before "truth" when referring to universal or definite truths.', 0, 0, 0, 1790961803684) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_30f1d211090d6842', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Analogy: Aerie : eagle :: _____?', '{"A":"Lair : wolf","B":"Venom : rattle snake","C":"Viper : reptiles","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An aerie is the nest/home of an eagle.Similarly, a lair is the den/home of a wolf — same place-to-animal relationship.', 0, 0, 0, 1790961803684) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_500bbb63eada16e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Keep a straight face means _____?', '{"A":"Remain silent","B":"Remain serious","C":"Remain mute","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Keep a straight face" is an idiomatic expression that means to maintain a serious and neutral expression, without showing any emotion, especially when someone is joking or trying to be funny.It is often used to describe a situation where someone is trying not to laugh or show amusement.', 0, 0, 0, 1790961803684) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dc43232c4cc9c2f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You should not feel jealous _____ your brother success.', '{"A":"Of","B":"To","C":"From","D":"But"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation You should not feel jealous "of" your brother''s success. The correct phrase is "jealous of" meaning you are envious of someone else''s achievement or good fortune.', 0, 0, 0, 1790961803684) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_16fc04a44e881144', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '"The Man of Life Upright" is a poem written by _____?', '{"A":"Walter Scott","B":"Leigh Hunt","C":"Thomas Campion","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "The Man of Life Upright" is a poem written by Thomas Campion, a Renaissance poet and composer.The poem praises a morally upright man who lives in peace, unaffected by worldly troubles.', 0, 0, 0, 1790961803684) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ea8ee98998ac04c7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The line of the poem "I had reached your doorsteps" is written by ______?', '{"A":"Lord Tennyson","B":"G. Allana","C":"Thomas Gray","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The line "I had reached your doorsteps" is from the poetry of Ghulam Ali Allana.Ghulam Ali Allana (often called G. Allana) was a 20th-century Pakistani poet, writer, and politician.He wrote in English and authored several books.', 0, 0, 0, 1790961803684) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_30b15d5c5ee83977', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The presence of armed forces guards _________ us from doing anything disruptive.', '{"A":"Defeated","B":"Excited","C":"Irritated","D":"Prevented"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The presence of armed forces guards prevented us from doing anything disruptive.مسلح افواج کے محافظوں کی موجودگی نے ہمیں کوئی بھی خلل ڈالنے سے روک دیا۔Prevented is the best to keep the meaning of the original sentence.', 0, 0, 0, 1790961803684) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_edd6ca1bc8e968a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He was _______ of all valuable possessions.', '{"A":"Robbed","B":"Stolen","C":"Pinched","D":"Established"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He was robbed of all valuable possessions.اس کا تمام قیمتی مال لوٹ لیا گیا۔"Robbed" is best to keep the meaning of the original sentence. If we choose another option, its changes the meaning of the whole sentence.', 0, 0, 0, 1790961803778) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_76f6f09e19b9582e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The gift was bought _____ her.', '{"A":"For","B":"From","C":"By","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "The gift was bought for her.""For" is used to indicate the recipient of the gift or action.The gift was bought from her.The correct preposition is "from" when indicating the source or seller.So, the sentence becomes: "The gift was bought from her."The gift was bought by her.The correct preposition is "by" when indicating the agent performing an action (who bought the gift).So, the sentence becomes: "The gift was bought by her."', 0, 0, 0, 1790961803778) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0a0ccdaa54a2a4b5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They ______ playing cricket at that time.', '{"A":"Shall be","B":"Will be","C":"Are","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "They will be playing cricket at that time."The phrase "at that time" suggests a future point in time. To express an action that will be happening at a specific time in the future, we use the future continuous tense: → "will be" + verb-ing', 0, 0, 0, 1790961803778) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f383e2b9372ff143', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose a pair of words with a similar relationship to of word given Agenda : Conference :: _____?', '{"A":"Map : trip","B":"Teacher : class","C":"Man : woman","D":"Agency : assignment"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Agenda: کاروائی نامہConference: اجلاسMap: نقشہTrip: سفر', 0, 0, 0, 1790961803778) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_66fe7ee2b3128145', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Error detection: There have been heavy rainfall yesterday.', '{"A":"Have","B":"Heavy","C":"There","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Rainfall" is uncountable, so we use "has" not "have."Correct sentence → There has been heavy rainfall yesterday.', 0, 0, 0, 1790961803778) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6816072323f7dea0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The Antonyms of Obstinate is?', '{"A":"Flexible","B":"Compliant","C":"Guilty","D":"Both A and B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Obstinate means رکاوٹFlexible means لچکدارCompliant means تعمیری', 0, 0, 0, 1790961803778) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cf3ea5d185c5c468', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The plural of Calf is?', '{"A":"Calfs","B":"Calves","C":"Calfes","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word "calf" ends in -f, and its plural changes -f to -ves → calves.This is a common rule for some nouns like leaf → leaves, wolf → wolves.', 0, 0, 0, 1790961803778) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9299c7960c7ef554', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She is interested _____ drawing and painting.', '{"A":"Into","B":"Of","C":"With","D":"In"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She is interested in drawing. We use "interested in" because "in" connects the feeling of interest to the activity or subject someone cares about.Pattern: be interested in + noun/verb-ing', 0, 0, 0, 1790961803778) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a12545d01207b4b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The books belongs ______ me.', '{"A":"On","B":"To","C":"For","D":"Of"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct verb-preposition combination is "belong to", which means to be the property of someone.The sentence is about ownership, so we use "to".The books belong to me.', 0, 0, 0, 1790961803873) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_07cd34d2e09cadfe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The masculine gender of Niece is?', '{"A":"Nephew","B":"Cousin","C":"Brother","D":"Friend"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nephew means بھتیجاNiece means بھتیجی', 0, 0, 0, 1790961803873) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a70f368c70068f55', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is the masculine of witch?', '{"A":"Wizard","B":"Swain","C":"Stag","D":"Stallion"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Wizard is the masculine of “witch”.Witch means ڈائنWizard means جادوگر', 0, 0, 0, 1790961803873) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b66d60d8a4b89b02', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What of the following is singular noun of people?', '{"A":"People","B":"Person","C":"Peer","D":"Pair"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Singular noun of People is Person.Person means شخصPeople means لوگ', 0, 0, 0, 1790961803873) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_996b65fc392db01e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The Plural of Goose is?', '{"A":"Gooses","B":"Geeses","C":"Geese","D":"Goosi"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The plural of "goose" is "geese." This is an example of an irregular plural form.', 0, 0, 0, 1790961803873) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dae28a373bd1a475', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Plural of Foot is?', '{"A":"Foots","B":"Feet","C":"Footes","D":"Feetes"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The plural of foot is feet.Foot means پیرFeet means پاؤں', 0, 0, 0, 1790961803873) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ce5e5518b8fe13e6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The plural of Tooth is _____?', '{"A":"Tooth''s","B":"Teeth","C":"Teeths","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct plural form of tooth is teeth.Teeth means دانتTooth means دانت', 0, 0, 0, 1790961803873) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_72fcc166e185b478', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Masculine gender of Mare is?', '{"A":"Horse/Stallion","B":"Dog","C":"Donkey","D":"Ox"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Masculine gender of Mare is Horse.Horse/Stallion means گھوڑاMare means گھوڑی', 0, 0, 0, 1790961803873) ON CONFLICT(id) DO NOTHING;
