INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b4f8e8efda483740', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They kept us waiting _____ two hours.', '{"A":"Between","B":"For","C":"Since","D":"Till"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence will be: They kept us waiting for two hours."For" is used to show the duration of time.', 0, 0, 0, 1790961803996) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_91dad55945b6d700', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_____ is always 1/3 of the actual text.', '{"A":"Precis","B":"Essay","C":"Summary","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A precis is a concise summary that is about one-third the length of the original text.Its purpose is to present the main ideas clearly and briefly.', 0, 0, 0, 1790961803996) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1ff9aea3e0c6f1b5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I prefer writing to _____?', '{"A":"Reading","B":"Reads","C":"Red","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation After “prefer … to”, the verb takes the -ing form.Correct usage: “I prefer writing to reading.”', 0, 0, 0, 1790961803996) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6442af4b6d5f2494', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The teacher ______ disciplined the students for their misbehavior.', '{"A":"Firmly","B":"With firm","C":"Very firm","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The adverb “firmly” correctly modifies the verb “disciplined.”Corrected sentence: “The teacher firmly disciplined the students for their misbehavior.”', 0, 0, 0, 1790961803996) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_68adf586e161cd2a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A common man has no _____ to the government offices.', '{"A":"Assess","B":"Excess","C":"Access","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Access means entry or approach → correct in this context.Assess means evaluate.Excess means extra.', 0, 0, 0, 1790961803996) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c18ed70a0f9dd7d7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Error detection: Neither Saima nor his friends were able to attend the theory class this morning.', '{"A":"Attend","B":"Were","C":"His","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The subject is Saima (female), so the pronoun should be her, not his.Correct sentence: Neither Saima nor her friends were able to attend the theory class this morning.', 0, 0, 0, 1790961803996) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e28f25f8bd5cad3f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Please let me borrow your calculator. I promise to take good care _____ it.', '{"A":"Of","B":"From","C":"To","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrase is "take care of".Correct sentence → I promise to take good care of it.', 0, 0, 0, 1790961803996) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_30d51c0eedcda197', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Select the lettered pair that best expresses similar relationship: Light year : Distance :: _____?', '{"A":"Meteor : Intensity","B":"Microphone : Volume","C":"Decibel : Sound","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A light year is a unit measuring distance (how far light travels in one year).Similarly, a decibel is a unit used to measure sound (specifically sound intensity or loudness).', 0, 0, 0, 1790961804105) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_41dd8a7c2ea800cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They wanted to serve some coffee to their guests; however ______?', '{"A":"There was not a great amount of the sugar","B":"They did not have much sugar","C":"They were lacking in the amount of the sugar","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sugar is an uncountable noun, so the correct quantifier is much, not many.The sentence is grammatically correct and natural: They did not have much sugar.', 0, 0, 0, 1790961804105) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bf50e12a2e797f35', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Sugar production in Pakistan _____?', '{"A":"Are going up and down all the time","B":"Has been rather erratic recently","C":"Have taken slumps and rises in recent years","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The subject sugar production is singular, so the correct helping verb is has (not are or have).The phrase “rather erratic recently” is grammatically smooth and conveys the intended meaning clearly.', 0, 0, 0, 1790961804105) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8e348745d48bc379', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Microsoft Windows Vista is becoming popular because it is ______?', '{"A":"Users’ friendly","B":"User’s friendly","C":"User friendly","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The standard and grammatically correct form is “user friendly” (without apostrophe).Apostrophe forms (users’ or user’s) are incorrect because it’s not possessive, it describes ease of use.', 0, 0, 0, 1790961804105) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ab748f724ada6208', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He appeared ______ began to take the test.', '{"A":"So nervous that","B":"Nervous as he","C":"Nervously as he","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct correlative phrase is “so…that”, showing cause and result.The sentence becomes complete and logical: He appeared so nervous that he began to take the test.', 0, 0, 0, 1790961804105) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5e1f4b77b2417c13', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The Professor ______ students that he could help them all.', '{"A":"Had too many","B":"Too many","C":"Had so many","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "had so many students" fits grammatically and conveys the idea that the professor had a large number of students.Had so many means بہت سارے تھے', 0, 0, 0, 1790961804105) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_98b0e423f62b510b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Every candidate should have ______ opportunity to contest the election.', '{"A":"The equal","B":"An equal","C":"A equal","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word equal begins with a vowel sound, so the correct article is "an" instead of a or the.The sentence expresses fairness, meaning every candidate should have an equal opportunity to contest the election.', 0, 0, 0, 1790961804105) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c57b68e9e89e27a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I was confident ______ my success.', '{"A":"On","B":"With","C":"Upon","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "I was confident on my success" is the grammatically correct usage.Confidence is generally followed by in/on depending on context, but with "success," on is standard.', 0, 0, 0, 1790961804105) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_95d5e2cc2eed4d3e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I _____ her for long time.', '{"A":"Have not seen","B":"Do not see","C":"Am not seen","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence refers to an action continuing up to the present, so present perfect tense is correct.Correct form: I have not seen her for a long time.', 0, 0, 0, 1790961804192) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_961c81e40f6a2195', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Can you please give me _____ coffee?', '{"A":"Some","B":"Any","C":"The","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Some" is used with uncountable nouns like "coffee" when making polite offers or requests."Can you please give me some coffee?" is grammatically and contextually correct.', 0, 0, 0, 1790961804192) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a2eb27f0a22981b8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Error detection: It is essential that nitrogen is present in the soil for plants to grow.', '{"A":"Grow","B":"Soil","C":"Is","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation After “It is essential that”, the verb should be in the subjunctive mood (base form).Correct sentence: It is essential that nitrogen be present in the soil for plants to grow.', 0, 0, 0, 1790961804192) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1aa111c5576e64de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is the term for a sentence that expresses strong emotion or surprise?', '{"A":"Statement","B":"Question","C":"Exclamation","D":"Imperative"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The term for a sentence that expresses strong emotion or surprise is an exclamatory sentence. These sentences typically end with an exclamation mark (!) and convey feelings such as excitement, anger, happiness, or admiration.', 0, 0, 0, 1790961804192) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bec57fe1991cf1f4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A figurative device in which one thing is compared to another unlike thing is _____?', '{"A":"Alliteration","B":"Metaphor","C":"Simile","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A metaphor directly compares two unlike things without using "like" or "as."Simile also compares but uses "like" or "as".Alliteration is repetition of consonant sounds.', 0, 0, 0, 1790961804192) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e8c80b16d1ef840b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'SAW is to CARPENTER so Pen is to _______?', '{"A":"Writer","B":"Ink","C":"Post","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation SAW is to CARPENTER so Pen is to Writer. A saw is used by a carpenter for his work. A saw is the carpenter''s tool. In the same manner, the PEN is writer''s tool.', 0, 0, 0, 1790961804192) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a5a24876a7cd1a79', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Sorrow : Death :: Happiness : ______?', '{"A":"Birth","B":"Cry","C":"Dance","D":"Brave"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Death commonly brings sorrow; likewise, birth commonly brings happiness.The relationship is cause → emotion: event (death/birth) leads to corresponding feeling (sorrow/happiness).', 0, 0, 0, 1790961804192) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7c3c7e30b2bf197f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Ruby : Gem :: ______?', '{"A":"Baseball : Basketball","B":"Trophy : Prize","C":"Party : House","D":"Concert : Music"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A ruby is a type of gem, just as a trophy is a type of prize.Both show the relationship specific : general category.', 0, 0, 0, 1790961804192) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_162fcd3512ca233d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is the adverb of "simple"?', '{"A":"Simpleness","B":"Simpleton","C":"Simplicity","D":"Simply"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The adverb form of "simple" is "simply".It means in a straightforward or easy manner.', 0, 0, 0, 1790961804283) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9ad52ee88f7644bc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Your report is not relevant ______ the topic.', '{"A":"From","B":"For","C":"On","D":"To"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Correct usage: “relevant to the topic.”“Relevant” is always followed by the preposition to.', 0, 0, 0, 1790961804283) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dfd214f1a31eee13', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He got the job _________ influence.', '{"A":"With","B":"From","C":"Of","D":"On"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation With is a preposition here.We generally use with before influence.He got the job with influence اس نے اثر و رسوخ سے کام حاصل کیا', 0, 0, 0, 1790961804283) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_17ddfb81e4d66ad4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A rumor that the corporation was close to the ______ caused panic among its creditors and stakeholders.', '{"A":"Bankruptcy","B":"New venture","C":"Dividend declaration","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence implies financial trouble, which naturally leads to panic.“Bankruptcy” correctly fits the context of creditors and stakeholders.', 0, 0, 0, 1790961804283) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4521ace245436ee1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She is confident _____ his ability to succeed.', '{"A":"Of","B":"At","C":"To","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrase is "confident of", meaning sure about something.Example: "She is confident of her skills in writing."', 0, 0, 0, 1790961804283) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_beffb80efe49ae88', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The people of Pakistan have undergone many social problems.', '{"A":"The people of Pakistan underwent a large number of problems of social nature","B":"The Pakistan’s people have undergone social problems","C":"The people of Pakistan have faced many social problems","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The people of Pakistan have faced many social problems.The verb “have faced” is the correct expression for experiencing problems.', 0, 0, 0, 1790961804283) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_73f6a36fa595f53b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'HAND : GLOVES :: ?', '{"A":"Legs : shoes","B":"Short : long","C":"Slim : fat","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Just as gloves are worn on hands, shoes are worn on legs (specifically feet).This is a relationship of covering or wearing.Last updated on 22-07-2026 by NA', 0, 0, 0, 1790961804283) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_34b927b1cf846542', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My cousin is ____ doctor.While my brother is ____ author.', '{"A":"a/an","B":"the/an","C":"a/a","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation My cousin is a doctor.While my brother is an author."A/an" is used to refer to a non-specific or non-particular member of the group.', 0, 0, 0, 1790961804283) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eabef315db0926f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Octopuses have not only large brains __________ also a well-developed nervous system.', '{"A":"And also","B":"But also","C":"Are also","D":"Have also","E":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Octopuses have not only large brains but also a well-developed nervous systemThe correct correlative conjunction pair is "not only... but also...".', 0, 0, 0, 1790961804384) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_337f7e274d030beb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My sister is bad _____ maths.', '{"A":"In","B":"With","C":"At","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation My sister is bad at maths.میری بہن ریاضی میں خراب ہے۔At is a preposition.We use "bad at" to describe someone''s weakness or lack of skill in a subject or activity.***', 0, 0, 0, 1790961804384) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5e01d85f95543857', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Brain Drains means ___?', '{"A":"Mad Person","B":"Migration Of Skilled Person To Other Country","C":"Emigration Of Intellectuals","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Brain Drains means Migration Of Skilled Person To Other Country.برین ڈرینز کا مطلب ہے ہنر مند افراد کی دوسرے ملک میں ہجرت۔', 0, 0, 0, 1790961804384) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1dd5913a41f782ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'To break the ice means what?', '{"A":"To start quarreling","B":"To end the hostility","C":"To start a conversation","D":"To end up partnership"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Idiom "to break the ice", which means to start a conversation or ease tension.It is often used in social or formal situations to make people feel comfortable.', 0, 0, 0, 1790961804384) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1a9e40bdeafc3854', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I saw _____ one rupee note on the road.', '{"A":"A","B":"An","C":"The","D":"No Article required"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article A is used with singular countable nouns pronounced with consonant sound.', 0, 0, 0, 1790961804384) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2c60aa0e320abdda', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which sentence is correctly punctuated? She said I am tired.', '{"A":"She said I am, tired.","B":"She, said I am tired.","C":"She said I am tired.","D":"She said, I am tired."}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In direct speech, a comma is used to separate the reporting clause from the quoted speech. The correct format is: She said, "I am tired."', 0, 0, 0, 1790961804384) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_699fe3071c07741e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '______ winters are generally very cold here.', '{"A":"A","B":"An","C":"The","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The winters are generally very cold here. Refers to winters in this specific place, as a known fact.', 0, 0, 0, 1790961804384) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c6fd52a31a9420b8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Antonyms of SLOWLY.', '{"A":"Quickly","B":"Swiftly","C":"loudly","D":"gradually"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation SLOWLY. آہستہ آہستہ.Quickly جلدی سے', 0, 0, 0, 1790961804384) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f7c25f2f37adfb34', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We get up early ____ the morning .', '{"A":"On","B":"To","C":"From","D":"In"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We generally use in before morningWe use "in the morning" to refer to time of day (like in the afternoon, in the evening).', 0, 0, 0, 1790961804513) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_48d4a2bbff24a9de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The Synonyms of Antique is?', '{"A":"Rare","B":"Modern","C":"Unique","D":"Ancient"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Antique means قدیمAncient means قدیم', 0, 0, 0, 1790961804513) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a2efbd630809978d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'WHISPER : SPEAK :: _____?', '{"A":"Listen : Bear","B":"Request : Ask","C":"Brush : Touch","D":"Eat : Drink"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Whisper is a form/synonym of speak (a way of speaking).Request is a synonym of ask (a way of asking).', 0, 0, 0, 1790961804513) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d3a2be3305929353', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am convinced _____ his innocence.', '{"A":"With","B":"For","C":"Of","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct preposition to use with "convinced" in this context is "of."The correct sentence is: "I am convinced of his innocence."میں اس کی بے گناہی کا قائل ہوں۔', 0, 0, 0, 1790961804513) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_627f926d9ddabd1e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Find an objective pronoun in sentence "Is everything alright with you? Yes, I am fine."', '{"A":"I","B":"You","C":"Everything","D":"With"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Objective pronouns receive the action of the verb or follow a preposition.In the sentence, with you → you is the objective pronoun.', 0, 0, 0, 1790961804513) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6ea413fac104c12f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I could not recognize her voice on phone. (Which word is an abstract noun?)', '{"A":"Phone","B":"Could not","C":"The","D":"Voice"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abstract nouns refer to ideas, qualities, or things we perceive but cannot touch.Voice is an abstract noun because it is heard but not physically touched.', 0, 0, 0, 1790961804513) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6d4465ce7271ec1a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I checked all primary classrooms, no one was there. (Which word is a compound noun?', '{"A":"Checked","B":"Classrooms","C":"Primary","D":"There"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Compound words are formed when two or more words are joined together to create a new word that has an entirely new meaning. For example, “class” and “room” are two different words, but when fused together, they form another word, classroom.', 0, 0, 0, 1790961804513) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f128c68e30ba693e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She complained ________ pains in her back.', '{"A":"By","B":"With","C":"Over","D":"About"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We word complain is followed by to/about.To & about are prepositions here.Complain to someone کسی انسان سے شکایت کرناComplain about something کسی معاملے پر شکایت کرناShe complained about pain in her neck.', 0, 0, 0, 1790961804513) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_775ed5272f5e28ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The boy who got full marks was suspected ________ cheating.', '{"A":"By","B":"From","C":"Of","D":"For"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrase is "suspected of cheating".Preposition "of" is always used with suspect.', 0, 0, 0, 1790961804629) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d5a1f7a967e235cd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Their share price fell to _______ ten rupees yesterday.', '{"A":"Under","B":"Below","C":"Upon","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Below" is used for numerical values (price, temperature, marks, etc.).Correct usage: "Their share price fell to below ten rupees yesterday."', 0, 0, 0, 1790961804629) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6cf34cf2a36f0774', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Do not take any notice ______ him.', '{"A":"About","B":"On","C":"Of","D":"In"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Do not take any notice of him means ignore him.Do not take any notice of him means نظر انداز کرنا****', 0, 0, 0, 1790961804629) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c8e757541be46c0d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is the superlative degree of Good?', '{"A":"Better","B":"Goodest","C":"Best","D":"Most Good"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Positive degree: Good Comparative degree: BetterSuperlative degree: Best Last updated by NS on 06 May 2026', 0, 0, 0, 1790961804629) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_86500b5066d44117', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'If you work hard _____', '{"A":"You was get success","B":"You will get success","C":"You were get success","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If you work hard You will get success اگر آپ محنت کریں گے تو آپ کو کامیابی ملے گی۔In conditional sentences, when the if-clause is in the present tense (If you work hard), the main clause takes the future tense (you will get success).*****RY 15-01-2023', 0, 0, 0, 1790961804629) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ed8c0a2062cf3c97', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Young one of dogs is called?', '{"A":"Puppy","B":"Cub","C":"Kitten","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The young dog is called a puppy.', 0, 0, 0, 1790961804629) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ad6a60aa4a284b0c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose analogous pair: Embarrass : Humiliate :: _____?', '{"A":"Enquire : Ask","B":"Embezzle : Peculate","C":"Gamble : Investment","D":"Annoy : Exasperate"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Embarrass” is similar in meaning to “Humiliate.”Similarly, “Annoy” is similar in meaning to “Exasperate.”', 0, 0, 0, 1790961804629) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9bdd525d8cad530e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is getting out _____ the car.', '{"A":"Of","B":"From","C":"To","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Getting out of something means کسی چیز یا جگہ سے باہر نکلناThe correct phrase is "getting out of the car" — "of" is used after "get out" when referring to vehicles.', 0, 0, 0, 1790961804629) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_63ef8f6f72edd656', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '"Inter alia" means _____?', '{"A":"Under concentration","B":"In between","C":"By the fact","D":"At the end"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Inter alia" is a Latin phrase that means "among other things" or "in between".Inter alia means دوسری چیزوں کے درمیانIn between means درمیان میں', 0, 0, 0, 1790961804730) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6b8f56bcebf00c52', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Secretly listening to a conversation of others is called ________?', '{"A":"Eavesdropper","B":"Overhearing","C":"Pigeonholing","D":"Spying","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Eavesdropper means وہ شخص جو چھپ کر دوسروں کی باتوں کو سنتا ہو', 0, 0, 0, 1790961804730) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_213080c12b9b9afd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The act of killing one self', '{"A":"Homicide","B":"Suicide","C":"Genocide","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Suicide is the act of intentionally causing one''s own death.*************VU FIA SUB INSPECTOR PAPER 30-1-2021', 0, 0, 0, 1790961804730) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9d6210cdb178a1cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '____ his principles, he has to be very careful.', '{"A":"With regard to","B":"With regard of","C":"With regard on","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "with regard to" is used to reference something specific.So "With regard to his principles, he has to be very careful" is the correct form.اپنے اصولوں کے حوالے سے اسے بہت محتاط رہنا پڑتا ہے۔', 0, 0, 0, 1790961804730) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a62e35c26246db2e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She deprived her husband ________ all he had.', '{"A":"Off","B":"Of","C":"With","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally deprive is followed by of.Deprive of means کسی چیز سے محروم کردیناShe deprived him of all he had.', 0, 0, 0, 1790961804730) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_333ba48a65096d71', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Insect : Disease :: War : _____?', '{"A":"Destruction","B":"Injury","C":"Relief","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Insects can cause or spread disease.Similarly, war can cause destruction.', 0, 0, 0, 1790961804730) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7d615456c8a8f41e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He reached Lahore ______ bus.', '{"A":"In","B":"With","C":"Through","D":"By"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation By is a preposition here.He reached Lahore by bus.وہ بس کے ذریعے لاہور پہنچا۔By bus = a means of transport', 0, 0, 0, 1790961804730) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6e4510415a1cb939', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He was accused ____ theft.', '{"A":"Of","B":"Over","C":"With","D":"In"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Accuse is generally followed by of.Accuse of means الزام عائد کرناOf is a preposition here.He was accused of theft means اس پر چوری کا الزام تھا', 0, 0, 0, 1790961804730) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cc25b8433e73f969', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'As ______ me, I will be happy to lend a hand.', '{"A":"In","B":"About","C":"For","D":"Of"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct sentence is: "As for me, I will be happy to lend a hand.""For" is the correct preposition to use in this context.It indicating "as far as I am concerned" or "with regard to me".', 0, 0, 0, 1790961804842) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_edbd8ce32ceb64f3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am good ______ tennis.', '{"A":"Of","B":"In","C":"At","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I am good at tennis."at" is the correct preposition to use with "good" when talking about a skill or activity.Common pattern: good at + activity/sport (e.g., good at tennis, good at cooking, good at math).We do not use "in," "on," or "for" in this context.', 0, 0, 0, 1790961804842) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_216efa59063c42af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He cares ________ the environment.', '{"A":"In","B":"At","C":"For","D":"About"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She cares about the environment.we always use "about" with "cares". The most common meaning of about as a preposition is ''on the subject of'' or ''connected with''.Care about something means کسی کا خیال رکھنا، پرواہ کرنا', 0, 0, 0, 1790961804842) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_33fe39ea1a0205aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Don’t be late ____ school.', '{"A":"With","B":"For","C":"To","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct sentence is: "Don’t be late to school.""Late to" is used when referring to specific places or events (e.g., late to school, late to class)."Late for" is also commonly used, especially for events or appointments (e.g., late for a meeting).', 0, 0, 0, 1790961804842) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b24ba32a8a459203', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Wasim moved here _______ October.', '{"A":"From","B":"To","C":"On","D":"In"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "In" is used for months, years, centuries, and longer periods (e.g., in October).It correctly shows the time of movement in a general sense.', 0, 0, 0, 1790961804842) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_965230092ea38fa1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Can I come and sit _____ you?', '{"A":"Beside","B":"Around","C":"Next","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Beside" means next to or by the side of someone, which fits the sentence correctly.It shows physical proximity, making it the right preposition here.', 0, 0, 0, 1790961804843) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8ef08dc8c84d5521', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The teacher set some homework ____ the end of lesson.', '{"A":"In","B":"At","C":"To","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The teacher set some homework at the end of lesson.استاد نے سبق کے اختتام پر کچھ ہوم ورک سیٹ کیا۔The correct preposition is "at" to indicate a specific point in time, such as the end of a lesson."At the end" is commonly used to refer to the conclusion of an event or activity.', 0, 0, 0, 1790961804843) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_26794865d9dd41e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He looks upset, I think he took the criticism _______ heart.', '{"A":"Of","B":"About","C":"To","D":"In"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He looks upset, I think he took the criticism to heart. وہ پریشان نظر آتے ہیں، مجھے لگتا ہے کہ اس نے تنقید کو دل پر لیا۔It means he was deeply affected or upset by the criticism. The preposition "to" indicates a personal impact.', 0, 0, 0, 1790961804843) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eb684ad5ae120033', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Unfortunately, we had to cancel it owing _________ the bad weather.', '{"A":"In","B":"To","C":"For","D":"About"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Owing to means because of. Owing to کی وجہ سےخراب موسم کی وجہ سے Owing to bad weather means***', 0, 0, 0, 1790961804946) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_aef64126486dd37c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She suffers _________ a heart disease.', '{"A":"Of","B":"On","C":"From","D":"With"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct preposition with "suffers" when talking about a medical condition is "from".For example, "She suffers from a heart disease."', 0, 0, 0, 1790961804946) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f1a6137a35b0661d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is superior _____ me.', '{"A":"Than","B":"To","C":"With","D":"From"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Superior, Senior, Junior etc are followed by preposition To.He is superior to me.She is senior to me.', 0, 0, 0, 1790961804946) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8ffc7564e7e37c8b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Mareena is afraid ______ spiders.', '{"A":"To","B":"Of","C":"For","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mareena is afraid of spiders.مرینہ مکڑیوں سے ڈرتی ہے۔"Afraid" is one of those adjectives that is followed by "of" when introducing the thing or person someone fears.Afraid of means خوفزدہ', 0, 0, 0, 1790961804946) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4f9c694b5021ec6e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Hyder is ____ vacation.', '{"A":"In","B":"For","C":"On","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct sentence is: "Hyder is on vacation.""On vacation" is the standard phrase in English.', 0, 0, 0, 1790961804946) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_05345621e7ea105b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They said, "God helps those who help themselves".', '{"A":"They said that God helped those whose helped themselves.","B":"They said that God helps those who helped themselves.","C":"They said that God helps those who help themselves.","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence is a universal truth (proverb), so the verb "helps" remains in the present tense.In indirect speech, universal truths do not change tense.', 0, 0, 0, 1790961804946) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cefab3250baa508e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '____ of locusts attacked the crops.', '{"A":"Swarm","B":"Flock","C":"Herd","D":"Gang"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A swarm of locust means ٹڈی دل کا غولA group of locusts or insects is called a swarm.Flock (birds), herd (animals), and gang (people)', 0, 0, 0, 1790961804946) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_db949e3c5ad9e833', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Several ducks had dark green heads. Here ''Several'' is an example of ______?', '{"A":"Subject","B":"Conjunction","C":"Pronoun","D":"Adjective"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Several" describes how many ducks there were — it''s giving more information about the noun "ducks".Words that describe or limit nouns (like number or quantity) are called adjectives.Words like Few, many, much, enough, a lot, a ton of, a number of, a quantity of, less, little, fewer, fewest, most, extra, half, thirty, several etc. are considered to Quantitative Adjectives.', 0, 0, 0, 1790961804946) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ce65587ed2be6129', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Running fast they caught the last bus. Here ''Running fast'' is an example of ______?', '{"A":"Adverb phrase","B":"Noun phrase","C":"Adjective phrase","D":"Object complement"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Running fast" is a participle phrase in form but acts as an adverb in the sentence, Describing how "they caught the last bus." So, the Adverb phrase is the right functional category from the given options', 0, 0, 0, 1790961805025) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3d07be86c06182c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Complete the analogy: Turtle : Crawl :: Frog : ?', '{"A":"Fast","B":"Run","C":"Hop","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A turtle crawls slowly, while a frog hops as its natural movement.Analogies show a relationship between two pairs based on a common action or trait.', 0, 0, 0, 1790961805025) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_16ae64539eaa4e64', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We are having a social service week _____ school.', '{"A":"At","B":"To","C":"Of","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct preposition here is "at".Because it indicates the location (school) where the social service week is taking place.', 0, 0, 0, 1790961805025) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_951e17c2ca0c9f47', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The fire alarm rang ________ yesterday''s meeting.', '{"A":"When","B":"While","C":"During","D":"Between"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation During means کے دورانThe fire alarm rang during yesterday''s meeting.کل کی میٹنگ کے دوران فائر الارم بج گیا۔', 0, 0, 0, 1790961805025) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4fd718440b1e83a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'God helps those who help ________?', '{"A":"Others","B":"Children","C":"Themselves","D":"Needy","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation God helps those who help themselves is a proverb which means ہمت مرداں مدد خدا', 0, 0, 0, 1790961805025) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_af5ce1c5c23b61e6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Migration out of an area is called _____?', '{"A":"Emigration","B":"Cordial","C":"Population growth","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Emigration refers to people leaving one country or region to settle in another.It contrasts with immigration, which means entering a new country to live permanently.', 0, 0, 0, 1790961805025) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a5cdc5363d0a8c86', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We continued working on the assignment last night. Here ''working'' is?', '{"A":"Gerund","B":"Clause","C":"Phrase","D":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the sentence, "We continued working on the assignment last night," the word "working" functions as a participle that is part of the verb phrase "continued working." It is specifically a present participle used as an auxiliary to the main verb "continued" to indicate ongoing action, rather than functioning as a gerund (which acts as a noun).', 0, 0, 0, 1790961805025) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_94ffb59a936e9386', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Look at the picture _____ the wall.', '{"A":"On","B":"At","C":"Above","D":"In"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct preposition is "on" when something is attached to or hanging on a surface.So: Look at the picture on the wall.', 0, 0, 0, 1790961805025) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_627c5055049a8c65', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'His father is anxious ________ his health.', '{"A":"Of","B":"After","C":"About","D":"For"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrase is "anxious about his health", meaning worried or concerned regarding someone''s well-being."Anxious about" is used to express concern or unease regarding a situation or person.His father is anxious about his health.اس کے والد اس کی صحت کے بارے میں فکر مند ہیں۔', 0, 0, 0, 1790961805113) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6a40f695cbe91b9e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Where _____ the car?', '{"A":"Did you parked","B":"Parked you","C":"Did you park","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In past tense questions, the auxiliary verb "did" is used, followed by the base form of the main verb ("park").Correct structure: "Where did you park the car?"', 0, 0, 0, 1790961805113) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_07312a2846d1c24c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She is not afraid _____ death.', '{"A":"By","B":"Of","C":"At","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrase is "afraid of", meaning to fear something.Example: "She is not afraid of death."', 0, 0, 0, 1790961805113) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b546c2f450f02592', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The poem "About Ben Adhem" is composed by _____?', '{"A":"Leigh Hunt","B":"Wordsworth","C":"Henry Wotton","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Abou Ben Adhem" was written by James Henry Leigh Hunt (1784–1859), a British Romantic poet and essayist.The poem celebrates love for humanity as the highest form of devotion, inspired by a Sufi tale.', 0, 0, 0, 1790961805113) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bc531ca301d16beb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The hero of the novel "The Prisoner of Zenda" is ______?', '{"A":"Black Michael","B":"Rudolph Clarksville","C":"Rudolf Rassendyl","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rudolf Rassendyl is the protagonist of "The Prisoner of Zenda", an Englishman who impersonates King Rudolf V to save the throne.Black Michael is the antagonist (villain).Rudolph Clarksville is a distractor (not in the novel).', 0, 0, 0, 1790961805113) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_88099aebb0c35732', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'In ''Seven Ages of Man'', which is the fourth stage of man?', '{"A":"Soldier","B":"Justice","C":"Lover","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Seven Ages of Man – by William Shakespeare (from As You Like It)Infant – Helpless baby in arms.Schoolboy – Whining child going to school.Lover – Sighing young lover, writing ballads.Soldier – Hot-headed, seeking honor and reputation.Justice – Wise, well-fed, full of sayings and judgments.Pantaloon – Aging man, lean and slippers on.Second childishness – Senility, without teeth, sight, taste, or memory.', 0, 0, 0, 1790961805113) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5da54d16b9216fcd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The poem "The Solitary Reaper" is composed by _____?', '{"A":"William Wordsworth","B":"William Blake","C":"John Keats","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "The Solitary Reaper" was written by William Wordsworth (1770–1850), a central figure of the Romantic Movement in English literature.Published in 1807 in his poetry collection "Poems, in Two Volumes," the poem describes a Highland girl singing in a field, blending nature with human emotion.', 0, 0, 0, 1790961805113) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cd06c3f8db6874ad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I have been staying in this hotel _____ three days.', '{"A":"For","B":"Since","C":"Until","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "For": Used to indicate a duration of time (e.g., for three days, for months)."Since": Refers to a specific starting point (e.g., since Monday, since 2020)."Until": Marks an endpoint (e.g., until tomorrow).', 0, 0, 0, 1790961805113) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_05e0bc37b7faf0ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We are answerable ______ God _____ his actions.', '{"A":"To - upon","B":"For - to","C":"To - For","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Answerable to": Indicates to whom you are accountable (God)."Answerable for": Specifies what you are accountable for (his actions).Example: "We are answerable to God for our deeds."', 0, 0, 0, 1790961805204) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_735a7f8d226e14c1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who is the hero in "The Count''s Revenge"?', '{"A":"Raymond Dantes","B":"The Count of Monte Cristo","C":"Albert","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The protagonist is Edmond Dantès, who later becomes The Count of Monte Cristo after his transformation from a wronged sailor to a vengeful nobleman."The Count''s Revenge" is an alternate title or adaptation of "The Count of Monte Cristo".', 0, 0, 0, 1790961805204) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5f1a216189101a63', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'William Wordsworth is a _____?', '{"A":"Classical poet","B":"Romantic poet","C":"Famous comedian","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation William Wordsworth (1770–1850) was a leading Romantic poet, emphasizing nature, emotion, and individualism in works like "Daffodils" and "The Prelude".Classical poets (e.g., Alexander Pope) focused on structure and reason.Wordsworth pioneered Romanticism’s spontaneity and natural beauty.', 0, 0, 0, 1790961805204) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2eada97baa63470f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '"This man is free from service bands, Of hope to rise or fear to fall" are famous lines in the poem _____?', '{"A":"Character of Happy Life","B":"Lucy Gray","C":"Abou Ben Adhem","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation These lines are from "The Character of a Happy Life" by Sir Henry Wotton, celebrating inner freedom and moral integrity.The poem contrasts worldly ambitions with the peace of a virtuous, independent life ("free from service bands").', 0, 0, 0, 1790961805204) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_93c284e1443a27ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The poem "Character of Happy Life" is written by _____?', '{"A":"Sir Henry Wotton","B":"William Shakespeare","C":"William Wordsworth","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The poem "The Character of a Happy Life" was written by Sir Henry Wotton (1568–1639), a diplomat and poet of the Renaissance era.It describes the virtues of a morally upright life (e.g., honesty, self-sufficiency) as the key to true happiness.', 0, 0, 0, 1790961805204) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4ed94b7c7f6dc23e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The play ''The Count''s Revenge'' is written by _____?', '{"A":"G. Ervine","B":"J.H Walsh","C":"Alexander Dumas","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Count’s Revenge is a one-act play adapted by J.H. Walsh,It is based on Alexandre Dumas’ novel The Count of Monte Cristo.It focuses on themes of revenge, justice, and redemption drawn from Dumas’ original story.', 0, 0, 0, 1790961805204) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_48f044b9a540b21d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Study hard, _____ you will fail the test.', '{"A":"If","B":"Or","C":"Unless","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is a conditional sentence giving a warning or consequence.Correct sentence: Study hard, or you will fail the test.("Or" shows the result if you don''t study.)', 0, 0, 0, 1790961805204) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d15d96403b2e192c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'If I ______ you, I would have told him the truth.', '{"A":"Were","B":"Was","C":"And","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is a conditional sentence (Type 2), which uses "were" with "I" in hypothetical situations.Correct sentence: "If I were you, I would have told him the truth."', 0, 0, 0, 1790961805204) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_36ef6dec3f823100', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I congratulated him _____ his success.', '{"A":"Upon","B":"At","C":"For","D":"On"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "I congratulated him on his success."میں نے اسے اس کی کامیابی پر مبارکباد دی۔The preposition "on" is commonly used when congratulating someone for an achievement or event.', 0, 0, 0, 1790961805285) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d51704c3c6b3a984', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My friend and benefactor ___ died.', '{"A":"Was","B":"Has","C":"Were","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "My friend and benefactor has died."میرا دوست اور محسن فوت ہو گیا ہے۔My friend and benefactor" is a singular subject, even though it refers to two roles that the person played.When referring to a single person, we use the singular verb "has".', 0, 0, 0, 1790961805286) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2f38af28b66cd628', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A poem with fourteen lines is known as _______?', '{"A":"Lyric","B":"Epic","C":"Sonnet","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A poem of 14 lines is called a sonnet.It is a short lyric poem typically written in iambic pentameter.There are 4 primary types of sonnets: Petrarchan, Shakespearean, Spenserian and Miltonic.A sonnet usually consists of two parts: an eight-line section (the octet) followed by a six-line section (a sestet).', 0, 0, 0, 1790961805286) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e59d7e0b2deee677', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She was brought ______ by her uncle.', '{"A":"Of","B":"On","C":"Up","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "brought up" means to raise or rear a child.Correct sentence: "She was brought up by her uncle."', 0, 0, 0, 1790961805286) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b9760303e14c8fe0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He _______ to college daily in time.', '{"A":"Go","B":"Goes","C":"Going","D":"Gone"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He goes to college daily in time.The subject "He" is third person singular, so in the present simple tense, we add -s to the verb. The sentence describes a habitual action, so the present simple tense is appropriate.', 0, 0, 0, 1790961805286) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e6e0cba001a446a8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He laughs as if he _____ mad.', '{"A":"Were","B":"Is","C":"Was","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In hypothetical or imaginary situations, we use the subjunctive mood, where "were" is used with all subjects.Correct sentence: "He laughs as if he were mad."', 0, 0, 0, 1790961805286) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fdfa1979e4e7f8de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'His house is adjacent ______ the mosque.', '{"A":"Of","B":"To","C":"At","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct preposition with "adjacent" is "to."Correct sentence: "His house is adjacent to the mosque."', 0, 0, 0, 1790961805286) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_19744d97f55455d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She _____ ill for a week.', '{"A":"Was","B":"Is","C":"Had","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence refers to a completed action in the past, so "was" is correct.Correct sentence: "She was ill for a week."', 0, 0, 0, 1790961805286) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_700b8b0466304d3c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He _____ out five minutes ago.', '{"A":"Has gone","B":"Had gone","C":"Went","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Minutes ago" indicates a completed action in the past, so simple past tense is used.Correct sentence: "He went out five minutes ago."', 0, 0, 0, 1790961805359) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1da8891ca8a9d754', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is not the casting pearls before ______?', '{"A":"Swine","B":"Pig","C":"Buffalo","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct idiom is "casting pearls before swine," which means offering something valuable to those who won’t appreciate it."Swine" refers to pigs in a figurative, biblical context.', 0, 0, 0, 1790961805359) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_64fca2a02c0b36cf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The wearer knows where the shoe ______?', '{"A":"Was pinching","B":"Pinches","C":"Is pinching","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct proverb is: "The wearer knows where the shoe pinches," meaning only the person experiencing something knows the discomfort.Present tense "pinches" is used for general truth.', 0, 0, 0, 1790961805359) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b2122f0fd7c1e6c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She congratulated me ______ my success.', '{"A":"On","B":"After","C":"Upon","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct preposition after "congratulated" is "on" when referring to success or achievements.So, the sentence is: "She congratulated me on my success."', 0, 0, 0, 1790961805359) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_45a9e264c875fd75', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She was yelling ______ her students.', '{"A":"For","B":"Against","C":"At","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrase is "yelling at" when someone is shouting angrily toward someone.Correct sentence: "She was yelling at her students."', 0, 0, 0, 1790961805359) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_54978281a5bcb10e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Our clean environment _______ our clean habits and thoughts.', '{"A":"Reflect","B":"Reflects","C":"Was reflecting","D":"Is reflecting"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The subject “Our clean environment” is singular, so we need the singular form of the verb.The verb “reflects” is the correct singular form of “reflect” in the present simple tense.', 0, 0, 0, 1790961805359) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c8d02e02764b5084', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The burglars, after searching the entire house, found the locker and opened it. Here ''AND'' is?', '{"A":"Adjective","B":"Conjunction","C":"Pronoun","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "And" is a conjunction because it is used to connect two actions or phrases in the sentence.In this case, it connects "found the locker" and "opened it."', 0, 0, 0, 1790961805359) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d3f82f1b768034eb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Identify the figure of speech used in the line: The story jumped off the stage.', '{"A":"Personification","B":"Simile","C":"Metaphor","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Personification gives human actions to non-human things — here, the story is described as if it could jump.Non-living things like a story cannot physically jump, which makes this an example of personification.', 0, 0, 0, 1790961805359) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_47ef764f9644743a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We should not sneer _____ the poor.', '{"A":"On","B":"Of","C":"Against","D":"At"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Both Laugh and Sneer are followed by preposition at. Sneer at means مزاق اڑانا یا طنز کرناYou should not sneer at the boy.We must not sneer at elders. He was laughing at the poor.', 0, 0, 0, 1790961805440) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0cde0217f85aed67', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Honesty never _____ to wasted.', '{"A":"Go","B":"Goes","C":"Went","D":"Gone"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Honesty never goes to waste.The subject "Honesty" is singular and uncountable, And the sentence is in the present simple tense, expressing a universal truth or general fact.In present simple tense: Singular subject → verb + s/es', 0, 0, 0, 1790961805440) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e154a210ee6fa814', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The meeting was held ______ the conference room.', '{"A":"In","B":"On","C":"At","D":"Inside"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The meeting was held in the conference room.یہ ملاقات کانفرنس روم میں ہوئی۔Use “in” when something happens inside an enclosed space, like a room, hall, or building.', 0, 0, 0, 1790961805440) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4be50ca9c92823ad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My sister has been living in Paris ______ three years', '{"A":"Since","B":"During","C":"By","D":"For"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation My sister has been living in Paris for three years.میری بہن تین سال سے پیرس میں رہ رہی ہے۔We use "for" with a duration of time (e.g., for two hours, for ten years).', 0, 0, 0, 1790961805440) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_38809aa81176ebee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The students were asked to submit their assignments ______ Friday.', '{"A":"On","B":"At","C":"In","D":"Till"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use “on” with days and dates (e.g., on Monday, on Friday, on July 5). This sentence refers to a specific day, so: “On Friday” is correct.', 0, 0, 0, 1790961805440) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_be611b09fe3192e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'In a torrent of thoughts, Chips made answers to himself.', '{"A":"Outburst","B":"Sleeplessness","C":"Confusion","D":"Imagination"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Torrent of thoughts" is a common phrase meaning a sudden, intense flow of thoughts — like an outburst.It''s not related to confusion, sleeplessness, or imagination directly.Torrent = Outburst (a rush or flood of something)', 0, 0, 0, 1790961805440) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8599780b238c7101', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which boarding school does Mr. Chips join as a teacher?', '{"A":"Brookfield","B":"Rockingham","C":"Colchester","D":"Wembley"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the novel "Goodbye, Mr. Chips" by James Hilton, Mr. Chips becomes a teacher at the fictional English public (boarding) school called Brookfield.', 0, 0, 0, 1790961805441) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2ad2f5847ed9289d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'In which subject does Mr. Chips teach?', '{"A":"Mathematics","B":"History","C":"English","D":"Latin"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the novel "Goodbye, Mr. Chips" by James Hilton,Mr. Chips becomes a teacher at the fictional English public (boarding) school called Brookfield.', 0, 0, 0, 1790961805441) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_85312f238dcea5f5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'His father _____ a book.', '{"A":"Write","B":"Is writing","C":"Has been writing","D":"Writes"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation His father is writing a book. (Present continuous tense) If the action is a regular or habitual activity Is writing – if it’s happening right now', 0, 0, 0, 1790961805512) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a649f48020c474c6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What does clay go to the beach?', '{"A":"To play","B":"To fish","C":"To look for stuff","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In many children''s stories or educational texts featuring a character named Clay, He often goes to the beach to collect or look for interesting things, like shells, driftwood, or lost itemsThis aligns with the phrase:Clay goes to the beach to look for stuff.', 0, 0, 0, 1790961805512) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_46b26b58cbaa19d2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is Harry''s philosophy?', '{"A":"To earn money","B":"To take time","C":"Take it easy away","D":"To depend up"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the context of the story where Harry appears (possibly a character in a humorous or slice-of-life tale), his philosophy is one of relaxed living and not worrying too much — summed up in the phrase:“Take it easy away”This reflects his laid-back, carefree attitude toward life', 0, 0, 0, 1790961805512) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_884864da2d283d1f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'How does the spaceship look?', '{"A":"Murky","B":"Shining","C":"Green","D":"Golden"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the story (likely from a science fiction narrative involving the landing of a spaceship).The spaceship is described as golden, highlighting its majestic, mysterious, or otherworldly appearanceThis detail helps to create a sense of awe and significance.', 0, 0, 0, 1790961805512) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_48e48575fed3b5ef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who brings the news of the landing of spaceship?', '{"A":"John","B":"General powers","C":"Ellen","D":"Spladings"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the story (likely a science fiction tale such as "The Last War" or similar genre), It is Spladings who informs others about the landing of the spaceship, delivering crucial news that advances the plot.', 0, 0, 0, 1790961805512) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e073cab57c7aa68f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I could have torn the child apart in my own FURY and enjoyed it. Fury means _____?', '{"A":"Dismay","B":"Embarrassment","C":"Apology","D":"Anger"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fury "شدید غصہ" یا "طیش" Anger = غصہ', 0, 0, 0, 1790961805513) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_623559bb3381f64f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She had fought VALIANTLY to keep me from unknowing secrets. Valiantly means ______?', '{"A":"Heroically","B":"Devilishly","C":"Violently","D":"Eccentrically"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Valiantly "بہادری سے" یا "دلیری سے"Heroically = بہادری سے / دلیر انداز میں', 0, 0, 0, 1790961805513) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_badfce5eb5548fb3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Perhaps I should have DESISTED and come back in an hour or more. Desisted means _____?', '{"A":"Resisted","B":"Discontinued","C":"Consented","D":"Proceeded"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Desisted "باز آنا" یا "رک جانا" Discontinued = بند کرنا / ترک کرنا', 0, 0, 0, 1790961805513) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_25235ae16f4e4fcc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She fought with CLENCHED teeth desperately. Clenched means _____?', '{"A":"Guarded","B":"Clasped","C":"Repressed","D":"Drenched"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Clenched "بھینچے ہوئے" (مثلاً دانت یا مٹھی سختی سے بند کرنا)Clasped = مضبوطی سے پکڑا ہوا / بند کیا ہوا', 0, 0, 0, 1790961805603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8c03908054a46956', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The sick girl shrieked "hysterically". Hysterically means ____?', '{"A":"Wildly","B":"Calmly","C":"Peacefully","D":"Delightfully"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hysterically means with uncontrolled extreme emotion, especially fear or panic. Wildly means a lack of control in emotion or behavior.Hysterically means غیر منسلک انتہائی جذبات کے ساتھ، خاص طور پر خوف یا خوفناکWildly means جذبات یا طرز عمل میں کنٹرول کا فقدان', 0, 0, 0, 1790961805603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a8bbd668a75d9f5f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What did Gorgios go to create post?', '{"A":"Politics","B":"Theater","C":"Cinema","D":"Circus"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gorgios becomes associated with creating or starting a circus, often as a way to make money or entertain.This refers to the short story "The Man Who Had No Eyes."', 0, 0, 0, 1790961805603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9301b79fe46853a8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Who disagreed with Jorkens about determination?', '{"A":"Hubert","B":"James","C":"Terbut","D":"David"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the story featuring Mr. Jorkens (a character from Lord Dunsany''s tales), Terbut is the one who disagrees with Jorkens’ views on determination. Their discussion at the club revolves around whether success comes more from determination or from opportunity.', 0, 0, 0, 1790961805603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_43ffe7760ee816ff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What was the subject of discussion at the club?', '{"A":"Determination and Opportunity","B":"Theft","C":"Sports","D":"Education"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In "Goodbye, Mr. Chips", there is a scene at the club where the discussion revolves around the themes of determination and opportunity, reflecting on how people rise in life through effort or circumstance.', 0, 0, 0, 1790961805603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1bcb0a860a72cc42', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The teacher is very popular ____ his students.', '{"A":"In","B":"On","C":"At","D":"With"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The corrected sentence would be: "The teacher is popular with his students."This means that the students like and admire the teacher."استاد اپنے طلباء میں مقبول ہوتا ہے۔"', 0, 0, 0, 1790961805603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f840ab861b217d39', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He has/You have no sympathy ______ the beggars/poor.', '{"A":"To","B":"At","C":"For","D":"In"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sympathy for someone means کسی کیلئے ہمدردی ہونا Examples: He has no sympathy for beggars. I have no sympathy for you.I have no sympathy for him.I have no sympathy for poor.', 0, 0, 0, 1790961805603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bb86d0b975d91b9f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Necessity is the mother of ______?', '{"A":"Invention","B":"Adventure","C":"Discovery","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is a well-known proverb: "Necessity is the mother of invention."It means that needs and problems inspire creative solutions.Necessity ضرورتInvention ایجاد', 0, 0, 0, 1790961805603) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e6db6fdf48b4d80a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is _____ film that I have ever seen.', '{"A":"The worse","B":"The worst","C":"Worst","D":"Worse"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It is the worst film that I have ever seen.یہ سب سے بری فلم ہے جو میں نے کبھی دیکھی ہے۔"The worst" is used to describe something as the lowest in quality compared to all others.', 0, 0, 0, 1790961805692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c5183f47980b5fd0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am very much ________ to meet you.', '{"A":"Delighted","B":"Delighting","C":"Delight to","D":"Delight"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I am very very much delighted to meet you meansمیں آپ سے ملنے کیلئے بے قرار ہوںDelighted means: you are extremely pleased and excited about something"Delighted" is best to keep the meaning of the original sentence.', 0, 0, 0, 1790961805692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ac3d733f2cc8abc8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The government which is ruled by a king or queen is _____?', '{"A":"Monarchy","B":"Oligarchy","C":"Plutocracy","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Monarchy means بادشاہت یا سلطنتMonarch means بادشاہ یا سلطانA government ruled by a king or queen is called a Monarchy.In a monarchy, power is usually inherited and passed through a royal family.', 0, 0, 0, 1790961805692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_569d3c96ea11781b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You may relay _____ our doing our utmost.', '{"A":"On","B":"With","C":"By","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrase is "rely on," meaning to depend or trust."You may rely on our doing our utmost" is the grammatically correct form.Relay on means انحصار کرنے یا اعتماد کرنے کے لئے', 0, 0, 0, 1790961805692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_914abbd2f237cad8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Do you understand what I mean?', '{"A":"What I mean is that understood by you?","B":"Was what I mean understood by you?","C":"Is what I mean understood by you?","D":"What I mean is understood by you?","E":"All of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is an interrogative sentence of Present Indefinite Tense.Present Indefinite TenseActive Voice: Subject + Verb + Object Passive Voice: Object + is/am/are+ third form of a verb + by + subject.', 0, 0, 0, 1790961805692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_581f2854e2065023', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You will go, or you will miss the train. It is which type of sentence?', '{"A":"Complex","B":"Compound","C":"Reflexive","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "You will go, or you will miss the train" is a compound sentence Because it contains two independent clauses ("You will go" and "you will miss the train") joined by the coordinating conjunction "or". Both clauses can stand alone as complete thoughts and express a complete idea,', 0, 0, 0, 1790961805692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0b24441de7a689a2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We knocked on the door but nobody answered. But is which part of speech?', '{"A":"Adverb","B":"Conjunction","C":"Interjection","D":"Adjective"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "But" connects two clauses, showing contrast.Thus, it is a conjunction.', 0, 0, 0, 1790961805692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_22e0fe5a2c7d33a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I don’t mind ______ if you are tired.', '{"A":"Driving","B":"To Drive","C":"Drive","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I don’t mind driving if you are tired.اگر آپ تھکے ہوئے ہیں تو مجھے گاڑی چلانے میں کوئی اعتراض نہیں ہے۔"Driving" is the correct form as it follows the verb "mind," which is typically followed by a gerund (verb + ing).', 0, 0, 0, 1790961805692) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d5686f37aa6675ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Change Voice: The Doctor bandaged the arm of the injured man.', '{"A":"The arm of the injured man was bandaged by the doctor.","B":"The injured man bandaged his arm.","C":"The injured man made the doctor injure his arm.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The arm of the injured man was bandaged by the doctor.This sentence is in the passive voice, which means the focus is on the action (bandaging) rather than the person performing the action (the doctor).The original sentence, "The Doctor bandaged the arm of the injured man," is in the active voice.', 0, 0, 0, 1790961805777) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8b1f1589a3054041', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'To pull socks up means _____?', '{"A":"To start","B":"To get ready","C":"Already late","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "To pull socks up" is an idiomatic expression that means to get ready, prepare oneself, or to make an effort to improve one''s performance or situation.It is often used to encourage someone to take action, work harder, or to improve their behavior.', 0, 0, 0, 1790961805777) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6b5655d5100775d2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is good _____ playing the piano.', '{"A":"At","B":"In","C":"On","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He is good at playing the piano.وہ پیانو بجانے میں اچھا ہے۔The correct preposition after "good" when referring to a skill or activity is "at."Example: She is good at singing.', 0, 0, 0, 1790961805777) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5906e85701a2e130', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'That doll is beautiful. The word "beautiful" is?', '{"A":"Adjective","B":"Noun","C":"Pronoun","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word "beautiful" describes the appearance of the noun "doll."It functioning as an adjective in the sentence.', 0, 0, 0, 1790961805777) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_df5abd81163f97d2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'To lay ______ something for rainy day.', '{"A":"By","B":"From","C":"To","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrase is "to lay by something for a rainy day."It means to save or set aside resources for future use.It especially in times of need or difficulty.', 0, 0, 0, 1790961805778) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_da12c7624e822b99', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Neither John nor his friends ____ present at that party.', '{"A":"Was","B":"Were","C":"Had","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When using "Neither...nor," the verb agrees with the noun closest to it."Friends" is plural, so the correct verb is "were."', 0, 0, 0, 1790961805778) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b725293dfd1628d1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Identify the gerund in the sentence: "Swimming is my favorite activity."', '{"A":"Activity","B":"Favorite","C":"Swimming","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A gerund is a verb ending in "-ing" that functions as a noun.In the sentence, "Swimming" acts as the subject and is a gerund.', 0, 0, 0, 1790961805778) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_20d1b3b23b95f092', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Mother congratulation the the son _______ his success.', '{"A":"To","B":"With","C":"On","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mother congratulation the the son on his success.ماں نے اپنے بیٹے کو کامیابی پر مبارکباد دی۔"On" is used to indicate the reason for the congratulation. In this case, it correctly connects the verb "congratulation" to the event of "success."', 0, 0, 0, 1790961805778) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8bc109263cad0fef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A group of birds or flock flying together in hundred or even in thousands is called ________?', '{"A":"Maturation","B":"Murmuration","C":"Both A and B","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Flock" is a general collective noun commonly used for a group of birds."Flight of birds" refers to birds flying together in the air."Murmuration" specifically describes a large, swirling group of starlings flying together in formation.', 0, 0, 0, 1790961805849) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_64bd33f1e7e0b573', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Warm is to hot as old is to _____?', '{"A":"Oldest","B":"Elderly","C":"Young","D":"Boldest"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The analogy is:Warm (less intense) → Hot (more intense)Old (less intense) → Elderly (more intense)***', 0, 0, 0, 1790961805849) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1c7863a9e36c31c6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My friend will accede ______ my wishes in this matter.', '{"A":"With","B":"For","C":"To","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "accede to" means to agree or consent to a request or wish."My Friend will accede to my wishes in this matter."میرا دوست اس معاملے میں میری خواہشات پر عمل پیرا ہوگا۔', 0, 0, 0, 1790961805849) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3f697dafcf699e17', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He kept me _______?', '{"A":"Waits","B":"Waiting","C":"Waited","D":"Wait"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct expression is "kept me waiting", where "waiting" is the present participle, indicating an ongoing action.It means he made me wait for a period of time.', 0, 0, 0, 1790961805849) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_baf9962ebbf8185b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A ________ opportunity never returns.', '{"A":"Losing","B":"Lost","C":"Lose","D":"Loss"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrase is "A lost opportunity never returns".Because "lost" is the past participle used to describe the opportunity that has already passed.It emphasizes that once an opportunity is missed, it doesn''t come back.', 0, 0, 0, 1790961805850) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c36f066fe0e08e6d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'His _____ coat needs mending.', '{"A":"Tattered","B":"Tatter","C":"Tettering","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation His tattered coat needs mending means اس کے پھٹے ہوئے کوٹ کو ٹھیک کرنے کی ضرورت ہے"Tattered" is the correct adjective meaning torn or worn out.The sentence needs an adjective to describe the condition of the coat — hence, "tattered coat" fits best.', 0, 0, 0, 1790961805850) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1b297c42bf5712fe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Do you still live in _______ Peshawar?', '{"A":"A","B":"An","C":"The","D":"No article"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We do not use an article before the names of most cities, including Peshawar.The sentence is correct as: "Do you still live in Peshawar?"', 0, 0, 0, 1790961805850) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5545ddd099ab375f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The multiple-word conjunction EITHER-OR, NEITHER-NOR, and NOT-ONLY, BUT-ALSO are called _______conjunction.', '{"A":"Addition","B":"Correlative","C":"Alternative","D":"Contrast"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Correlative conjunctions are pairs such as neither . . . nor, not . . . only, and but . . . also.These conjunctions connect two balanced clauses, phrases, or words.', 0, 0, 0, 1790961805850) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d3fa061e350bd42d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She bought it for herself. Here ''herself'' is?', '{"A":"Reflexive pronoun","B":"Personal pronoun","C":"Demonstrative pronoun","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ''Herself'' reflects back to the subject ''She'', showing the action is done by the subject to herself.Reflexive pronouns end in -self or -selves.They are used when the subject and object are the same person.', 0, 0, 0, 1790961805934) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_876f69ef9bd2d11d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'There are several mistakes in your composition. Here ''several'' is?', '{"A":"Quantity adjective","B":"Adjective of number","C":"Both A and B","D":"Quality adjective"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Several" refers to an indefinite number, indicating how many mistakes — qualifying it as an Adjective of Number.It also shows quantity (not exact), so it works as a Quantity Adjective too.', 0, 0, 0, 1790961805934) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d436e253aa327924', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He suggests that the meeting _____ postponed.', '{"A":"Be","B":"Would be","C":"Is","D":"Must"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In formal English, after verbs like "suggest," "recommend," "insist," we use the subjunctive mood. The subjunctive uses the base form of the verb (without "to") regardless of the subject.', 0, 0, 0, 1790961805934) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4fc20647585078b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The frog hurt itself while playing. Here ''itself'' is?', '{"A":"Reflective pronoun","B":"Adverb of frequency","C":"Adverb of action","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Itself reflects the action back to the subject (the frog).Reflexive pronouns are used when the subject and object are the same.', 0, 0, 0, 1790961805934) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_aadaff789e86f9b1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She was afraid _____ snakes.', '{"A":"By","B":"From","C":"Of","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct preposition after "afraid" is "of".So, the correct sentence is: "She was afraid of snakes."', 0, 0, 0, 1790961805934) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6a3ecffb6848bae9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He still lives here. Here ''still'' is?', '{"A":"Adjective","B":"Adverb","C":"Conjunction","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Still is modifying the verb lives, showing that the action continues.Adverbs describe how, when, where, or to what extent something happens—still tells when in this case.', 0, 0, 0, 1790961805934) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3fdf62220db28481', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Identify the type of sentence: Drive to the roundabout and then turn left.', '{"A":"Imperative sentence","B":"Exclamatory sentence","C":"Conditional sentence","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence "Drive to the roundabout and then turn left" gives a command or instruction.Sentences that give orders, directions, or requests are called imperative sentences.', 0, 0, 0, 1790961805934) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b8bd5d028d18e4ba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Decorate this wall. Which type of sentence it is?', '{"A":"Imperative","B":"Interrogative","C":"Optative","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Imperative sentences give commands, requests, or instructions (e.g., "Decorate this wall.").They usually begin with the base form of a verb and may not have a stated subject.', 0, 0, 0, 1790961805934) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1e7a17b024c5687e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The petrol boat picked up signals of a ship in _____?', '{"A":"Distress","B":"Distressed","C":"Distressing","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "The petrol boat picked up signals of a ship in distress." "Distress" is a noun that refers to a state of danger or emergency. "Distressed" is an adjective, but it doesn’t fit the grammatical structure of the sentence. "Distressing" is a present participle/adjective that refers to something causing distress, but here we need the noun "distress".', 0, 0, 0, 1790961806018) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_991fe73e704d9e3f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'As it was a minor _______ the traffic policeman let him off with the warning.', '{"A":"Offend","B":"Offence","C":"Offender","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "As it was a minor offence, the traffic policeman let him off with a warning." "Offence" (noun) means a violation or a wrongdoing, especially of a law or rule. The sentence is talking about a small violation, so "minor offence" is the correct phrase.', 0, 0, 0, 1790961806018) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_40ffcfcb1b3ddb82', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '______ people do not spend their money foolishly.', '{"A":"Wise","B":"Wisely","C":"Wisdom","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Wise people do not spend their money foolishly." "Wise" is an adjective describing people. We use adjectives before nouns (e.g., wise people). "Wisely" is an adverb, and "wisdom" is a noun — both do not fit here.', 0, 0, 0, 1790961806018) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d8a3793503644cce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'An honest person always speaks the ______?', '{"A":"True","B":"Truth","C":"Truly","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "An honest person always speaks the truth." "Truth" is a noun and is the correct object of the verb "speaks". "True" is an adjective, and "truly" is an adverb — neither fits grammatically here.', 0, 0, 0, 1790961806018) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a25cda336c38a489', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I laughed _____ him _____ making silly mistake.', '{"A":"On, for","B":"On, of","C":"At, for","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "I laughed at him for making a silly mistake." "Laughed at" is the correct phrase used when you are mocking "For" is used to explain the reason for the action (in this case, making a silly mistake).', 0, 0, 0, 1790961806018) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bd470e6dbfb2c8c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Even his opponents admit that he is endowed_____ rare talents.', '{"A":"Of","B":"With","C":"At","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Even his opponents admit that he is endowed with rare talents." The verb "endowed" is commonly followed by "with" when describing the possession of a particular quality or talent. "With" is the correct preposition in this context.', 0, 0, 0, 1790961806018) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0c21d679e7c31b16', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He seems to be quite contented _______ his life.', '{"A":"At","B":"of","C":"With","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "He seems to be quite contented with his life.""Contented" is commonly followed by "with" to indicate satisfaction or happiness with something."With" is the correct preposition in this context.', 0, 0, 0, 1790961806018) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_07f65a4a4946be20', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Two and two make four. The word AND is ______?', '{"A":"Co-ordinate","B":"Subordinate","C":"Adversative","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A coordinating conjunction is a word that joins two elements of equal grammatical rank and syntactic importance. They can join two verbs, two nouns, two adjectives, two phrases, or two independent clauses. The seven coordinating conjunctions are for, and, nor, but, or, yet, and so.', 0, 0, 0, 1790961806018) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e2c9ed24e4ce5293', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The ship is going slowly. Here ''slowly'' is ____?', '{"A":"Adverb","B":"Adjective","C":"Verb","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An adverb is a word or an expression that generally modifies a verb, adjective, another adverb, determiner, clause, preposition, or sentence. Adverbs typically express manner, place, time, frequency, degree, level of certainty, etc., answering questions such as how, in what way, when, where, to what extent.', 0, 0, 0, 1790961806098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_921342bc9214c3f1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He does not care ___ losing his job.', '{"A":"About","B":"At","C":"To","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct preposition after "care" in this context is "about.""Care about" means to be concerned or worried regarding something.', 0, 0, 0, 1790961806098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_806435b8d13f1a6f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_______ I have some more tea please?', '{"A":"Shall","B":"Would","C":"Could","D":"May"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Could is a modal verb.Could can be used for polite/formal request.Could I have some more tea please? کیا میں مزید چائے پی سکتا ہوں؟', 0, 0, 0, 1790961806098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_669269b5fe53d743', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Ms. Kate ____ her youngest child for three years.', '{"A":"Is nursing","B":"Will been nursing","C":"Has been nursing","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Here three years indicate that this sentence belongs to Present Continuous Tense. We use has been + ing form of verb with singular subject in this tense.She has been nursing her youngest child for three yearsوہ تین سال سے اپنے سب سے چھوٹے بچے کی پرورش کر رہی ہے۔', 0, 0, 0, 1790961806098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dbe9aa94d1837018', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'If you work in collaboration, you _____ rapid progress.', '{"A":"Would make","B":"Will make","C":"Will be making","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Formula of First conditional sentence: If/when + present simple >> will + infinitiveIf you work in collaboration, you will make rapid progress.اگر آپ تعاون سے کام کریں گے تو آپ تیزی سے ترقی کریں گے', 0, 0, 0, 1790961806098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eadae0f31304db42', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The examiner _____ that the candidate was cheating.', '{"A":"Knows","B":"Known","C":"Knew","D":"Knowing"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Here was cheating shows past tense.We use second form of verb (knew) in simple sentence of Past Indefinite Tense.The examiner knew that the candidate was cheating.امتحان دینے والے کو معلوم تھا کہ امیدوار دھوکہ دے رہا ہے۔', 0, 0, 0, 1790961806098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_49ad958e9039dcfd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Many things happened ________ I left the school.', '{"A":"Because","B":"But","C":"Since","D":"Until"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Since" is used to indicate the time from a past event up to now or another point in the past.The sentence refers to events that occurred after the speaker left school — so "since I left the school" is correct.', 0, 0, 0, 1790961806098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_83e714920100aa9a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My parents _____ this car for about ten years.', '{"A":"Have been","B":"Have had","C":"Have","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Have had" is the correct present perfect tense to show ownership continuing from the past to the present."Have been" requires a verb ending in -ing, which is not present here.', 0, 0, 0, 1790961806098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8cbc629a3728225f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The Prime Minister "declassified" the government document. What does this imply?', '{"A":"Released","B":"Segregated","C":"Formed","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Declassified means making information public by removing its confidential status.The government document was released for public access or transparency.', 0, 0, 0, 1790961806171) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7bdcd609a1cbd1f5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Meaning of the word "En masse"?', '{"A":"On the way","B":"All together","C":"Genuine","D":"Actual"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "En masse" is a French phrase that means "all together" or "as a whole". It is used to describe a group of people or things doing something simultaneously or in a collective manner.Example: "The crowd moved en masse to the exit when the fire alarm sounded."', 0, 0, 0, 1790961806171) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8d760c9f1d291329', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The tree stands ______ the wall.', '{"A":"Beside","B":"Near","C":"Besides","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Beside" means next to or by the side of (the tree is positioned directly adjacent to the wall).Example: "The tree stands beside the wall."', 0, 0, 0, 1790961806171) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e4661705ea566b33', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Take these to the clerk. Here ''these'' is ____?', '{"A":"Demonstrative pronoun","B":"Indefinite pronoun","C":"Possessive pronoun","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ''These'' is a demonstrative pronoun because it points to specific things (in this case, objects being taken to the clerk). Indefinite pronouns (e.g., someone, anything) do not specify particular items.Possessive pronouns (e.g., his, theirs) show ownership.', 0, 0, 0, 1790961806172) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8375921950f8cceb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Noor Fatima falls _____ the horse.', '{"A":"From","B":"Of","C":"Off","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Noor Fatima falls off the horse.""Off" is used to indicate a movement away from a surface or position.', 0, 0, 0, 1790961806172) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_10e4e52ddac8aabd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The sun rises ______ the East.', '{"A":"From","B":"In","C":"At","D":"On"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase should be: "The sun rises in the East".It indicating the location or direction where the sun rises.', 0, 0, 0, 1790961806172) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a737c2a2f592821f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is as easy to do it right as ____?', '{"A":"To do","B":"Doing","C":"Do","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It is as easy to do it right as do. یہ کرنا اتنا ہی آسان ہے جتنا صحیح کرناDo is best to keep the meaning of the original sentence.Do is an irregular verb.Sh4-8-2023', 0, 0, 0, 1790961806172) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_185bf4ec8747cdb4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am totally agreed _____ your proposal.', '{"A":"To","B":"From","C":"With","D":"On"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrase is "agree with" when expressing agreement with a proposal or opinion.Example: I am totally agreed with your proposal.', 0, 0, 0, 1790961806172) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_22726d2c3fb89d50', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Call on means ______?', '{"A":"Doubtful","B":"Prove a theory","C":"Pay a visit to someone","D":"Summon as a witness"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Call on means کال آن کا مطلب ہےPay a visit to someone means کسی سے ملاحظہ کریںThe idiom "call on" commonly means to visit someone, especially formally or socially.Example: She decided to call on her grandmother over the weekend.', 0, 0, 0, 1790961806246) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3c859ef2543f9946', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He died _____ fever?', '{"A":"From","B":"By","C":"Of","D":"In"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct preposition to indicate cause of death due to illness is "of".He died of fever.وہ بخار سے مر گیا۔', 0, 0, 0, 1790961806246) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_75bd87a5c2da8f00', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose analogous pair: Chalk : Blackboard ::?', '{"A":"Type : Paint","B":"Table : Chair","C":"Ink : Paper","D":"Door : Handle"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chalk : Blackboard Ink : PaperChalk is used to write on the blackboard. Similarly, ink is used to write on paper.', 0, 0, 0, 1790961806246) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_52aac26ef65038cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She admitted ______ her mistake.', '{"A":"Me","B":"To me","C":"For me","D":"Non of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She admitted me her mistake. اس نے مجھے اپنی غلطی تسلیم کر لی۔Me is best to keep the meaning of the original sentence.me is an objective pronoun.', 0, 0, 0, 1790961806246) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_38b0d1c9b068e3d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It has been raining _____ an hour.', '{"A":"Since","B":"From","C":"For","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "It has been raining for an hour.""For" is used to indicate the duration of time.', 0, 0, 0, 1790961806246) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4cf7b90a855b2296', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is interested ____________ learning Spanish.', '{"A":"With","B":"In","C":"At","D":"On"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Interested In ہمیشہ انٹرسٹڈ کے ساتھ ان آتا ہے********He is interested in learning Spanish.اسے ہسپانوی سیکھنے میں دلچسپی ہے', 0, 0, 0, 1790961806246) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2d88ceeb632a1c92', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_______ cow is a useful animal.', '{"A":"Many","B":"Those","C":"The","D":"As"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The cow is a useful animal. The definite article "the" specifies a particular cow or cows in general.', 0, 0, 0, 1790961806246) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c5750373d0975672', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The vowel used in cool is _____?', '{"A":"/u:/","B":"/u/","C":"/a/","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The vowel sound in "cool" is a long vowel sound, pronounced /u:/ as in "food."It is held longer than the short /u/ sound.', 0, 0, 0, 1790961806246) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ceced65b5e827c39', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Now I am free. The subject predicate division for this sentence is ____?', '{"A":"Now I | am free.","B":"Now | I am free.","C":"Now I am free","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Subject: "Now I" – includes the time reference "Now" and the pronoun "I".Predicate: "am free" – tells what the subject is or does.', 0, 0, 0, 1790961806319) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f8c68f5cd0b13f76', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which of the following is an adverb? Unwisely, Wise, Happy, Good', '{"A":"Unwisely","B":"Wise","C":"Happy","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Unwisely describes how an action is done, which is the role of an adverb.The suffix -ly often indicates an adverb formed from an adjective (e.g., "wise" → "unwisely").', 0, 0, 0, 1790961806319) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bcd9c529e6852c3e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Last night she sets the cake on the table. Here ''she sets'' is?', '{"A":"She sat","B":"She set","C":"She settled","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The verb "sets" is present tense, but the sentence begins with "Last night," requiring past tense.The past tense of "set" is also "set", so the correct form is "she set."', 0, 0, 0, 1790961806319) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_21557be902456a7c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She is _______ with her doll.', '{"A":"Play","B":"Plays","C":"Playing","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She is playing with her doll.It uses the present continuous tense to describe an action that is happening right now.', 0, 0, 0, 1790961806319) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0c7d3aa185512f79', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The adverb of abrupt is _____?', '{"A":"Abrupt","B":"Abruption","C":"Abruptly","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Abruptly" is the adverb form of the adjective "abrupt", describing how an action is done.The suffix "-ly" typically turns adjectives into adverbs.', 0, 0, 0, 1790961806319) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e4507da4d230ebb7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which part of speech joins words, phrases, or clauses together?', '{"A":"Noun","B":"Adverb","C":"Conjunction","D":"Interjection"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The part of speech that joins words, phrases, or clauses together is a Conjunction.Conjunctions like "and," "but," and "or" link different parts of a sentence to provide cohesion and clarity.', 0, 0, 0, 1790961806319) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4e0963eddea0a622', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Because his father was away ______ he did not go to town.', '{"A":"?","B":",","C":"!","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The comma connects the dependent clause "Because his father was away" to the main clause.It correctly separates the reason from the result in the sentence.', 0, 0, 0, 1790961806319) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_78ebc19564a0ada8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I do not have much _____ its just two small bags.', '{"A":"Bags","B":"Space","C":"Luggage","D":"Weight"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Luggage" is an uncountable noun used to refer to bags and suitcases collectively.The sentence means the speaker has only a small amount of luggage (just two bags).Luggage means سامان', 0, 0, 0, 1790961806319) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_14f0b11c0ee5c5cf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is the feminine of Bachelor?', '{"A":"Spinster","B":"Mistress","C":"Lady","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Spinster" is traditionally used as the feminine form of "Bachelor".It referring to an unmarried woman.Bachelor means کَنواراSpinster means کواری', 0, 0, 0, 1790961806381) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_052d464272e5e559', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Hurrah! We have got the prize. Which kind of sentence is this?', '{"A":"Sentence of Request","B":"Sentence of Order","C":"Exclamatory sentence","D":"Interrogative Sentence"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence "Hurrah! We have got the prize" is an exclamatory sentence, which is used to express strong emotions such as joy, excitement, or surprise.It is characterized by the use of words like "Hurrah", "Hurray", "Wow", and "Ah".It is typically punctuated with an exclamation mark (!).Exclamatory sentences are used to express sudden feelings or reactions.', 0, 0, 0, 1790961806381) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_264361a881bfd4f9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The streets of Peshawar are worse than those of Lahore. Here ''those'' is?', '{"A":"Relative pronoun","B":"Demonstrative pronoun","C":"Indefinite pronoun","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Those" refers to "the streets (of Lahore)" mentioned earlier.It is a demonstrative pronoun used to point out specific things.', 0, 0, 0, 1790961806381) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0328bb56ea6eb9f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the part of sentence: The hour to prepare lesson "has arrived".', '{"A":"Predicate","B":"Subject","C":"Preposition","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Has arrived" is the verb phrase that tells what the subject (The hour to prepare lesson) has done. A predicate includes the verb and provides information about the subject.', 0, 0, 0, 1790961806381) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c7fc1e705c5ecea2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I prefer to ride my bike _____ the hill.', '{"A":"Down","B":"From","C":"On","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When moving from a higher place to a lower place, we use "down" (e.g., ride down the hill).So, "I prefer to ride my bike down the hill" is correct.', 0, 0, 0, 1790961806381) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5e2fb929a8c5a27c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The street runs _____ the sea font.', '{"A":"Across","B":"Along","C":"From","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Along" means following the length or edge of something, like the sea front.So, the street runs along the sea front, following its direction.', 0, 0, 0, 1790961806381) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_86bdd9394741c000', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The boat will take you _____ the river.', '{"A":"At","B":"Across","C":"In","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The boat moves from one side to the other side of the river, so "across" is used."Across the river" means crossing over the river.', 0, 0, 0, 1790961806381) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_89209a9fabe5d2d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Her apartment is _____ the second floor.', '{"A":"At","B":"In","C":"On","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use "on" for floors in a building (e.g., on the second floor).So, "Her apartment is on the second floor" is correct.', 0, 0, 0, 1790961806381) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_123f34601ff304e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is ______ home.', '{"A":"In","B":"By","C":"At","D":"With"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We commonly use "at home" to indicate someone''s location.So, "He is at home" is the correct phrase.', 0, 0, 0, 1790961806454) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_193d19caa9f52a6c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We took a trip ____ town last week.', '{"A":"To","B":"From","C":"In","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "To" is used to indicate movement toward a place.So, "We took a trip to town last week" is the correct sentence.', 0, 0, 0, 1790961806454) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_26949173c34749c0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'When we got ready for dinner, I had to take my book _____ the table.', '{"A":"Far","B":"From","C":"At","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "From" is used to show removal or separation (taking something away).So, "I had to take my book from the table" is correct.', 0, 0, 0, 1790961806454) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d1faaa6fb8e5420d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My sister sat _____ my mom in the bus.', '{"A":"With","B":"By","C":"On","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "By" means next to or beside someone.So, "My sister sat by my mom in the bus" is the correct sentence.', 0, 0, 0, 1790961806454) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d24a80ad22407814', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I bought some milk _____ the grocery store.', '{"A":"With","B":"From","C":"In","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "From" shows the source or place where something was obtained.So, "I bought some milk from the grocery store" is correct.', 0, 0, 0, 1790961806454) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2af2732be8c3ce40', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The princess  lives _____ the castle.', '{"A":"With","B":"By","C":"In","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use "in" to show that someone lives inside a place like a castle.So, "The princess lives in the castle" is the correct usage.', 0, 0, 0, 1790961806454) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_885db2f719bd1c01', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Mother prepares chicken _____ than grandmother.', '{"A":"Best","B":"Good","C":"Better","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Better" is the correct comparative form of "good" used to compare two people.It shows that mother’s chicken preparation is of higher quality than grandmother’s.', 0, 0, 0, 1790961806454) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a49bbda9e038edab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Mrs. Haseeb speaks _____ than Mrs. Amir.', '{"A":"More clearly","B":"Clearly","C":"Very clearly","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When comparing how two people speak, use the comparative form "more clearly" with an adverb of more than one syllable."Clearly" alone is positive.', 0, 0, 0, 1790961806454) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_31e68d6a23d63141', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Your husband Kamal writes _____ of all.', '{"A":"Better","B":"Best","C":"The best","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "The best" is the superlative form used when comparing one person against all others.It means Kamal writes better than everyone else.', 0, 0, 0, 1790961806531) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cb49ca420afdf9a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My sister looked _____ than Amara.', '{"A":"Most beautiful","B":"More beautiful","C":"Beautiful","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When comparing two people, we use "more beautiful" (comparative form of "beautiful")."Most beautiful" is used when comparing more than two.', 0, 0, 0, 1790961806531) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_46c169ae450dc352', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My father arrived ____ than the rest of family.', '{"A":"Latest","B":"Late","C":"Later","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Later" is the correct comparative form of "late" used when comparing two or more people''s arrival times.The sentence compares the father''s arrival to the rest of the family, so "later" fits best.', 0, 0, 0, 1790961806531) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_70a77167c4c431b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which of the following is an anagram of Listen?', '{"A":"Listed","B":"Silent","C":"Lister","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An anagram is formed by rearranging the letters of a word to form a new word."Silent" is an anagram of "Listen" as it uses the exact same letters in a different order.', 0, 0, 0, 1790961806531) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dbe09d65d6eb917b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The feminine gender of Fox is?', '{"A":"Vixen","B":"Cat","C":"Jackal","D":"Bitch"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fox means لومڑVixen means لومڑی', 0, 0, 0, 1790961806531) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_69029d5724f13bf5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which of the following is a prefix? un, ness, ful, None of these', '{"A":"-er","B":"-ing","C":"un-","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A prefix is a group of letters added at the beginning of a word to change its meaning."un-" is a prefix meaning "not" (e.g., unhappy = not happy)', 0, 0, 0, 1790961806531) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_34f581556bd81eab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Can you see that blue car? Here ''that'' is?', '{"A":"Indefinite adjective","B":"Demonstrative adjective","C":"Possessive adjective","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "That" is used to point out a specific noun (blue car), making it a demonstrative adjective.Indefinite adjectives (e.g., some, many) do not specify a particular noun.', 0, 0, 0, 1790961806531) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_65bda6379e050f67', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'According to "Dreams", what will happen if our dreams die?', '{"A":"Life will be real","B":"Life will be hopeless","C":"Life will be a punishment","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the poem "Dreams" by Langston Hughes, it’s emphasized that without dreams, life loses purpose and becomes bleak.The poet compares life without dreams to a "broken-winged bird" — unable to fly, symbolizing hopelessness.', 0, 0, 0, 1790961806531) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2da0ccc1e2038b0c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Cannon had ________ unique qualities _________ it was used widely in ancient times.', '{"A":"Such, that","B":"Such, so","C":"That, since","D":"That, that"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Such means of type about to be mentioned.That is used refer specific things mentioned earlier. Such means ایساThat means جو', 0, 0, 0, 1790961806605) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a5c93b439d1c27f2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Insert quotation marks where necessary?', '{"A":"She''s been known to sing beautifully, commented \"Ali\".","B":"\"She''s been known to sing beautifully\", commented Ali.","C":"She''s been known to sing beautifully, \"commented Ali\".","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct punctuated sentence is:"She''s been known to sing beautifully," commented AliQuotation marks must enclose the exact spoken words: "She''s been known to sing beautifully"A comma is used to separate the quotation from the dialogue tag (commented Ali).The comma always goes inside the quotation marks.', 0, 0, 0, 1790961806606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dbb107d3b6875e41', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The word PERSEVERANCE means?', '{"A":"Debate","B":"Compassion","C":"Persistence","D":"Gracious"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PERSEVERANCE means استقامتPersistence means ثابت قدمی', 0, 0, 0, 1790961806606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_25003cab63622e19', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I have not seen her _______ June.', '{"A":"Since","B":"For","C":"In","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "I have not seen her since June."میں نے اسے جون سے نہیں دیکھا۔"Since" is used to indicate a starting point in time for something that continues to the present.', 0, 0, 0, 1790961806606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d1141cde7185f49c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Do you like sailing on the lake? Here ''sailing on the lake'' is?', '{"A":"Gerund phrase","B":"Adjective clause","C":"Main clause","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Sailing on the lake" acts as the object of the verb "like" — this shows it functions as a noun.Since it begins with a verb in -ing form ("sailing") and acts as a noun, it''s a gerund phrase.', 0, 0, 0, 1790961806606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_77455ab1e1b3de04', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The secret of visit to his aunt was know by few. Here ''few'' is?', '{"A":"Possessive pronoun","B":"Indefinite pronoun","C":"Demonstrative pronoun","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Few" is an indefinite pronoun because it refers to an unspecified number of people.Indefinite pronouns do not point to any particular person or thing, e.g., few, some, many, several.', 0, 0, 0, 1790961806606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b53ef975ddcae1f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What punctuation mark is generally used before certain coordinating conjunctions?', '{"A":"Comma","B":"Hyphen","C":"Full stop","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A comma is generally used before coordinating conjunctions like and, but, or, nor, for, so, yet when joining two independent clauses.Example: She was tired, but she kept working.', 0, 0, 0, 1790961806606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c777f18b9b8c0d6b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Do you have ____ broom? I drooped ____ piece of cake and i need to clean it up.', '{"A":"A/a","B":"The/a","C":"An/the","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Do you have a broom?" – we use "a" before singular countable nouns that are mentioned for the first time."I dropped a piece of cake" – again, "a" is used as it''s a non-specific, singular item.', 0, 0, 0, 1790961806606) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_01e5b7e04aa2dd24', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She laughed at the joke. Here laughed is a an _____?', '{"A":"Transitive Verb","B":"Intransitive Verb","C":"Modal Verb","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Laugh is an intransitive verb and does not take any object.Laughed is the second and third form of Laugh.', 0, 0, 0, 1790961806689) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_855cfeb25ca9ee73', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the imperative sentence in the following?', '{"A":"Please sit down","B":"He likes coffee","C":"Does she not play badminton","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An imperative sentence gives a command, request, or instruction. "Please sit down" is a direct command, making it an imperative sentence.', 0, 0, 0, 1790961806689) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7342418b7e870197', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Contractions can be used in ______?', '{"A":"Informal letters","B":"Formal letters","C":"Official letters","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Contractions (like "I''m," "you''re," "don''t") are commonly used in informal writing, such as personal or friendly letters.In formal and official letters, contractions are generally avoided to maintain a more professional tone.', 0, 0, 0, 1790961806690) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a6e100f4af036e64', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose analogous pair: Light : Blind ::?', '{"A":"Speech : Dumb","B":"Tongue : Sound","C":"Language : Deaf","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Absence of Light will make Blind.Absence of Speech will make Dumb.', 0, 0, 0, 1790961806690) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_be0d62b7fbc706f9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Pain : Sedative ::?', '{"A":"Comfort : Stimulant","B":"Trance : Narcotic","C":"Grief : Consolation","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PAIN: دردSEDATIVE: سکون آورGrief: غمconsolation: تسلی******A sedative (type of drug) provides relief from Pain. Similarly, Consolation provides relief from grief.************', 0, 0, 0, 1790961806690) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_262af12fb5a926b8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Select the pair which has the same relationship: Grain : Salt ::?', '{"A":"Chip : glass","B":"Shred : wood","C":"Blades : grass","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Just as grain is a small particle of salt, a chip is a small piece of glass.The relationship is part to whole, showing a tiny fragment or unit of a larger substance.', 0, 0, 0, 1790961806690) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ce89484d6a8d4642', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Identify the three dots in the sentence: The guests ... were impressed by the library. Here three dots is?', '{"A":"Colon","B":"Ellipsis","C":"Comma","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ellipsis (…) is used to indicate a pause, omission, or unfinished thought in a sentence.In this case, it suggests missing words or an intentional pause before completing the sentence.', 0, 0, 0, 1790961806690) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_27620bd4995a81e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which of the following is an example of alliteration?', '{"A":"He is as fast as a cheetah.","B":"She sells seashells by the seashore.","C":"The moon shines brightly in the sky.","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Alliteration is the repetition of the same consonant sound at the beginning of closely connected words.In this sentence, the ‘s’ sound is repeated in “she,” “sells,” “seashells,” and “seashore.”', 0, 0, 0, 1790961806690) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ca49cd46e2a14102', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She can return tonight. Here ''can'' is?', '{"A":"Modal verb","B":"Helping verb","C":"Main verb","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Can" is a modal verb used to express possibility or ability.In the sentence, it shows the possibility of her returning tonight.', 0, 0, 0, 1790961806758) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_62cc6b1de9986523', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My father has little patience. Here the word ''little'' is an _____?', '{"A":"Adverb of praise","B":"Adverb of number","C":"Adverb of quantity","D":"Adverb of quality"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the sentence "My father has little patience," the word ''little'' modifies the noun ''patience'', indicating the amount or quantity of patience.Hence, it is an adverb of quantity, describing the degree or extent of the patience.The words like almost, just, nearly, only, quite etc. are called: Adverb of Quantity.', 0, 0, 0, 1790961806758) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8907e421c2ef3897', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The student will go camping ______ the vacation.', '{"A":"At","B":"For","C":"During","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The student will go camping during the vacation.طالب علم چھٹی کے دوران کیمپنگ میں جائے گا۔During is a preposition. It is used throughout the duration of (a period of time). By indication of "period of time throughout students vacation", we marked the option "during".', 0, 0, 0, 1790961806758) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_66c9e7c4a2089189', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is junior _____ me?', '{"A":"To","B":"Not","C":"Than","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrase is “He is junior to me”. This is because junior is a comparative adjective.that is used to show the relation between two people in terms of rank, age, or experience.Comparative adjectives like junior, senior, superior, or inferior are followed by the preposition to, not than.', 0, 0, 0, 1790961806758) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_390386c9a74139cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Where the topic sentence is generally placed in a paragraph?', '{"A":"It can be positioned anywhere","B":"In the middle of the paragraph","C":"At the start of the paragraph","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The topic sentence is usually placed at the beginning to introduce the main idea clearly.This helps readers quickly understand what the paragraph will discuss.', 0, 0, 0, 1790961806758) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5fda8e5bac3698ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Generally, children have irregular sleep patterns. Here ''generally'' is?', '{"A":"Adverb of manner","B":"Adverb of frequency","C":"Adverb of time","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Generally" indicates how often something happens, referring to the usual or common occurrence.It modifies the verb "have" to express a typical frequency of sleep patterns in children.', 0, 0, 0, 1790961806758) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_09cac0c1783f95e6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You sit on a throne of lies. The given sentence is an example of _____?', '{"A":"Personification","B":"Alliteration","C":"Metaphor","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "You sit on a throne of lies" is a metaphor because it compares lies to a throne without using "like" or "as."It implies that the person is ruling or living in falsehood, making it a direct comparison.', 0, 0, 0, 1790961806758) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_279e290b64a11b85', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '"Lord, in the morning I start each day". From which poem this line has been taken?', '{"A":"Thank You, Lord","B":"Little Things","C":"Whole Duty of Children","D":"Caterpillar"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The line "Lord, in the morning I start each day" is the opening of the poem "Thank You, Lord".It is a devotional poem expressing gratitude to God at the start of the day.E.E. Cummings, an American poet is the writer of Thank You, Lord.', 0, 0, 0, 1790961806758) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_949cff4ff0fdffd0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Hush! do not disturb me. Here ''hush!'' is?', '{"A":"Injunction","B":"Interjection","C":"Adjective","D":"Adverb"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hush! is an interjection—a sudden expression of emotion or command, often standing alone.It expresses a strong feeling (silence).It is not grammatically related to the rest of the sentence.', 0, 0, 0, 1790961806836) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f4d156cd27987593', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Identify the conditional sentence: If you study hard, you will pass the test.', '{"A":"Second Conditional","B":"Zero Conditional","C":"Third Conditional","D":"First Conditional"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Conditional is used for real and possible situations in the future.Structure: If + present simple, will + base verb→ "If you study hard, you will pass the test."', 0, 0, 0, 1790961806836) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ba12f81b7865e0ca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'This is the best _______we can do.', '{"A":"That","B":"Which","C":"Of","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is the best that we can do یہ سب سے بہتر ہے جو ہم کر سکتے ہیں۔***" that" is used as a pronoun which means: here used to identify a specific person or thing observed or heard by the speaker.', 0, 0, 0, 1790961806836) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8bbb0075c71e2889', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She _____ finish the work by tomorrow.', '{"A":"Does","B":"Has","C":"Will","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct sentence is: "She will finish the work by tomorrow.""Will" is the appropriate auxiliary verb to indicate future action.', 0, 0, 0, 1790961806836) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c5e6189a1179c8e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Could you tell me where ____?', '{"A":"The cinema is","B":"Is the cinema","C":"The cinema has","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This sentence is an indirect question, which is a polite way to ask for information.In the indirect question, we do not invert the subject and verb as we do in direct questions. Instead, the subject ("the cinema") comes before the verb ("is"), maintaining the normal subject-verb order of a declarative sentence.Therefore, the correct choice is: The cinema is', 0, 0, 0, 1790961806836) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_23d75b07943550d6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Are they hardworking _____ lazy?', '{"A":"Yet","B":"But","C":"Or","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Or" is used to show a choice or alternative between two options: hardworking or lazy.The sentence is asking which one applies, not contrasting or adding, so "or" fits best.', 0, 0, 0, 1790961806836) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_01af83c7a7ce9636', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'There were __________ people in the mall, so we weren’t completely alone.', '{"A":"A few","B":"Fewer","C":"Very little","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There were a few people in the mall, so we weren’t completely alone.“A few” is used for a small number of countable nouns like “people”.', 0, 0, 0, 1790961806836) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6920b36de6b1cdee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She wished she _____ the new car.', '{"A":"Had bought","B":"Bought","C":"Would buy","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She wished she had bought the new car.اس کی خواہش تھی کہ اس نے نئی کار خریدی ہو۔"She wished" refers to a past regret, so the past perfect "had bought" is correct.', 0, 0, 0, 1790961806836) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c3d11af91aa0bfaf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She could not refrain ____ that shedding tears.', '{"A":"To","B":"From","C":"By","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally refrain is followed by from.Refrain someone from doing something means کسی کو کسی کام کرنے سے روکنا یا منع کرنا', 0, 0, 0, 1790961806923) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6edcbefe948eb7ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We _____ the bus. Now we''ll have to walk.', '{"A":"Missed","B":"Miss","C":"Have been missed","D":"Have missed"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence should read: "We missed the bus. Now we''ll have to walk."This indicates that the bus has departed and you were not able to board it, so you will need to walk instead.', 0, 0, 0, 1790961806923) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5c23280e38951e6d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You _____ care of your health.', '{"A":"Had better to take","B":"Had better taken","C":"Had better take","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation You had better take care of your health.بہتر تھا کہ آپ اپنی صحت کا خیال رکھیں۔The phrase "had better" is used to give strong advice or a warning.It is followed by the base form of the verb.', 0, 0, 0, 1790961806923) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5d4db51dfdf14a0e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am playing football. Here ''am'' is an example of _____?', '{"A":"Auxiliary verb","B":"Irregular verb","C":"Main verb","D":"Model verb"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Is, am, are, was and were are examples of Auxiliary verbs.In the sentence "I am playing football," the word "am" is an auxiliary verb (also known as a helping verb), Which helps form the present continuous tense.The main verb here is "playing."Last updated question by NS on 11 May 2026', 0, 0, 0, 1790961806923) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_59406a8b6452ae0a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Identify the possessive pronouns?', '{"A":"His, her, ours, mine","B":"Go, eat, drink","C":"Bat, ball, pitch","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The possessive pronouns is Mine, hers, ours, and theirs.Possessive pronouns show ownership.The independent possessive pronouns are mine, ours, yours, his, hers, its, and theirs.The possessive adjectives, also called possessive determiners, are my, our, your, his, her, its, and their.', 0, 0, 0, 1790961806923) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e2b7e68e00364bd9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is the similar word of Calligraphy?', '{"A":"Computers","B":"Handwriting","C":"Blood pressure","D":"Brain Waves"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Calligraphy means خطاطیHandwriting means خطاطی', 0, 0, 0, 1790961806923) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c2fc9b95f45065fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She is suffering _____ fever.', '{"A":"With","B":"From","C":"Of","D":"By"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She is suffering from a fever.وہ بخار میں مبتلا ہے۔We use "from" here because it indicates the cause of the suffering. "Suffering from" is a common collocation in English that denotes experiencing a particular condition or ailment.', 0, 0, 0, 1790961806923) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_db8e5aa728c03187', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The men are there to help you. Here ''to help'' is?', '{"A":"Helping verb","B":"Infinitive","C":"Copular verb","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "To help" is in its infinitive form, which is the base form of the verb preceded by "to."It expresses the purpose or intent of the action in the sentence.', 0, 0, 0, 1790961806923) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b8c837ed232aa146', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My colleague has been up to his eyes in work ever since he returned from Europe. Here ''up to his eyes'' means?', '{"A":"Extremely busy","B":"In trouble","C":"Enjoying his work","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The idiom "up to his eyes" means someone is extremely busy or deeply involved in something.In this context, it shows the colleague has had a heavy workload.', 0, 0, 0, 1790961807025) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_98abb9323ba90704', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Man is the only animal ______ can think in a positive way about the progress of mankind.', '{"A":"Which","B":"That","C":"Whose","D":"Whome"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "That" is correctly used to refer to people or animals in a defining clause.The sentence means man is the only animal that can think positively about human progress.', 0, 0, 0, 1790961807025) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_686ccafc916103db', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Sara is _____ honest girl.', '{"A":"An","B":"The","C":"A","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct sentence is "Sara is an honest girl". The article "an" is used because the letter "h" in "honest" is silent and the letter "o" is a vowel.', 0, 0, 0, 1790961807025) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ff49b037cb38da14', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Remove the cover from boxes and discard them. Here ''them'' is?', '{"A":"Objective pronoun","B":"Reflective pronoun","C":"Ambiguous pronoun","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Them" is the object of the verb "discard."Objective pronouns receive the action in a sentence.', 0, 0, 0, 1790961807025) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c683ae30af90b523', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He loves ___ TV .', '{"A":"Watch","B":"Watching","C":"Watched","D":"To Watch"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence requires a gerund (verb + ing) after the verb "loves.""He loves watching TV" is grammatically correct.', 0, 0, 0, 1790961807025) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1ae4df4f043568d6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Select the regular verb from the given sentence: "I walk to school every day."', '{"A":"Walk","B":"School","C":"Everyday","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Walk" is a regular verb — its past form is made by simply adding -ed (walk → walked).Regular verbs follow a predictable pattern in tense changes, unlike irregular verbs.', 0, 0, 0, 1790961807025) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_facd553513eb7f1c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Of the three brothers, Sam is the _____?', '{"A":"Taller","B":"Tallest","C":"Most tallest","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tallest is the superlative degree of tall."tallest" is used when comparing the heights of two or more people or objects.Additional information:If we were talking about just one person''s height, we would use the word "tall" instead of "tallest."', 0, 0, 0, 1790961807025) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d71f75b53da27230', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The new owners of the paper changed the _____ completely.', '{"A":"Outlook","B":"Outlay","C":"Layout","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Layout means ترتیبThe new owners of the paper changed the layout completelyکاغذ کے نئے مالکان نے ترتیب کو مکمل طور پر تبدیل کر دیا', 0, 0, 0, 1790961807025) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8bada67a447709d9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'If I ________ her name, I would tell you.', '{"A":"Know","B":"Known","C":"Knew","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If I knew her name, I would tell you means اگر مجھے اس کا نام معلوم ہوتا تو میں آپ کو بتاتاThe second part of the sentence is in the past tense.The verb to be used should also be in the same tense.The past tense of the word "know" is "knew".Therefore, the correct tense here is past tense and the verb used is "knew".', 0, 0, 0, 1790961807100) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_54a1e311bff386af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'If they had more money, they _______ a new house.', '{"A":"Should buy","B":"Will be buying","C":"Would buy","D":"Have bought"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is the second type of Conditional Sentences.Formula: If + past simple, would/wouldn''t + verbIf they had more money, they will buy a new house اگر ان کے پاس زیادہ پیسے ہوتے تو وہ نیا مکان خرید لیتے ہیں', 0, 0, 0, 1790961807100) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0d2f1de591a5e4fe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He died before he could complete his ____?', '{"A":"Autobiography","B":"Biography","C":"Monograph","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Autobiography is a life story written by the person themselves.Since he died before completing it, it refers to his own life story — autobiography.', 0, 0, 0, 1790961807100) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9d875d4ca7f43d18', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The vice-president will be seated _______ the chairman at the banquet.', '{"A":"As","B":"By","C":"To","D":"From"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This sentence belongs to Passive Voice.We use by in Passive voice.We use doer of an action after by.By is considered to be preposition.The vice-president will be seated by the chairman at the banquet. ****', 0, 0, 0, 1790961807100) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_91332ee7c8a0bc04', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Giving is better than ________?', '{"A":"To receive","B":"Will be receiving","C":"Received","D":"Receiving"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If there is ing form in first word (giving) we need to use also ing form (receiving) in the last word. Giving is better than receiving means دینا وصول کرنے سے بہتر ہے***', 0, 0, 0, 1790961807100) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c7bef3ef28c188d1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A record of complaints _______ kept in the purser''s office.', '{"A":"Are","B":"Were","C":"Is","D":"Will"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Here we need to use verb for a.A shows something singular.We use is for singular.A record of complaints is kept in the purser''s office.*****', 0, 0, 0, 1790961807100) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c00639ae886f87f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A disease that spreads over a large area and affects a large number of people at one place and time is known as ______?', '{"A":"Academic","B":"Incorrigible","C":"Invincible","D":"Epidemic"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An epidemic is a disease that spreads over a large area.It affecting a significant number of people or populations.It is a widespread outbreak of a disease.It often caused by infectious agents such as viruses, bacteria, or fungi.', 0, 0, 0, 1790961807100) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7febff04e1e77130', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'His proposal fell out for ______ of support.', '{"A":"Demand","B":"Require","C":"Need","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrase is "for need of support," meaning it failed due to lack of support."Need" fits grammatically and contextually.', 0, 0, 0, 1790961807100) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6116fdbab384a048', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is nothing ______ but pride.', '{"A":"Neither","B":"Else","C":"Either","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrase is "nothing else but," which means "only.""It is nothing else but pride" is the proper usage.', 0, 0, 0, 1790961807161) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9d87b80728ea2ac2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A rolling stone ____ no moss.', '{"A":"Gathers","B":"Collects","C":"Holds","D":"Attracts"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The proverb "A rolling stone gathers no moss".It means that a person who is always moving or changing jobs does not settle downAs a result, avoids responsibilities or long-term commitments.', 0, 0, 0, 1790961807161) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2b10cfbc098ec1be', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Verbs that do not show action are called?', '{"A":"Main Verbs","B":"Linking Verbs","C":"Phrasal Verbs","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Linking verbs do not express action; instead, they connect the subject to additional information, such as a state or condition.Examples include is, am, are, was, were, seem, become, which link the subject to a complement (e.g., "She is happy.").', 0, 0, 0, 1790961807161) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_301e54dc12e95d44', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Surely you recognize somebody. Here ''somebody'' is?', '{"A":"Personal pronoun","B":"Indefinite pronoun","C":"Possessive pronoun","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Somebody is an indefinite pronoun because it refers to an unspecified person.Indefinite pronouns do not point to any specific individual.', 0, 0, 0, 1790961807161) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_df318af82860513b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Select the zero conditional sentence?', '{"A":"If you heat ice, it melts.","B":"If you heat ice, it would melt.","C":"If you heat ice, it will melt.","D":"If you heated ice, it melts."}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If you heat ice, it melts.A zero conditional sentence describes general truths or facts.It uses the present simple tense in both the "if" clause and the main clause.', 0, 0, 0, 1790961807161) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7fb8dbca2abd849c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'In formal letters, the most common salutation is ____?', '{"A":"Yours sincerely","B":"Yours faithfully","C":"Yours dearly","D":"Dear XYZ (Name)"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Yours faithfully" is used when you don’t know the recipient''s name (e.g., "Dear Sir/Madam").It is the most common formal salutation in British English formal letters.', 0, 0, 0, 1790961807161) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_45b5633123a0b940', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Identify the exclamatory sentence: I like the ice cream, Are you coming with us?, Stop talking right now, What an amazing performance!', '{"A":"Are you coming with us?","B":"Stop talking right now","C":"What an amazing performance!","D":"Noneof of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An exclamatory sentence expresses strong emotion or excitement and ends with an exclamation mark (!)."What an amazing performance!" fits this definition.', 0, 0, 0, 1790961807161) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8c4447bc002c243a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A ______ sentence is made up of an independent and one or more dependent clauses connected to it.', '{"A":"Simple sentence","B":"Compound sentence","C":"Complex sentence","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A complex sentence consists of one independent clause and one or more dependent clauses connected by subordinating conjunctions.Dependent clauses cannot stand alone as complete sentences, whereas the independent clause can.', 0, 0, 0, 1790961807161) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_15c547f312a9ee4c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which sentence is imperative?', '{"A":"Move the chairs into that corner quickly.","B":"The player was nervous before the game.","C":"Kareem went to school to earn a study.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Imperative sentences give commands, requests, or instructions."Move the chairs into that corner quickly." is a command, making it an imperative sentence.', 0, 0, 0, 1790961807297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_28c4a7792aa0285d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'On leaving the shopping plaza, Sania was robbed _______ purse.', '{"A":"By her","B":"Of her","C":"Of hers","D":"By hers"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On leaving the shopping plaza, Sania was robbed of her purse.شاپنگ پلازہ سے نکلتے ہی ثانیہ کا پرس چھین لیا گیا۔The correct phrase is "robbed of her purse," as "of" indicates the item taken from her.', 0, 0, 0, 1790961807297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4d6c4057735e9884', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is accustomed _________ drinking so much.', '{"A":"Towards","B":"Too","C":"Together","D":"To"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase accustomed ended with “To” and is followed by “ing” form of a verb.Accustomed to something means کسی چیز کا عادی ہوناHe is accustomed to drinking so much means وہ بہت زیادہ پینے کا عادی ہے', 0, 0, 0, 1790961807297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c0bde6f76d5f7dc9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is averse ______ hard work.', '{"A":"On","B":"To","C":"At","D":"From"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "He is averse to hard work."Averse means having a strong dislike or opposition to something, in this case, hard work.The phrase "averse to" is a common idiomatic expression used to indicate a strong distaste or avoidance of something.', 0, 0, 0, 1790961807297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2b57157f9f2a9dea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I have disposed ____ my car.', '{"A":"Of","B":"Off","C":"To","D":"From"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dispose is always followed by of.Of is a preposition here.Dispose of means چھٹکارا حاصل کرناDispose of means ہٹادیناI have disposed of my car.', 0, 0, 0, 1790961807297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4106812d53ee9abb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We warned him ____ the danger.', '{"A":"With","B":"Of","C":"Against","D":"From"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Warn of خطرے سے خبردار کرناWarn against غلطی پر خبردار کرناWe warned him of the danger.', 0, 0, 0, 1790961807297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dcac1178ec50bf98', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Send the book ______ my address.', '{"A":"In","B":"On","C":"To","D":"The"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Send the book to my address."کتاب میرے ایڈریس پر بھیج دوIn this context, "to" indicates the direction or destination of the action.', 0, 0, 0, 1790961807297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9ed5361135a5e8b5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'His health is broken ____ due to hard work.', '{"A":"Up","B":"Down","C":"Into","D":"Out"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Broken down" means weakened or deteriorated, often due to stress or excessive work.In this sentence, it indicates that his health has worsened because of hard work.', 0, 0, 0, 1790961807297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_66ba7232f124f16e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The flight _______ for Islamabad tomorrow.', '{"A":"Is leaving","B":"Leave","C":"Was leaving","D":"Left"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Present Continuous Tense is used for present continuous action and future action as well.The word “Tomorrow” shows something will happen in the future. Therefore, we need to use present continuous tense here.', 0, 0, 0, 1790961807388) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1595ba7a7fc8b5e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The ability to perform daily routine work without fatigue and to bear during fatigue is known as ______?', '{"A":"Wellness","B":"Fitness","C":"Stiffness","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fitness refers to the ability to perform daily activities without fatigue and with enough energy for leisure.Wellness is broader (mental/social well-being).Stiffness implies rigidity.', 0, 0, 0, 1790961807388) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ac70eeb84e4de3be', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The term Aqua means ______?', '{"A":"Water","B":"Marsh","C":"Alloy","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Aqua is a greenish-blue color, often thought of as the shade of water.Aqua, water in Latin, is a variation of cyan that sits between green and blue in the color wheel.Aqua means پانیWater means پانی', 0, 0, 0, 1790961807388) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_05477cadfd88d35a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He was married ______ a rich family.', '{"A":"To","B":"With","C":"Of","D":"In"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct preposition after "married" is "to".So the correct sentence is: "He was married to a rich family.""Married to" is used to show a connection between a person and their spouse or family.', 0, 0, 0, 1790961807388) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_20e7e05e6ea2dc50', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He has been ____ his pen since morning.', '{"A":"Searching","B":"Search","C":"Searched","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Has been searching" is the correct present perfect continuous tense.It indicates an action that started in the past and is still ongoing.', 0, 0, 0, 1790961807388) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9f5c4b8eba8ebac6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'In 44 sounds of English language, ____ are vowel sounds and ____ are consonant sounds.', '{"A":"20, 24","B":"30, 14","C":"23, 21","D":"15, 21"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation English has 44 phonemes: 20 vowel sounds (including monophthongs and diphthongs) and 24 consonant sounds.Vowel sounds are produced without obstruction, while consonant sounds involve some restriction in airflow.', 0, 0, 0, 1790961807388) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_33416be449a6c918', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A verb that requires an object to receive the action is called?', '{"A":"Transitive Verb","B":"Intransitive Verb","C":"Helping Verb","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A transitive verb requires a direct object to receive the action of the verb.Such as "She kicked the ball."In contrast, an intransitive verb does not require an object.', 0, 0, 0, 1790961807388) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_14ca87c09bc1bf99', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the part of sentence: "Smoking" is injurious to health.', '{"A":"Complement","B":"Participle","C":"Gerund","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Smoking" acts as a noun, referring to the activity of smoking. A verb form ending in "-ing" that functions as a noun is called a gerund.', 0, 0, 0, 1790961807388) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_af154f090e9b6237', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Commencement of words with same letter _____?', '{"A":"Alliteration","B":"Pun","C":"Oxymoron","D":"Transferred epithet"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Alliteration is a literary device in which words that start with the same sound or letter are repeated in close proximity to each other, typically in a phrase or sentence.Examples include "sweet silver slippers" or "fluffy friendly felines".', 0, 0, 0, 1790961807478) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3a9317ec1fe4b8b8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is the time ______ your watch?', '{"A":"From","B":"On","C":"With","D":"By"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We generally use by with time.by is a preposition hereWhat is the time by your watch means آپ کی گھڑی میں کیا وقت ہوا ہے', 0, 0, 0, 1790961807478) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_00cd199e75d5bf65', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The defendant claimed that he was innocent and that his confession was _____?', '{"A":"Flagrant","B":"Coerced","C":"Terse","D":"Benign"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Coerced means زبردستی"Coerced" means forced or obtained under pressure.It implies the confession was not given voluntarily.', 0, 0, 0, 1790961807478) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_26d0673a41cf83e3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Swims like a ______?', '{"A":"Ghost","B":"Kitten","C":"Monkey","D":"Fish"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "swims like a fish" is a common idiom that means someone swims very well. Fish are naturally excellent swimmers, making this the most logical comparison.', 0, 0, 0, 1790961807478) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_937f23d8288f5822', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The shopkeeper said to the man, "What kind of books do you need."', '{"A":"The shopkeeper told the man what kind books he was needed.","B":"The shopkeeper asked the man what kind of books he needed.","C":"The shopkeeper asked the man what kind of books he is needed.","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The shopkeeper asked the man what kind of books he needed. The sentence is converted from direct to indirect speech, so "said to" changes to "asked" (since it''s a question). "Do you need" (present simple) changes to "he needed" (past simple) in reported speech.', 0, 0, 0, 1790961807478) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8b8cd0675372cf63', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He takes ___ his father.', '{"A":"After","B":"Off","C":"Up","D":"Out"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He takes after his father.Takes after means to look or act like an older family member.It shows a shared family trait, habit, or facial shape.', 0, 0, 0, 1790961807478) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_80721e847da23f5c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The meaning of ''Allege'' is?', '{"A":"Stop","B":"Assert","C":"Include","D":"Finish"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Allege means الزام ہےAssert means الزام ہے', 0, 0, 0, 1790961807478) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_82c5527250031fcd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The meaning of Abort is?', '{"A":"Cancel/Give up","B":"Continue","C":"Complete","D":"Maintain"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word ''abort'' means to cancel or give up.Abort means ملتوی یا منسوخ کرناCancel means منسوخ کرنا***', 0, 0, 0, 1790961807478) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f673beb70a6ca620', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'This merchant deals ________ silk goods?', '{"A":"In","B":"For","C":"About","D":"With"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This merchant deals in silk goods.یہ سوداگر ریشم کے سامان کا کاروبار کرتا ہے۔The preposition "in" is used to indicate the type of goods a merchant trades or specializes in.', 0, 0, 0, 1790961807569) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_632100d4bac46624', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'His Father passed ____last night?', '{"A":"Out","B":"Off","C":"Over","D":"Away"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation His father passed away last Night.ان کے والد کا گزشتہ اتوار کو انتقال ہو گیا تھا۔"Passed away" is a polite or softer way of saying someone has died.', 0, 0, 0, 1790961807569) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c2bf4d3b1f07f66f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is ten o''clock _____ my watch.', '{"A":"With","B":"In","C":"By","D":"On"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "It is ten o''clock by my watch."میری گھڑی کے دس بج رہے ہیں۔It indicates that the time shown is based on the watch being referenced.', 0, 0, 0, 1790961807569) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_69ccc4005cf33d5a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The burglar jumped ______ the compound wall.', '{"A":"On","B":"Across","C":"Over","D":"In"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The burglar jumped over the compound wall.Burglar means: چور***We use "over" to talk about movement or position at a higher level than something else.in the above sentence, we use " over preposition" because someone "jumped over the wall"******', 0, 0, 0, 1790961807569) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2fd4501dc32ffd3d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'This is a matter _____ little importance.', '{"A":"With","B":"Of","C":"On","D":"In"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is a matter of little importance.** we always use the "of " preposition with the "matter." "Of " is always used after the noun (matter is a noun in the above sentence)If we can choose the " in, on, and with with" preposition it changes the meaning of the original sentence.******', 0, 0, 0, 1790961807569) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_77726fe8cd9d73b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is cool ________ February.', '{"A":"For","B":"In","C":"With","D":"Of"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Usually preposition “In” is used before a month. فروری میں ٹھنڈ ہے۔', 0, 0, 0, 1790961807569) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f19d44dc8ece83f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'This work is ______ his capacity.', '{"A":"Below","B":"Beyond","C":"Under","D":"Over"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This work is beyond his capacity یہ کام اس کی استطاعت سے باہر ہے۔*******If the sentence indicates physical condition, we would use under, below, and over.But the sentence indicated the "capacity of someone" so, we select the option "beyond"******', 0, 0, 0, 1790961807569) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f2148a7ce4fb58a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Please speak in ____ English.', '{"A":"Plane","B":"Plan","C":"Plain","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Plain English" means simple and clear language. "Plane" refers to an aircraft. "Plan" refers to a scheme or strategy.', 0, 0, 0, 1790961807569) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b12a1246b41854b2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Health is preferable ___ riches.', '{"A":"To","B":"On","C":"Of","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Health is preferable to riches. صحت دولت سے افضل ہے۔Generally preferable is followed by To.', 0, 0, 0, 1790961807659) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_38338859ee081e1e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Students are advised to write their names ____ ink.', '{"A":"Through","B":"With","C":"By","D":"In"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Students are advised to write (their names) in ink. when we use ( pen) to write, we use ( ink) instead of (pen). Then we have to use the preposition ( in ) but not ( with). Eg. I write in ink.', 0, 0, 0, 1790961807659) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ae6497dfce83ea97', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'How long ____ English?', '{"A":"Have you been learning","B":"You learn","C":"Are you learning","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The present perfect continuous is formed with have/has been and the -ing form of the verb. We normally use the present perfect continuous to emphasize that something is still continuing in the present. Here the person is asking “how long have you been learning?”, this sentence is a present perfect continuous because the subject is still learning English.', 0, 0, 0, 1790961807659) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3cc684fc2706d361', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We are answerable ______ God.', '{"A":"Before","B":"For","C":"To","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We are answerable to God.ہم خدا کے لئے جوابدہ ہیں۔We use "to" because it conveys the idea of being responsible.', 0, 0, 0, 1790961807659) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3793d8ca4b784f9a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'By the time she arrives, we ___ our homework.', '{"A":"Finish","B":"Will have finished","C":"Will finish","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "By the time she arrives" indicates a future point before which the action will be completed.The correct tense to express a completed action before a specific future time is Future Perfect Tense (will have finished).', 0, 0, 0, 1790961807659) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4e67cb06b853e120', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'How many consonants are there in English?', '{"A":"5","B":"21","C":"26","D":"22"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation English has total 26 letters.English has 5 vowels (a,e,i,o,u).English has 21 consonants.', 0, 0, 0, 1790961807659) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0534dd13760642e5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The analogy of Lion : Carnivores ::', '{"A":"Granivore : Reptile","B":"Omnivore : Beetle","C":"Hen : Herbivores","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lion is to carnivores as rhino is to herbivore. Reason: Lion eats only flesh and hence called a carnivores animal. On the other hand, rhino eats vegetation only, hence called a herbivores animal.', 0, 0, 0, 1790961807659) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c2900d06d2125504', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A fool dog fell _______ water?', '{"A":"For","B":"Of","C":"Into","D":"In"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A fool dog fell into the water.ایک بیوقوف کتا پانی میں گر گیا۔The dog fell within the water, so we use the "into" preposition.The "into" preposition is used in a sentence because they show the dog is within or inside the water.Into is a preposition that shows what something is within or inside.', 0, 0, 0, 1790961807660) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d64301950b3138c8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Nuclear energy is _____ dangerous to be used widely.', '{"A":"So","B":"Much","C":"Too","D":"That"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nuclear energy is too dangerous to be used widely. جوہری توانائی کا وسیع پیمانے پر استعمال کے لیے بہت خطرناک ہے۔*The word "too" is used as an adverb to modify the adjective "dangerous" in this sentence.', 0, 0, 0, 1790961807742) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1ee2f125d42e7c0b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Tania, accompanied by her brother _____ at the party.', '{"A":"Was","B":"Were","C":"Is","D":"Are"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tania, accompanied by her brother, was at the party.تانیہ ، اس کے ساتھ اپنے بھائی کے ساتھ ، پارٹی میں تھیں۔The phrase "accompanied by her brother" does not change the singular subject "Tania".So the singular verb "was" is correct.', 0, 0, 0, 1790961807742) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_775d95fe84b6f0b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The market is nearer to them than ____?', '{"A":"We","B":"Ourselves","C":"Ours","D":"Us"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Than" is a conjunction, and after it, we use an object pronoun (us).Correct sentence: "The market is nearer to them than us."مارکیٹ ہم سے قریب ہے۔', 0, 0, 0, 1790961807743) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_45a8b144246f728d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The students in our school are ___ in other schools.', '{"A":"Smarter","B":"Smarter than","C":"Smarter than those","D":"More smarter than"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The students in our school are smarter than those in other schools.Smarter than those means ان سے زیادہ ہوشیارThis comparison is complete with the word "those" indicating the other schools'' students.', 0, 0, 0, 1790961807743) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e71ba82e570fac8e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'When she was younger, she ________ five kilometres a day.', '{"A":"Walk","B":"Walking","C":"Walks","D":"Walked"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence refers to a past habit, so the simple past tense ("walked") is correct.Example: When she was younger, she walked five kilometres a day.جب وہ چھوٹی تھی ، تو وہ ایک دن میں پانچ کلومیٹر کے فاصلے پر چلتی تھی۔The second form of verb is always used with in a sentence of past indefinite tense.Walk, walked, walked', 0, 0, 0, 1790961807743) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6686f0db8bca55f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The woman ________ is standing by the table works in electronic media.', '{"A":"Who","B":"Which","C":"Whom","D":"Whose"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Who is a pronoun.Who means جو"Who" is used for the subject of the sentence referring to a person."Which" is used for things."Whom" is used as an object."Whose" shows possession.', 0, 0, 0, 1790961807743) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_744278421ee3c575', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I enjoy ______ tennis.', '{"A":"Playing","B":"To play","C":"Playing","D":"To playing"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I enjoy playing tennis.میں ٹینس کھیل کر لطف اندوز ہوتا ہوں۔The verb "enjoy" is followed by a gerund (verb + ing).So "playing" is correct.', 0, 0, 0, 1790961807743) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_592e42d03b5b8a7d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He takes his turn, and she takes ______?', '{"A":"Herself","B":"Her","C":"Hers","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct sentence is "He takes his turn, and she takes hers," indicating possession.وہ اپنی باری لیتا ہے، اور وہ اپنی باری لے لیتی ہے۔Hers is the possessive pronoun replacing "her turn."', 0, 0, 0, 1790961807743) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_142ea79329d0005a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The man ___ wallet was stolen called the police.', '{"A":"Who","B":"Which","C":"Whom","D":"Whose"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Whose" shows possession (the wallet belongs to the man).The correct sentence: "The man whose wallet was stolen called the police."وہ شخص جس کا پرس چوری ہوا تھا اسے پولیس نے بلایا۔', 0, 0, 0, 1790961807855) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9bca5eed6702c4cd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Anna and Tania went shopping but _______ couldn''t find anything _________ liked.', '{"A":"They, those","B":"They, them","C":"They, they","D":"Those, they"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Anna and Tania went shopping but they couldn''t find anything they liked. انا اور تانیہ خریداری کرنے گئے تھے لیکن انہیں اپنی پسند کی کوئی چیز نہیں مل سکی۔The pronoun "they" is used as the subject referring to both Anna and Tania.The second "they" is also correct as it refers back to the subject.It indicating neither found anything they liked.', 0, 0, 0, 1790961807855) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bda893e825a17bbe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'While UK has earned record revenue this year, __________ well behind in exports.', '{"A":"It still lag","B":"It still lags","C":"It lag still","D":"It lags still"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "While the UK has earned record revenue this year, it still lags well behind in exports."It still lags means یہ اب بھی پیچھے ہےThis indicates that despite high revenue, the UK is still significantly behind in export performance.', 0, 0, 0, 1790961807855) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1c97669b341db774', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'After dinner, grandmother used to tell us stories while ____ old socks.', '{"A":"Sewing","B":"Stitching","C":"Darning","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Darning is the correct term for repairing holes in socks or knitted fabric.Sewing and stitching refer to general needlework.', 0, 0, 0, 1790961807855) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_50694f768eec913d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Skyscraper means _____?', '{"A":"A large building, typically of the medieval period","B":"A very tall building of many storeys","C":"Private room or a compartment on a ship","D":"A small house, typically one in the country"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Skyscraper means بہت ہی اونچی عمارتSkyscraper is a noun.A skyscraper refers to a very tall building with multiple floors, usually found in cities.It is designed to maximize space in urban areas by building vertically.', 0, 0, 0, 1790961807855) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_91174d27918cfc9f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The literal meaning of the word "Ethics" is ______?', '{"A":"Understand human nature","B":"Study of morality","C":"Both A and B","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word "Ethics" is derived from the Greek word "Ethos," meaning character or morality.Ethics is the study of moral principles that govern human behavior and decision-making.', 0, 0, 0, 1790961807855) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_37876aae18884a2f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They went _____ the rain.', '{"A":"Under","B":"Avoiding","C":"Inspite","D":"Despite"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation They went despite the rain.***Despite means کے باوجودWent is a simple past sentence so we use infinite foam of the verb "despite".', 0, 0, 0, 1790961807855) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_27c6fd175dab4753', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'There was a roof _____ my head.', '{"A":"On","B":"Over","C":"above","D":"with"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The preposition over is used to refer to something placed at a higher position.', 0, 0, 0, 1790961807855) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_78e7e73eb119e312', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She sang a Medley of old songs. In the above sentence, the word "Medley" is a?', '{"A":"Noun","B":"Pronoun","C":"Verb","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Medley" refers to a mixture of different things, in this case, a combination of old songs.It is used as a noun in the sentence, meaning a collection or assortment.', 0, 0, 0, 1790961807954) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_24770efb70e32a8c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The committee regrets that it cannot accede _____ your request for a month’s unpaid leave.', '{"A":"For","B":"On","C":"In","D":"To"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally preposition to is used after accede.Accede means agree or accept.The authorities did not accede to the strikers'' demands".', 0, 0, 0, 1790961807954) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d3035c51f273f300', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The town has mushroomed recently. In the above sentence, the word "Mushroomed" is a?', '{"A":"Adverb","B":"Adjective","C":"Verb","D":"Preposition"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mushroom is a verb which means to increase very quickly.Mushroom means تیزی سے بڑھناFor example:The number of teachers in school has mushroomed in recent months.', 0, 0, 0, 1790961807954) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1d92c49d33a63d80', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I was surprised by the large ________ people who came.', '{"A":"Number of","B":"Amount of","C":"Sum of","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I was surprised by the large number of people who cameمیں آنے والے لوگوں کی بڑی تعداد سے حیران تھا***"The number of" is different and always takes a plural noun followed by a singular verbthe phrase "a large number of" is used to indicate that there were many people who came', 0, 0, 0, 1790961807954) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e7f61adcfce12145', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the appropriate word for " A critical judge of any art or craft".', '{"A":"Referee","B":"Arbitrator","C":"Connoisseur","D":"Magistrate"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Connoisseur is a person with expert knowledge and judgment in a particular art or craft.They critically evaluate quality, especially in fields like fine arts, food, or wine.', 0, 0, 0, 1790961807954) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_356ac682258d3082', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Analogy of Native : Aboriginal :: Naive : ______?', '{"A":"Learned","B":"Arid","C":"Unsophisticated","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Native آبائی is a synonym for aboriginal اصلیNaive بولی is a synonym for unsophisticated غیر مہذب', 0, 0, 0, 1790961807954) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d8267680b3c3e747', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'This neighborhood looks a little _______ and tatty these day.', '{"A":"Well-heeled","B":"Well-off","C":"Run down","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This neighborhood looks a little run down and tatty these day.یہ پڑوس اس دن تھوڑا سا رن اور ٹیٹی نظر آرہا ہے۔"Run down" means in poor condition or neglected, which fits the context of a neighborhood looking worn out.', 0, 0, 0, 1790961807954) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fa8db5ba23f808b2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What did you make ___ the lecture?', '{"A":"To","B":"Of","C":"For","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrase is "make of something," meaning to understand or interpret it.Example: What did you make of the lecture? (What is your opinion or understanding of it?)', 0, 0, 0, 1790961807954) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c4ed224410754ca8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'To be at daggers drawn means _____?', '{"A":"Complete Agreement","B":"Bitter Enmity","C":"Strong Friendship","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The idiom "to be at daggers drawn" means to be in a state of intense hostility or conflict.It signifies bitter enmity or a situation where two parties are ready to fight.', 0, 0, 0, 1790961808073) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_52abf3c3c81d889f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Promise : Fulfill ::', '{"A":"Pledge : Deny","B":"Confession : Hedge","C":"Law : Enforce","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The analogy is:Promise : Fulfill :: Law : EnforceJust as a promise is fulfilled, a law is enforced.', 0, 0, 0, 1790961808073) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dd86345209cad7e3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'One Word Substitute: Triumvirate?', '{"A":"Group of Five Powerful People","B":"A Group of Four Powerful People","C":"A Group of Three Powerful People","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A triumvirate is a group of three people who hold power or authority, often in a political or governmental context. The term is often used to describe a coalition of three individuals who share control or influence.', 0, 0, 0, 1790961808073) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4526b95c05ce78a1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The Plural of Thief is ______?', '{"A":"Thiefs","B":"Thieves","C":"Thieves","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Thief is a noun. Thieves is the plural of Thief. Thief means چور', 0, 0, 0, 1790961808073) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_489465171db63b6a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Dowry is no longer permitted by law even in _______ marriage.', '{"A":"Love","B":"Conventional","C":"Natural","D":"Bigamous","E":"Polygamous"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dowry is no longer permitted by law even in love marriage.جہیز کی شادی میں بھی جہیز کو قانون کے ذریعہ اجازت نہیں ہے۔Dowry is legally prohibited in all types of marriages, including love marriages, to prevent financial exploitation.', 0, 0, 0, 1790961808073) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1b3bd1e15172c51e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'His logic ______ everyone, including the experts.', '{"A":"Surprised","B":"Defied","C":"Teased","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation His logic surprised everyone, including the experts.Surprise is a verb here.Surprise means حیران کردینا', 0, 0, 0, 1790961808073) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_db7fb7654a351705', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It was raining yesterday, so we ________ out.', '{"A":"Did not go","B":"Did not gone","C":"Did not went","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It was raining yesterday, so we did not go out.We use Past Indefinite Tense/Past Simple Tense with Yesterday.Formula of Negative sentence of Past Indefinite Tense:Subject + did + not + first form of a verb + object.', 0, 0, 0, 1790961808073) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a54ed08b6df3dd54', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He parted _______ all his possessions happily.', '{"A":"For","B":"With","C":"On","D":"from","E":"Into"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Part from someone کسی انسان سے الگ ہوناPart with someone کسی چیز سے الگ ہوناHe parted with all his possessions.', 0, 0, 0, 1790961808073) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0d9191b369c7f169', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He complains _______ headache.', '{"A":"For","B":"At","C":"Of","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use of to show a relation of noun. Of is a preposition here.He complains of headache وہ سر درد کی شکایت کرتا ہے', 0, 0, 0, 1790961808177) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0fd152aacc0622a0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is zealous _____ the popularity of games.', '{"A":"With","B":"For","C":"In","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He is zealous for the popularity of games."Zealous for" is the proper expression when expressing strong enthusiasm or passion for something.****ND04-12-2022', 0, 0, 0, 1790961808177) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6a63d5708f703327', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It''s the first time I _______ seafood in my life.', '{"A":"Eating","B":"Have eaten","C":"Had eaten","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use Present Perfect Tense for actions we have done once in our lives.Examples: It''s the first time I have visited Karachi. It''s the first time I have eaten sea-food in my life.It''s the first time she has won the match.', 0, 0, 0, 1790961808177) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d18a1daac326c005', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Many a man _____ done so.', '{"A":"Had","B":"Has","C":"Have","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Many a man" is singular, so it requires the singular verb "has."The correct sentence is: "Many a man has done so."بہت سے آدمیوں نے ایسا کیا ہے۔', 0, 0, 0, 1790961808177) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_82172f30e6dfb66b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'ARGOSY means ______?', '{"A":"Arrogant","B":"A big trading ship","C":"Misguiding","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ARGOSY means a big trading ship.Trading ship means a seagoing ship engaged in trade and proceeding to sea on regular voyages, excluding.', 0, 0, 0, 1790961808177) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_07534037ee49e915', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'HOGWASH can be substituted with _____?', '{"A":"Running Fast","B":"Flying kite","C":"Nonsense","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hogwash means بے معنی یا فضولNonsense بکواس', 0, 0, 0, 1790961808177) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7206b4e8e57da758', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The police said that the burglars broke ___ shortly after midnight.', '{"A":"Into","B":"Over","C":"Up","D":"In"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Break in => ناجائز طور پر داخل ہوناBreak in => to enterBurglars => نقب زن The burglar broke in shortly.', 0, 0, 0, 1790961808177) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c9f2dcb63ce6139f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The debate adjourned _____ the following week.', '{"A":"To","B":"For","C":"With","D":"Into"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct sentence is "The debate adjourned to the following week".بحث اگلے ہفتے تک ملتوی کر دی گئی۔It indicating that the discussion or meeting was postponed until the next week.', 0, 0, 0, 1790961808177) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_06621c7ee305e9c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Anam is the smartest _____ girl?', '{"A":"Among others","B":"Of all","C":"Of all others","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "of all" is used to compare one person or thing with everyone or everything in a group.Correct sentence: "Anam is the smartest of all girls."انعم تمام لڑکیوں میں ذہین ہے۔', 0, 0, 0, 1790961808260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_76775c37e0213833', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The Prime Minister has arrived _______ Peshawar.', '{"A":"On","B":"With","C":"Into","D":"For","E":"In"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use In for places, cities or countries.In is a preposition here.The prime minister has arrived in Peshawar. وزیراعظم پشاور پہنچ گئے*****', 0, 0, 0, 1790961808260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b10922974402e665', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I had scarcely entered the room ____ the guest arrived.', '{"A":"Than","B":"When","C":"Then","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I had scarcely entered the room when the guest arrived.جب مہمان آیا تو میں مشکل سے کمرے میں داخل ہوا تھا۔When means "at or during the time that" (as conjunction)When is used as a conjunction here "someone entered the room at or during the time that".', 0, 0, 0, 1790961808260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e47c7228981852da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Depressed is to Elated, as Submissive is to:', '{"A":"Exhausted","B":"Angry","C":"Resistant","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Depressed" and "elated" are antonyms "Depressed" represents a feeling of sadness while "elated" represents a feeling of joy.Similarly, "submissive" and "resistant" represent opposite behavioral characteristics. "Submissive" refers to a person who is obedient while "resistant" describes someone who is defiant or unwilling to comply.', 0, 0, 0, 1790961808260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b1bea6a3ef73242a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He was born ____ December 12, 1990.', '{"A":"On","B":"In","C":"At","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He was born in December 12, 1990.وہ 12 دسمبر 1990 کو پیدا ہوئے۔For month, year, and season, we use in.For month, year, and season, we use in.For example in August, in 1992, in the ''90s, in winter.For date and day, we use on.For example 5 of August, on the fifth, on Monday.', 0, 0, 0, 1790961808260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a07e93f534c79227', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'If I had money, I ________ it now.', '{"A":"Will purchase","B":"Would purchase","C":"Would have","D":"Would have purchased"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is a conditional sentence.We use subject + past tense in first clause, subject + would + first form of verb in such type of sentences.If I had money, I would purchase it now.', 0, 0, 0, 1790961808260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6649f285931bc041', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The departmental store is open ______ eight to seven.', '{"A":"From","B":"On","C":"Between","D":"During"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "The departmental store is open from eight to seven."This indicates the range of time the store is open.It starting at eight and ending at seven.', 0, 0, 0, 1790961808260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c5f87f1cbceed8fd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Katherine made her children ________ chores on Sunday.', '{"A":"Make some","B":"Take some","C":"Do some","D":"Does some"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Katherine made her children do some chores on Sunday.کیتھرین نے اتوار کو اپنے بچوں کو کچھ کام کرنے پر مجبور کیا۔The verb "do" is commonly used with "chores," making "do some chores" the correct expression."Made" in the sentence requires the base form of the verb, so "do" fits grammatically.', 0, 0, 0, 1790961808260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cc9d4925498a1c3b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'If I have money, I ______ it tomorrow.', '{"A":"Will purchase","B":"Have purchase","C":"Would purchase","D":"Have purchased"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "We use ''will purchase'' to express your intent to buy something in the future if you have the money." The modal verb ''will'' is used to express future tense,while ''purchase'' is the base form of the verb used to describe the action of buying something.', 0, 0, 0, 1790961808377) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_df56d2da1f17646a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '“A fair-weather friend” means what?', '{"A":"False friend","B":"Good friend","C":"Loyal Friend","D":"Close friend","E":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A fair-weather friend means مطبی دوستA "fair-weather friend" is someone who is supportive only when things are going well but disappears during difficult times.They are not reliable or loyal.', 0, 0, 0, 1790961808377) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_375fb7107b341abc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Alma mater means ____?', '{"A":"College","B":"House","C":"Hospital","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Alma mater is a Latin term meaning "nourishing mother."It commonly used to refer to the school, college, or university one has graduated from.', 0, 0, 0, 1790961808378) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9eeea19cc758078a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which word is correctly spelt in the following set of words? Obsilote, Obsolete, Absoliete, None of these', '{"A":"Obsilote","B":"Obsolete","C":"Absoliete","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct spelling is Obsolete.It means something that is no longer in use.Obsolete means متروک', 0, 0, 0, 1790961808378) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_91568561dbc20f9e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Complete the sentence: Justice delayed is justice ________?', '{"A":"Delayed","B":"Deprived","C":"Denied","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation British Prime Minister William Ewart Gladstone is credited with saying “Justice delayed is justice denied” in 1868.Additional InformationThe phrase is often used to emphasize the importance of delivering justice in a timely and efficient manner.When a legal system fails to do so, it can lead to frustration, loss of faith, and even further injustice', 0, 0, 0, 1790961808378) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_023e28e354b95ddb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'There has been a complete break ______ of law and order.', '{"A":"Up","B":"Off","C":"Of","D":"Down"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "There has been a complete break down of law and order".امن و امان مکمل طور پر درہم برہم ہو چکا ہے۔"Break down" means a failure or collapse of a system or structure.', 0, 0, 0, 1790961808378) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6ba93079a019c5a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A young officer was charged _____ the task of taking 200 prisoners to the rear.', '{"A":"From","B":"At","C":"With","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "charged with" means assigned or entrusted with a specific task or responsibility.In this context, the young officer was given the responsibility of taking the prisoners to the rear.نوجوان افسر کو قیدیوں کو عقب میں لے جانے کی ذمہ داری دی گئی۔', 0, 0, 0, 1790961808378) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8c1e6bff8e5df26a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which word is wrongly spelt in the following A set of words? Speach, Speak, Break, Bleed', '{"A":"Speach","B":"Speak","C":"Break","D":"Bleed"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct spelling is Speech. The other words (Speak, Break, Bleed) are spelled correctly.', 0, 0, 0, 1790961808378) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ecfe52e2eda56b7b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He was ________ such a hurry that he forgot his keys.', '{"A":"At","B":"In","C":"With","D":"By","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He was in such a hurry that he forgot his keys.وہ اتنی جلدی میں تھا کہ اپنی چابیاں بھول گیا۔The correct phrase is "in a hurry," which means to be in a rushed or hurried state.', 0, 0, 0, 1790961808457) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b094f3e6bebce817', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is _____ M.A.', '{"A":"The","B":"A","C":"An","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "He is an M.A."The article "an" is used before abbreviations that start with a vowel sound, like "M.A."', 0, 0, 0, 1790961808457) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f47486b684d8f195', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Do it quickly. Here Quickly is an example of which parts of speech?', '{"A":"Pronoun","B":"Adjective","C":"Adverb","D":"Preposition"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Quickly" modifies the verb "do," describing how the action should be performed.Adverbs often end in "-ly".It provide information about the manner, place, time, frequency, or degree of the action.', 0, 0, 0, 1790961808457) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3b74130a7656ee7e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Send this letter ___ my address.', '{"A":"To","B":"On","C":"At","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct sentence should be: "Send this letter to my address."یہ خط میرے پتے پر بھیج دو۔The preposition "to" is used to indicate the recipient or destination of the letter.', 0, 0, 0, 1790961808457) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5a5e1e5674c347d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Tall is to Short as Treachery is to _____?', '{"A":"Loyalty","B":"Respect","C":"Honour","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Just as tall is the opposite of short, treachery is the opposite of loyalty.', 0, 0, 0, 1790961808457) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d6d91d45d41427bf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Oligarchy is ____?', '{"A":"Rich and mighty dominating the economic scene","B":"Government by small group of person","C":"Government of the drug Barons","D":"Corrupt land mafia"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Oligarchy means government by a small group of very powerful people.Oligarchy means چند لوگ یا امیروں کی حکومت', 0, 0, 0, 1790961808457) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_90010b76bae1fa46', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He said: "Sit down Ali."', '{"A":"He said sit down Ali","B":"He asked Ali to sit down","C":"He said Ali to sit down","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "He asked Ali to sit down" is correct.It converts the direct command into reported speech.Using "asked" maintains the polite request.It removes quotation marks and rephrases for indirect reporting.', 0, 0, 0, 1790961808458) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5166c5c9bffea594', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He would enjoy this, if he _______ present.', '{"A":"Has","B":"Was","C":"Were","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is a conditional sentence (Hypothetical sentence)We use would & were in such type of sentences.If he were present means اگر وہ حاضر ہوتا', 0, 0, 0, 1790961808458) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a99d5404c873021d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Reptile is to Lizard as Flower is to ______?', '{"A":"Petal","B":"Stem","C":"Daisy","D":"Alligator"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Reptile is to Lizard as Flower is to Daisy.A lizard is a specific type of reptile, just as a daisy is a specific type of flower. The relationship is based on categorization.', 0, 0, 0, 1790961808568) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_05190347e9e8a23a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am worried _______ my exams.', '{"A":"At","B":"In","C":"About","D":"Of"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Be worried about something means کسی چیز کے بارے میں فکر مند ہونامیں اپنے امتحانات کیلئے فکرمند ہوں۔', 0, 0, 0, 1790961808568) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_23cd97ff56d23490', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Pork : Pig ::', '{"A":"Steer : Beef","B":"Rooster : Chicken","C":"Mutton: Sheep","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The analogy is:Pork : Pig :: Mutton : SheepJust as pork is the meat that comes from a pig.Mutton is the meat that comes from a sheep.', 0, 0, 0, 1790961808568) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9722d4b99f5c91ff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Analogy: Bull : Cow ::?', '{"A":"Doe : Bunny","B":"Rooster : Chick","C":"Lion : Cub","D":"Stallion : Mare"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bull is a male cattle and Cow is female cattle.Similarly,Stallion is a male horse and Mare is female horse.', 0, 0, 0, 1790961808568) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2b508b3927c7b4bf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Another name of Full Stop is ____?', '{"A":"Period","B":"Dash","C":"Colon","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Punctuation Marks:Full Stop (.): It is used to end sentences.Comma (,): Indicates a pause between parts of a sentence.Semicolon (;): Links closely related independent clauses.Colon (:): Introduces a list or explanation.Question Mark (?): Used at the end of a question.Exclamation Mark (!): Expresses strong emotion or emphasis.Dash (—): Indicates a range, pause, or emphasis.Apostrophe (’): Indicates possession or contraction.Quotation Marks (“”): Enclose direct speech or quotes.Ellipsis (...): Indicates omission or pause in speech.', 0, 0, 0, 1790961808568) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_399ecf1b32066d7c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which of the following join two clauses of sentence?', '{"A":"Interjenction","B":"Conjunction","C":"Preposition","D":"Verb"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A conjunction is a word used to connect two clauses, such as "and," "but," or "because."While conjunctions can also link phrases or sentences, their primary role is to join clauses for smoother sentence construction.', 0, 0, 0, 1790961808568) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d4d4ee522637ac5c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She learnt the poem _____ heart.', '{"A":"By","B":"To","C":"From","D":"With"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrase is "she learnt the poem by heart."اس نے نظم دل سے سیکھی۔It means to memorize something thoroughly.', 0, 0, 0, 1790961808568) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4129e91d64f77709', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Murad said, "I completed my master last year".', '{"A":"Murad said that he is completed his master the previous year","B":"Murad said that he have completed his master the previous year","C":"Murad said that he had completed his master the previous year","D":"Murad said that he has completed his master the previous year"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In reported speech, past perfect ("had completed") is used when the direct speech is in the past simple tense ("completed").Time expressions change accordingly: "last year" becomes "the previous year" in indirect speech.', 0, 0, 0, 1790961808568) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f7cce7874959aef5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My friend and brother always ___ me in my studies.', '{"A":"Helps","B":"Help","C":"Helping","D":"Helped"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation My friend and brother always helps me in my studiesWhy "Helps" (Singular): When "friend and brother" is preceded by a single possessive pronoun ("my"), It is generally interpreted as one person fulfilling both roles (singular subject)', 0, 0, 0, 1790961808683) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1a0fec9dc717b763', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He said to him, ‘Thank you for your kind help.’', '{"A":"He asked him for his kind help","B":"He thanked him for his kind help","C":"He requested him for his kind help","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He thanked him for his kind help. (Indirect)said to ⇒ thankedyou ⇒ himyour ⇒ his', 0, 0, 0, 1790961808683) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d782d17620c43b2b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am sick ___ this nasty job.', '{"A":"With","B":"In","C":"Of","D":"Over"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sick of means اکتا جانا"I am sick of this nasty job."We use sick of to express being tired, bored, or fed up with something.', 0, 0, 0, 1790961808683) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_106616a1fcfd63f6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Yolk : Egg ::?', '{"A":"Rind: melon","B":"Nucleus: cell","C":"Stalk: corn","D":"Duck: fowl"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation York means زردیEgg means انڈا Nucleus means مرکزہ Cell means خلیہ', 0, 0, 0, 1790961808683) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_86e0849162f5fd8e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Always : Never ::?', '{"A":"Intermittently: Casually","B":"Constantly: Continually","C":"Often: rarely","D":"Frequently: Occasionally"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Always means ہمیشہNever means کبھی نہیںOften means اکثر Rarely means کبھی کبھار', 0, 0, 0, 1790961808683) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_07f2f8ee00511943', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He died ______ corona.', '{"A":"Of","B":"From","C":"To","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct preposition is "of," as in "He died of corona."اس کی موت کورونا سے ہوئی۔"Died of" is commonly used to indicate the cause of death.', 0, 0, 0, 1790961808683) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_49852b333d1f960d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose analogous pair: Poverty : Prosperity :: ____?', '{"A":"Intelligence : Stupidity","B":"Love : Sorrow","C":"Train : Cart","D":"Rain : Flood"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Poverty" and "Prosperity" are opposites.Just as "Intelligence" and "Stupidity" are.Both pairs follow the relationship of contrasting qualities.', 0, 0, 0, 1790961808683) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_350116076bbe9093', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is knocking ______ the door.', '{"A":"And","B":"At","C":"For","D":"That","E":"With"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He is knocking at the door وہ دروازے پر دستک دے رہا ہےthe preposition "at" is used to indicate a specific location where the action of knocking is taking place.', 0, 0, 0, 1790961808683) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eb71af117595dbf2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Birds of a feather _______ together.', '{"A":"Fly","B":"Sit","C":"Flock","D":"Swim","E":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Birds of a feather flock togetherہم خیال لوگ اکٹھے رہنا پسند کرتے ہیںIt is a common English proverb.Means: People with the same habits often form groups.Last updated 17 July 2026 by NA', 0, 0, 0, 1790961808751) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c00fd01c1413e25b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The manager likes to be ____ control?', '{"A":"About","B":"In","C":"of","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The manager likes to be in control?مینیجر کنٹرول میں رہنا پسند کرتا ہے؟"In control" means having power or authority over something.This phrase is commonly used to describe someone who is managing or directing a situation effectively.', 0, 0, 0, 1790961808751) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8bed44f6ce60a0b5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I shall abide ______ my promise.', '{"A":"On","B":"To","C":"By","D":"With"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I shall abide by my promise.میں اپنے وعدے پر قائم رہوں گا۔This means to adhere to or follow the commitment made.', 0, 0, 0, 1790961808751) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b8468fdbad39d53f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Blow _______ the lamp when you go to bed.', '{"A":"Of","B":"Out","C":"Off","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Out" is correct because "blow out" is a phrasal verb meaning to extinguish something, like a flame.In this case, it refers to putting out the lamp before going to bed.', 0, 0, 0, 1790961808751) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_898d20026d800bee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Salma was ill _____ fever.', '{"A":"On","B":"To","C":"Of","D":"With"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Salma was ill with fever.سلمیٰ بخار سے بیمار تھی۔The correct phrase is "ill with fever." "With" is used to indicate the cause or reason for her illness.', 0, 0, 0, 1790961808751) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_14c233d899874f35', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '______ of what he said was very sensible.', '{"A":"A few","B":"Much","C":"Many","D":"Few"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Much of what he said was very sensible.اس نے جو کچھ کہا اس کا بیشتر حصہ بہت سمجھدار تھا۔"Much" is used with uncountable nouns like "what he said".It referring to a large amount of sensible content.', 0, 0, 0, 1790961808751) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f6901b2ede1d7652', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Are there ____ apples in kitchen?', '{"A":"Much","B":"Some","C":"Any","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Are there any apples in kitchen?کیا کچن میں کوئی سیب ہے؟"Any" is used in questions to inquire about the presence of something.', 0, 0, 0, 1790961808751) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5c249eeb81494560', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'His reply was such _____ I expected him to give.', '{"A":"That","B":"Which","C":"As","D":"When"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation His reply was such as I expected him to give.The phrase "such as" compares or indicates a similarity between something mentioned and something expected or described.', 0, 0, 0, 1790961808751) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e2f46af2c0a78611', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Correct the sentence by using right option, " I am tired as i am working since morning."', '{"A":"I was working","B":"I have been working","C":"I had been working","D":"I will be working"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "I am tired as I have been working since morning." میں صبح سے کام کر کے تھک گیا ہوں۔The present perfect continuous tense is used here to indicate an action that started in the past and is still ongoing.', 0, 0, 0, 1790961808840) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4edc9a5f70f1ea3b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Circumstances will oblige me to go.', '{"A":"I shall be obliged to go by the circumstances","B":"I am obliged to go by the circumstances","C":"I was obliged to go by the circumstances","D":"I should be obliged to go by the circumstances"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: Circumstances will oblige me to go. Passive Voice: I shall be obliged to go by the circumstances.Future Indefinite Tense Active Voice Formula: Subject + Will/Shall + Verb (Ist form) + Object + (.) Passive Voice Formula: Convert Object to Subject + Will/Shall + Be + Verb (3rd form) + By + Convert Subject to Object + Remaining + (.)', 0, 0, 0, 1790961808840) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_08206ea1cf7f9cfd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Ten year ago, I ______ in Lahore.', '{"A":"Will work","B":"Had worked","C":"Have worked","D":"Worked"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ten year ago, I had worked in Lahore.دس سال پہلے میں نے لاہور میں کام کیا تھا۔The past perfect tense "had worked" is used here to indicate an action that was completed before another point in time, in this case, ten years ago.', 0, 0, 0, 1790961808840) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f89dc41a9761db27', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Convert to indirect : She said "stop staring at me".', '{"A":"She told him to stop staring at me","B":"She told him to stop staring to her","C":"She said him to stop staring to her","D":"She told me to stop staring at her"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the indirect version, the statement is reported as a request or instruction from the speaker ("She") to the listener ("me"). Additionally, the direct question "why" is incorporated into the reported speech as part of the speaker''s inquiry about the listener''s actions.', 0, 0, 0, 1790961808840) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cb6eeb7475d9e41d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Convert into indirect: She asked him "Are you crazy?".', '{"A":"She asked him if he was crazy","B":"She asked him if he is crazy","C":"She asked him if he has crazy","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct indirect form is: "She asked him if he was crazy.""It accurately changes the direct question to indirect speech with the appropriate past tense.', 0, 0, 0, 1790961808840) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_245195feb4ab919a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Convert to indirect: She said, "Go upstairs".', '{"A":"She told me to go upstairs","B":"She told me to  upstairs","C":"She said me to go upstairs","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct indirect form is: "She told me to go upstairs."This correctly conveys the command in indirect speech.', 0, 0, 0, 1790961808840) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_550197f47a0a5408', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Convert to indirect form: He said "Do i have to do it."', '{"A":"He asked that he had to do it","B":"He asked that he has to do it","C":"He asked if he had to do it","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In indirect speech, questions beginning with "Do" are converted into "if" clauses, and the tense is shifted back.Here, "Do I have" becomes "if he had."', 0, 0, 0, 1790961808840) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a276f96b99c0b6a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Smoking is injurious _______ health.', '{"A":"For","B":"To","C":"With","D":"From"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Smoking is injurious to health.تمباکوشی مضر صحت ہےInjurious to means harmful or damaging to something.We use “to” because injurious is normally followed by the preposition “to” when we say what is harmed.Rule:Injurious + to + something/someone', 0, 0, 0, 1790961808840) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_df27a8ad99e57bca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She assured me ________ her help.', '{"A":"With","B":"To","C":"On","D":"Of"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She assured me of her help.اس نے مجھے اپنی مدد کا یقین دلایا۔Here "of" shows that the "help" belongs to "she" (noun).', 0, 0, 0, 1790961808931) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ba0eeac88b40883e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She ______ English now.', '{"A":"Is speaking","B":"Speak","C":"Speaks","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She is speaking English now.وہ اب انگریزی بول رہی ہے۔The present continuous tense "is speaking.".It is used to describe an action happening at the moment of speaking.', 0, 0, 0, 1790961808931) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dc7faab5cba8bce4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My Dad was delighted when I showed him my result. The sentence is _____?', '{"A":"Simple","B":"Compound","C":"Complex","D":"Compound-complex"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "My Dad was delighted when I showed him my result" is a complex sentenceBecause it consists of one independent clause and one dependent clause, connected by the subordinating conjunction "when."Independent Clause: "My Dad was delighted"Dependent Clause: "When I showed him my result"****', 0, 0, 0, 1790961808931) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_df545fd15ca78a39', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It was raining heavily yesterday night, so they ________ out.', '{"A":"Did not go","B":"Did not went","C":"Would not go","D":"Would not Gone"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It was raining heavily last night, so they did not go out. The phrase correctly uses "did not go" to indicate that their plans were canceled due to the weather.', 0, 0, 0, 1790961808931) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ee20b795852da377', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose analogous pair: Horse: Mare ::', '{"A":"Duck : Geese","B":"Dog : Puppy","C":"Donkey : Pony","D":"Fox : Vixen"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Horse (an older or archaic term for a male horse) is to Mare (a female horse)Fox (a male fox) is to Vixen (a female fox)', 0, 0, 0, 1790961808931) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_645be18ffb0a3cdf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Dollar : Dime ::', '{"A":"Saleswoman : Pitch","B":"Retreat : Victory","C":"Century : Decade","D":"Ring : Necklace"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dollar : Dime :: Century: DecadeA dime is worth one-tenth of a dollar.A decade is one-tenth of a century (10 years in a decade, 100 years in a century).', 0, 0, 0, 1790961808931) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b71d99f5b7a05614', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My friend requested me to bring him a sandwich.', '{"A":"He asked “my friend to bring me a sandwich”.","B":"My friend said “will you bring me a sandwich”.","C":"“Please bring me a sandwich,” said my friend.","D":"“Please bring my friend a sandwich,” said he."}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Please bring me a sandwich,” said my friend.This accurately represents a polite request made by the friend.', 0, 0, 0, 1790961808931) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1870e87938d4784c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Bear vs Bare, Here vs Hear, Flower vs Flour, Sell vs Cell are the examples of ______?', '{"A":"Homograph","B":"Homophones","C":"Eggcorns","D":"More than one correct answer"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sell vs Cell, Bear vs. Bare, Here vs. Hear, and Flower vs. Flour are examples of Homophones.Homophones are words that sound the same but have different meanings and spellings.', 0, 0, 0, 1790961808931) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4ab66266c2edb3bc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He said, ''By God I am not guilty''.', '{"A":"He swore by God that he is not guilty.","B":"He swore by God that he will not guilty.","C":"He swore by God that he was not guilty.","D":"All are correct","E":"All are wrong"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Direct Speech: He said, ''By God I am not guilty''.Indirect speech: He swore by God that he was not guilty. Present Tense changes into Past Tense.He is changes into He was.Use second form of verb (swore)Remove inverted commas.AGM 30.4.23', 0, 0, 0, 1790961809015) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_445ba60d0da8f0da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Blindness is to the Eye as Deafness is to _____?', '{"A":"Ear","B":"Brain","C":"Head","D":"Nose"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Blindness is the loss of the ability to see with the eye, Just as deafness is the loss of the ability to hear with the ear. Last updated by NA on 23-April-2026', 0, 0, 0, 1790961809015) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ab331605497476ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Employees in this department always _____ close relations with each other.', '{"A":"Maintenance","B":"Maintained","C":"Maintains","D":"Maintain"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Employees in this department always maintain close relations with each other".اس محکمہ کے ملازمین ہمیشہ ایک دوسرے کے ساتھ قریبی تعلقات برقرار رکھتے ہیں۔It uses the base form "maintain" to correctly indicate a continuous or habitual action.', 0, 0, 0, 1790961809015) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5c8ce431b90ebc85', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I watched TV last night but my sister______?', '{"A":"Hasn''t","B":"Didn''t","C":"Isn''t","D":"Doesn''t"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "I watched TV last night, but my sister didn''t."This indicates that your sister did not watch TV last night, using the simple past tense to match the context.', 0, 0, 0, 1790961809015) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1ae35f32a592fb96', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is looking for accommodation __________ in flat or shared house.', '{"A":"Either","B":"Neither","C":"Until","D":"Both"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Either" is used to indicate that there are two options, and the person is open to considering both.The word "or" is used to connect the two options.', 0, 0, 0, 1790961809016) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0af753fa302928bf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the meaning of underlined word. I will ''pencil you'' in for Tuseday the 18th.', '{"A":"Appointment","B":"Particular","C":"Respect","D":"Independent"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "I will pencil you in" in the context of an appointment Means the appointment is not confirmed and may change. It shows that you''re reserving a time slot but might need to adjust it later.', 0, 0, 0, 1790961809016) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1ab408f797123fd3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Correct the sentence: His father is a poet and a novelist.', '{"A":"His father is a poet and novelist.","B":"His father is poet and novelist.","C":"His father isa poet and a novelist.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct answer is: His father is a poet and a novelist.This sentence is grammatically correct and uses the correct articles ("a" and "a") before the nouns "poet" and "novelist".The sentence is a simple sentence, and the use of "and" connects the two professions, indicating that his father is both a poet and a novelist.', 0, 0, 0, 1790961809016) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7478fb6cc8770d7c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Correct the sentence: His spectacles is new?', '{"A":"His spectacles was new.","B":"His spectacles has new.","C":"His spectacles are new.","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The subject of the sentence is "spectacles", which is a plural noun.The verb "are" is the correct form to use with a plural subject. "Spectacles" refers to two glasses, one for each eye, so it''s a plural noun.', 0, 0, 0, 1790961809016) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3c3cb0de461c7b59', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My sister is not studying hard but I ______?', '{"A":"Has","B":"Have","C":"Am","D":"Are"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence should read: "My sister is not studying hard, but I am."This is a comparative sentence, where the speaker is contrasting their own behavior with that of their sister.The correct verb to use in this case is "am", which is the first person singular form of the verb "to be".', 0, 0, 0, 1790961809103) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ddc1bdd074716bd8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Punctuation is the series of _____?', '{"A":"Norm","B":"Conventions","C":"Symbols","D":"Letters"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Punctuation is a series of symbols and marks that make written language easier to read. We use punctuation marks to denote pauses, separate elements of sentences, or add emphasis to parts of our writing.', 0, 0, 0, 1790961809103) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2a935700c16f0d5b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The man (who is sitting in the room) is good one. Which type of punctuation is used in this sentence.', '{"A":"Parenthesis","B":"Hyphen","C":"Square bracket","D":"Colon"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Punctuation is used to clarify the meaning of written or printed language.Well-planned word order requires a minimum of punc - tuation.', 0, 0, 0, 1790961809103) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cd62733ca45eac9e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Frugal : Parsimonious :: ?', '{"A":"Joy : Ecstasy","B":"Rich : Poor","C":"Love : Hate","D":"Poor : Misery"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Frugal and parsimonious are synonyms of each other and bear the meaning ''being stingy'' or ''sparing''. Similarly, joy and ecstasy are related to happiness.', 0, 0, 0, 1790961809103) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e85498e9968c0e73', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He tames animals because he _______?', '{"A":"Is fond of them","B":"Hates them","C":"Is afraid of them","D":"Wants to set them free","E":"Seldom loves them"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tame animals mean جانور پالناHe is fond وہ شوقین ہے', 0, 0, 0, 1790961809103) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_42372da1a3e8de32', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'How many compound consonants are there in shorthand?', '{"A":"22","B":"24","C":"26","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In shorthand, there are 24 compound consonants.They are formed by combining simple consonant sounds to represent complex sounds.', 0, 0, 0, 1790961809103) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0eaa22cbbc9029f8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which type of sentence: Go to your room?', '{"A":"Declarative","B":"Interrogative","C":"Imperative","D":"Exclamatory"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “Go to your room” is an imperative sentence because it expresses an order or command.', 0, 0, 0, 1790961809103) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4a15a8387cb55597', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which consonant is written in two different ways?', '{"A":"H","B":"Y","C":"K","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The consonant "H" can be written in two distinct ways:Uppercase (H)Lowercase (h)', 0, 0, 0, 1790961809103) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_347fe48e19d7b580', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'To carry the day means _____?', '{"A":"To succeed","B":"To loose something","C":"To win a victory","D":"To do something wrong"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The meaning of the phrase to carry the day: to achieve victory. They had a bad start, but the home team managed to carry the day in the end.ND4-5-2023', 0, 0, 0, 1790961809201) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_48f05f1305d2c4dd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Dream transferred ______ reality by did not of Hard work.', '{"A":"Into","B":"In","C":"To","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Into is a preposition that shows what something is within or inside. As separate words, in and to sometimes simply wind up next to each other.', 0, 0, 0, 1790961809201) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2173be3798f7efe1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is ______ the menu today?', '{"A":"On","B":"In","C":"Onto","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In can be used in the following ways: as a preposition (followed by a noun): The children are in the garden. As an adverb (without a following noun): Come in and sit down.', 0, 0, 0, 1790961809201) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d86b2dc1a29997dc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Have you applied ______ this job.', '{"A":"For","B":"To","C":"On","D":"In"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It can serve as another means of disclosing distance, quantity, or a duration of time (e.g., “for several miles,” “for five dollars,” or “for ten minutes”). One of the most common uses of “for” is simply to identify the object in a sentence.', 0, 0, 0, 1790961809201) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fa51e9e5e177ee17', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Change voice: By whom are these clothes are needed?', '{"A":"Who needs these clothes?","B":"Whom needs these clothes?","C":"Who needs  are these clothes?","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct sentence is "Who needs these clothes?"In passive voice, the subject is changed to "who," and the verb is adjusted to match the structure.', 0, 0, 0, 1790961809201) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3cd80f9c61d02975', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Change voice: The company has fired some workers?', '{"A":"Some workers has been fired by the company","B":"Some workers have been fired by the company","C":"Some workers had been fired by the company","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In passive voice, the object (some workers) becomes the subject.The verb (has fired) changes to have been fired to agree with the plural subject.', 0, 0, 0, 1790961809201) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4522be5fc031d20f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The word "but" is a ____?', '{"A":"Conjunction","B":"Preposition","C":"Interjection","D":"Verb"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Explanation: "But" is used to connect contrasting ideas, making it a conjunction.', 0, 0, 0, 1790961809201) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d655fa0690155c8a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Life promises a lot ______ pleasure.', '{"A":"With","B":"For","C":"Of","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Life promises a lot of pleasure.***a lot of (Idiom): a large number or amount of somebody/ somethingHere, of is the right usage.because "of" is the preposition used to show somebody/something belongs to a group (a lot of pleasure)**', 0, 0, 0, 1790961809201) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a83cda963403ea7e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The United States is __________that there are five time zones.', '{"A":"Too big","B":"So big","C":"Very big","D":"Much big"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ''So'' is placed before a modifier — adjective or adverb — to intensify its quality or manner.‘So’ emphasis on the modifier expresses a remarkable situation.This clause can stand alone as a sentence, or it can be paired with ''that'' + clause to express an effect (result) of the remarkable situation mentioned in the main clause.The United States is so big that there are five time zones.', 0, 0, 0, 1790961809323) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e24c2ad70b010145', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Well I don''t think i will be home before 6 pm. In this sentence well is _____?', '{"A":"Interjection","B":"Adverb","C":"Adjective","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the sentence "Well, I don''t think I will be home before 6 pm", the word "well" is an interjection.In this sentence, "well" is used to express a sense of hesitation, resignation, or softening the tone of the statement.', 0, 0, 0, 1790961809323) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_25b0d1a29e955416', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She is my mother in law. Which punctuation mark is used in the sentence?', '{"A":"Exclamation","B":"Apostrophe","C":"Hyphen","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence "She is my mother-in-law" contains a hyphen (-) which is used to join two words (mother and in-law) to form a compound adjective.It modifying the noun "She".', 0, 0, 0, 1790961809323) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e193b58786ce7236', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'If wishes _____ horses, beggars would ride.', '{"A":"Were","B":"Was","C":"Have","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase is: "If wishes were horses, beggars would ride."This is a common English idiom that means that wishes are not enough to make something happen; it takes more than just wishing for something to become a reality.The phrase is often used to convey that simply wishing for something is not enough; it requires effort and action to achieve it.', 0, 0, 0, 1790961809323) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cdeb532294d881ba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Madness : Brain :: Paralysis : ____?', '{"A":"Body","B":"Arms","C":"Nerves","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Madness is to Brain as Paralysis is to Nerves.Paralysis typically results from damage to the Nerves, which control muscle movements in the body.Much like Madness affects the Brain.', 0, 0, 0, 1790961809323) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9706cf45e5bc853e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is looking for someone to offer, her glamours and well paid and undemanding job, but I think he is _____?', '{"A":"Crying for moon","B":"Hard boiled","C":"Happy go lucky","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Crying for the moon" means wanting something impossible or unrealistic.In this context, it suggests he is seeking an ideal job that may not exist.', 0, 0, 0, 1790961809323) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_699f3605179650df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Talk : Stammer ::', '{"A":"Play : Speak","B":"Scrabble : Walk","C":"Walk : Stagger","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Talk : Stammer :: Walk : StaggerImproper writing is called scribbling. Similarly, improper speaking is called stammering.ND07-3-2023', 0, 0, 0, 1790961809323) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fc096f1a8e8a3827', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Change Voice: Daniel is singing a song.', '{"A":"A song is being sung by Danial.","B":"A song had being sung by Danial.","C":"A song was being sung by Danial.","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Convert the object of the Active Voice Sentence into the subject of the Passive Voice Sentence. Use the additional helping verb “being” with “is/are/am”, to show the continuous tense. Use 3rd form of the verb. Use the word “by”, to show the doer.', 0, 0, 0, 1790961809323) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a19d76ec16d07c68', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Eat one''s cake and have it means ____?', '{"A":"Policy in coach fighting among friends","B":"A policy to keep dog as a house guard","C":"To maintain disease cat","D":"Have it both ways"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To have or do two good things at the same time that are impossible to have or do at the same time.چوپڑیاں اور وہ بھی دو دو کی خواہش', 0, 0, 0, 1790961809413) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ce7084bcb2bd591c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The Principal will preside ______ the function.', '{"A":"Over","B":"From","C":"With","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Preside over is a phrasal verb.Preside over means صدارت کرناHe will preside over the function.', 0, 0, 0, 1790961809413) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d6f1d63ab306fd0c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He has been suffering from fever ____ the last 3 days.', '{"A":"Since","B":"For","C":"From","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use since with a point in time in the past. For refers to periods of time, e.g. 3 years, 4 hours, ages, a long time, months, years.', 0, 0, 0, 1790961809413) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ce8108b6587feac5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My father was so poor ________?', '{"A":"That he could not buy our food","B":"That who could not buy us food","C":"To he could not buy us food","D":"That he could not buy us food"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence should read: "My father was so poor that he could not buy us food."This sentence is a common idiomatic expression used to describe someone''s extreme poverty.The phrase "so poor" is an intensifier, emphasizing the extent of the poverty, and the clause "that he could not buy us food" explains the severity of the situation.', 0, 0, 0, 1790961809413) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a0ae5f300d5a8fba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Young : Old :: Morning : ____?', '{"A":"Early","B":"Late","C":"Time","D":"Evening"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Young : Old :: Morning : Evening', 0, 0, 0, 1790961809413) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_157fec8fea166874', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He sat _____ the shadow of the tree.', '{"A":"Under","B":"Below","C":"Beneath","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "under the shadow of the tree" is commonly used in English to indicate sitting within the shade provided by the tree.So, the complete sentence is: He sat under the tree''s shadow.', 0, 0, 0, 1790961809413) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3522d576fb121249', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He have had _____ trouble ____ he parked the car in garage.', '{"A":"Some/that","B":"So much/that","C":"Much/and","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "So much" expresses the quantity of trouble, while "that" introduces the result of parking the car in the garage. The phrase "so much...that" is commonly used to indicate cause and effect.', 0, 0, 0, 1790961809413) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2e938f91a56078d6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They burst _______ tears.', '{"A":"Into","B":"On","C":"In","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation They burst into tears means to start to cry.In the phrase "burst into tears," the word "into" is used to indicate a transition or change of state."Burst" suggests a sudden.', 0, 0, 0, 1790961809413) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f103b1842dc83007', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Monkeys live _____ the trees.', '{"A":"Into","B":"By","C":"Over","D":"On"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On is used to refer a surface.On اوپر، پرOn is a preposition here.Monkeys live on the trees.', 0, 0, 0, 1790961809494) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c058f1385637c951', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Imperative mode verb represents _____?', '{"A":"Pray, advice and request","B":"Wishes and purpose","C":"Pity and curse","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The imperative mode verb is used to express commands, requests, advice, or prayers, directing someone to take action.It typically forms direct statements or instructions.', 0, 0, 0, 1790961809494) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8aad1f472a712620', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'While this incident come ______?', '{"A":"Round","B":"About","C":"By","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation While this incident come about.جبکہ یہ واقعہ کے بارے میں آیا ہے۔The correct phrase is "come about," which means to happen or occur.It’s commonly used to describe how an event or incident took place.', 0, 0, 0, 1790961809494) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c5839aca46b32f71', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which verb form ends in "ing" and acts as a noun?', '{"A":"Participle","B":"Infinitive","C":"Gerund","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A gerund is a verb form that ends in "-ing" and acts as a noun.It is formed by adding the suffix "-ing" to the base form of a verb.Gerunds can function as subjects, complements, or objects of a sentence.Examples:Singing is my favorite hobby. (Here, "singing" is a gerund and the subject of the sentence.)I love watching movies. (Here, "watching movies" is a gerund and the object of the verb "love".)', 0, 0, 0, 1790961809494) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d9b419ce0ec02732', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'John Came later than I. The word later is?', '{"A":"Adverb","B":"Verb","C":"Noun","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Later" is an adverb in this sentence.It modifying the verb "came" to indicate when John arrived.', 0, 0, 0, 1790961809494) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8547bd01a43ccd9a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Select the pair which has the same relationship "MUNDANE: SPIRITUAL?', '{"A":"Common: Ghostly","B":"Routine: Novel","C":"Worldly: Unworldly","D":"Secular : Clerical"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mundane: Spiritual :: Worldly : Unworldly', 0, 0, 0, 1790961809494) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_65893de1ac8a2c25', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'This chair resembles _____ that of Mr. Rasool Bux.', '{"A":"Of","B":"To","C":"With","D":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This chair resembles that of Mr. Rasool Bux.یہ کرسی جناب رسول بخش کی کرسی سے ملتی ہے۔----"Resemble" is a transitive verb, meaning it takes a direct object. It doesn''t require a preposition like "to", "with", or "of" before the object it describes. In this case, the object is "that of Mr. Rasool Bux"So, no preposition like of, to, or with is used after resemble.', 0, 0, 0, 1790961809494) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7d6b2d137dd30966', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'LFO stands for what?', '{"A":"Legal Federation Order","B":"Legal Framework Ordinance","C":"Legal Framework Order","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first constitution of Pakistan was abrogated in favor of the Legal Framework Order (LFO) in 1958 during General Ayub Khan''s military coup.The LFO served as a temporary legal framework until the 1962 constitution.', 0, 0, 0, 1790961809494) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7f52705cfa34418b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Alia parted _______ her parents in tears.', '{"A":"With","B":"By","C":"From","D":"Of"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "parted from" is used when someone is leaving or separating from another person.It especially in an emotional context like Alia parting from her parents in tears.', 0, 0, 0, 1790961809598) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_30e147821440eaa7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I met ___ European.', '{"A":"A","B":"An","C":"The","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I met a <-----( article )European <---(noun)The indefinite article (a, an) is used before a noun that is general or when its identity is not known.ND07-3-2023', 0, 0, 0, 1790961809598) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6e49f0eb6fd9094d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_____ dangerously a person lives, _____ likely he or she is to die young.', '{"A":"So/much more","B":"As much/too","C":"The more/the more","D":"The most/the most"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "The more dangerously a person lives, the more likely he or she is to die young".ایک شخص جتنی خطرناک زندگی گزارتا ہے، اس کے جوان مرنے کا امکان اتنا ہی زیادہ ہوتا ہے۔It means that increased danger in one''s lifestyle correlates with a higher likelihood of an early death.', 0, 0, 0, 1790961809598) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5873d515ef9e98a8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'After Lunch let''s go out for a coffee. Here "After" is _____?', '{"A":"Adjective","B":"Noun","C":"Adverb","D":"Preposition"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word after can be used as a preposition, an adverb and a conjunction. When it is used as a preposition, it is followed by a noun.', 0, 0, 0, 1790961809598) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e1fd1fb3824149da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I should hate to be confined ______ an office all day .', '{"A":"From","B":"In","C":"By","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct sentence is "I should hate to be confined in an office all day."The preposition "in" is used to indicate being enclosed or restricted within a place.', 0, 0, 0, 1790961809598) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3654dde025f9b396', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Identify the part of speech that policeman is friend of "mine."', '{"A":"Brussels","B":"Pronoun","C":"Accra","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the sentence, "mine" is a possessive pronoun.It indicating ownership or association with "friend."', 0, 0, 0, 1790961809598) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e839a90bb76db3ba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She was sitting _____ her mother.', '{"A":"Along","B":"Besides","C":"Beside","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The preposition "beside" indicates that she was sitting next to her mother.Beside means پاس', 0, 0, 0, 1790961809598) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_77c6603392918945', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which one is correct? That car is not yours., That car is not theirs., The library lost all its books., None of these', '{"A":"That car is not yours.","B":"That car is not theirs.","C":"The library lost all its books.","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation All three sentences are grammatically correct. However, if you need to mark only one, you can choose:"The library lost all its books."', 0, 0, 0, 1790961809598) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9f1b5a4c1ba870c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They decided to buy the house because ______ location would allow _____ to work to get very easily.', '{"A":"Its/them","B":"Its/they","C":"Its/that","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Its" to refer to the location of the house."Them" as the pronoun referring to the individuals deciding to buy it.', 0, 0, 0, 1790961809702) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2094920fda4556ef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Send the parcel _______ this address.', '{"A":"To","B":"In","C":"On","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When sending a parcel, the preposition "to" indicates the destination or recipient''s address.It is used to specify the location where the parcel should be sent.', 0, 0, 0, 1790961809702) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_10d97911a21312d8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Coffee : Beverages ::', '{"A":"Bread : Butter","B":"Milk : Tea","C":"Burger : Snacks","D":"Grapes : Wine"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Coffee means قہوہBeverage means مشروبBurger means سادَہ بَند جِس کے اندَر انڈا، قِیمَہ اور سَلاد ڈال کَر کھانے کے لِیے بَنایا گَیا ہو Snacks means کھانے کی ہلکی چیز', 0, 0, 0, 1790961809702) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dea53d3737500d94', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We should take taxi ___ it is more expensive.', '{"A":"And","B":"Though","C":"Even if","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We should take a taxi even if it is more expensive.ہمیں ٹیکسی لینا چاہئے چاہے وہ زیادہ مہنگی ہو۔"Even if" is used to show a condition that will not change the decision or outcome.', 0, 0, 0, 1790961809702) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cdfe985c4a5cefcd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The Son amused himself. Himself is?', '{"A":"Noun","B":"Adverb","C":"Pronoun","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Himself" is a reflexive pronoun.It is used here to reflect back on the subject "The Son."It indicates that the action was done by him for his own enjoyment.', 0, 0, 0, 1790961809702) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f831298b2704c5a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It was a mistake that I didn''t ______ the contract before signing it.', '{"A":"Check out","B":"Look through","C":"Come by","D":"See out"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It was a mistake that I didn''t look through the contract before signing it.یہ ایک غلطی تھی کہ میں نے معاہدے پر دستخط کرنے سے پہلے اسے نہیں دیکھا۔"Look through" means to carefully examine or review something.It would have been the appropriate action to avoid mistakes in signing the contract.', 0, 0, 0, 1790961809702) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_323907dd3df95028', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Wow what a cold weather which sign is use at the end?', '{"A":":","B":"?","C":"!","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An exclamation mark (❗) is used to express strong feelings or emotions. As in "Wow, what a cold weather!"', 0, 0, 0, 1790961809702) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_46d57e736d9ef681', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Do you think we won a match. Which sign is used?', '{"A":".","B":"?","C":",","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A question mark (❓) is used at the end of interrogative sentences.Like "Do you think we won a match?" to indicate a question.', 0, 0, 0, 1790961809702) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eebafb5b5f65faec', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The authority failed to carry ______ its statutory duties.', '{"A":"Up","B":"Out","C":"With","D":"On"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "carry out" means to perform or execute a task or duty.In this context, the sentence suggests that the authority failed to perform its statutory duties.', 0, 0, 0, 1790961809781) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ed4ed2a28b6f5625', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Don''t change _____ in midstream.', '{"A":"Horses","B":"Trophies","C":"Players","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The idiom "Don''t change horses in midstream."It means not to make major changes or switch plans when you''re already in the middle of a process.', 0, 0, 0, 1790961809781) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_763d9571807db78d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The Opposte of Profane is?', '{"A":"Arrogant","B":"Benign","C":"Respectful","D":"Pious"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Profane means بے حرمتی کرناRespectful means با عزت', 0, 0, 0, 1790961809781) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bd78abe6a6a708f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You cannot have your _______ and eat it too.', '{"A":"Rolls","B":"Pudding","C":"Cake","D":"Meat"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "You can''t have your cake and eat it too".آپ اپنا کیک نہیں کھا سکتے اور اسے بھی کھا سکتے ہیں۔It means that you can''t enjoy the benefits of two things that are mutually exclusive.It''s a idiomatic expression that suggests you can''t have two things that don''t go together.', 0, 0, 0, 1790961809781) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_66207e6219dbd13c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Work hard lest you ______?', '{"A":"Should fail","B":"Can fail","C":"May fail","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lest always takes should. Because “should” is used to indicate what is probable, here failure on not working hard.', 0, 0, 0, 1790961809781) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b45be5d49d4d7185', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He was destined ___ the bar.', '{"A":"To","B":"For","C":"At","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He is destined for the bar.وہ بار کا مقدر ہے۔The phrase "destined for" is used to indicate that someone is meant or fated to achieve or reach a particular goal, like "the bar" in this case.', 0, 0, 0, 1790961809781) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fcf14a67fac4c86f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The sound produced by horse is called?', '{"A":"Jingle","B":"Neigh","C":"Scream","D":"Squeak","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Neighing گھوڑے کی آوازMewing بلی کی آوازCawing کوے کی آواز', 0, 0, 0, 1790961809781) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7fc937637a2dffa3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The word “Troupe” means a collection of _____?', '{"A":"Actors","B":"Players","C":"Trees","D":"None of these","E":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Troupe means فنکاروں یا پھر رقص کرنے والوں کا گروہ', 0, 0, 0, 1790961809781) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c0439a62a221f3a0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She covered her face with a ________?', '{"A":"Wail","B":"Vail","C":"Veil","D":"Vale","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Veil means پردہ', 0, 0, 0, 1790961809870) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_61fb230d28ec76f1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Of wealth and health, the _______ is the most important.', '{"A":"Later","B":"Latter","C":"Latest","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Later means بعد میں آنے والا', 0, 0, 0, 1790961809870) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9e6e547be0881095', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She is ______ than I.', '{"A":"More pretty","B":"Most pretty","C":"Pretty","D":"Prettier","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Adjective: PrettyComparative: Prettier Superlative: Prettiest', 0, 0, 0, 1790961809870) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_64e3721c8ee08b03', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The father ______ the son to remain honest in life.', '{"A":"Adviced","B":"Advised","C":"Advices","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Advise is a verb which means نصیحت کرنا', 0, 0, 0, 1790961809870) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0c59c9169270556e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The plural of Mrs. is?', '{"A":"Messers","B":"Misses","C":"Mesdames","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The plural of "Mrs." is "Mesdames".It is used to address or refer to multiple married women.It is derived from French and means "ladies" in formal usage.', 0, 0, 0, 1790961809870) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f116a938689e919e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The plural of the nouns “Negro” is?', '{"A":"Negroes","B":"Negrose","C":"Negros","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Negro means سیاہ فامجو افریقہ سے ہو یا پھر جس کے آباو اجداد افریقی ہوں۔', 0, 0, 0, 1790961809870) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e43d9d86c59153c3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The plural of the Noun “Dwarf” is?', '{"A":"Dwarves","B":"Dwarvs","C":"Dwarfes","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dwarf means پست قد والا آدمی The plural of "dwarf" is "dwarfs" or "dwarves." Dwarfs are often also described as short and ugly.Dwarves in folklore are usually described as old men with long beards.', 0, 0, 0, 1790961809870) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3f57f686c3c90ce6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Past Participle of the Verb “Bend” is?', '{"A":"Bended","B":"Bound","C":"Binded","D":"Bent"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The past participle of the verb "bend" is bent.It is used in perfect tenses, like "She has bent the metal into shape."', 0, 0, 0, 1790961809870) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d57400ffcceea233', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Past Participle of the Verb “Lie” is?', '{"A":"Lay","B":"Laid","C":"Lain","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A past participle is a word that is formed from a verb is used as an adjective or to form verb tense.The past participle of the verb "lie" (to recline) is "lain."It is used in perfect tenses, like "I have lain down for a nap."', 0, 0, 0, 1790961809958) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fdeb9c2735629db5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '______ you call your friend yesterday?', '{"A":"Have","B":"Had","C":"Will","D":"Did"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Did you call your friend yesterday?did used in past simple tense the simple past tense is: did + [subject] + [root form of verb].ND11-4-2023', 0, 0, 0, 1790961809958) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8c9ecb9eee7b14a8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I ______ lie from now.', '{"A":"Don''t","B":"Won''t","C":"Haven''t","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I won''t lie from now on?***Won''t is a contraction of will not.Won’t is a modal verb. It is the negative of the word ‘will’. It is used to talk about future tense. ND11-4-2023', 0, 0, 0, 1790961809958) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d76e76f7baba62c3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He always comes _______ home late.', '{"A":"To","B":"At","C":"Both","D":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He comes home late.Usually no article required before home or house.', 0, 0, 0, 1790961809958) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_59aa123da3476c14', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is now ashamed ___ his conduct.', '{"A":"From","B":"With","C":"Of","D":"By"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ashamed is generally followed by of.Of is a preposition here.Ashamed of something means کسی بات پر شرمندہ ہوناHe is ashamed of his conduct.', 0, 0, 0, 1790961809958) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_640f337100a0bb41', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I did not ____ to university yesterday', '{"A":"Went","B":"Go","C":"Gone","D":"Going"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use the "first form of the verb" because of the use of " did"the simple past tense is did + [subject] + [root form of verb].ND11-4-2023', 0, 0, 0, 1790961809958) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_105a87aa42cdb491', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He tried to park his car but _______ space wasn''t big enough.', '{"A":"A","B":"An","C":"The","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation His tried to park his car but the space wasn''t big enough.article (the) is used before a noun to indicate the identity of the noun''''space'''' is a common noun.ND11-4-2023', 0, 0, 0, 1790961809958) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_605d6754f9d04244', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Can you switch off ___ television, please.', '{"A":"The","B":"A","C":"Of","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Can you switch off the television?We use the article THE when we refer to television as a device or a piece of furnitureND11-4-2023', 0, 0, 0, 1790961809958) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_aca61afada46f9aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My brother was trembling ____ cold.', '{"A":"From","B":"With","C":"By"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation With is a preposition here.Trembling with cold means سردی سے کانپنا"My brother was trembling with cold."We use with here to show the cause or reason for the trembling.', 0, 0, 0, 1790961810051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_af379162da046783', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Would you mind ____a picture with me?', '{"A":"Take","B":"To take","C":"Taking","D":"Taken"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Would you mind taking a picture with me?taking present participle of takeND11-4-2023', 0, 0, 0, 1790961810051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3a343b3da5005428', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A group of cattle is called ______?', '{"A":"Herd","B":"Swarm","C":"Troop","D":"Company","E":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cattle means مویشیSwarm means مچھر یا تڈی دل وغیرہ کا بہت بڑا اڑتا ہوا گروپTroop means فوجی دستہ Herd means ریوڑ', 0, 0, 0, 1790961810051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ea7147a9b8174b2c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_______ is the best policy.', '{"A":"Integrity","B":"Honesty","C":"Silence","D":"Telling","E":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "Honesty is the best policy".Itmeans that being truthful and straightforward is the most effective and morally sound approach in life.It leading to trust and long-term success.Honesty is the best policy means ایمانداری بہترین پالیسی ہے۔', 0, 0, 0, 1790961810051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ed23450e8bde0c83', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He was waiting _______ the door.', '{"A":"At","B":"Over","C":"On","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He was waiting at the door.وہ دروازے پر انتظار کر رہا تھا۔"At" is used to indicate a specific location, such as waiting at the door.It conveys that the person is positioned near or in front of the door.', 0, 0, 0, 1790961810051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1b9dead6f33b588a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Honesty is the _____ policy.', '{"A":"Best","B":"Worst","C":"Manifest","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "Honesty is the best policy".Itmeans that being truthful and straightforward is the most effective and morally sound approach in life.It leading to trust and long-term success.', 0, 0, 0, 1790961810051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dd624d8c7ac37f97', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She slept ___ the movie.', '{"A":"While","B":"During","C":"At","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use during to talk about when something happens in relation to another event which lasts for a period of time.During means کے درمیان', 0, 0, 0, 1790961810051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a5acaa9b1fe1af5b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She found it easy _______ the test.', '{"A":"Finish","B":"Finished","C":"Finishing","D":"To finish"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She found it easy to finish the test.اسے امتحان ختم کرنا آسان معلوم ہوا۔The phrase "found it easy to finish" correctly uses the infinitive form "to finish" to describe the ease of completing the test.', 0, 0, 0, 1790961810051) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_47845d3df3e3c4d2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She lives _______ Madiha.', '{"A":"With","B":"Above","C":"Under","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She lives with Madiha means وہ مدیحہ کے ساتھ رہتی ہےWith is a preposition here.', 0, 0, 0, 1790961810143) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_32599db103c6f53c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The Chairman is ill and we will have to ___ the meeting for a few days.', '{"A":"Put on","B":"Put of","C":"Put off","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The chairman is ill and we will have to put off the meeting for a few days.چیئرمین بیمار ہیں ہمیں چند روز کے لیے اجلاس ملتوی کرنا پڑے گا۔Put off : postpone; to change something to a later time or dateHere, put off is the right usage.Put off is a phrasal verbSh6-8-2023', 0, 0, 0, 1790961810143) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_28ce93fe56a32849', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'AERIE : EAGLE ::', '{"A":"Capital : Government","B":"Bridge : Architect","C":"House : Person","D":"Kennel Veterinarian"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation AERIE : EAGLE :: House : personAn aerie is where an eagle lives; a house is where a person lives.', 0, 0, 0, 1790961810143) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_62268860f5092599', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We lost confidence in Amjad _______ that grandiose promises he had made.', '{"A":"Tired of","B":"Delivered on","C":"Retreated form","D":"Forgot about"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We lost confidence in Amjad delivered on the grandiose promises he had made.ہم نے امجد کے ان شاندار وعدوں پر اعتماد کھو دیا جو اس نے کیے تھے۔***delivered on: to do what is required by (a promise or pledge)"Delivered on" is best to keep the meaning of the original sentence***This is the past sentences we use the second foam of the verbInfinitive Past Simple Present ParticipleDeliver Delivered Delivering', 0, 0, 0, 1790961810143) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7430e110c8242f8d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The unruly behavior of the children ____ their parents.', '{"A":"Incensed","B":"Impeached","C":"Aggrieved","D":"Tempered"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The unruly behavior of the children incensed their parents.incensed: ناراضOption A is best to keep the meaning original sentenceIf we choose another option It can change the meaning of the whole sentenceND-21-5-2023', 0, 0, 0, 1790961810143) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cfc7e25cd42c5b29', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He traveled ____ difficult circumstances.', '{"A":"Under","B":"In","C":"About","D":"Above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He traveled under difficult circumstances.The preposition "under" is used to indicate being affected by or enduring certain conditions.', 0, 0, 0, 1790961810143) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9581e0424f9b75bc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Either you or he _______ at fault.', '{"A":"Are","B":"Have","C":"Is","D":"Will","E":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Either or takes verb from second subject (he) We use is with he or she. Either you or he is at fault یا تو آپ یا وہ غلطی پر ہیں', 0, 0, 0, 1790961810143) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_beac158a6943e5d6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Free books should be provided ________ poor students.', '{"A":"For","B":"Or","C":"On","D":"To"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Free books should be provided to poor students.غریب طلباء کو مفت کتابیں فراہم کی جائیں۔''Provide to'' means that something is provided directly to someone.', 0, 0, 0, 1790961810144) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9eed0071494b2c14', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Here are your shoes. I ________ them.', '{"A":"Have just cleaned","B":"Just Cleaned","C":"Had Just Cleant","D":"Just clean","E":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence should read: "Here are your shoes. I have just cleaned them."یہ رہے آپ کے جوتے۔ میں نے ابھی انہیں صاف کیا ہے۔This is a present perfect tense construction, indicating that the action of cleaning the shoes has been completed recently.', 0, 0, 0, 1790961810259) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_62049d07d8474ac5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The robbers set _____ the unarmed travellers.', '{"A":"Upon","B":"With","C":"From","D":"To"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Set upon/on is a phrase.Set upon/on means اچانک حملہ کردیناThe robbers set upon the unarmed travellers ڈاکوؤں نے نہتے مسافروں پر حملہ کر دیا', 0, 0, 0, 1790961810259) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4065be2e0b790321', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Can I have some milk before ____ to bed.', '{"A":"Going","B":"Goes","C":"Go","D":"am going"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrasing is "Can I have some milk before going to bed?When using "before," the gerund form (verb + -ing) is used to indicate the action that happens before another action.', 0, 0, 0, 1790961810259) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_45263bcf416600f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She _____ her degree twenty years ago.', '{"A":"Has completed","B":"Was completed","C":"Completed","D":"Has been completing"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Here twenty years ago indicates past tense. We use second form of verb (completed) in simple sentence of this tense. She completed her degree twenty years ago means اس نے بیس سال پہلے اپنی ڈگری مکمل کی تھی', 0, 0, 0, 1790961810259) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3a0636a824d4ae3c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is ______ at copying.', '{"A":"Adept","B":"Adopt","C":"Edept","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He is adept at copying.وہ نقل کرنے میں ماہر ہے۔Adept is an adjective meaning “proficient or well trained.”Adept is best to keep the meaning of the original sentence.', 0, 0, 0, 1790961810259) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ff3e506d22d95973', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'All cabin attendants must lock the cabin door ______ leaving the room.', '{"A":"Afterwards","B":"Letter than","C":"After","D":"Therefore"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation All cabin attendants must lock the cabin door after leaving the roomتمام کیبن اٹینڈنٹ کو کمرے سے نکلنے کے بعد کیبن کا دروازہ لاک کرنا چاہیے', 0, 0, 0, 1790961810259) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6d2d29d3666ff909', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Seeing is believing. Here "believing" is ________', '{"A":"Noun phrase","B":"Adjective phrase","C":"Gerund phrase","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Believing is a gerund used as a noun.The gerund phrase functions as the subject of the sentence.gerunds by adding “-ing” to a verb base, for instance, “seeing” or “believing,” as in “seeing is believing.” The underlying sense of “seeing” and “believing” in that sentence is “the act of seeing” and “the act of believing.” Note that “-ing” can turn an English verb base into a gerund (a noun)ND-18-8-2023', 0, 0, 0, 1790961810259) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9b7bdad46faed838', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'This house is superior ________ the other.', '{"A":"Over","B":"From","C":"Than","D":"To"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This house is superior to the other.یہ گھر دوسرے سے برتر ہے۔***superior to: one who is above another in rankpreposition "to" is used to show the comparison between the two things. ND-18-8-2023', 0, 0, 0, 1790961810259) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9e646e9a2ffd8514', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He ran ____ as he could.', '{"A":"Quick","B":"Quickly","C":"Faster","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He ran quickly as he could وہ جتنی جلدی ہو سکا بھاگا۔Quickly is best to keep the meaning of the original sentenceSH18-8-2023.', 0, 0, 0, 1790961810344) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3e6e04e8e1ac367f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am exhausted, let''s ______ a day?', '{"A":"Call at","B":"Call it","C":"Call in","D":"Call of"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I am exhausted, let''s call it a day.میں تھک گیا ہوں چلو آج کا کام یہیں ختم کرتے ہیںThe correct phrase is "call it a day," meaning to stop working or end an activity.It typically because you''re tired or have accomplished enough for the day.', 0, 0, 0, 1790961810344) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_70870ff6d9040afe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Slow and steady _____ the race.', '{"A":"Win","B":"Wins","C":"Is winning","D":"Won","E":"Has won"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Slow and steady wins the race means consistent, effective effort leads to success.Slow and steady wins the race means آہستہ اور اطیمنان کا کا م بہتر ہوتا ہےAGM 30.4.23', 0, 0, 0, 1790961810344) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_044a66ae52b9cfaa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Graceful : Movement ::', '{"A":"Servile : Rebellion","B":"Humorous : Laughter","C":"Fastidious : Grime","D":"Articulate : Speech"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct analogy is "Articulate : Speech".As being articulate relates to clear and effective speech.Just as being graceful relates to elegant movement.', 0, 0, 0, 1790961810344) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e2e743da7577bf6f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The word pair given in the following question has a certain relationship. Select from answer choices a word pair having same relationship. Encourage : restrict ::?', '{"A":"Dearth : Surplus","B":"Gain : Succeed","C":"Laugh : Smile","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The relationship between the words "Encourage" and "Restrict" is that they are antonyms, meaning they have opposite meanings. "Encourage" means to support or promote something."Restrict" means to limit or control something.Similarly, the word pair "Dearth" and "Surplus" are also antonyms."Dearth" means a scarcity or lack of something."Surplus" means an excess or abundance of something.', 0, 0, 0, 1790961810344) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1d62b1726a677c92', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'His voice gets on my ____?', '{"A":"Ears","B":"Mind","C":"Brain","D":"Nerves"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "His voice gets on my nerves".اس کی آواز میرے اعصاب پر سوار ہو جاتی ہے۔It means that the person''s voice annoys or irritates the speaker.It suggests a level of discomfort or frustration caused by the sound or manner of speaking.', 0, 0, 0, 1790961810344) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0dc180ccd5db5456', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The practice of taking someone else’s work or ideas and passing them off as one’s own is known as?', '{"A":"Original","B":"Plagiarism","C":"Fake","D":"Inspired"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Plagiarism is the practice of taking someone else’s work, ideas, or intellectual property and presenting them as one''s own without proper attribution.It is considered unethical and dishonest in academic and professional settings.', 0, 0, 0, 1790961810344) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_21decdff43f0b3eb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Never-never land means ______?', '{"A":"An ideal place.","B":"Dream land.","C":"A worthless place.","D":"A useless situation."}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Never-never land" typically refers to a dreamlike or idealized place or situation.It often associated with fantasy or imagination.', 0, 0, 0, 1790961810344) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1836e8187f862285', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She will invite me.', '{"A":"I will invited by her.","B":"I shall being invited by her.","C":"I will been invited by her.","D":"I shall be invited by her."}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct passive form is: "I shall be invited by her."In passive voice, "will invite" changes to "shall be invited" to maintain proper future tense and passive structure.', 0, 0, 0, 1790961810426) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f69737af228ddf84', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Prosaic means _____?', '{"A":"Dull","B":"Dashing","C":"Litigious","D":"Petulant"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Prosaic means بے لطف بے مزہDull means پھیکا', 0, 0, 0, 1790961810426) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4dc18f0f931fdb65', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My friend said me, has Saima talked to Sonia?', '{"A":"My friend asked me to have some talk with Saima","B":"My friend asked me if Saima had talked to Sonia","C":"My friend inquired me to has Saima talk with Sonia","D":"My friend said to me that has Saima talk with Sonia"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The original sentence is a direct question, and when reporting it in indirect speech, we use the verb "asked" and the correct word order (subject + verb + question word). The correct indirect speech is:"My friend asked me if Saima had talked to Sonia."', 0, 0, 0, 1790961810426) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a9c38e59183f15bf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '"To hit the road " means _____?', '{"A":"Flunnish Journey","B":"Start Journey","C":"Dismantle","D":"Repair Road"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "To hit the road " means to leave a place or begin a tripND5-5-2023', 0, 0, 0, 1790961810426) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_91a9757480645c8a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'As you sow, so shall you ____?', '{"A":"Snow","B":"Reap","C":"Read","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “As you sow, so shall you reap” is a known proverb جیسا بوو گے ویسا ہی کاٹو گے۔mean that the way you behave in life will affect the treatment you will receive from others.', 0, 0, 0, 1790961810426) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7a3d72b359754502', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Both parties must adhere _____ the terms of the contract.', '{"A":"By","B":"In","C":"With","D":"To"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Both parties must adhere to the terms of the contract.This means they are obligated to follow and fulfill the conditions, obligations, and responsibilities outlined in the agreement.', 0, 0, 0, 1790961810426) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9bb660b1e770b1aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'William Shakespeare is the greatest playwright in European literature. In which category his plays fall?', '{"A":"History","B":"Tragedies","C":"Comedies","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation William Shakespeare''s plays fall into three main categories: Histories, Tragedies, and Comedies.He wrote iconic works in each genre, including Julius Caesar (history), Hamlet (tragedy), and A Midsummer Night''s Dream (comedy).', 0, 0, 0, 1790961810426) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_81ab456c8511834a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the one which best expresses the meaning of the given word ASSIMILATE?', '{"A":"Arrange","B":"Receive","C":"Absorb","D":"Assemble"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ASSIMILATE: ضم کرناAbsorb: جذب کرنا', 0, 0, 0, 1790961810426) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2fcf864956bc6bb1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Mark used to resume a scattered subject is?', '{"A":"Semicolon","B":"Inverted Commas","C":"Dash","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A dash (—) is often used to indicate a break in thought or to set off a parenthetical remark.It is commonly used to resume a scattered subject or to indicate a shift in thought.Additional InformationA colon (:) is used to introduce a list, a quotation, or an explanation.A semicolon (;) is used to separate two independent clauses that are closely related in meaning.Inverted commas ("") are used to indicate direct speech or to set off a quotation.', 0, 0, 0, 1790961810508) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d28232620c2ac28b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is the similar word of "Incendiary"?', '{"A":"Happy","B":"Jolly","C":"Causing fire","D":"Sneer"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Incendiary means آگ لگانے والاCausing fire means آگ لگانے والا', 0, 0, 0, 1790961810509) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7843a1fe3e5c4dbd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A penny for your _____?', '{"A":"Efforts","B":"Thoughts","C":"Apples","D":"Writings"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A penny for your thoughts is an idiom used to ask someone what they are thinking.It often when they seem quiet or deep in thought.', 0, 0, 0, 1790961810509) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bc917f8fb2d6c350', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She said, "What are they doing"?', '{"A":"She asked what they were doing","B":"She said what they was doing","C":"She asked what they are doing","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Direct Speech: She said, “What are they doing?”Indirect Speech: She asked what they were doing.said → asked because it is a question.are → were because the reporting verb “said/asked” is in the past tense.they remains unchanged.', 0, 0, 0, 1790961810509) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_981b027cb324975a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the statement with best punctuation: He is to tell the truth a fool?', '{"A":"He is to tell the truth a fool.","B":"He is, to tell the truth, a fool.","C":"He is to tell the truth; a fool.","D":"He is: to tell the truth, a fool."}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He is, to tell the truth, a fool.This sentence uses commas to set off the parenthetical phrase "to tell the truth".This making it clear and grammatically correct.', 0, 0, 0, 1790961810509) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_638a316aaed68ad1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Upon the inquiry I found out that I had _______ the car.', '{"A":"Mistake","B":"Mistaken","C":"Mistook","D":"Mistaking","E":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I found out that I had mistaken the car.مجھے پتہ چلا کہ میں نے گاڑی کو غلط کر دیا تھا۔Here ''had'' indicates past perfect tense. We generally use third form (mistaken) of verb in this tense. First form: MistakeSecond form: MistookThird form: Mistaken****', 0, 0, 0, 1790961810509) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_144d0f5deb42ab17', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am not concerned ______ his affairs.', '{"A":"With","B":"By","C":"Until","D":"To"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I am not concerned with his affairs With means ''in the same place as someone or something'' or ''accompanying'': She arrived with her boyfriend. I don''t like tea with milk. There was a free phone with the car.', 0, 0, 0, 1790961810509) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_70df57215c28d022', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am intent ________?', '{"A":"For winning","B":"To win","C":"On winning","D":"Of winning"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I am intent on winning means میں جیتنے کا ارادہ رکھتا ہوںGenerally preposition on is used after intent.', 0, 0, 0, 1790961810509) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2a81e13b69485ed6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which out of the following is not a novel by Thomas Hardy?', '{"A":"The Return of the Native","B":"The Winner Stands Alone","C":"Tess of the D''Urbervilles","D":"Under the Greenwood tree"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Winner Stands Alone is not a novel by Thomas Hardy; it was written by Brazilian author Paulo Coelho.Thomas Hardy is known for works like The Return of the Native, Tess of the D''Urbervilles, and Under the Greenwood Tree.', 0, 0, 0, 1790961810598) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7ce86b9f81b921d8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Exports in Chemicals and sugar have _____ a phenomenal rise this year.', '{"A":"Projected","B":"Proclaimed","C":"Declared","D":"Registered"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Exports in Chemicals and sugar have registered a phenomenal rise this year.کیمیکلز اور چینی کی برآمدات میں اس سال غیر معمولی اضافہ ہوا ہےRegistered means during this year rise has been observed', 0, 0, 0, 1790961810598) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b74b4972a99f220f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I can’t help you, I am short _____ money at present.', '{"A":"On","B":"Of","C":"From","D":"At"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "short of" is an idiom used to indicate a lack or deficiency of something. In this case, "short of money" means that you do not have enough money.', 0, 0, 0, 1790961810598) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_90b9ecc1a8e7543a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is meant by Meander?', '{"A":"A grassy area","B":"A barren area","C":"A bend of a river","D":"A bend of canal"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A bend of a river or curved path of a river is the meaning of "meander."It refers to the winding curves or turns of a river as it flows through the landscape.', 0, 0, 0, 1790961810598) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1501bb050b31dab1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He was shy _______ fighting with his opponent.', '{"A":"On","B":"Of","C":"To","D":"With","E":"In"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally shy is followed by of.Of is a preposition here.Shy of someone means کسی سے شرماناHe was shy of fighting.', 0, 0, 0, 1790961810598) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_24ec282e4e8ea1c6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He has no trust ________ his own skill.', '{"A":"On","B":"It","C":"To","D":"Against","E":"In"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He has no trust in his own skill. Trust in something means کسی چیز پر اعتماد ہونا', 0, 0, 0, 1790961810599) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b7f99ce02ed0f688', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He showed great tenacity _______ purpose in bringing the task to completion.', '{"A":"Of","B":"For","C":"At","D":"In","E":"Off"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He showed great tenacity of purpose in bringing the task to completion​.Tenacity means ثابت قدمی یا مضبوطی', 0, 0, 0, 1790961810599) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8a7a7b1f32f5239a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Our body has remarkable resistance _________ diseases.', '{"A":"To","B":"With","C":"In","D":"Off","E":"At"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct phrase is "resistance to diseases."ہمارے جسم میں بیماریوں کے خلاف غیر معمولی مزاحمت ہوتی ہے۔"To" is used to indicate the target or focus of resistance in this context.', 0, 0, 0, 1790961810599) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c5997b0b16cfa0d0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Arrange the words given below in a meaningful sequence. 1. Tree 2. Seed 3. Flowers 4. Fruit 5. Plant', '{"A":"5, 2, 1, 3, 4","B":"2, 5, 1, 4, 3","C":"2, 5, 1, 3, 4","D":"2, 5, 3, 1, 4"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Seed Plant Tree Flowers Fruit2 5 1 3 4', 0, 0, 0, 1790961810687) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5340246f89dfc31f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'FOOD is to Hunger as SLEEP is to ________ ?', '{"A":"Weariness","B":"Dream","C":"Night","D":"Rest"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Becoz without food we get hunger and without sleep we feel weariness.', 0, 0, 0, 1790961810687) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b70340da5ea3e53f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Police said they found thirty bodies ____ the wreckage.', '{"A":"In","B":"Between","C":"Among","D":"Under"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To refer to a place, use the prepositions "in" (the point itself), "at" (the general vicinity), "on" (the surface), and "inside" (something contained). They will meet in the lunchroom. She was waiting in the car.', 0, 0, 0, 1790961810687) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c4b9d215dd4f37b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I assure you ____ my cooperation.', '{"A":"Of","B":"In","C":"To","D":"For"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word "of" indicates the subject or topic of assurance. In the phrase "I assure you of my cooperation," the preposition "of" connects the verb "assure" to the noun "cooperation," specifying what is being assured.', 0, 0, 0, 1790961810687) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2ca1f95671479f1a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'This passport is valid ______ five years.', '{"A":"To","B":"For","C":"Of","D":"In"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation For indicates a period of time (amount of time) in the past, present or future. Example: He stayed there for four days. I will be staying there for five months', 0, 0, 0, 1790961810687) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_14fdfcd4986bd976', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He struggled and gained a victory ________ his enemies.', '{"A":"Over","B":"With","C":"At","D":"Between"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The suitable preposition for the blanks is "over". We use "over" for movement and position or talk about movement or position at a higher level than something else.', 0, 0, 0, 1790961810687) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3028b9486aae01f9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The people of Iran staged a revolt ______ their shah.', '{"A":"With","B":"To","C":"In","D":"Against"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The people of Iran staged a revolt against their shah.ایران کے لوگوں نے اپنے شاہ کے خلاف بغاوت کر دی۔**Against is best to keep the meaning of the original sentenceuse prepositions against:Preposition We must continue the struggle for justice and against injustice', 0, 0, 0, 1790961810687) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c26628c57f6cda4b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Do not put much reliance ______ his promises.', '{"A":"At","B":"On","C":"With","D":"About"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Do not put much reliance on his promises.اس کے وعدوں پر زیادہ بھروسہ نہ کریں۔**on is the best keep in the original sentence', 0, 0, 0, 1790961810687) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6738f78fcd50f3bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He bears a resemblance _____ his father.', '{"A":"At","B":"To","C":"With","D":"For"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He bears resemblance to his fatherوہ اپنے باپ سے مشابہت رکھتا ہے۔** "To" is best to keep in the original sentence Use the preposition ''to'' with verbs such as drive, walk, go, hike, fly, sail, etc.', 0, 0, 0, 1790961810757) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3db21cd339e677da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Your request _____ leave is under consideration.', '{"A":"For","B":"To","C":"With","D":"On"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Your request for leave is under consideration.آپ کی چھٹی کی درخواست زیر غور ہے۔**For is best to keep in the original sentence The preposition for is used to express the duration of an action; the period of an action or event.', 0, 0, 0, 1790961810757) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ebf442b498d60dee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They are planning _____ out to dinner tonight.', '{"A":"To take their guests","B":"Guests taking","C":"Taking their guests","D":"Guests to take"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "They are planning to take their guests out to dinner tonight."وہ آج رات اپنے مہمانوں کو باہر کھانے پر لے جانے کا منصوبہ بنا رہے ہیں۔This phrase correctly indicates that they intend to accompany their guests to a dinner event.', 0, 0, 0, 1790961810757) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ffbecfb63dcc3c6b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They have been living in Switzerland ________ seven years.', '{"A":"For","B":"That","C":"It","D":"Was"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation They have been living in Switzerland for seven years.وہ سات سال سے سوئٹزرلینڈ میں رہ رہے ہیں۔The word "for" is used to indicate the duration of time during which the action (living in Switzerland) has been happening. This usage is common when talking about actions or states that have been ongoing for a specific period.', 0, 0, 0, 1790961810757) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bc7e53722a775599', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They have all been friends _____ their first match as a team.', '{"A":"Since","B":"For","C":"From","D":"During"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation They have all been friends since their first match as a team.وہ سب ایک ٹیم کے طور پر اپنے پہلے میچ سے ہی دوست ہیں۔"Since" is used to indicate the starting point of a continuous period of time.', 0, 0, 0, 1790961810757) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_699b72c600ddbf6a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which of the following is conjunction?', '{"A":"Is","B":"Are","C":"But","D":"Have"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Examples of conjunctions:And, or, so, since, for, because, as, but, yet, still, whileConjunctions are parts of speech that connect words, phrases, clauses, or sentences.', 0, 0, 0, 1790961810757) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_49694ee21d4e765f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Meaning of word "Incognito"?', '{"A":"Modern","B":"Genuine","C":"Team spirit","D":"In disguise"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Incognito means پوشیدگیIn disguise means بھیس ​​میں', 0, 0, 0, 1790961810757) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b91e9f15cb02ac9d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My room is infested _____ insects.', '{"A":"In","B":"On","C":"With","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We generally use with after infested and filled.Infested with something means کسی چیز سے بھرا ہواND17-7-2023', 0, 0, 0, 1790961810757) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_83d4aa7f25e0ab3b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She completed her literature review, and she created her reference list. Identify the sentence:', '{"A":"Simple Sentences","B":"Complex Sentences","C":"Compound Sentences","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A compound sentence contains at least two independent clauses. These two independent clauses can be combined with a comma and a coordinating conjunction or with a semicolon.', 0, 0, 0, 1790961810838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0e5440e282f68411', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '''Where is Rabia? ______ to bed''.', '{"A":"She has gone","B":"She is gone","C":"She goes","D":"She have gone"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ''Where is Rabia? She has gone to bed''.رابعہ کہاں ہے؟ وہ بستر پر چلی گئی ہے۔This indicates that Rabia has already gone to bed.', 0, 0, 0, 1790961810838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6adb730f953e2ee1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'If you did not support him, he _____ assistance from some other quarter.', '{"A":"Seeks","B":"Seek","C":"Will seek","D":"Would seek"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Would" is the correct form for this hypothetical situation."Would seek" is used to indicate a hypothetical outcome in a conditional situation."If you did not support him, he would seek assistance from some other quarter."اگر آپ نے اس کا ساتھ نہ دیا تو وہ کسی اور سہ ماہی سے مدد طلب کرے گا۔', 0, 0, 0, 1790961810838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_16518c6044790e88', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The electrical field produced by a single wire is not very strong, so to increase it, _______ into a coil.', '{"A":"The wire is wound","B":"The wire wound","C":"To wind the wire","D":"By winding the wire"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The electrical field produced by a single wire is not very strong, so to increase it, the wire is wound into a coil.ایک تار سے پیدا ہونے والا برقی میدان زیادہ مضبوط نہیں ہوتا، اس لیے اس کو بڑھانے کے لیے تار کو ایک کنڈلی میں گھسا دیا جاتا ہے۔Here the use of “the wire is wound” forms a completely meaningful sentence and option A is correct.ND27-7-2023', 0, 0, 0, 1790961810838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_81d692b7c247d2a8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'His thirst _______ knowledge left him leisure for anything else.', '{"A":"To","B":"With","C":"For","D":"Over"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation His thirst for knowledge left him leisure for anything elseعلم کی پیاس نے اسے کسی اور چیز کے لیے فرصت ہی چھوڑ دی۔We use for to talk about a purpose or a reason for something.', 0, 0, 0, 1790961810838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ab4a0e438e731168', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '"You may go home as soon as your work is done". The given sentence is an example of ____?', '{"A":"Simple sentence","B":"Complex sentence","C":"Compound sentence","D":"Imperative sentence"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The given sentence is an example of a Complex sentence.This is because it contains one independent clause ("You may go home") and one dependent clause ("as soon as your work is done").', 0, 0, 0, 1790961810838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3b330ab6668e58e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She is _____ for the upcoming tennis tournament.', '{"A":"Is training","B":"Was training","C":"Were training","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She is training for the upcoming tennis tournament.The present continuous tense "is training" correctly describes an ongoing action.', 0, 0, 0, 1790961810838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_180d0e33e17d7140', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Everyone at the wedding party ______ amazed by her performance?', '{"A":"Was","B":"Are","C":"Have","D":"Were"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Everyone at the wedding party was amazed by her performance."Everyone" is a singular collective noun, so it takes a singular verb.', 0, 0, 0, 1790961810838) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f8bb16007e1b1742', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Nomadic is related to _____?', '{"A":"Static","B":"Urban","C":"Itinerant","D":"Sedentary"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nomadic is related to Itinerant.As both terms describe a lifestyle characterized by constant movement or travel.Nomadic people frequently move from place to place.Itinerant refers to traveling or wandering from one location to another.', 0, 0, 0, 1790961810920) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9a4f5f3e9b3d9676', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '"Lyrics" is a form of ____?', '{"A":"Poetry","B":"Prose","C":"Drama","D":"Essay"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Lyrics" is a form of "Poetry."They are short, poetic compositions that express personal emotions or thoughts.It often set to music.', 0, 0, 0, 1790961810920) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d091a9dc08a3125e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Ali is ______ good boy.', '{"A":"A","B":"An","C":"The","D":"No Article"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "A" is used before words that start with a consonant sound."Ali is a good boy".وہ ایک اچھا لڑکا ہے۔', 0, 0, 0, 1790961810920) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d6cc1bcb7dd94198', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'In a letter, the writer''s address details are written in separate lines, the lines end with a ______ and the last line ends with a ______.', '{"A":"Colon ... semi colon","B":"Comma ... full stop","C":"Full stop ... comma","D":"Semi colon ... colon"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In a letter, the writer''s address details are written in separate lines, each line ending with a comma, and the last line ending with a full stop.This format helps to clearly separate each part of the address for clarity.', 0, 0, 0, 1790961810920) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0e3bdaed1d181c45', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The salutation of a letter to younger relatives includes ____?', '{"A":"The essential part of their name","B":"Dear sir/Dear madam","C":"Dear Mr.","D":"My dear sir"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The salutation of a letter to younger relatives includes the essential part of their name.It is typically informal, like "Dear [Name]".It reflecting a personal and familiar tone.', 0, 0, 0, 1790961810920) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1157a0b00ce45ecc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Letters between relatives and friends are called?', '{"A":"Formal letters","B":"Business letters","C":"Semi formal letters","D":"Personal letters"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Letters between relatives and friends are called personal letters.These letters are informal.It often include personal thoughts, feelings, and updates.', 0, 0, 0, 1790961810920) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_41b32758c53627ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The first paragraph in a formal essay is it''s?', '{"A":"Introduction","B":"Body","C":"Conclusion","D":"Evidences"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first paragraph in a formal essay is its Introduction.The introduction sets the stage for the essay by presenting the main topic and thesis statement.Parts of a formal essay:Introduction: Presents the topic and thesis.Body: Contains the main points and supporting evidence.Conclusion: Summarizes the essay and restates the thesis.', 0, 0, 0, 1790961810920) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_17f181eebb728c30', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The location and the time in which a story takes place in the _____ of a story.', '{"A":"Resolution","B":"Setting","C":"Plot","D":"Characterization"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The location and the time in which a story takes place is the Setting of a story.The setting provides the backdrop and context for the narrative, influencing the plot and characters.', 0, 0, 0, 1790961810920) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3bab1cb37045744a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which of these is used to separate short coordinate clauses of a compound sentence?', '{"A":"Comma","B":"Colon","C":"Full stop","D":"Semicolon"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The comma is used to separate short co-ordinate clauses of a compound sentence. It helps to link related independent clauses for better readability.For example, “ She came, she stooped, she conquered.”', 0, 0, 0, 1790961810981) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bd76cb6f211d8fe8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She has been working ______ morning.', '{"A":"For","B":"Since","C":"In","D":"On"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She has been working since morning.This indicates that she started working in the morning and continues to do so.', 0, 0, 0, 1790961810981) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1c3fc72a650feeb9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Is this the bus, ______ goes to the Sadar Bazar?', '{"A":"That","B":"Who","C":"Which","D":"To arrive"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Is this the bus, which goes to the Sadar Bazar?"Which" is the correct relative pronoun to use in this context.', 0, 0, 0, 1790961810981) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5490a674097a0571', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Akbar Nama was a _____ volume history of Akbar''s reign, written by Abul Fazl.', '{"A":"Two","B":"First","C":"Three","D":"Four"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Akbar Nama was a three-volume history of Akbar''s reign, written by Abul Fazl.It details the events of Akbar''s empire and his administration.Akbar Nama was written in Persian language.Abu al Fazal was killed by Bir Singh Deva Bundela.', 0, 0, 0, 1790961810981) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b90fd9e0f55341f4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am ______ sure of it as you are.', '{"A":"Quit","B":"As","C":"Very","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I am as sure of it as you are.This means that you have the same level of confidence or certainty about something as the other person does.', 0, 0, 0, 1790961810981) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c0fccd97dc84eef5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '"Keep at bay" means:', '{"A":"Keep at a distance","B":"Keep at the keep shore","C":"Keep in mind","D":"Keep thinking about something"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Keep at bay" means to keep something/someone at a distance, physically or metaphorically.To maintain a safe margin and prevent overwhelm or danger.', 0, 0, 0, 1790961810981) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d59a97f4e3b53e74', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You can’t always pass ______ appearance.', '{"A":"Into","B":"Down","C":"By","D":"Of"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation You can’t always pass by appearance.The correct phrase is "pass by appearance" or more commonly:”"Pass by" in this context means to rely on or judge based on something, especially visual impression.', 0, 0, 0, 1790961810981) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a27914d9c7cf1fc4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I inquired ____ the servant if his master was at home.', '{"A":"of","B":"in","C":"on","D":"at"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Inquire of means to ask something.Inquire of means پوچھنا', 0, 0, 0, 1790961810981) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0d65a42129bcd587', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Neither he nor his friends _____reading books.', '{"A":"is","B":"are","C":"yet","D":"am"}', 'B', NULL, 0, 0, 0, 1790961811063) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6c2577540637dfa3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'An adverb is a word which qualifies (or adds to) the meaning of a noun?', '{"A":"True","B":"False","C":"All of these","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An adverb is a word that typically modifies a verb, an adjective,or another adverb to provide more information about when,how, where, or to what extent something happens but not a noun.Additional trick: Mostly words ending with (ly) are all adverbs. But a little bit of explanation below: Noun ke Sath (ly ) ho to adjective bn jata hai. Adjective ke sath ly ho Adverb ban jata hai.e.g Beautiful adjective hai Beautifully adverb hai.', 0, 0, 0, 1790961811063) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7daa41a808951645', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am tired as I am working since 8 o''clock in the morning.', '{"A":"I was working","B":"I have been working","C":"I had been working","D":"No improvement"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Have been or has been is used with present perfect continuous tense.', 0, 0, 0, 1790961811063) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_53c4910c29f11523', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The ship is bound ________________ Pakistan.', '{"A":"To","B":"For","C":"At","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The ship is bound for Pakistan. جہاز پاکستان کے لیے روانہ ہے۔Be bound for is followed by a noun. ship (noun)Bound for is an idiom which means منزل کی جانب رواں دواںSo "bound for" is the best option to make a meaningful sentence, if in the sentence " the shipped" is mentioned we select option A "to" because " bound to" is followed by a verb and "ships or shipping is a transitive verbso bound for is the correct optionND12_8_2023', 0, 0, 0, 1790961811063) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e6919d277ad026db', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Air is ___________ most essential thing for life.', '{"A":"A","B":"The","C":"Some","D":"Any","E":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Air is the most essential thing for life زندگی کیلئے سب سے اہم چیز ہوا ہے Generally, article the is used for a superlative degree of adjective.', 0, 0, 0, 1790961811063) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_29958de3e9ed8eec', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I saw a beautiful bird.', '{"A":"A beautiful bird is seen by me","B":"A beautiful bird was seen by me","C":"A beautiful bird will be seen by me","D":"A beautiful bird should be seen by me","E":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I saw a beautiful bird means میں نے ایک خوبصورت پرندہ دیکھا This is a sentence of past indefinite tense.See is a verb which means دیکھناSaw is the second form and seen is the third form of see.Past Indefinite tenseActive Voice= Subject + Second Form of Verb + Object.Passive Voice = Object + was/were + third of verb + by + subject.', 0, 0, 0, 1790961811063) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c2e4002c29a9f33b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We eat fruit.', '{"A":"Fruit is eaten by us","B":"Fruit was eaten by us","C":"Fruit has been eaten by us","D":"Fruit is being eaten by us","E":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We eat fruit = ہم پھل کھاتے ہیںFruit is eaten by us = پھل ہم سے کھایا جاتا ہےThis is a sentence of Present Indefinite Tense.Present Indefinite TenseActive Voice: Subject + Verb + Object Passive Voice: Object + is/am/are+ third form of a verb + by + subject.', 0, 0, 0, 1790961811063) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_55f6b323dec95e5a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the misspelt word? Annex, Aniversary, Animate, Animosity.', '{"A":"Annex","B":"Aniversary","C":"Animate","D":"Animosity"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Anniversary is the correct spelling. Anniversary means برسی یا سالگرہ ND4-5-2023', 0, 0, 0, 1790961811063) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8cae554f256215dd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He decided their cases with " justice". The underlined word "Justice" is an /a', '{"A":"Abstract noun","B":"proper noun","C":"Collective noun","D":"Concrete noun."}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the sentence "He decided their cases with ''justice''," the word "justice" is an abstract noun.It represents a concept, quality, or state—the quality of being fair or just—rather than a tangible, physical object.', 0, 0, 0, 1790961811153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3c66b1da00e0f44e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Jim works _____ than his brother.', '{"A":"Hard","B":"Harder","C":"Hardest","D":"Harding","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hard is a positive degree of Adjective.Harder is the comparative degree of Hard.Hardest is the superlative degree of Hard.', 0, 0, 0, 1790961811153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1cd6ca3c99ecf74c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They would have been late, if they had not taken a taxi." the given sentence is an example of the sentence.', '{"A":"Zero condition","B":"First condition","C":"Second condition","D":"Third condition"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The third condition is used to describe past situations that did not occur and past events that did not occur as a result. They can be used to represent missed opportunities. The important thing about the third condition is that both the condition and the result are currently impossible.', 0, 0, 0, 1790961811153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ca763bc6463656a1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The flame of the candle was moving and waving in the air. Here the words "moving and waving : are known as', '{"A":"Simile","B":"Alliteration","C":"Metaphor","D":"Personification"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "The flame of the candle was moving and waving in the air," the words "moving and waving" are considered a figure of speech called personificationThey attribute human-like actions (like waving) to the candle flame, an inanimate object.', 0, 0, 0, 1790961811153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3a8b7941c7114741', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It rained for 3 days and the streets in my neighborhood were flooded', '{"A":"Simple sentence","B":"complex sentence","C":"Compound sentence","D":"imperative sentence"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence "It rained for 3 days and the streets in my neighborhood were flooded" It is a compound sentence Because it consists of two independent clauses joined by a coordinating conjunction ("and").', 0, 0, 0, 1790961811153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cd7e28a68f2b6afc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'If they are busy people, they will miss the news. The given sentence is a kind of the sentence', '{"A":"First condition","B":"Second condition","C":"third condition","D":"Zero condition"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the First condition or Type 1 conditional clauses, the tense of the "if" clause is the present tense and the tense of the main clause is the future tense.If clause (condition) Main clause (result)If + simple present simple futureIf this thing happens that thing will happen.', 0, 0, 0, 1790961811153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4048c6a73a4ab6e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He bore a banner with a strange device. Here "with a strange device" is a', '{"A":"Noun phrase","B":"Prepositional phrase","C":"Adverb phrase","D":"Adjective phrase"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ans: dHere the phrase "with a strange device" is acting as adjective phraseHe= subjectBore= verbBanner= nounTherefore the adjectival phrase is ‘with a strange device''', 0, 0, 0, 1790961811153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_39b5f281b0973c37', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'This is an old-fashioned hat. The sentence "an old fashioned hat" here is an', '{"A":"Prepositional phrase","B":"Adjective phrase","C":"Adverb phrase","D":"Noun phrase"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase "an old-fashioned hat" is a noun phrase because:"hat" is the main noun (head of the phrase)."an" is a determiner (article) modifying the noun."old-fashioned" is an adjective describing the noun "hat."', 0, 0, 0, 1790961811153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7a4fefd9e21c6ce7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Synonyms of AFFECTION', '{"A":"attachment","B":"love","C":"reform","D":"merger"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation AFFECTION پیارLove پیار***', 0, 0, 0, 1790961811232) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f6c414aebb3f7b7b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The prisoner said to the judge, "I am not guilty of this crime"', '{"A":"The prisoner told the judge that he was not guilty of that crime","B":"The prisoner told the judge that I was not guilty of that crime","C":"The prisoner told the judge that he was not guilty of this crime","D":"The prisoner told the judge that you were not guilty of that crime","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Direct Speech: The prisoner said to the judge, "I am not guilty of this crime."Indirect speech: The prisoner told the judge that he was not guilty of that crimePresent Tense changes into Past Tense.I am changes into I was.Change This into ThatRemove inverted commas.', 0, 0, 0, 1790961811232) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8bd08310431a6c90', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'In a list of languages ranked by number of native (L1) speakers where does English come?', '{"A":"First","B":"Second","C":"Third","D":"Fourth"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Number of native speakers of English: Around 369.7 million', 0, 0, 0, 1790961811232) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1f8b47daa66f6db0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is the phrasal meaning of carry-on?', '{"A":"To continue doing something","B":"To end doing something","C":"To start doing something","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To Continue/Keep Going: Persisting with an action or task.Example: "Please carry on with your work".', 0, 0, 0, 1790961811232) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_234e29b45bed2d5d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Translation into English: پولیس ملزمان کو تلاش کررہی ہے', '{"A":"Police are looking for the accused","B":"Police is looking for the accused","C":"Police was looking for the accused","D":"Police will looking for the accused"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Translation into English: پولیس ملزمان کو تلاش کررہی ہےPolice are looking for the accused', 0, 0, 0, 1790961811232) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_574187853f665554', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We had to walk ________ a thick forest.', '{"A":"In","B":"Across","C":"Through","D":"On"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word "through" is used to indicate movement from one side or point to another within a space or obstacle, in this case, through the thick forest. It implies traversing the forest, going from one end to the other, or navigating within its confines.', 0, 0, 0, 1790961811232) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e40df3e6f348b92f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My sister helped me ________ my homework.', '{"A":"For","B":"In","C":"With","D":"On","E":"From"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In is a preposition here. My sister helped me in my homework میری بہن نے میرے ہوم ورک میں میری مدد کی۔****', 0, 0, 0, 1790961811232) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2b09db054ae1d506', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I will also take a bath every day ___________ going to bed.', '{"A":"By","B":"For","C":"In","D":"Before","E":"From"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word ‘Before’ is used to refer to timed eventsI will also take a bath every day before going to bed میں بھی ہر روز سونے سے پہلے نہا لوں گا۔****', 0, 0, 0, 1790961811232) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_33bd08474a32ec79', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Feminine of noun LANDLORD is?', '{"A":"Land owner","B":"Land woman","C":"Landlady","D":"Landmistress"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Both LANDLORD and Landlady are nouns.LANDLORD means جاگیر دارLandlady means جاگیردارنی****', 0, 0, 0, 1790961811306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a4ba98761bc0f2f6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Masculine of LIONESS is?', '{"A":"Loin","B":"Lion","C":"Tiger","D":"Panther","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lion is a noun. Masculine Gender: Lion Feminine Gender: Lioness Lion means شیر Lioness means شیرنی***', 0, 0, 0, 1790961811306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7282a419b2441d3f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Singular of plural noun AUNTIES is', '{"A":"Aunti","B":"Anty","C":"Aunty","D":"Untie"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Aunty means چاچی یا مامیAunty is a noun Plural of Aunty is Aunties. ****', 0, 0, 0, 1790961811306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2f40e81f7c1936fe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Plural of noun BUY is', '{"A":"Buies","B":"Buyes","C":"Buys","D":"Buyss"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Buy means خریداریBuy is a noun. The plural form of buy is buys.', 0, 0, 0, 1790961811306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9cdb76c4ead8b2b2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She was watching a movie when I____', '{"A":"walked","B":"walk","C":"walking","D":"walks"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961811306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_28b80e6c25672e1a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is my problem, not ____', '{"A":"theirs","B":"their","C":"there''s","D":"there"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961811306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_da87020fe9691c02', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Ali once met me in London; I have not seen him since. (Identify the adverb of time)', '{"A":"Since","B":"Once","C":"Met","D":"Him"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961811306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ddd6e7c5e875720e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the part of sentence: He does his work "carefully"?', '{"A":"Noun","B":"Adjective","C":"Adverb","D":"Noun of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Carefully" is an adverb; as such it describes, explains, or limits a verb (an action word)."Carefully" describes how he does his work, modifying the verb "does."Adverbs modify verbs, adjectives, or other adverbs, often answering "how?"', 0, 0, 0, 1790961811306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7fb2fe0e53a0781e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '__________ is a brief pointed say introducing antithetical ideas.', '{"A":"Antithesis","B":"Epilogue","C":"Epigram","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An Epigram is a brief pointed saying frequently introducing antithetical ideas which excite surprise and arrest attention.*', 0, 0, 0, 1790961811392) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7881d49d74955da7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The debate was ___ the following week', '{"A":"Adjourned to","B":"Adjoruned with","C":"Adourned of","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The debate was Adjourned to the following weekبحث کو اگلے ہفتے تک ملتوی کر دیا گیا۔An adjournment in meetings is a formal process to bring them to a close, often until a designated periodAdjourned to is a verb', 0, 0, 0, 1790961811393) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d46a3b6f1f2f4e24', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The fabric felt soft. Here ''felt'' is an example of?', '{"A":"Action verb","B":"Auxiliary Verb","C":"Linking verb","D":"Helping verb"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A linking verb is a verb that links the subject to a noun or an adjective to re-identify it or describe it. We have a linking verb: to appear, to feel, to look, to smell, to sound, and to taste.Felt is an example of Linking Verb here. ***', 0, 0, 0, 1790961811393) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_44d9887b55fbc79f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Swimming is my favourite recreation. Here ''swimming'' is an example of?', '{"A":"Complement","B":"Subject","C":"Gerund","D":"Object"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Swimming is the Gerund here. In the sentence, "swimming" acts as the subjectAs a gerund, "swimming" takes on the role of a noun, allowing it to be the subject of the sentence and to be described as a favorite recreation.A gerund is a verb in its present participle form (root verb + “ing”) that acts as a noun in a sentence.****', 0, 0, 0, 1790961811393) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7bb9aa376b3f6c57', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He sold his house to John. Here ''John'' is an example of?', '{"A":"Helping verb","B":"Direct Object","C":"Indirect Object","D":"Subject"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He sold his house to John.He = Subject Sold = Main verb His = Personal Pronoun House = Object To = Preposition John = Indirect Object', 0, 0, 0, 1790961811393) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4a91ea4bd3199a3a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is the meaning of Latent', '{"A":"Hidden","B":"Genuine","C":"Trustworthy","D":"Generous"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The term "latent" means: existing but not yet developed or manifest; hidden or concealed.', 0, 0, 0, 1790961811393) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_237b38ca6430e72d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Marathon: Stamina::', '{"A":"Relay: independence","B":"Hurdle: perseverance","C":"Spring: celerity","D":"Jog: weariness","E":"Ramble: directness"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Marathon means بڑی لمبی دوڑStamina means توانائی یا طاقت Spring means چھلانگ Celerity means عجلت یا تیزی', 0, 0, 0, 1790961811393) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_692812123968d4df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Auger : Carpenter ::', '{"A":"Cement : Mason","B":"Awl : Cobbler","C":"Apron : Chef","D":"Seam : Seamstress"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Auger means لکڑی یا زمین میں سوراخ کرنے کا آلہCarpenter ترکھانAwl means سواCobbler means موچی Note: Auger is used by carpenter and Awl is used by cobbler.', 0, 0, 0, 1790961811393) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0ecddda60f663c96', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She was mistaken _______ switch?', '{"A":"With","B":"From","C":"For","D":"Of","E":"To"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mistaken is generally followed by For.For is a preposition here. She was mistaken for switch.****', 0, 0, 0, 1790961811484) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e8774a2ef009fee9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They are talking _____ a confidential matter, so do not interrupt .', '{"A":"In","B":"on","C":"For","D":"over","E":"With"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Talk over is a phrase.Talk over means to review.Talk over means بات کرناThey are talking over a confidential matter.وہ ایک خفیہ معاملے پر بات کر رہے ہیں۔****', 0, 0, 0, 1790961811484) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f138aeb3c99395a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'To pay off old scores', '{"A":"To have one''s revenge","B":"To settle a dispute","C":"To repay the old loan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To pay off old scores is an idiom.To pay off old scores means to settle old grudges by taking revenge.To pay off old scores پرانی دشمنی کا بدلہ لینا******', 0, 0, 0, 1790961811484) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_99373cfb255ced0f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Don''t be late __________?', '{"A":"Won''t you","B":"Should you","C":"Have you","D":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The two ways of relating what a person has said are 1)direct and 2)indirect (reported).In direct speech, the exact words of the original speaker are repeated.In indirect speech (reported speech), the exact meaning of what the speaker told is expressed but not necessarily in the speaker’s exact words.The correct answer is A) not to be late.', 0, 0, 0, 1790961811484) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9b0f6ebc526ff08b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is suffering ___________ anaphylactic shock.', '{"A":"With","B":"To","C":"On","D":"From","E":"In"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We generally use from with diseases.From is a preposition here. He is suffering from anaphylactic shock', 0, 0, 0, 1790961811484) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5b06ec1334cf5c12', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He died __________ heart attack in 1982.', '{"A":"From","B":"With","C":"By","D":"Of","E":"In"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Died of means کسی بیماری سے مرناDie from means کسی حادثے میں مرنا He died of heart attack ان کی موت دل کا دورہ پڑنے سے ہوئی', 0, 0, 0, 1790961811484) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_575077fb0f74df52', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Hand _________ answer sheet to me.', '{"A":"From","B":"With","C":"On","D":"Over","E":"In"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hand over is a phrasal verb.Hand over means to give.Hand over means حوالے کرناHand over answer sheet to me انسر شیٹ میرے حوالے کریں', 0, 0, 0, 1790961811484) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_14f3df1040fc4e9c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We should pay maximum accolade _______ our national heroes.', '{"A":"From","B":"With","C":"To","D":"Of","E":"On"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To is a preposition here.To is generally used to address someone (national heroes)We should pay maximum accolade to our national heroes. ہمیں اپنے قومی ہیروز کو زیادہ سے زیادہ خراج تحسین پیش کرنا چاہیے۔', 0, 0, 0, 1790961811484) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cbdb8a4b73c0f78d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Inside the carton was a push-button unit fastened _________ a small Wooden box.', '{"A":"From","B":"Too","C":"With","D":"To","E":"Of"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To is a prepositionInside the carton was a push-button unit fastened to a small Wooden box.کارٹن کے اندر ایک پش بٹن یونٹ تھا جسے لکڑی کے ایک چھوٹے سے ڈبے سے جکڑ دیا گیا تھا۔', 0, 0, 0, 1790961811570) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fe37c4614bea2167', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The lovely sentiments we go on ________ repeating!', '{"A":"Through","B":"About","C":"On","D":"From","E":"In"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The lovely sentiments we go about repeating!جن خوبصورت جذبات کو ہم دہراتے ہیں۔ The lovely sentiments we go on about repeating!In this sentence, “about” indicates the subject of what is being discussed or repeated. It shows that the repetition focuses on the "lovely sentiments." The phrase “go on about” means to talk or dwell on something at length.', 0, 0, 0, 1790961811570) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_027465245436c225', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She watched all the important matches ___________ the Brookfield ground.', '{"A":"On","B":"In","C":"From","D":"Of","E":"With"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In is a preposition here.She watched all the important matches in the Brookfield ground.وہ بروک فیلڈ گراؤنڈ میں تمام اہم میچ دیکھتی تھیں', 0, 0, 0, 1790961811570) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bcb5ff5ca5f0a27a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Our sir teaches Mathematics_____________English.', '{"A":"Across","B":"besides","C":"beside","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Beside means بغل میںBesides means کے علاوہ He teaches Urdu besides English وہ انگریزی کے علاوہ اردو بھی پڑھاتے ہیں', 0, 0, 0, 1790961811570) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_80db274486b1ad9b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She might be forgiven for __________ beneath the pressure.', '{"A":"Undertaking","B":"Buckling","C":"Extricating","D":"Resounding","E":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Buckle means جھکناShe might be forgiven for buckling beneath the pressure.دباؤ سے جھکنے پر اسے معاف کیا جا سکتا ہے۔', 0, 0, 0, 1790961811570) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f493315d9eaa050e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He was _________ of theft in the court.', '{"A":"Charged","B":"Blamed","C":"Accused","D":"Reported","E":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Accuse is generally followed by of.Accuse of means الزام عائد کرناHe was accused of theft in the court عدالت میں اس پر چوری کا الزام تھا', 0, 0, 0, 1790961811570) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9d960460f77c1603', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The Quaid''s _____ enthusiasm led the Muslims of Indo-Pak to independence.', '{"A":"Latent","B":"Onerous","C":"Simplified","D":"Much","E":"Very"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Much enthusiasm means بہت زیادہ ولولہ The Quaid''s much enthusiasm led the Muslims of Indo-Pak to independenceقائد کا بہت زیادہ جوش و جذبہ ہند پاک کے مسلمانوں کو آزادی کی طرف لے گیا', 0, 0, 0, 1790961811570) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1510af36a983eb7f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Everyone should be __________ duties and assignments according to his abilities.', '{"A":"Told","B":"Suggested","C":"Advised","D":"Delegated","E":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Delegate is a transitive verb.Delegate means سونپنا یا سپرد کرناEveryone should be delegated duties and assignments according to his abilities ہر ایک کو اس کی صلاحیتوں کے مطابق فرائض اور ذمہ داریاں سونپی جائیں', 0, 0, 0, 1790961811570) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ee50a12db22b0bba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She _________ about the excitement on hearing the news of her sister''s wedding.', '{"A":"Ran","B":"Jiggled","C":"Talked","D":"Jumped","E":"Walked"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Jumped" fits best because people often jump when they are very excited or happy."Ran" and "Walked" do not indicate excitement."Jiggled" means small shaking movements, which is not a common reaction to excitement."Talked" does not express a physical reaction to excitement.', 0, 0, 0, 1790961811660) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8a0edf0aba9d1a52', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is our national duty to _________ our vote in the general election.', '{"A":"Drop","B":"Give","C":"Take","D":"Cast","E":"Serve"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cast is a verb.Cast vote means ووٹ دیناIt is our national duty to cast our vote in the general electionعام انتخابات میں اپنا ووٹ کاسٹ کرنا ہمارا قومی فریضہ ہے', 0, 0, 0, 1790961811660) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0dd54026d3843bd5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He, she and it are _________ pronouns?', '{"A":"Second person","B":"First person","C":"Third person","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First-person pronouns: We, us, our,and ourselvesSecond-person pronouns: you, your, yours Third-person pronouns: he, him, his, himself, she, her, hers, herself, it, its, itself, they, them, their, theirs, and themselves', 0, 0, 0, 1790961811660) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9c3c7b3e1a73f984', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What are they doing does not seem ___________ working?', '{"A":"Being","B":"Be","C":"To be","D":"To being"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation What are they doing does not seem to be working جو کچھ کر رہے ہیں وہ کام کرتا نظر نہیں آتا۔', 0, 0, 0, 1790961811660) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c0ea736a0ef5e14a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The masculine of the noun BEE is:', '{"A":"Dog","B":"Drake","C":"Drone","D":"Bull"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bee means شہد کی مکھیDrone means شہد کی نر مکھیAGM 24-12-2022ND5-07-2023', 0, 0, 0, 1790961811660) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6e93dd4efe197199', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The year is month and week is to __________?', '{"A":"Hours","B":"Day","C":"Night","D":"Minute"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Year is to Month as Week is to DayYear : Month (A year consists of 12 months)Week : Day (A week consists of 7 days)Last updated by NA on 23-April-2026', 0, 0, 0, 1790961811660) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ba9d78fff1ca4238', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is meant by " ForeFathers"?', '{"A":"Relatives","B":"Grandmother","C":"Grandfather","D":"Ancestor"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Forefathers means آباو اجداد', 0, 0, 0, 1790961811660) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3726136e63437d36', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Brush is too painting as pencil is to ___.', '{"A":"Notebook","B":"book","C":"map","D":"drawing"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The brush is too painting and the pencil is for drawing*****The Brush tool and the Pencil tool work like traditional drawing*****ND04-12-2022ND23-6-2023', 0, 0, 0, 1790961811660) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4c1d854f9f64915e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I don''t really want to go, besides, it''s too late now. (here BESIDES is an example of)', '{"A":"Adverb","B":"Preposition","C":"Conjunction","D":"Noun"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "I don''t really want to go, besides, it''s too late now.""Besides" is used to add extra information, meaning "moreover" or "in addition to that."It modifies the whole sentence, which is a function of an adverb.Why not the other options?Preposition (e.g., "Besides my brother, no one was there." – Here, "besides" functions as a preposition.)Conjunction (It does not join two clauses like "and" or "but.")Noun ("Besides" is not a thing or entity.)', 0, 0, 0, 1790961811733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8f666a71d7a38ec2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Somebody wants Zainab on the telephone.', '{"A":"Zainab had been wanted on the telephone","B":"Zainab is being wanted on the telephone","C":"Zainab is wanted on the telephone","D":"Zainab was wanted on the telephone"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When the active verb is in the simple present tense, we make passive verb forms with is/am/are + past participle form of the verb.', 0, 0, 0, 1790961811733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_009cfbb7d6883602', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Don''t add too much salt to you food. (Here SALT is an example of)', '{"A":"Abstract Noun","B":"Proper Noun","C":"Collective Noun","D":"Concrete Noun"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A concrete noun is a noun that refers to a physical thing, person, or place.Salt, Orange, Pencil, book etc. are examples of Concrete Noun.', 0, 0, 0, 1790961811733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_729215e7affe628d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which letter is silent in ''Honest''?', '{"A":"S","B":"O","C":"H","D":"T","E":"E"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Honest is an Adjective.''H'' is silent in ''Honest'' Honest means ایماندار', 0, 0, 0, 1790961811733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_faa649217731daaf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is the comparative degree of ''Hard''?', '{"A":"Harding","B":"Hardest","C":"Harder","D":"Hards"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hard is an adjective.Hard means difficult.Hard means مشکل Positive degree: HardComparative degree: Harder Superlative degree: Hardest', 0, 0, 0, 1790961811733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f4468bc5c9e73ca1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She is a brilliant student. (here BRILLIANT is an example of)', '{"A":"Quantity","B":"Shape","C":"Size","D":"Quality"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Brilliant is an example of Adjective of Quality.Brilliant means intelligent.Brilliant means ذہین', 0, 0, 0, 1790961811733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_48ff740620e2b3b2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the exclamation mark in the following.', '{"A":"?","B":".","C":":","D":"!"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Period (.)Comma (,) Colon (:) semicolon (;) Question mark (?)Exclamation (!)', 0, 0, 0, 1790961811733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4613db2872a69e7d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which of the below sentence has tongue twisters?', '{"A":"She lives in a big room","B":"How the children came to school","C":"we should respect our elders","D":"She sells sea shells by the sea shore"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation She sells sea shells by the sea shore is an example of Tongue Twister. Tongue Twister: a word, phrase, or sentence difficult to articulate because of a succession of similar consonantal sounds', 0, 0, 0, 1790961811733) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_439a5cd5a24b045e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the countable noun. Flour, Salt, Honey, Spoon', '{"A":"Flour","B":"Salt","C":"Honey","D":"Spoon"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Flour means آٹا Salt means نمکHoney means شہد Spoon means چمچ', 0, 0, 0, 1790961811834) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5fc5df058b5c1bc4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Identify the "countable noun":', '{"A":"sand","B":"salt","C":"soap","D":"soil"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Soap is a countable noun the plural of which is soaps and that means “kinds of soaps”.ND-7-5-2023', 0, 0, 0, 1790961811834) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9bb42b11cd5fae5c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Do not intrude _______ the privacy of anyone.', '{"A":"With","B":"Of","C":"On","D":"In","E":"From"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Intrude into کہیں زبردستی گھسناIntrude on دخل اندازی کرناIntrude on is a phrasal verb.Do not intrude on the privacy of anyone.', 0, 0, 0, 1790961811834) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5adf0fe5bc3b891b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Have you ______ them?', '{"A":"See","B":"Saw","C":"Seeing","D":"Seen","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation See is a verb.Second form: SawThird form: Seen Have you seen them means کیا آپ انہیں دیکھ چکے ہیں', 0, 0, 0, 1790961811834) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4fc051e0df89310b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Ingredient: Recipe ::', '{"A":"Chair: Table","B":"Moral: Story","C":"Map: Plan","D":"Constituent: Formula"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ingredient means اجزاءRecipe means ترکیبConstituent means جزو Formula means کلیہ', 0, 0, 0, 1790961811834) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fcc55af71e73920d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am searching ـــــــــــ my car?', '{"A":"To","B":"For","C":"Of","D":"About","E":"In"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "For" is used to indicate the object of the search. The sentence "I am searching for my car" means you are trying to locate your car.', 0, 0, 0, 1790961811834) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3ba3031d00775d04', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I want to go ______ England next year.', '{"A":"From","B":"Of","C":"On","D":"To","E":"Too"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We generally use to for a direction.To is a preposition here.I want to go to England next year means میں اگلے سال انگلینڈ جانا چاہتا ہوں', 0, 0, 0, 1790961811834) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a80b43d8d2ab6bea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I have full faith _____ you.', '{"A":"To","B":"With","C":"Upon","D":"In"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally faith is followed by in.In is a preposition here.I have full faith in you means مجھے تم پر پورا بھروسہ ہے', 0, 0, 0, 1790961811834) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_49b49645b4c460ba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is essential __________ here on time.', '{"A":"that you will","B":"that were are","C":"that you are","D":"that you be"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation It is essential that you are here on time meansیہ ضروری ہے کہ آپ وقت پر یہاں موجود ہوں', 0, 0, 0, 1790961811908) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b7ebe2891a23e284', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Put this painting __________ the well.', '{"A":"Upon","B":"On","C":"To","D":"Into","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use on when we think of a place as a surface or if a thing is placed in contact.Put this painting on the well.', 0, 0, 0, 1790961811908) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_07885019e6f43826', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Did you ____ well last night?', '{"A":"Sleep","B":"Slept","C":"Sought","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Did is the second form of do.Therefore, the second form of sleep should be used.******VU FIA CONSTABLE PAPER 2021', 0, 0, 0, 1790961811908) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f89c46a1de7690ff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Boat : Wake ::', '{"A":"Path: Trail","B":"Thought: Rumination","C":"Inspiration: Music","D":"Foot: Track"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Boat means کشتی Wake means پانی میں ہموار لکیر Foot means پاوںTrack means راستہ', 0, 0, 0, 1790961811908) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f5aee3ff6c74b38f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The noise of traffic kept me awake.', '{"A":"I was kept awake by the noise of the traffic","B":"The traffic kept me awake by noise","C":"I kept myself awake due to the noise of the traffic","D":"I remained awake by the noise of the traffic","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is a sentence of past indefinite tense.Active Voice= Subject + Second Form of Verb + Object.Passive Voice = Object + was/were + third of verb + by + subject.A.V :The noise of the traffic kept me awake means ٹریفک کے شور نے مجھے جگائے رکھا۔ Correct P.V: I was kept awake by the noise of the traffic.Keep is an irregular verb which means رکھناKept is the second form of Keep.Kept is the third of Keep.', 0, 0, 0, 1790961811908) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_44a0e7d894ef7268', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Duster : Chalk ::', '{"A":"Blackboard : Chalk","B":"Eraser : Pen","C":"Cloth : Air","D":"Sponge : Water"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chalk means لکھائی کیلیئے استعمال ہونے والا چوناDuster means لکھائی کو صاف کرنے والا کپڑا Sponge means جذب کرناWater means پانی', 0, 0, 0, 1790961811908) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b4536d7709fad69d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Dishonesty : Distrust ::', '{"A":"Murder : Jail","B":"Carelessness : Accident","C":"Money : Pickpocket","D":"Hand : Paper"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dishonesty means بے ایمانی Distrust means عدم اعتماد Carelessness means لاپروائیAccident means حادثہ', 0, 0, 0, 1790961811908) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a7750e75e41ca59a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The project was separated _______ equal parts.', '{"A":"Of","B":"From","C":"In","D":"On","E":"Into"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Into is a preposition.Into is used to show when something is changing from one form to another.The project was separated into equal parts. منصوبے کو برابر حصوں میں تقسیم کیا گیا تھا۔', 0, 0, 0, 1790961811908) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1f2496d4fb7ee3db', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'That is very kind ___________ you. I thanked him', '{"A":"From","B":"For","C":"Of","D":"To","E":"On"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation it is very Kind of you means آپ نے بہت مہربانی کی ****we use the "of" preposition with "kind" because it competes for the meaning of the original sentence"kind of you" is the most formal, “correct” use of the expression.***', 0, 0, 0, 1790961811992) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_10056912819eb76f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Waiter: Tip::', '{"A":"Officer: Kickback","B":"Student: Marks","C":"Worker: Bonus","D":"Employee: Wages","E":"Clerk: Bribe"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The tip is the additional money given to the waiter for good service.Similarly, a bonus is an additional money given to the worker for good serviceWaiter means خدمت گارTip means بخشیش Worker means کام کرنے والا Bonus انعام یا عطیہ (جو کام والے کو دیا جائے)ND27-7-2023', 0, 0, 0, 1790961811992) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2d96755aacaef04a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Overlook: Aberration::', '{"A":"Mitigate: Penitence","B":"Condone: Offence","C":"Error: Omission","D":"Conviction: Criminal"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Overlook بھول جاناAberration چوک جاناCondone معاف کرنا Offence ناراضگی', 0, 0, 0, 1790961811992) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dbcbd3ddec54de25', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Fury: Ire::', '{"A":"Amusement: Happiness","B":"Joke : Laugh","C":"Cry : Whisper","D":"Convulsion : Spasm"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fury means غصہIre means غصہConvulsion means کپکپی Spasm means پٹھہ چڑھ جانا', 0, 0, 0, 1790961811992) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_09d716c7c3b9613d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I promise to _____ you in all circumstances.', '{"A":"Stand up to","B":"Stand with","C":"Stand off","D":"Stand by"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I promise to stand with you in all circumstances.میں ہر حال میں آپ کے ساتھ کھڑا ہونے کا وعدہ کرتا ہوں۔', 0, 0, 0, 1790961811992) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_79b78833f0c8f4e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A speed limit is the ______ legal speed that you can travel on the road.', '{"A":"Highest","B":"Biggest","C":"Maximum","D":"Longest"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A speed limit is the Maximum legal speed that you can travel on the road.سپیڈ کے لیے لفظ میکسیمم استعمال ہوتا ہے', 0, 0, 0, 1790961811992) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a38110fd51b6cf98', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '____ moon shone, and the floor of heaven was studded with silver stars.', '{"A":"A","B":"An","C":"The","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Usually Article the is used before unique things like Sun, Earth, Moon etc.', 0, 0, 0, 1790961811992) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_73297e810633aa76', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Though fond of many acquaintances, I desire_____ only with a few.', '{"A":"Introduction","B":"cordiality","C":"intimacy","D":"encounter","E":"all of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Though fond of many acquaintances, I desire intimacy only with a few.An acquaintance is a person whom one knows, especially through work or business, but who is not a close (intimate) friend.Intimacy means دوستی یا قربت Acquaintance means واقفیت', 0, 0, 0, 1790961811992) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_858d7b02eb93e458', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'As delicate and ________ as insect bodies are, it is remarkable that over the ages enough of them have _____, preserved in amber, for scientists to trace insect evolution.', '{"A":"Beautiful. Disappeared","B":"Fragile. Survived","C":"impervious. Multiplied","D":"refined. awakened"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation As delicate and beautiful as insect bodies are, it is remarkable that over the ages enough of them have disappeared preserved in amber, for scientists to trace insect evolution.Beautiful means خوبصورتDisappeared غائب ہونا', 0, 0, 0, 1790961812075) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5c47d71cf5aaf5fd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Rehana has been pursuing her career in architecture ____ she graduated in May.', '{"A":"For","B":"until","C":"when","D":"since","E":"from"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use since before name of months. Since is also used when you achieve something very big in your career.Rehana has been pursuing her career in architecture since she graduated in May ریحانہ مئی میں گریجویشن کے بعد سے فن تعمیر میں اپنا کیرئیر بنا رہی ہے', 0, 0, 0, 1790961812075) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9e481f7275e32af3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is not true, I _______________ it.', '{"A":"believe","B":"do not believe","C":"does not believe","D":"truly believe"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first clause indicates something negative. we use ''do'' with ''I'' in simple sentences of Present Indefinite Tense. It is not true, I do not believe it means یہ سچ نہیں ہے، میں نہیں مانتا', 0, 0, 0, 1790961812075) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bec94c2083366dd4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We must ______ trade with neighbouring countries.', '{"A":"add","B":"promote","C":"enter","D":"go"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Promote is a verb.Promote means فروغ دیناWe must promote trade with neighbouring countries ہمیں پڑوسی ممالک کے ساتھ تجارت کو فروغ دینا چاہیے', 0, 0, 0, 1790961812075) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1ab4a6cdd69f13ee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Due to his _________ reputation, few were surprised when he joined the fight against _______ medical reforms.', '{"A":"modest, acceptable","B":"inescapable, legitimate","C":"insufficient, overpowering","D":"admirable, unjust"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Due to his admirable reputation, few were surprised when he joined the fight against unjust medical reforms ان کی قابل تعریف شہرت کی وجہ سے، جب وہ غیر منصفانہ طبی اصلاحات کے خلاف جنگ میں شامل ہوئے تو بہت کم لوگ حیران ہوئے', 0, 0, 0, 1790961812075) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c74c1d056e43f192', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Cargo: Ship ::', '{"A":"Patrons: Library","B":"Animals: Barn","C":"Helium: Dirigible","D":"Passenger: Airplane"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cargo means وہ چیزیں جو جہاز وغیرہ سے لیجائی جائیںShip means بحری جہازPassenger means مسافرAirplane means ہوائی جہاز', 0, 0, 0, 1790961812075) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ab2d002cf32f4ff8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Carbohydrate: Obesity::', '{"A":"Pressure: Extrusion","B":"Sugar: cavities","C":"Aversion: regression","D":"Hostility: war"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Carbohydrate means نشاستہObesity means موٹاپاHostility means دشمنی War means جنگ', 0, 0, 0, 1790961812075) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c05bc82e68096c7d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Bread: Oven::', '{"A":"Silo: corn","B":"Pottery: wheel","C":"Iron: furnace","D":"Ceramics: kiln"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bread means روٹیOven means تندورCeramics means مٹی کے برتنوں کی صنعتKiln means بھٹہ', 0, 0, 0, 1790961812075) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e61556ecf6dd80e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Our friends often come to ________ us.', '{"A":"Saw","B":"Seen","C":"Seeing","D":"See","E":"Sees"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation See is a verb here.See means ملنا یا ملاقات کرناSaw is the second form, seen is the third form of see.We generally use first form after ‘to’.‘to’ is a preposition here.Our friends often come to see us means ہمارے دوست اکثر ہم سے ملنے آتے ہیں۔', 0, 0, 0, 1790961812159) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dbaccfa9b5e333c3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Please vote for the member ____________ has done most for our village.', '{"A":"What you believe","B":"who you believed","C":"who you believe","D":"that you believe"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Who is a relative pronoun.Who means جوWho is used for personsPlease vote for the member who you believe has done most for our village means براہ کرم اس ممبر کو ووٹ دیں جس نے آپ کے خیال میں ہمارے گاؤں کے لئے سب سے زیادہ کام کیا ہے', 0, 0, 0, 1790961812159) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_52f717635d1a0e6d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Meeting: Chairperson ::', '{"A":"Trial: judge","B":"committee: nominee","C":"seminar: student","D":"rostrum: speaker"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Meeting: Chairperson" → A chairperson presides over or leads a meeting."Trial: Judge" → A judge presides over or leads a trial', 0, 0, 0, 1790961812159) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cfa3cf2adf0d8b5a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Retirement: Employment::', '{"A":"Leisure: time","B":"Graduation: degree","C":"divorce: marriage","D":"promotion","E":"performance"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Retirement means ملازمت سے فارغ ہونے کا عملEmployment means ملازمت, نوکریDivorce means طلاق دے کر علیحدہ کرنا Marriage means شادی', 0, 0, 0, 1790961812159) ON CONFLICT(id) DO NOTHING;
