INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_80d4de34680db3ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'One word for ‘Living for years and years’ is?', '{"A":"Permanent","B":"Annual","C":"Continuous","D":"Perennial","E":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Perennial means lasting a very long time. Perennial means دائمی, دیر پا', 0, 0, 0, 1790961812414) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b8236eaceb837db6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The image formed on the retina of the human eye is?', '{"A":"Real and upright","B":"Real and inverted","C":"Virtual and upright","D":"Real and enlarge"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The image formed at the retina of the human eye is real and inverted. Real and inverted is due to the presence of a convex lens in the eye.', 0, 0, 0, 1790961812414) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5656197181a2e32b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which of the following is an example of a transitive verb? laughed ,fell, but ,ate', '{"A":"laughed","B":"fell","C":"but","D":"ate"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A transitive verb is a verb that requires an object to receive the action.Example SentencesSome other examples of transitive verbs are "address," "borrow," "bring," "discuss," "raise," "offer," "pay," "write," "promise," and "have."ND-21-5-2023', 0, 0, 0, 1790961812485) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_10f9363baae169f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I lived in Holland _________ the 1990s.', '{"A":"In","B":"At","C":"On","D":"To"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We generally use in before years and months.In is a preposition here.I lived in Holland in the 1990s میں 1990 کی دہائی میں ہالینڈ میں رہتا تھا', 0, 0, 0, 1790961812485) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9fd342433a1453c2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She ‘ll be at work ___________ Thursday.', '{"A":"In","B":"At","C":"On","D":"To"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We generally use on before days of a week.On is a preposition here. She ‘ll be at work on Thursday وہ جمعرات کو کام پر ہوں گی', 0, 0, 0, 1790961812485) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8d4a8951a9b26585', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You have to leave your shoes ________the door when you enter the house.', '{"A":"In","B":"By","C":"Over","D":"To","E":"Up"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation You have to leave your shoes by the doorآپ کو اپنے جوتے دروازے پر چھوڑنا ہوں گے۔', 0, 0, 0, 1790961812485) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5eb94c2208c29cf8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Do not stay in the grasslands after dark as some animals become ________ when they see humans.', '{"A":"Alerted","B":"Aggressive","C":"Threatened","D":"Provoked"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation As some animals become aggressive when they see humans.Aggressive means غاصب', 0, 0, 0, 1790961812485) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_395ad719451d02b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Analogy Lion: Roar', '{"A":"Snake :Slither","B":"Elephant : Tusk","C":"Lizard : Crawl","D":"Goat : Bleat"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lion means شیر Roar means شیر کی آوازGoat means بکری Bleat means بکری کی آوازND07-3-2023', 0, 0, 0, 1790961812485) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4c793e7cb1e56aed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Choose the one which best expresses the meaning of the given word. OBEISANCE:', '{"A":"Obedience","B":"Indifference","C":"Insult","D":"Disrespect"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation OBEISANCE: تعظیمObedience: اطاعت', 0, 0, 0, 1790961812485) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2bee754c99578f74', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Lila is a ______ girl and does not like to go out alone.', '{"A":"Scared","B":"Frightened","C":"Lonely","D":"Timid","E":"All are correct"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lila is a timid girl and does not like to go out alone.Timid is the most appropriate option here.Timid means coward.Timid means ڈرپوک AGM 07.5.23', 0, 0, 0, 1790961812485) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_965c9687933a1f60', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'If I _____________ you, I would not do it.', '{"A":"Am","B":"had been","C":"Was","D":"Were","E":"Will"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In conditional sentences, “If I were you” is grammatically correct (subjunctive mood) — it expresses an unreal or imaginary situation.This is a hypothetical sentence. Were is used with I in such sentences.If I were you, I would not do it means اگر میں آپ کی جگہ ہوتا تو یہ نہیں کرتا', 0, 0, 0, 1790961812576) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0ac56901f089d713', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Four independent__________testified to seeing him at the scene of the crime.', '{"A":"Persons","B":"Witnesses","C":"Spectators","D":"All of these","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Four independent witnesses testified to seeing him at the scene of the crime.witnesses means عینی شاہدین', 0, 0, 0, 1790961812576) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8fa3109c45cdc686', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I _____________ tennis every Saturday.', '{"A":"Was playing","B":"Played","C":"Play","D":"Plays","E":"Had been playing"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Here the word ''every indicated this sentence belong to President Indefinite Tense. We use first form of verb (play) with I in this tense.I play tennis every Saturday means میں ہر ہفتے کو ٹینس کھیلتا ہوں', 0, 0, 0, 1790961812576) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c9f7ad52afc0793d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He was __________ from all charges leveled against him?', '{"A":"Liberated","B":"Exonerated","C":"Apprehended","D":"Released","E":"Judged"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He was exonerated from the charges.Exonerate means acquit.Exonerate means الزام سے بری کر دیناAGM 02.05.2023', 0, 0, 0, 1790961812576) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_32d1a933b2660278', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Modern industry abounds _____ opportunities for young people with good scientific qualifications.', '{"A":"With","B":"From","C":"In","D":"For","E":"Into"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abound with is a phrase.Abound with means to be filled with. Abound with means بکثرت ہوناAGM 02.05.2023', 0, 0, 0, 1790961812576) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a1b23b14e04008e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '_________she is clever, she often makes mistakes.', '{"A":"Beside","B":"Despite","C":"Since","D":"Although","E":"Yet"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Although she is clever, she often makes mistakes.Here ‘although’ means despite the fact that. Although means اگرچہ، باوجودیکہAGM 02.05.2023', 0, 0, 0, 1790961812576) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a97176940c831fd6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The action or practice of persuading someone to do something by using force or threats is known as _________?', '{"A":"Coercion","B":"Conviction","C":"Confession","D":"Cajolement","E":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Coercion means the act of compelling by force of authority.Coercion means جبر کرنا، مجبور کرناAGM 02.05.2023', 0, 0, 0, 1790961812576) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_aef3768e38307412', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'A statement that can have a double meaning is?', '{"A":"Ambiguous","B":"Epigraph","C":"Ambivalent","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ambiguous means more than one possible meaning. Ambiguous دو معنی، مشکوکAGM 02.05.2023', 0, 0, 0, 1790961812576) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_79dd3413eecf1a6c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Contemporary refers ti people living in the same', '{"A":"Place","B":"Period","C":"Country","D":"City","E":"Town"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Contemporary refers ti people living in the same period.Contemporary people means ہم عصر لوگ', 0, 0, 0, 1790961812663) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1ab63c40a347f88a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Living at the same time is?', '{"A":"Concurrent","B":"Coincident","C":"Concomitant","D":"Contemporary","E":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Contemporary refers ti people living in the same period.Contemporary people means ہم عصر لوگ AGM 02.05.2023', 0, 0, 0, 1790961812663) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6465034e04bbda87', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The flying coach is bound ____ Karachi.', '{"A":"in","B":"from","C":"to","D":"for","E":"of"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bound for is an idiom which means منزل کی جانب رواں دواںThis flying coach is bound for Karachi.AGM 02.05.2023', 0, 0, 0, 1790961812663) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_22ab929b6828e39c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She is writing a letter.', '{"A":"A letter is written by her.","B":"A letter is being written by her.","C":"A letter was written by her.","D":"A letter was being written by her."}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active voice formula: Subject + Verb + Object (She is writing a letter)Passive Voice Formula: Object + (Be+ V3)+ (By+ subject)A letter is being written by her. AGM 30.4.23', 0, 0, 0, 1790961812663) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0be0979b01dab079', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He met her before. Here BEFORE is an example of?', '{"A":"Adjective","B":"Conjunction","C":"Adverb","D":"Noun","E":"Verb"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The words like yesterday, before, now, daily, tomorrow etc. are called Adverb of Time.Adverb of Time وہ الفاظ جو وقت بتائیںAGM 30.4.23', 0, 0, 0, 1790961812663) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fd129a946768068a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Have something to eat before you ________', '{"A":"Left","B":"Leave","C":"Leaving","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Have something to eat before you leave means جانے سے پہلے کچھ کھالیں', 0, 0, 0, 1790961812663) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_127d4b9917f17a3e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I worked morning till noon. Here ''till'' is an example of?', '{"A":"Noun","B":"Preposition","C":"Conjunction","D":"Verb","E":"Adverb"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "I worked morning till noon.""Till" is a preposition because it shows the relationship between "morning" and "noon" (expressing time).Noun – "Till" is not a person, place, or thing.Conjunction – "Till" can sometimes be a conjunction, but here it does not connect two clauses.Verb – "Till" can mean "to prepare land for farming," but not in this context.Adverb – It does not modify a verb, adjective, or another adverb.AGM 30.4.23', 0, 0, 0, 1790961812663) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bf6f964d9e5d3502', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Demography studies what?', '{"A":"Births","B":"Deaths","C":"Hearts","D":"Both A & B","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Demography is the statistical study of human populations.Demography means مردم شماری کا علمAGM 30.4.23', 0, 0, 0, 1790961812663) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_415c27aee6bf580f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He _________ his work before father arrived.', '{"A":"Finished","B":"Has finished","C":"Had finished","D":"will have finished","E":"All are correct"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This sentence is talking about two actions in the past.In such case, we use Past Perfect Tense in first, we use Past Indefinite Tense in second. He had finished his work before father arrived ابو کے آنے سے پہلے وہ کام مکمل کرچکا تھا', 0, 0, 0, 1790961812730) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6d6258b7aec4c039', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The pros and coins', '{"A":"For and against","B":"Fresh and stale","C":"Foul and fair","D":"New and Old"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation pros and consفائدے اور نقصانات', 0, 0, 0, 1790961812730) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b49211b7e4a623b2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'There is _____ airport in my city.', '{"A":"The","B":"A","C":"An","D":"Own","E":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We must use “the airport” or “an airport” depending on whether or not you mean a specific airport.', 0, 0, 0, 1790961812730) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fba669a91e2e6af8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'How many books does she study?', '{"A":"How many books are studied by her?","B":"How many books were studied by her?","C":"How many books should be studied by her?","D":"How many books will be studied by her?","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation How many books does she study is an interrogative sentence of Present Indefinite Tense.How many mean کتنے یا کتنیBook means کتابShe means وہStudy means مطالعہHow many books does she study means وہ کتنی کتابوں کا مطالعہ کرتی ہےPresent Indefinite TenseActive Voice: Subject + Verb + Object Passive Voice: Object + is/am/are+ third form of a verb + by + subject.', 0, 0, 0, 1790961812730) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b47a37f3415d6549', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Our flight was _________ From Lahore to Islamabad:', '{"A":"Diverted","B":"Deflected","C":"Reflected","D":"Shifted"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Our flight was Diverted From Lahore to Islamabadہماری فلائٹ کا رخ لاہور سے اسلام آباد کی طرف موڑ دیا گیا تھا۔" Diverted " is the best to keep the meaning of the original sentence "', 0, 0, 0, 1790961812730) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c04b29196b04ee55', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Please do __________ as you are directed :', '{"A":"same","B":"exactly","C":"exact","D":"solemnly"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Please do exactly as you are directedبراہ کرم بالکل ویسا ہی کریں جیسا آپ کو ہدایت کی گئی ہے۔"exactly " is the best to keep the meaning of the original sentence "ND23-4-2023', 0, 0, 0, 1790961812730) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_272e56af61a31965', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He ran as ___________ as he could', '{"A":"cleverly","B":"fastly","C":"fast","D":"solemny"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He ran as fast as he couldوہ جتنی تیزی سے بھاگ سکتا تھا، بھاگا۔"Fast" is both an adjective and an adverbND23-4-2023', 0, 0, 0, 1790961812730) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_61a48b57868788ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is delightful to hear her speak as she speaks __________.', '{"A":"slowly","B":"rythmically","C":"softly","D":"melodiously"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "It is delightful to hear her speak as she speaks melodiously ." Explanation:Melodiously means "musically or pleasantly," which fits the idea of speech that brings delight.Slowly means "at a slow pace," which doesn''t necessarily imply delight.Rhythmically means "in a regular, repeated pattern," but it doesn’t always mean pleasant.Softly means "in a low voice," which doesn''t convey musicality or delight.ND23-4-2023', 0, 0, 0, 1790961812730) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_54170a3444ce1790', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The words in the summery are so __________To understand easily', '{"A":"short","B":"diligent","C":"true","D":"ambiguous"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The words in the summary are so ambiguous To understand easilyخلاصہ میں الفاظ اتنے مبہم ہیں کہ آسانی سے سمجھ میں آجائے" ambiguous " is the best to keep the meaning of the original sentence "ND23-4-2023', 0, 0, 0, 1790961812836) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3bcf954657b29eda', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He showed me how to fix a car and _______ a wheel.', '{"A":"change","B":"displace","C":"place","D":"fix"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation So, the complete sentence would be:"He showed me how to fix a car and change a wheel."You fix a car (repair it), but you change a wheel (replace it with a new one).ND23-4-2023', 0, 0, 0, 1790961812836) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fc1444d0941360a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Potato was ___________ Food of Ireland in the 50s', '{"A":"major","B":"main","C":"delicious","D":"staple"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Potato was major Food of Ireland in the 50s.آلو 50 کی دہائی میں آئرلینڈ کی اہم خوراک تھی۔" major " is the best to keep the meaning of the original sentence "ND23-4-2023', 0, 0, 0, 1790961812836) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_df8cf6c1b869f2d8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My uncle Ahmed is wiser than my siblings because he is _____________ than them', '{"A":"elder","B":"eldest","C":"older","D":"oldest"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation My Uncle Ahmed is wiser than my siblings because he is older than themمیرے چچا احمد میرے بہن بھائیوں سے زیادہ سمجھدار ہیں کیونکہ وہ ان سے بڑے ہیں۔" older " is the best to keep the meaning of the original sentence "ND23-4-2023', 0, 0, 0, 1790961812836) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8700b3a675d790b1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I am _________ forward to our picnic scheduled next month.', '{"A":"looking","B":"planning","C":"seeing","D":"going"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I am looking forward to our picnic scheduled next month. میں اگلے ماہ طے شدہ ہماری پکنک کا منتظر ہوں۔looking is the "best to keep the meaning of the original sentence"ND23-4-2023', 0, 0, 0, 1790961812836) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_235aa6ecab6de7f3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Which of following is not a nuclear site of Iran ?', '{"A":"QOM","B":"Natanz","C":"Abadan","D":"Bushehr"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Nuclear Technology Center of Isfahan is a nuclear research facility that currently operates four small nuclear research reactors, all supplied by China. It is run by the AEOI.', 0, 0, 0, 1790961812836) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_59f9caceb40a0713', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Can''t you hear that _________ is knocking the door?', '{"A":"Nothing","B":"Either","C":"Another","D":"Someone"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Someone is an Indefinite Pronoun here.Someone is knocking the door means کوئی دروازے پر دستک دے رہا ہے', 0, 0, 0, 1790961812836) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_79beb6036a6062d2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The means of PRESERVE is:', '{"A":"Attack","B":"Protect","C":"Blast","D":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PRESERVE means محفوظ کرناProtect means حفاظت کرنا', 0, 0, 0, 1790961812836) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_725eca77a8b46c78', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What is the meaning of "Perish"?', '{"A":"Bear","B":"Adhere","C":"Die","D":"Wrack"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Perish means اچانک سے مرناDie means فوت ہونا، مرنا', 0, 0, 0, 1790961812920) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f2abddbe364f08bf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My friends _____________ the prime minister yesterday.', '{"A":"See","B":"Have seen","C":"Saw","D":"Were Seeing","E":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation See is a verb which means دیکھنا یا ملناSaw is the second while Seen is the third form of See.“Yesterday” shows past indefinite tense here. Second form of a verb is used in Past Indefinite Tense in simple sentences.', 0, 0, 0, 1790961812920) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5087fb7ab7faa788', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The odds ________ against us.', '{"A":"Is","B":"am","C":"are","D":"none of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Odds are plural noun.Odds mean difficulties.', 0, 0, 0, 1790961812920) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_067324dd55607018', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They usually ______ to Murree In summer.', '{"A":"Go","B":"Went","C":"Gone","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Here usually indicates present indefinite tense.We use first form of verb (go) with they in Present Indefinite Tense.They usually go to Murree in summer وہ عموماً گرمیوں میں مری جاتے ہیں', 0, 0, 0, 1790961812920) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a1b56bcdf298f3a7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He has written a poem which fascinates every one.', '{"A":"A poem has been written by him which fascinates every one","B":"Every one is fascinated by the poem which has been written by him","C":"Poem written by him fascinates every one","D":"Every one fascinates the poem which is written by him","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Past Indefinite tenseActive Voice= Subject + Second Form of Verb + Object. Passive Voice = Object + was/were + third of verb + by + subject.Active voice: He has written a poem which fascinated everyone. Passive voice: Every one is fascinated by the poem which has been written by him', 0, 0, 0, 1790961812920) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_977acd12e65df81a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Talkative means', '{"A":"Stuff","B":"Garrulous","C":"Surround","D":"surrender"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation talkative باتونیSurround گھیراؤGarrulous باتونیStuff سامانsurrender ہتھیار ڈالنا', 0, 0, 0, 1790961812920) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f53200b0e3034ad8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Saleem agrees -------------- me in this matter.', '{"A":"at","B":"on","C":"to","D":"of","E":"with"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Agree to کسی چیز پر اتفاق کرناAgree with کسی شخص سے اتفاق کرناWith is a preposition hereSaleem agrees with me in this matter.سلیم اس معاملے میں مجھ سے متفق ہیں۔', 0, 0, 0, 1790961812920) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d8a25db7f9692297', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Thank you. That was __________ very nice dinner?', '{"A":"a","B":"an","C":"the","D":"none"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Thank you. That was a very nice dinner.article (a, an) is used before a noundinner is a noun"a" is used before singular, countable nouns that begin with a consonant sound."very nice dinner" refers to one specific dinner, but since "nice" starts with a consonant sound, "a" is the correct choice."an" is incorrect because it is used before words starting with a vowel sound."the" is incorrect because it refers to something specific that the speaker and listener already know about.ND11-4-2023', 0, 0, 0, 1790961812920) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_18093bee2c439ff1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It is your duty to make tea at seven O` clock.', '{"A":"You are asked to make tea at seven O` clock","B":"Your are required to make tea at seven O` clock","C":"You are supposed to make tea at seven O`clock","D":"Tea is to be made by you at seven O` clock","E":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: It is your duty to make tea at seven O` clock means سات بجے چائے تیار کرنا آپ کی ڈیوٹی ہےPassive Voice: You are supposed to make tea at seven O`clock.************', 0, 0, 0, 1790961812992) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5c34eda3717901cd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Phone me after 8 O'' clock .____ dinner by them', '{"A":"I''ll finish","B":"I''ll have been finished","C":"I''ll have finished","D":"none"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This sentence belongs to Future Perfect Tense.I''ll have finished means I will have finished.', 0, 0, 0, 1790961812992) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_428c536d41d00235', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Select similar word: Curious', '{"A":"Dim","B":"Bemuse","C":"Snoopy","D":"Decease"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Curious متجسس', 0, 0, 0, 1790961812992) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cc095f5e2d34a893', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Animals which lay eggs are called_________', '{"A":"Viviparous","B":"Mammals","C":"Oviparous","D":"Vertebrates"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Animals that lay eggs are called oviparous. This term distinguishes them from animals that give birth to live young, which are called viviparous.', 0, 0, 0, 1790961812992) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5c4f31acd3869358', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The anatomy of categorical:', '{"A":"absolute","B":"certain","C":"conditional","D":"none of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation categorical meaning: دو ٹوکconditional meaning : مشروط طور پرSH24-8-2023', 0, 0, 0, 1790961812992) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9fb8632cb9212a07', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '____ manager was absent today.', '{"A":"A","B":"An","C":"The","D":"Both A & B"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use a/an for unknown persons.We use the for particular person.We are talking about a particular manager hereThe manager was absent today.مینیجر آج غیر حاضر تھا۔', 0, 0, 0, 1790961812992) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bc896d78c84b84c7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Meaning of: To feel at home.', '{"A":"To feel at ease","B":"To feel Happy","C":"To feel difficult","D":"To be sick"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To feel at home means to feel comfortable and relaxed.To feel at home means آرام دہ ہونا', 0, 0, 0, 1790961812992) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c488bb24a4a7b4b9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He greatly feels _____________ the needy.', '{"A":"About","B":"For","C":"With","D":"Against"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Feel For is a phrasal verbFeel for means ہمدردی دکھاناHe feels for the needy.', 0, 0, 0, 1790961812992) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_812c979a8564ca90', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They are very grateful _________ your kindness.', '{"A":"Towards","B":"For","C":"With","D":"To"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally grateful is followed by for.Grateful for something means کسی چیز کیلئے احسان مند ہوناGrateful to someone means کسی انسان کا احسان مند ہوناThey are very grateful for your kindness.', 0, 0, 0, 1790961813082) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a096a1a5e15a698f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Whom does he look for?', '{"A":"Whom he is looked after for?","B":"Who is looked after for him?","C":"Who is looked for by him?","D":"Whom he looked after by?","E":"All of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We change WHOM into who. Don''t forget keeping the ? at the end. Formula: Who + helping verb + Subject + V3 + Other objects + ?(question mark).Active: Whom does he look for?Passive: Who is looked for by him?', 0, 0, 0, 1790961813082) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ed04c676bbee5cb1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I was surprised __________ and pleased at his writing skills.', '{"A":"At","B":"Upto","C":"Into","D":"Of","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surprise is a verb which means حیران رہ جاناWe use at after surprise.At is a preposition here. I was surprised at and pleased at his writing skills.', 0, 0, 0, 1790961813082) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1efdd2a2f89d6f01', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'His behaviour surprised us.', '{"A":"We were surprised at his behaviour","B":"We are surprised at his behaviour","C":"We will be surprised at his behaviour","D":"We shall surprised at his behaviour","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Surprise is a verb which means حیران رہ جاناWe use at after surprise.Past Indefinite tenseActive Voice= Subject + Second Form of Verb + Object (His behaviour surprised us)Passive Voice = Object + was/were + third of verb + by + subject (We were surprised at his behaviour)', 0, 0, 0, 1790961813082) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c9cecc77f13418cf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Her results of final year examination surprised the teachers.', '{"A":"The teachers were surprised at his result of final year examination","B":"The teachers are surprised at his result of final year examination","C":"The teachers will be surprised at his result of final year examination","D":"The teachers should be surprised at his result of final year examination","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The given sentence is in Past Indefinite Tense.Active voice structure: Subject + past tense form of the verb + object (Her results of final year examination surprised the teachers) Passive voice structure: Object of the active sentence + was/were + past participle form of the verb + by + subject of the active sentence (The teachers were surprised at his result of final year examination)', 0, 0, 0, 1790961813082) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_29a221973c2e9578', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'It _____________ too cold to go out last night so we stayed at home.', '{"A":"Has Been","B":"Was","C":"Used To Be","D":"None of these","E":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Last Night” shows Past Tense. So, “was” is the correct option here.It was too cold to go out.', 0, 0, 0, 1790961813082) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4b941d9c90d622b3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He has great liking _________ his children.', '{"A":"From","B":"At","C":"For","D":"To","E":"With"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Liking takes for.For is a preposition here.Like for means پیار،پسندگیNadeem has great liking for his children means ندیم کو اپنے بچوں سے بہت پیار ہے', 0, 0, 0, 1790961813082) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a6b5ad0773f20020', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He was embarrassed because everybody was laughing __________ him?', '{"A":"In","B":"At","C":"For","D":"On","E":"With"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Laugh at someone means کسی پر ہنسنا یا مذاق اڑانا Laugh is generally followed by atEverybody was laughing at him means ہر کوئی اس پر ہنس رہا تھا', 0, 0, 0, 1790961813082) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fa6af696991c47e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Hamza is well known _____ his benevolence.', '{"A":"At","B":"With","C":"For","D":"From","E":"Of"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Well known takes for.Well known for something means well known for qualities.For is a preposition here.Hamza is well known for his benevolence.Benevolence means خیر خوائی', 0, 0, 0, 1790961813183) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dbd2fdfd7b224bbd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'There were several policemen ____________ duty on Republic Day.', '{"A":"At","B":"In","C":"With","D":"On","E":"By"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The phrase “on duty” means اپنے فرض نبھانے میں مصروف', 0, 0, 0, 1790961813183) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c01a4796df18dbb6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The players agreed to abide _____ the referee’s decision.', '{"A":"By","B":"On","C":"With","D":"In"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word “abide” takes the preposition “by”. Abide means قبول کرنا، مان لینا', 0, 0, 0, 1790961813183) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ebd727eadb0bad08', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'That charming girl was the ___ of all eyes', '{"A":"Cynosure","B":"doggerel","C":"target","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “cynosure” means a person who is the center of attraction or attention.', 0, 0, 0, 1790961813183) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_050c1e7113ecc978', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You have no business to ___pain on week and poor person', '{"A":"Inflict","B":"conflict","C":"Given","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Inflict meaning دیا گیا', 0, 0, 0, 1790961813183) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5e8f34930835adde', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My brother and friend _____ me in my studies', '{"A":"Helps","B":"Helped","C":"Help","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation My brother and friend help me in my studiesمیرا بھائی اور دوست میری پڑھائی میں مدد کرتے ہیں۔The subject is "My brother and friend," which is plural (two people)Plural subjects take the base form of the verb"Help" is the base form Last updated 13 August 2026 by NA', 0, 0, 0, 1790961813183) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_103200ca420d841d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Football will be and has played by a number of players.', '{"A":"A number of players will play and have played football","B":"A number of players will be play and have played football","C":"A number of players will play and has played football","D":"The number of players will play and have played football","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active verb form: will/shall + have + past participle form of the verb Passive verb form: will/shall + have been + past participle form of the verb', 0, 0, 0, 1790961813183) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6d4056ea23f7f6c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'My aunt has invited me to her place _____ three o’clock this afternoon _____ tea.', '{"A":"At, for","B":"On, to","C":"During, so that","D":"From, for"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use preposition at before clock. Like at 7 o'' clock, at 9 o''clock, at 4 o'' clock.We use preposition for to tell a reason. (Here tea is the reason of invitation) My aunt has invited me to her place at three o’clock this afternoon for tea.', 0, 0, 0, 1790961813183) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_945dd586d49743ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Pine is most similar to', '{"A":"Clean","B":"Hate","C":"Resolve","D":"Crave"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pine اور Crave دونوں کا مطلب کسی چیز کی شدید خواہش کرنا ہے، لیکن ان کے استعمال میں کچھ فرق ہے۔Pine (ترسنا، تڑپنا، یاد میں کمزور پڑنا)Crave (شدید خواہش رکھنا، طلب ہونا)', 0, 0, 0, 1790961813271) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7da68e5c6d069438', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The anatomys of ENDEAR is:', '{"A":"Give money","B":"Alienate","C":"Chance","D":"Make beautiful"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Endear means پیارا، عزیز یا لاڈلہAlienate means اجنبی ***Last updated by NS on 06 May 2026', 0, 0, 0, 1790961813271) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_21deb8bca5408097', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '___ pane can not be found in power point.', '{"A":"Clip Art","B":"Word art","C":"Search results","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Word Art is not available in Task Pane', 0, 0, 0, 1790961813271) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_663ca0f3d6813ee2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Grammar can be defined as', '{"A":"Art of politics","B":"science of oratory","C":"Composing poetry","D":"Rules to combine words into larger unit of language"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The rules for writing and speaking of any language is called Grammar.', 0, 0, 0, 1790961813271) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c9e4432df6e84150', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'She teaches us grammar.', '{"A":"We are taught grammar by her","B":"We were taught grammar by her","C":"We will be taught grammar by her","D":"We should  taught grammar by her","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Present Indefinite TenseActive Voice: Subject + Verb + Object Passive Voice: Object + is/am/are+ third form of a verb + by + subject.', 0, 0, 0, 1790961813272) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4529096d859bdc79', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I never expected this ____ you.', '{"A":"From","B":"For","C":"With","D":"Of"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally expect takes of.Of is a preposition here.Expect means توقع کرناI never expected this of you مجھے تم سے یہ توقع کبھی نہیں تھی۔Both are correct, but "of" is more about the person''s character, while "from" is about their actions."Expect something of someone" → Correct"I never expected this of you." (Meaning: I didn’t think you could do this.)"Expect something from someone" → Sometimes correct, but with a different meaning"I expect honesty from you." (Meaning: I want you to be honest.)', 0, 0, 0, 1790961813272) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_23a2f198ec2a1e7a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Faint Heart never won fair lady. WON is', '{"A":"Verb","B":"Adverb","C":"Preposition","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Verb a word used to describe an action, state, or occurrence, and forming the main part of the predicate of a sentence, such as hear, become, happen.******', 0, 0, 0, 1790961813272) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d09544411e8e7cd9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The Pilot was a _______________ in the Air Force.', '{"A":"Leutenant","B":"Lieutenant","C":"Leutienanat","D":"Lutenanat"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lieutenant is the correct spelling.لیفٹیننٹ', 0, 0, 0, 1790961813272) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_210d6e8055b88fb4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', '''Cat'' is related to ''Kitten'' in the same way as ''Woman'' is related to:', '{"A":"Baby","B":"Calf","C":"Colt","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation As the young one a ''cat'' is a ''kitten'' in the same way the young one of a ''woman'' is a ''baby''.ND17-1-2023', 0, 0, 0, 1790961813436) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_db3f82f997a70711', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Take it out', '{"A":"Let it be taken out","B":"Let it be take out","C":"Let it be taken in","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation take it outاسے باہر لے“Take it out “Passive voice would beLet it be taken out.', 0, 0, 0, 1790961813436) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7ed6111d89e2dd7f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He tried to _______ my ring.', '{"A":"Stile","B":"Steel","C":"Steal","D":"Still"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We generally use first form (steal) of verb after to.Steal is a verb here.Steal means چوری کرناHe tried to steal my ring اس نے میری انگوٹھی چرانے کی کوشش کی', 0, 0, 0, 1790961813436) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9a58b32a699b9e25', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I saw ____ thousand rupees note under the chair', '{"A":"a","B":"and","C":"the","D":"No article"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation I saw a thousand rupees note under the chair****"A" indefinite articleThe indefinite article (a, an) is used before a noun that is general or when its identity is not known. a/an is used to modify non-specific or non-particular nouns.', 0, 0, 0, 1790961813436) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a1d197f569c1df34', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The sun _______in the west', '{"A":"set","B":"sets","C":"Setting","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sun is a singular noun We always use a plural form of the verb with a singular noun that''s why we use "sets" hereplural, 3rd person singular present tense setsND7-3-2023', 0, 0, 0, 1790961813436) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cf7b335210c82330', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Meaning of “hegemony” is _________?', '{"A":"Power to control others","B":"Supremacy of Power","C":"Autocracy","D":"Controlled Democracy","E":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hegemony means بالادستی یا غالبیت Supremacy of Power means طاقت کی بالادستی', 0, 0, 0, 1790961813436) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_621e4b21d61c36d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Rehearsal :Performance ?', '{"A":"Engagement :Marriage","B":"Satisfaction : Appetite","C":"Applause : Audience","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A rehearsal is a preparation or practice for a performance, just like an engagement is a preparation or commitment before a marriage.', 0, 0, 0, 1790961813436) ON CONFLICT(id) DO NOTHING;
