INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fc586a6d8dc197f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The government has launched a massive tribal welfare programme in Lahore.', '{"A":"A massive tribal welfare programme is launched by the government in Lahore","B":"A massive tribal welfare programme has been launched by the government in Lahore","C":"Lahore government has launched a massive tribal welfare programme","D":"The government in Lahore has launched a massive tribal welfare programme","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The given sentence is in active voice and it is in Present Perfect Tense. Rule : Subject + (has /have) + been + V3 + Other agents.', 0, 0, 0, 1790961817690) ON CONFLICT(id) DO NOTHING;
