INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fe1f62ec46d85a85', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'I used to ____ a lot of money, but I don''t make much now.', '{"A":"Maded","B":"Maked","C":"Made","D":"Make"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally first form of verb is used after To.', 0, 0, 0, 1790961818426) ON CONFLICT(id) DO NOTHING;
