INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b013a78e9619987d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'If they could be friends like you and me, imagine what the world could be?', '{"A":"Adjective clause","B":"Noun clause","C":"Adverb clause","D":"Adverb clause,Noun clause"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Adverb clauses answer questions of how, when, where, and why. Adverb clauses start with a subordinating conjunction. A noun clause contains a subject and a verb but it does not express a complete thought and cannot stand alone as a complete sentence.', 0, 0, 0, 1790961818827) ON CONFLICT(id) DO NOTHING;
