INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_23371d1c7a2a52b4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Honesty is _____ best policy.', '{"A":"A","B":"An","C":"The","D":"No article required"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally Abstract Noun takes article the.', 0, 0, 0, 1790961819157) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5a6a7f87b213befd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'His opponents launched a political ______ against him.', '{"A":"Regimen","B":"Remission","C":"Tirade","D":"None the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Regimen means پرہیزRemission means Reduction Tirade means a long speech', 0, 0, 0, 1790961819157) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1e225c8e9a46f13e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'High time means', '{"A":"Bad time","B":"Appropriate time","C":"Both","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Suitable time', 0, 0, 0, 1790961819157) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b6588c9f0014635c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He __________ to Lahore yesterday.', '{"A":"Had gone","B":"Went","C":"Goes","D":"Was gone","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally Past Indefinite/Simple Tense is used before words like yesterday, last night, last year, last June etc.', 0, 0, 0, 1790961819157) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e2b9b2b67f8397f1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He will not turn ______________ my respect', '{"A":"on","B":"over","C":"down","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Turn - Down', 0, 0, 0, 1790961819157) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_faa13f020ec59d7a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He wore a beautiful dress. Beautiful is :', '{"A":"Adverb","B":"Adjective","C":"Noun","D":"Pronoun"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the sentence "He wore a beautiful dress," The word beautiful is an adjective Because it describes and modifies the noun "dress" by providing more information about its quality.', 0, 0, 0, 1790961819157) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_10516d47c0f00167', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He would draw a picture in the competition.', '{"A":"In the competition he would have to draw a picture","B":"A picture in the competition would have been drawn by him","C":"In the competition he would be drawn a picture","D":"A picture would be drawn by him in the competition","E":"All of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: He would draw a picture in the competition. Passive Voice: A picture would be drawn by him in the competition Given sentence is in simple future tense and it is in active voice. Rule : Subject + (will/shall/would) + be + V3 + Other agents. Draw is a verb.Drew is the second form while withdrawn is the third form of Drawn.', 0, 0, 0, 1790961819244) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bd38e900aaa1f5d8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He would have written this essay in time.', '{"A":"The essay was written on time","B":"This essay would have been written by him in time","C":"The essay was written by him in time","D":"He wrote the essay on time","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Write is an irregular verb which means لکھنا Wrote is the second and written is the third form of write. This essay would have been written by him in time. (Passive) The sentence is in Future Perfect Tense. (Active)', 0, 0, 0, 1790961819244) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ad4442e0eab6bed3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He ____ go .', '{"A":"must","B":"ought to","C":"Both A&B","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Must is used to express obligation, give orders and give advice. It can only be used for present and future reference.', 0, 0, 0, 1790961819244) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_79f090e1add54bff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He __________ to come but he ___________.', '{"A":"Promised, did not","B":"Promised, did not have","C":"Promised, did have not","D":"Promised, did will have"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He promised to come but he did not means اس نے آنے کا وعدہ کیا لیکن آیا نہیں', 0, 0, 0, 1790961819244) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f0c28d880b5715f9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He walked _________ the end of the street yesterday.', '{"A":"Till","B":"Upto","C":"From","D":"With","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He walked upto the end of the street yesterday.Here upto shows distance.We use till for time not distance.', 0, 0, 0, 1790961819244) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0fe67d6fdf61f617', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He was driving a car, when accident occurred.', '{"A":"A car was driven by him, when the accident occur.","B":"A car was being driven by him, when accident occurred.","C":"A car driven by him, when the accident occur.","D":"A car was been driven by him, when the accident occurred."}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Direct indirect after was use being.', 0, 0, 0, 1790961819244) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_86d1c794394461bd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He was obliged to resign.', '{"A":"He was make to resign","B":"To resign was his obligation","C":"Circumstances obliged him to resign","D":"Registration obliged him","E":"All of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Note: More details about this question will be uploaded soon.', 0, 0, 0, 1790961819244) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d6cc8e399fe7c589', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He said to the arrogant servant, “Do not provoke me unnecessarily,”', '{"A":"He ordered the arrogant servant not to provoke him unnecessarily","B":"He ordered the arrogant servant not to provoke her unnecessarily","C":"He ordered the arrogant servant to provoke him unnecessarily","D":"He ordered the arrogant servant not to provoke unnecessarily"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Option A is the correct answer because the pronoun her is used in second option which is used for females not males, the word not is was not mentioned in third option, the word him was not mentioned in fourth option.', 0, 0, 0, 1790961819244) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_855f06902d6b36a2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He said ________ me not to worry.', '{"A":"To","B":"With","C":"Of","D":"On","E":"Across"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “To” is used after following verbs if the object is a “person”.Say, suggest, speak, reply, explain, complain, talk, listen, write, report, pray and describe”. He said to me not to worry.', 0, 0, 0, 1790961819320) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_18fe58a0136ded08', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He spoke these words ___his face', '{"A":"On","B":"At","C":"In","D":"Of"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On as preposition used for date and day', 0, 0, 0, 1790961819320) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e05b6bf3ba4f4cb2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He swore___ God', '{"A":"To","B":"By","C":"Of","D":"From"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use "by" in "swear by the gods" Because "by" introduces the thing or being, a person is called upon as a witness to their oath or promise."Swear by" means to make an oath invoking someone or something as a witness', 0, 0, 0, 1790961819320) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c02f63fe1c4789c1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He teaches me English.', '{"A":"I am taught English by him","B":"I am taught English by her","C":"I am teach English by him","D":"I am taught English him","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He teaches me English means وہ مجھے انگریزی پڑھاتا ہےTeach is a verb which means پڑھاناTaught is the second and third form of teach.Present Indefinite TenseActive Voice: Subject + Verb + Object Passive Voice: Object + is/am/are+ third form of a verb + by + subject.', 0, 0, 0, 1790961819320) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_682a0d72302686ba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He teaches us grammar.', '{"A":"Grammar was taught to us by him.","B":"We are taught grammar by him.","C":"Grammar will be taught to us by him.","D":"We were teached grammar by him.","E":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Given sentence is in Present simple tense. Rule : Subject + (is /am /are) + V3+ Other agents.', 0, 0, 0, 1790961819320) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4eedacfcc0a0f686', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He took the pen from ____________.', '{"A":"I","B":"Me","C":"Mine","D":"None of the above","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally, objective case comes after a preposition. He took the pen from me."From" is a preposition here. “I” is the subjective case while “me” is the objective case.', 0, 0, 0, 1790961819320) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6aecf748bf9f3952', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He runs ______.', '{"A":"Fastly","B":"Fast","C":"A&B both","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fast is both an adjective and an adverb.', 0, 0, 0, 1790961819320) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a7f1b60eb0fb6bd5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He run twelve miles --- 2 hours .', '{"A":"in","B":"of","C":"at","D":"on"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Into is used when something or someone is going or being put into another location. In is used to describe where someone or something already is.', 0, 0, 0, 1790961819320) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6804b8f0b84599af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He said, "I have been writing this essay".', '{"A":"He said that he is writing this essay","B":"He said that he was writing this essay","C":"He said that he had been writing that essay","D":"All of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation اس نے کہا "میں ایک مضمون لکھ رہا ہوں"', 0, 0, 0, 1790961819382) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3b905d33c00da478', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He said, "I visited Oxford yesterday."', '{"A":"He said that he was visited Oxford","B":"He said that he had visited Oxford previous day.","C":"He said that he had been visited Oxford.","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Because it is a sentence of indirect narration', 0, 0, 0, 1790961819382) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3111c6b8003ed8d9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He said to her, “what a hot day!”', '{"A":"He said her that it was a hot day","B":"He said that it was a hot day","C":"He told her that it was a hot day","D":"He exclaimed that it was a very hot day"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sentence that express strong feeling or emotions (like joy, sorrow, surprise, hatred, contempt, etc) are called exclamatory sentences. Exclamatory sentence ends with exclamation mark (!).', 0, 0, 0, 1790961819382) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_49a2a009a2686f67', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He said to me, "Not to smoke."', '{"A":"He told me not to smoke","B":"He asked me not to smoke","C":"He forbade me to smoke","D":"He shouted at me not to smoke","E":"All Of The Above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He forbade me to smoke means اس نے مجھے تمباکونوشی سے منع کیا', 0, 0, 0, 1790961819382) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_43665ba33448f32f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He said to me, “Has anybody been unkind to you ?”', '{"A":"He asked me if anybody had been unkind to him","B":"He asked me had anybody been unkind to me","C":"He asked me if anybody had been unkind to you","D":"He asked me if anybody had been unkind to me."}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In this case,Present Perfect Continuous of Direct Speech becomes Past Perfect Continuous of Indirect Speech', 0, 0, 0, 1790961819382) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9596667cf873d4a8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He parked his bicycle ___________ the wall.', '{"A":"Against","B":"Before","C":"At","D":"About"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation More details about this question will be shared.', 0, 0, 0, 1790961819382) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_23ceaae1f3a6d4db', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He performs different roles convincingly as he is a _________ actor.', '{"A":"Versatile","B":"verbose","C":"voracious","D":"virtuous","E":"bad"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Versatile ہر فن مولا، بہت سے فن جاننے والا Versatile means multi-talented', 0, 0, 0, 1790961819382) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_773118133875710d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He rammed his truck _________ the back of the one in front:', '{"A":"Against","B":"In","C":"Into","D":"To","E":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He rammed his truck into the back of the one in front means اس نے اپنے ٹرک کو سامنے والے کے پچھلے حصے میں ٹکرا دیاIf you know more details about this question, let us know please', 0, 0, 0, 1790961819382) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_53f64e489ec3a550', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He ran fast and delicately. Pick the verb.', '{"A":"Ran","B":"And","C":"Fast","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Verb Forms of Run(Base) 1st (Past) 2nd (Past Participle) 3rdRun Ran Run', 0, 0, 0, 1790961819456) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1f0558148dfeb8d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He reached the examination centre ________ time.', '{"A":"On","B":"With","C":"Form","D":"Of","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Usage of “On” and “In” for time. On time = on scheduled time In time = In the given time span.', 0, 0, 0, 1790961819456) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_964cd05df9da95a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Here is a question to solve.', '{"A":"Here is a question to be solved","B":"Here was a question to be solved","C":"Here should be a question to be solved","D":"Here will be a question to be solved","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Here is a question to solve is a sentence of present tense.Is means ہےA means ایکQuestion means سوالSolve means حل کرناPresent Indefinite TenseActive Voice: Subject + Verb + Object Passive Voice: Object + is/am/are+ third form of a verb + by + subject.', 0, 0, 0, 1790961819456) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3dceca21392773cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He relied on _______.', '{"A":"She","B":"Her","C":"Hers","D":"None of the above","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Generally, objective case comes after a preposition. He relied on her."On" is a preposition here. “She” is the subjective case while “Her” is the objective case.', 0, 0, 0, 1790961819456) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5b8049e018114e61', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He resembles ___________ his father.', '{"A":"As","B":"With","C":"About","D":"Same As","E":"No Preposition Required"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Certain words when used in “Active Voice” are not followed by any preposition. “Accompany, affect, consider, compromise, emphasize, resemble, ensure, attack, invade, order, reach, describe, discuss, tell” etc.He resembles his father means وہ اپنے والد سے مشابہت رکھتا ہے', 0, 0, 0, 1790961819456) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_57ab2cf96912155b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He kept ____________ from school for three years.', '{"A":"In","B":"off","C":"away","D":"of"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Keep away is a phrasal verb which means دور رہنا Kept is the second form of keep.', 0, 0, 0, 1790961819456) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5025a578f3162f70', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He loves ____ television.', '{"A":"Watching","B":"Watches","C":"Watch","D":"Watched","E":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation وہ ٹی وی دیکھنا پسند کرتا ہے۔', 0, 0, 0, 1790961819456) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_76d456b0b533f825', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is quite good ______ making paintings.', '{"A":"in","B":"at","C":"on","D":"about"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation AT is used when you are at the top, bottom or end of something. At a specific address; at a general location; at a point.', 0, 0, 0, 1790961819456) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e88410165a75cfd8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is ______ SDO in KE', '{"A":"An","B":"a","C":"The","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation How to Use A and An:v A is used with consonant sounds.v An is used with vowel sounds.v a + singular noun beginning with a consonant: a boy; a car; a bike; a zoo; a dogv an + singular noun beginning with a vowel: an elephant; an egg; an apple; an idiot; an orphanv a + singular noun beginning with a consonant sound: a user (sounds like ''yoo-zer,'' i.e. begins with a consonant ''y'' sound, so ''a'' is used); a university; a unicyclev an + nouns starting with silent "h": an hourv a + nouns starting with a pronounced "h": a horse', 0, 0, 0, 1790961819531) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_07f6afd9a3e976b4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is in Dutch with his family members. Here "In Dutch" means what?', '{"A":"In love","B":"in bad terms","C":"in good terms","D":"in trouble","E":"all of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation To be in Dutch is an idiom which means مشکل میں ہونا', 0, 0, 0, 1790961819531) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_17c56160be232cf7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He has ___ ulcer on his leg', '{"A":"a","B":"an","C":"every","D":"big"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When the word begins with a vowel sound (a,e,i,o,u) then you should use ''an'' as it sounds better and feels easier to say.', 0, 0, 0, 1790961819531) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_58a2be94565c847f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He is a good ___ of football.', '{"A":"Playing","B":"Player","C":"Play","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Player means کھلاڑی', 0, 0, 0, 1790961819531) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0a48c9308031b9b8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He does not like people praising him.', '{"A":"He does not like being praised","B":"He did not like being praised","C":"He was not like being praised","D":"He should not like being praised","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: He does not like people praising him.Correct Passive Voice: He does not like being praised.Note:- It may be noted that more valuable details about this question shall be upload here very soon.', 0, 0, 0, 1790961819531) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2cc4913d915a21b5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He has eaten nothing ________ a long time.', '{"A":"For","B":"Since","C":"With","D":"From","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation For is used for period.Since is used for point of time. He has eaten nothing for a long time means اس نے کافی عرصے سے کچھ نہیں کھایا', 0, 0, 0, 1790961819531) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ffc9e1f2259ddbaa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He cried hysterically as the flames enveloped his house: Hysterically used as?', '{"A":"Verb","B":"Adverb","C":"Noun","D":"Pronoun"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Adverb is a word or phrase that modifies or qualifies an adjective, verb, or other adverb or a word group, expressing a relation of place, time, circumstance, manner, cause, degree, etc.', 0, 0, 0, 1790961819531) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8a01b204fe38e32b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He decided to dress in a gray suit in order to be :', '{"A":"Conspecious","B":"Inconspicuous","C":"Both","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation inconspicuousناقابل تسخیر', 0, 0, 0, 1790961819531) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9df22c8b4d28491d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He decided to sell the car.', '{"A":"It was decided that the car should be sold","B":"The decision was made by him to sell the car","C":"The decision that the car must be sold was made by him","D":"He decided that the car should be sold","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He decided to sell the car means اس نے کار فروخت کرنے کا فیصلہ کیاPast Indefinite tenseActive Voice= Subject + Second Form of Verb + Object. Passive Voice = Object + was/were + third of verb + by + subject.', 0, 0, 0, 1790961819601) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a3e6988195bba92a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He did not reply _________ me.', '{"A":"To","B":"Too","C":"Of","D":"On","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation “To” is used after following verbs if the object is a “person”.Say, suggest, speak, reply, explain, complain, talk, listen, write, report, pray and describe” He did not reply to me.', 0, 0, 0, 1790961819601) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_59b0eb1f294f8748', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He did not _________ a letter.', '{"A":"Write","B":"Wrote","C":"Written","D":"Writes"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He did not write a letter.this is past Indefinite tense. so we use to write with did not', 0, 0, 0, 1790961819601) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e52242de10dca62c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He discussed ___________ the topic with me.', '{"A":"About","B":"With","C":"Above","D":"Across","E":"No Preposition Required"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Certain words when used in “Active Voice” are not followed by any preposition. “Accompany, affect, consider, compromise, emphasize, resemble, ensure, attack, invade, order, reach, describe, discuss, tell” etc.He discussed the topic with me.', 0, 0, 0, 1790961819601) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_27f2a0b86e5b0004', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He and ______ are playing.', '{"A":"I","B":"Am","C":"is","D":"are"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961819601) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5d001adf86832738', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He asked me to finish the work in time.', '{"A":"I was asked that I should finish the work in time","B":"He asked me that I should finish the work in time","C":"I was asked to finish the work in time","D":"I was asked to finish the work in time by him","E":"All of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence is in Simple Past Tense.Past Indefinite tenseActive Voice= Subject + Second Form of Verb + Object.Passive Voice = Object + was/were + third of verb + by + subject.', 0, 0, 0, 1790961819601) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_15d345f30455780e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'He ---- his job Last week ?', '{"A":"Left","B":"Right","C":"Join","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961819601) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_688c622f5711f152', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Having finished at college Sohail thought of going of going to Lahore in search ________ some job.', '{"A":"Of","B":"Off","C":"To","D":"With","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In search of something means کسی چیز کی تلاش میں', 0, 0, 0, 1790961819601) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ef1e3e317e9dac61', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Gul Majeed recommended____ goods dentist but ___ dentist was not available.', '{"A":"a/an","B":"the/a","C":"a/the","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "A/an" is used to refer to a non-specific or non-particular member of the group.The definite article is used before singular and plural nouns when the noun is specific or particular.', 0, 0, 0, 1790961819660) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_885c9190198cd211', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Had the police not reached there in time the bandits _____________ him.', '{"A":"Would have killed","B":"would killed","C":"will have killed","D":"did have killed","E":"none of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is a conditional sentence which means اگر پولیس وہاں وقت پر نہ پہنچتی تو ڈاکو اسے ماردیتے', 0, 0, 0, 1790961819660) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_6a25ac8d0fae3202', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Grapes taste sour.', '{"A":"Grapes are sour when they are tasted","B":"Grapes were sour when they are tasted","C":"Grapes will be sour when they are tasted","D":"Grapes should be sour when they are tasted","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: Grapes taste sour. Passive Voice: Grapes are sour when they are tasted. Active Voice: The surface feels smooth. Passive Voice: The surface is smooth when it is felt. Active Voice: Roses smell sweat. Passive Voice: Roses are sweat when they are smelt.', 0, 0, 0, 1790961819660) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_50dd84edc051470f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'For his novelty , gift ordered to me ___ very lovely.', '{"A":"Were","B":"Is","C":"Are","D":"Was"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Was is a past tense indicative form of be, meaning “to exist or live,” and is used in the first person singular (I) and the third person singular (he/she/it).', 0, 0, 0, 1790961819660) ON CONFLICT(id) DO NOTHING;
