INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_43c2a2cdae44f365', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Roses smell sweat.', '{"A":"Roses are sweat when they are smelt","B":"Roses were sweat when they are smelt","C":"Roses will be sweat when they are smelt","D":"Roses should be sweat when they are smelt","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: The surface feels smooth. Passive Voice: The surface is smooth when it is felt. Active Voice:Roses smell sweat. Passive Voice: Roses are sweat when they are smelt.', 0, 0, 0, 1790961821020) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f35f5939b40c7f9c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Sajid believed that Asif and Anwar would help Ahmed.', '{"A":"It was believed by Sajid that Ahmed would be helped by Asif and Anwar","B":"It is believed by Sajid that Ahmed would be helped by Asif and Anwar","C":"It will be believed by Sajid that Ahmed would be helped by Asif and Anwar","D":"It should be believed by Sajid that Ahmed would be helped by Asif and Anwar","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Past Indefinite tense Active Voice= Subject + Second Form of Verb + Object. Passive Voice = Object + was/were + third of verb + by + subject.', 0, 0, 0, 1790961821020) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a925c9eda49f8fad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Saif''s father suffered a major stroke but he managed to pull _____?', '{"A":"Over","B":"Out","C":"Through","D":"None of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Saif''s father suffered a major stroke but he managed to pull offHe managed to pull offthe meaning of pull off: to succeed in doing something difficult or unexpected:"pull off" is best to keep the meaning of the original sentenceND13-07-2023', 0, 0, 0, 1790961821020) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f34d369fea2c8b1a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Sana was making a cloud. In the above sentence, the word “Sana” is a:', '{"A":"Noun","B":"Pronoun","C":"Verb","D":"Preposition"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the sentence "Sana was making a cloud," the word "Sana" is a Noun"Sana" is a proper noun as it represents the name of a specific person. Nouns are words that name people, places, things, or ideas. In this sentence, "Sana" is the subject acting.', 0, 0, 0, 1790961821020) ON CONFLICT(id) DO NOTHING;
