INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f79762748524f4d7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Synonyms of epidemic', '{"A":"Pandemic","B":"Contagious","C":"Communicable","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Epidemic وبائی مرض spreading from one person to another Pandemic عالمی وبا (Global Epidemic) or وسیع پھیلنے والی وباContagious متعدی or وبائی Communicab متعدی', 0, 0, 0, 1790961821471) ON CONFLICT(id) DO NOTHING;
