INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ce41c15dd9047fa5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The collective name given to some of pre-Shakespearean playwrights, like Marlowe, Kyd, Peele, and Greene is:', '{"A":"Romantic playwrights","B":"university wits","C":"Elizathan dramatists","D":"court playwrights"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The University Wits is a phrase used to name a group of late 16th-century English playwrights and pamphleteers who were educated at the universities (Oxford or Cambridge) and who became popular secular writers.', 0, 0, 0, 1790961821630) ON CONFLICT(id) DO NOTHING;
