INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d5cec5eb14549f61', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The main skills we seek to develop include analysing, interpreting and evaluating ideas.', '{"A":"The main skills sought to be developed by us include analysing, interpreting and evaluating ideas","B":"The main skills sought to developed by us include analysing, interpreting and evaluating ideas","C":"The main skills should be developed by us include analysing, interpreting and evaluating ideas","D":"he main skills sought to be developed include analysing, interpreting and evaluating ideas,","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Seek is a verb which means get or achieve.Sought is the second and third form of seek.Present Indefinite TenseActive Voice: Subject + Verb + Object Passive Voice: Object + is/am/are+ third form of a verb + by + subject.', 0, 0, 0, 1790961821788) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4c473fa582e22254', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The matter has been referred ___ the minister for decision.', '{"A":"to","B":"for","C":"with","D":"over"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Use the preposition ''to'' when indicating that there is movement from one place to another.', 0, 0, 0, 1790961821788) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_66cf7a54d533b002', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The man _________ you met is the professor.', '{"A":"Whom","B":"Who","C":"That","D":"Which"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The man whom you met is a professor means آپ جس آدمی سے ملے وہ ایک پروفیسر ہے Use "whom" when referring to the object of the verb in a relative clause.In this sentence, "you met" — you is the subject, met is the verb, and the man (or "whom") is the object.', 0, 0, 0, 1790961821788) ON CONFLICT(id) DO NOTHING;
