INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d353549b5c9e5ca2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The president administers the oath.', '{"A":"The oath is administered by the president","B":"The oath was administered by the president","C":"The oath will be administered by the president","D":"None of the above","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation This is the sentence of present indefinite tense.Present Indefinite TenseActive Voice: Subject + Verb + ObjectPassive Voice: Object + is/am/are+ third form of a verb + by + subject.', 0, 0, 0, 1790961821945) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1ed71f9d8f18786d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The prime minister emphasized _________ the matter.', '{"A":"On","B":"Onto","C":"In","D":"About","E":"No Preposition Required"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Certain words when used in “Active Voice” are not followed by any preposition. “Accompany, affect, consider, compromise, emphasize, resemble, ensure, attack, invade, order, reach, describe, discuss, tell” etc.The prime minister emphasized the matter.', 0, 0, 0, 1790961821945) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ef85e61d9a2abeec', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The price(s) of meat ...... increased twice in this year', '{"A":"is","B":"have been","C":"Are","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961821945) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_32bbe9a22a831997', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The principal kept the staff members waiting.', '{"A":"The staff members were kept waiting for the principal","B":"The staff members were kept waiting by the principal","C":"The staff members were waiting for the principal","D":"The staff members were being kept waiting for the principal","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The given sentence is in the active voice, as the subject ''The principal'' performs an action ''kept'' against the object ''the staff members''.If this sentence is changed to passive voice, then the subject is also changed, in order to retain the meaning of the sentence. So, the object takes the place of the subject and vice versa and the word ''by'' is introduced as now the subject receives the action by the object. The verb form of the sentence is also changed from active form to passive.', 0, 0, 0, 1790961821945) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eda97d2b41f10e98', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The principal has granted him a scholarship.', '{"A":"He had been granted a scholarship by the principal","B":"He has been granted a scholarship by the principal","C":"He was been granted a scholarship by the principal","D":"He will be granted a scholarship by the principal","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Object + have / has + been + verb3 (past participle) Have / has + object + been + verb3 (past participle)', 0, 0, 0, 1790961821945) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e10ee2f62bfa4d09', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The Quaid-e-Azam founded the daily newspaper Dawn. Identify the mistake in the sentence:', '{"A":"The not use here","B":"founded not use here","C":"The correct spelling is","D":"The correct spelling is","E":"This sentence requires no correction"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation کسی بھی پراپر نان سے پہلے ارٹیکل کا استعمال نہں کرتے قائد اعظم پراپر نان ہے اس لے دی کا استعمال نہں ہو سکتاThere are three articles "The", "A" and "An".Around 90% article "the" is not used before proper nouns.Generally we should not use "the" before a proper noun and "Quaid-e-Azam" is a proper noun here.For example: He lives in the Karachi. (Incorrect)He lives in Karachi. (Correct)Around 10% article is used before proper nouns to emphasize a sentence.For example: It was the Jinnah who struggled for Pakistan.', 0, 0, 0, 1790961821945) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_29c2c50d5cb5e98c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'There are, as yet no vegetarian types or ecosystems whose study has been perfected to the extent that they no longer ______ ecologists.', '{"A":"Interest","B":"Require","C":"Challenge","D":"Hinder"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961822072) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bcc604d37022b363', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'There is nothing to say.', '{"A":"There is nothing to be say","B":"There is nothing to be said","C":"There was nothing to be said","D":"There is nothing to be sayed","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice = There + verb + Subject + to + first form of a verb.Passive Voice = There + verb + subject + to be + third form of a verb.', 0, 0, 0, 1790961822072) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b2ee3bd093372ed5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'There is the man ___son died.', '{"A":"Whose","B":"Who","C":"Who is","D":"Who are","E":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Whose is a possessive pronoun. Use it when you''re asking (or telling) to whom something belongs. For example: whose sandwich is this?', 0, 0, 0, 1790961822072) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1513e195328457c8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'There was no co- operation ________ the boys.', '{"A":"Amongst","B":"Among","C":"Between","D":"With","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Amongst and Among mean the same though slightly different from each other.Amongst comes before “The”. There was no co- operation amongst the boys. Among is used before consonant sound, while amongst is used before vowel sound. Among them (“Them” starts consonant sound) Amongst us (“Us” starts vowel sound)', 0, 0, 0, 1790961822072) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_81fd527bba7037a4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'there was a guard with a dart gun hiding __________ a door.', '{"A":"Besides","B":"Behind","C":"Alongside","D":"Outside"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation کسی جیز کےبلکل پیچھے چھپی ہوئی چیز', 0, 0, 0, 1790961822072) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0531082d2a313c6d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'There was a great hue and cry against Hardy`s novels, Tess and Jude the Obscure because of _______ in them.', '{"A":"Obscenity","B":"violence","C":"Abnormality","D":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Obscenity means immoralityViolence means inhumanity Abnormality means deviation', 0, 0, 0, 1790961822072) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d597b00bbd427741', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'There __ three different ways to make perfect pie crust.', '{"A":"is","B":"Being","C":"Are","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation If it is plural or there is more than one noun, use are.', 0, 0, 0, 1790961822072) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9b2d272f34234040', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The ruler must not be Government ___ the law and order situation .', '{"A":"Of","B":"The","C":"Bye","D":"At","E":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961822072) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0e396e7fea2ea9c3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'These are flowers', '{"A":"Personal pronoun","B":"Indefinite pronoun","C":"demonstrative pronoun","D":"emphatic pronoun"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pronouns that point to specific things: this, that, these, and those, as in “This is an apple,” “Those are boys,” or “Take these to the clerk.”These is used as demonstrative pronoun', 0, 0, 0, 1790961822160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1af82aad1aadcd2b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The secretary was ______ because of her outstanding performance.', '{"A":"Progressed","B":"Raised","C":"Promoted","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Promote means ترقی دینا', 0, 0, 0, 1790961822160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1a1796f2e84d3860', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The Secretariat comprises __________ many air-conditioned rooms.', '{"A":"Of","B":"Off","C":"With","D":"In","E":"No preposition required"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Comprise means consist.Comprise means مشتمل ہوناDo not use of after comprise in active voice.', 0, 0, 0, 1790961822160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_adb39f270f5b7123', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The servant might have opened the secret.', '{"A":"The secret might have been opened by the servant","B":"The secret might have been open by the servant","C":"The secret might have been opened by him","D":"The secret have been opened by the servant","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: Might have + third form of a verb Passive Voice: Might have been + third form of a verb.', 0, 0, 0, 1790961822160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7c670a0fa39a2599', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The series of lectures ___delivered', '{"A":"were","B":"was","C":"is","D":"are"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Was is a past tense indicative form of be, meaning “to exist or live,” and is used in the first person singular (I) and the third person singular (he/she/it).', 0, 0, 0, 1790961822160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_01c41ddaaa134385', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'These ____ are mine', '{"A":"Cattle","B":"Cattles","C":"Both","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cattle مویشی', 0, 0, 0, 1790961822160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_366bccf068129290', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The shopkeeper lowered the prices.', '{"A":"The prices lowered by shopkeeper","B":"The prices were lowered by shopkeeper","C":"Down went prices","D":"The shopkeeper got down the prices","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Given sentence is in Past simple tense and it is in active voice, we need to change it into passive voice. Rule : Subject + (was / were) + V3 + Optional Agents.', 0, 0, 0, 1790961822160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_254e15ed8d547430', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The smugglers did not realise that their conversation was being recorded.', '{"A":"The smugglers did not realise that someone was recording their conversation","B":"Someone did not realise that the smugglers were recording their conversation","C":"Conversation was recorded when the smugglers did not realise","D":"The smugglers recorded their conversation without realising","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sentence is in Past Continuous Tense. Present Continuous TenseActive Voice: Subject + is/am/are + First of verb + ing + object. Passive Voice: Object + is being/am being/ are being + third form of verb + by + subject.', 0, 0, 0, 1790961822160) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_80ca44bb2aa81bac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The sounds of the footsteps died _____ when the man moved away towards woods.', '{"A":"For","B":"With","C":"Away","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961822232) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_654850752172d91c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The sound made with air passing through the nose and making the “ng” sound of “sing” is called:', '{"A":"Nasals","B":"Uvula","C":"Velum","D":"Bilabial"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nasals are sounds made with air passing through the nose. In English, these are m, n, and ng. 5.', 0, 0, 0, 1790961822232) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9767e6d0330f62c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The spectators ------loudly after acrobat had shown his feats.', '{"A":"Chatted","B":"Clapped","C":"Contributed","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961822232) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_eafb611563d468b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The story is too fantastic to be credible. In the above sentence the word "Credible" means what?', '{"A":"Praise Worthy","B":"Readable","C":"Believable","D":"False"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Credible means قابل یقین', 0, 0, 0, 1790961822232) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_833b5728d433fde7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The students consider that the teachers are wise.', '{"A":"The teachers are considered to be wise","B":"The teachers were considered to be wise","C":"The teachers will be considered to be wise","D":"The teachers should be considered to be wise","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice = Subject + believe/find/claim/consider/know/report/say/think/ + that + clause.Passive Voice = It + be + third form of a verb + clause.People believe that every child is born with different abilities. It is believed that every child is born with different abilities.', 0, 0, 0, 1790961822232) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_da75f736f55aa497', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The superior thought _____ the most suitable person to the job.', '{"A":"On","B":"At","C":"Out","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961822232) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_19970bdca0585478', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The sweets were shared _______ the four boys.', '{"A":"Between","B":"Among","C":"From","D":"Since","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sweets were shared among the four boys means چار لڑکوں میں مٹھائی تقسیم کی گی تھی یBetween is used for two persons or things.Among is used for more than two persons or things.', 0, 0, 0, 1790961822232) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5e4e48bcbf0b93c0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The surface feels smooth.', '{"A":"The surface is smooth when it is felt","B":"The surface was smooth when it is felt","C":"The surface will smooth when it is felt","D":"The surface should be smooth when it is felt","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: The surface feels smooth. Passive Voice: The surface is smooth when it is felt. Active Voice: Roses smell sweat. Passive Voice: Roses are sweat when they are smelt.', 0, 0, 0, 1790961822232) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_5125fb7685ff4c65', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The teacher told me frankly that the son __________failed .', '{"A":"will","B":"Would","C":"Should","D":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961822303) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0f69eadf11823d50', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The teachers said that they were no longer prepared to _________ the ways of the new headmaster.', '{"A":"Put over with","B":"Put on with","C":"Put up with","D":"Put up to"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Put over with someone means to pursuede someone.', 0, 0, 0, 1790961822303) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_ea8e9a0b3d43b896', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The teachers of various schools met to discuss ________ how to improve standard of English', '{"A":"About","B":"Of","C":"With","D":"Upon","E":"No preposition required"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation About should not be used after discuss.Discuss means کسی بات کا جائزہ لینا، بات چیت کرنا، گفتگو کرنا', 0, 0, 0, 1790961822304) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_581ccbf1a498b88d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The teacher provided the number of difficult questions.', '{"A":"The number of difficult questions was provided by the teacher","B":"The number of difficult questions were provided by the teacher","C":"The number of difficult questions will be provided by the teacher","D":"The number of difficult questions should be provided by the teacher","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The number of + plural noun + singular verbA number of + plural noun + plural verb', 0, 0, 0, 1790961822304) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_7d641e833e270a74', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The term "Capital Punishment" means _____?', '{"A":"Releasing from prison","B":"Death Penalty","C":"Parole to the prisoner","D":"none of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Capital Punishment means سزائے موت', 0, 0, 0, 1790961822304) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d37728be3c120751', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The title of Sir Philip Sidney''s pastoral romance in prose is:', '{"A":"Utopia","B":"Arcadia","C":"Hydriotaphia","D":"Lamia"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sir Philip Sidney was an English poet, courtier, scholar and soldier who is remembered as one of the most prominent figures of the Elizabethan age. His works include Astrophel and Stella, The Defence of Poesy and The Countess of Pembroke''s Arcadia.', 0, 0, 0, 1790961822304) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a1e063e51539caae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The tiger caught a fox.', '{"A":"A fox has been caught by the tiger","B":"A fox was caught by the tiger","C":"A fox is caught by the tiger","D":"A fox had been caught by the tiger","E":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Given sentence is in Past simple tense and it is in active voice, we need to change it into passive voice. Rule : Subject + (was / were) + V3 + Optional Agents.', 0, 0, 0, 1790961822304) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0efb7660cca2c441', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The total number of people living in an area, city, country or the world at a specific time is called_____.', '{"A":"People","B":"Population","C":"citizens","D":"members"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Population means آبادی', 0, 0, 0, 1790961822304) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f1b613dc1cb2540b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The watch has run__', '{"A":"down","B":"in","C":"out","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation نیچےdown', 0, 0, 0, 1790961822373) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_049227b887e0cba8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The waiter gets a ___________ from the cosumers.', '{"A":"Bonus","B":"Tip","C":"Fee","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961822373) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_159769ae3e031c5b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The windows are bear because I ____ like curtains.', '{"A":"don''t","B":"can''t","C":"will","D":"shall"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In English, don''t is used when speaking in the first and second person plural and singular and the third person plural', 0, 0, 0, 1790961822373) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_03163952bd3884a0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The whole firm offered its good wishes', '{"A":"Indirect object","B":"Direct object","C":"Linking verb","D":"Complement"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation indirect object is a noun phrase referring to someone or something that is affected by the action of a transitive verb, but is not the primary object.', 0, 0, 0, 1790961822373) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f4fe5f98a560ee64', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The word “Novel” is derived from the Italian word:', '{"A":"Novella","B":"Novelle","C":"Novelette","D":"Noval"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A novel means a long printed story about imaginary characters and events.', 0, 0, 0, 1790961822373) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e73e665494f79e3a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The word that is used instead of a Noun is called:', '{"A":"Verb","B":"Preposition","C":"Adverb","D":"Adjective","E":"Pronoun"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pronoun is a word which is used in place of a noun.Pronoun means اسم ضمیر', 0, 0, 0, 1790961822373) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_28143a129a3a786a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They are a political important family; one of her sisters is a minister and the other is married ______________a minister.', '{"A":"With","B":"To","C":"Of","D":"Upon","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The other is married = This is a sentence of passive voice.Female married a male = Married toMale married a female = Married with', 0, 0, 0, 1790961822373) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f58818d8f64e49e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They drew a circle in the morning.', '{"A":"A circle was being drawn by them in the morning","B":"A circle was drawn by them in the morning","C":"In the morning a circle have been drawn by them","D":"A circle has been drawing since morning","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A circle was drawn by them in the morning. Given sentence is in Past simple tense and it is in active voice, we need to change it into passive voice. Rule : Subject + (was / were) + V3 + Optional Agents.', 0, 0, 0, 1790961822373) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_3d77e8867bcba2dc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They have painted their house. the Painted word is:', '{"A":"Transitive","B":"Intransitive","C":"Complex Transitive","D":"Adverb"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Transitive verbکے بعد ابجیکٹ ہوتاہے مثلاThey have painted their houseI am sleeping in the room----------Intransitive verbکےبعد ابجیکٹ نہیں ہوتا مثلاI am sleeping---Complex Transitive جس میں ڈبل ورب ہو', 0, 0, 0, 1790961822448) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a7eeca3591d295b8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They elected him president last month.', '{"A":"He is elected president last month by them","B":"He had been elected president last month by them","C":"He was elect president last month by them","D":"He could be elected president last month by them","E":"All of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active sentences in the simple past tense have the following structure: Subject + past tense form of the verb + object Passive sentences in the simple past tense have the following structure: Object of the active sentence + was/were + past participle form of the verb + by + subject of the active sentence', 0, 0, 0, 1790961822448) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0f55d88f1d348225', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They say that you did that.', '{"A":"You are said to have done that","B":"You are said to have do that","C":"You are say to have done that","D":"You were said to have done that","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Past Indefinite tenseActive Voice= Subject + Second Form of Verb + Object. Passive Voice = Object + was/were + third of verb + by + subject.', 0, 0, 0, 1790961822448) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9976c368aa2f9129', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They say that the war is imminent.', '{"A":"It is said by them that the war is imminent","B":"It is said by them that the war war imminent","C":"It is say by them that the war is imminent","D":"It is said by they that the war is imminent","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation They say that the war is imminent means وہ کیتے ہیں کہ جنگ قریب ہےPresent Indefinite TenseActive Voice: Subject + Verb + ObjectPassive Voice: Object + is/am/are+ third form of a verb + by + subject.', 0, 0, 0, 1790961822448) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_37c6ca9fcfd9a968', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They say he can teach almost anything in this world.', '{"A":"It is said that almost anything in this world can be taught by him","B":"It was said that almost anything could be taught by him","C":"They say almost anything could be taught by him","D":"They say anything almost will be taught by him","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: They sayPassive Voice: It is saidPresent Indefinite TenseActive Voice: Subject + Verb + Object Passive Voice: Object + is/am/are+ third form of a verb + by + subject.', 0, 0, 0, 1790961822448) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_8d1abc3b95a52f67', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They said, "They were taking exercise".', '{"A":"They told that they had taken exercise.","B":"They told that they had been taken exercise.","C":"They told that they have been taken exercise.","D":"They told that they was taken exercise."}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation They said, "They were taking exercise".were (Past Continue) will change into had been (past perfect tense). this is direct to indirect rule', 0, 0, 0, 1790961822448) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c526998ebe6a4c1b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They ___ spoken to the cabinet before signing on the contract', '{"A":"Have","B":"Had","C":"Will be","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation When you need to talk about two things that happened in the past and one event started and finished before the other one started, place “had” before the main verb for the event that happened first', 0, 0, 0, 1790961822448) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d5df9748b54c74f5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They will sing a song.', '{"A":"A song was sung by them","B":"A song is sung by them","C":"A song will be sung by them","D":"A song should be sung by them","E":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation They will sing a song means وہ ایک گانا گائیں گےFuture Indefinite Tense Active Voice Formula: Subject + Will/Shall + Verb (Ist form) + Object + (.) Passive Voice Formula: Convert Object to Subject + Will/Shall + Be + Verb (3rd form) + By + Convert Subject to Object + Remaining + (.)', 0, 0, 0, 1790961822448) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_45f3237a02d65fe4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They were sitting __________ the room.', '{"A":"In","B":"Into","C":"On","D":"Upon","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In and Into In = (Located inside or within)Into = (Indicates entry or insertion)The girl jumped into the sea.They were sitting in the room means وہ کمرے میں بیٹھے ہوئے تھے Note: “Into” is not used with “Enter” as the sentence becomes superfluous.She entered into the room. The boy threw the ball into the well.', 0, 0, 0, 1790961822521) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_524e066dc0ce5eed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They ___ cats', '{"A":"like","B":"likes","C":"both","D":"none"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation (Base) 1st (Past) 2nd (Past Participle) 3rdLike Liked Liked', 0, 0, 0, 1790961822521) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_52be27927628f5d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They will share all you want to know.They are going to give you enough____.', '{"A":"Time","B":"Information","C":"Food","D":"Books"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation information معلومات', 0, 0, 0, 1790961822521) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9e1d95c34b2efce2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They will give all the help to new staff.', '{"A":"The new staff will be given all the help by them","B":"The new staff will have been given all the help by them","C":"The new staff will be given all the help by him","D":"The new staff will be given all the help by us"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Option A is the correct answer because have been was mentioned in second option which is used for perfect tense, the word him was mentioned in third option which is used for he not they, the word us was mentioned in fourth option which is used for we not they.', 0, 0, 0, 1790961822521) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_afa42555ae340b2f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They will demolish the entire block.', '{"A":"The entire block is being demolished","B":"The block may be demolished entirely","C":"The entire block will have to be demolished by the boy","D":"The entire block will be demolished","E":"All of the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The given sentence contains one of Model verb (Model Verb = will, shall, can, may, might, could, might, must, would). It is in active voice. Rule : Subject + Model verb + be + V3 + Optional Objects.', 0, 0, 0, 1790961822521) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_60f73a2130b29112', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'They will cast the votes.', '{"A":"Votes will be cast by them","B":"Votes will be casted by them","C":"Votes were cast by them","D":"Votes can be cast by them","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: They will cast the votes.Passive Voice: Votes will be cast by them. Future Indefinite Tense-Passive Voice Convert the object of the Active Voice Sentence into the subject of the Passive Voice sentence.Then use helping verb will be/shall be according to the subject of the Passive Voice Sentence.Then use the 3rd form of Verb.After that, use the word “by”, in order to show the doer.', 0, 0, 0, 1790961822521) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_1000ed7e6763eb79', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The _______ was served before the dinner.', '{"A":"Horse de saison","B":"Hors d''oeuvres","C":"Horse De Combat","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hors d''oeuvres means an additional dish usually served before main meal.', 0, 0, 0, 1790961822521) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_b39ac8afdbb5bc5b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The ______ maintained even after the change of government.', '{"A":"Virtouso","B":"Status Quo","C":"De Facto","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Status Quo means صورتحال', 0, 0, 0, 1790961822521) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2a37177b6e2e8348', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'The “old wives” Tale is a novel by:', '{"A":"Hardy","B":"Henry James","C":"Arnold Bennett","D":"John Galsworthy"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Old Wives'' Tale is a novel by Arnold Bennett, first published in 1908. It deals with the lives of two very different sisters, Constance and Sophia Baines, following their stories from their youth, working in their mother''s draper''s shop, into old age.', 0, 0, 0, 1790961822594) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_585a7dbce321e9a8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'This book is ___ by Shakespeare .', '{"A":"Writing","B":"Written","C":"Wrote","D":"Write"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Base Form (Infinitive): To WritePast Simple: WrotePast Participle: Written3rd Person Singular: WritesPresent Participle/Gerund: Writing', 0, 0, 0, 1790961822594) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_56064d7957b53dc6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'This idea --- longer matches the reality of the modern world', '{"A":"no","B":"in","C":"on","D":"at"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961822594) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_31cadd94535e0510', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'This book ____ to him by me.', '{"A":"Given","B":"will given","C":"was given","D":"None of the above."}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation givenدیاThird form of verb', 0, 0, 0, 1790961822594) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_fabe7513b0a1d904', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'This music sounds melodious.', '{"A":"The music is melodious when it is listened","B":"The music was melodious when it is listened","C":"The music is melodious when it was listened","D":"The music is melodious when that is listened","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Present Indefinite TenseActive Voice: Subject + Verb + Object Passive Voice: Object + is/am/are+ third form of a verb + by + subject.', 0, 0, 0, 1790961822594) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_23f4eb6170dc27da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'This is___ most beautiful desert I have seen.', '{"A":"The","B":"An","C":"A","D":"And"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The definite article (the) is used before a noun to indicate that the identity of the noun is known to the reader', 0, 0, 0, 1790961822594) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_f6ca79725fc23b0f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'This is time to offer prayers.', '{"A":"This is time for prayers to be offered","B":"This was time for prayers to be offered","C":"This is time for prayers to be offer","D":"This is time for prayers to offered","E":"All of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active Voice: This is time to offer prayers.Correct Passive Voice: This is time for prayers to be offered.This is time to offer prayers means عبادت کرنے کا وقت آگیا ہےOffer is a verb here.Third form of verb is always used in passive voice sentence.', 0, 0, 0, 1790961822594) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_e31da21319f82fa4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'This paper is based _______ history.', '{"A":"On","B":"Into","C":"At","D":"Over"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Based is generally followed by on.', 0, 0, 0, 1790961822594) ON CONFLICT(id) DO NOTHING;
