INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_a88a934dd34f1d07', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'To which of these language groups does English belong?', '{"A":"Baltic","B":"Romance","C":"Germanic","D":"Slavonic"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Germanic languages are a branch of the Indo-European language family spoken natively by a population of about 515 million people mainly in Europe, North America, Oceania and Southern Africa.', 0, 0, 0, 1790961822674) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_04a291791f9dec03', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Twice, the whistle has blown', '{"A":"Adverb","B":"Adjective","C":"Noun","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Twice is used as AdverbAn adverb is a part of speech that provides greater description to a verb, adjective or another adverb.', 0, 0, 0, 1790961822674) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_50a5dff506e4a9c6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Twelve inches make a foot . The underlying word is', '{"A":"Definite Article","B":"Preposition","C":"Pronoun","D":"Indefinite Article"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation the word a or an used in English to refer to a person or thing that is not identified or specified In "I gave a book to the boy" the word "a" is an indefinite article and the word "the" is a definite article. also : a word that has a similar use in another language.', 0, 0, 0, 1790961822740) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c4e5a197d74275f6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Two of the notebooks_______ Musa had lost on the bus were returned to the main desk at his room.', '{"A":"What","B":"Who","C":"Which","D":"Whose"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use which in questions as a determiner and interrogative pronoun to ask for specific information. We use both which and what to ask questions. We use which when there is a restricted range of answers. We use what more commonly when the range of answers is not restricted', 0, 0, 0, 1790961822740) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_cbdd9c035d6ae601', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Two words with very close meanings called.', '{"A":"Antonyms","B":"Synonyms","C":"Homonyms","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A word or phrase that means exactly or nearly the same as another word or phrase is called synonym.', 0, 0, 0, 1790961822740) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_d5f5efd5c503c04e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Vitamins ___ our body fit.', '{"A":"Keep","B":"Will kept","C":"shall keeping","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation', 0, 0, 0, 1790961822740) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_bbc71bd29316ff99', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'WAIT FOR ME BY _______ SCHOOL GATE AT 4 O’CLOCK.', '{"A":"An","B":"A","C":"The","D":"Article not required"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An article is any member of a class of dedicated words that are used with noun phrases to mark the identifiability of the referents of the noun phrases.', 0, 0, 0, 1790961822740) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_9b3d40a70d93b041', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Wash away the thoughts inside that keep my mind away from you.', '{"A":"Noun clause","B":"Adverb clause","C":"Adjective clause","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation An adjective clause is a multiword adjective that includes a subject and a verb. When we think of an adjective, we usually think about a single word used before a noun to modify its meanings.', 0, 0, 0, 1790961822740) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_0d112f1fb5ca6c8d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'Was the story being written by him?', '{"A":"Is he writing the story?","B":"Was he writing the story?","C":"Did you write the story?","D":"Do you write the story","E":"All of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active sentences in the past continuous tense have the following structure: Subject + was/were + -ing form of the verb + object Passive sentences in the past continuous tense have the following structure: Object of the active sentence + was/were + being + past participle form of the verb + by + subject of the active sentence', 0, 0, 0, 1790961822740) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_dc5197e4766db69f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We had to stop all other work to complete our assignment.', '{"A":"All other work has to be stopped by us to complete our assignment","B":"All other work had stopped by us to complete our assignment.","C":"All other work had to be stopped by us to complete our assignment.","D":"All other work was stopped by us to complete our assignment","E":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Active voice: Had to + first form of a verb Passive Voice: Had to + third form of a verb', 0, 0, 0, 1790961822740) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_4047867d70c6fb38', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We felt as if the ground was ___ beneath our feet', '{"A":"Slipping","B":"Digging","C":"Bursting","D":"Sinking"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation slippingپھسلنا', 0, 0, 0, 1790961822826) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_2c4c9813605e561f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We all can fit in here.There are a lot of ___ in the room:', '{"A":"Space","B":"Chairs","C":"Fans","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation space جگہ', 0, 0, 0, 1790961822826) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_43b17e8c7969121a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'We must respect the elders.', '{"A":"The elders deserve respect from us","B":"The elders must be respected","C":"The elders must respected","D":"Respect the elders we must","E":"The elders must be respected by us"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The given sentence contains one of Model verb (Model Verb = will, shall, can, may, might, could, might, must, would). It is in active voice. Rule : Subject + Model verb + be + V3 + Optional Objects.', 0, 0, 0, 1790961822826) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_64c44a777203f447', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'What ---- you call who take monthly wage', '{"A":"in","B":"do","C":"on","D":"at"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation We use do, does present simple to give extra force to the main verb.', 0, 0, 0, 1790961822826) ON CONFLICT(id) DO NOTHING;
