INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_te_c364777da7a44d4e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_general', 'You have seen.', '{"A":"آپ کھا چکے ہیں","B":"آپ کھیل چکے ہیں","C":"آپ شروع کرچکے ہیں","D":"ان میں سے کوئی ںہیں"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation You have seen means آپ دیکھ چکے ہیں The word see is a verb which means دیکھناSaw is the second form while Seen is the third form of Saw.', 0, 0, 0, 1790961823868) ON CONFLICT(id) DO NOTHING;
